P.entries["zone:moonglade"] = {n="Mondlichtung",s="In der Mondlichtung versammeln sich Druiden des Zirkels des Cenarius unter einer endlosen Dämmerung. Das Tal im Norden Kalimdors ist Zuflucht für nachtelfische und taurische Druiden, während Reisende zu Fuß die Holzschlundfeste durchqueren müssen, um es zu erreichen.",h="In der Mondlichtung versammeln sich Druiden des Zirkels des Cenarius unter einer endlosen Dämmerung.",kw={"zirkel des cenarius","dendrite sternenschauer","smaragdgrüner traum","see von elune'ara","mondlichtung","nachthafen","remulos","sturmgrimms grabhügel"},ang={["class:Druid"]="Als Druide ist die Mondlichtung Euer heiliges Zuhause und Zufluchtsort. Eure spirituelle Bindung ermöglicht es Euch, Euch von überall in Azeroth hierher zu teleportieren, Meister wie Dendrite Sternenschauer zu befragen, mit großen Geistern Zwiesprache zu halten und Formen wie die Aquatic Form zu meistern.",["race:NightElf"]="Als Nachtelf war die Mondlichtung zehntausend Jahre lang das spirituelle Herzland Eures Volkes und die Ruhestätte Eurer schlafenden Erzdrui­den. Elunes anhaltender Segen beschützte sie.",["race:Tauren"]="Als Tauren erneuert Euer Platz im Zirkel des Cenarius ein uraltes Band zu Cenarius. Hamuul Runetotem setzte sich für Eure Aufnahme ein, die die Mondlichtung ehrt, obwohl sich die Nachtelfen lange abgeschottet hielten."},sec={{t="Heilige Dämmerung",b="Die Mondlichtung liegt zwischen den Bergen nördlich des Teufelswalds und Winterquells. Unter Elunes Mondschein hält die Dämmerung über dem See von Elune'ara an, im Herzen eines Tals, das seit den Anfängen der kaldoreiischen Zivilisation heilig ist. Die Brennende Legion ließ die Lichtung bei ihren uralten Invasionen und im jüngsten Dritten Krieg unberührt, aufgehalten von Cenarius und seinen Nachkommen. Hüter Remulos wacht nun über die Mondlichtung und bewahrt das Gleichgewicht der Natur in einem Zufluchtsort, an dem Fraktionskonflikte keinen Platz haben."},{t="Sitz des Zirkels",b="Malfurion Sturmgrimm gründete den Zirkel des Cenarius vor Jahrtausenden, und die Mondlichtung ist bis heute sein Hauptsitz. In Nachthafen am See lernen Druiden uralte Traditionen kennen. Nach dem Dritten Krieg nahm der Zirkel Tauren in seine Reihen auf und folgte den Lehren des Erzdrui­den Hamuul Runetotem. Hier treten die Loyalitäten zur Allianz und zur Horde in den Hintergrund. Bewaffnete Wächter wahren den Frieden, und Mitglieder, die zu Gewalt greifen, werden rasch zur Rechenschaft gezogen."},{t="Die Grabhügel und der Traum",b="Südlich des Sees von Elune'ara liegen die Sturmgrimms Grabhügel. Tausende von Jahren schliefen elfische Druiden in diesen unterirdischen Höhlen, während ihre Geister den Smaragdgrünen Traum durchstreiften. Ihre Körper ruhten unter ständiger Bewachung. Während des Dritten Krieges blies Tyrande Wisperwind hier das Horn des Cenarius und erweckte Malfurion.\n\nDie Grabhügel sind weiterhin mit dem Traum verbunden. Doch nun steigen seltsame Wellen aus ihren tiefen Tunneln auf, und dunkle Flüsterstimmen beunruhigen das smaragdgrüne Reich."}},faq={{q="Wie erreichen Reisende, die keine Druiden sind, die Mondlichtung?",a="Zu Fuß durchquert Ihr die Holzschlundfeste, ein Tunnelnetz, das den oberen Teufelswald, Winterquell und die Mondlichtung verbindet, sofern Euch bei saisonalen Ereignissen keine Ritualmagie dorthin bringt. Die Holzschlund-Furbolgs bewachen den Durchgang streng, und Fremde müssen ihren guten Willen beweisen, um sicher hindurchzukommen.",al={"wie gelangt man zur mondlichtung","zur mondlichtung gelangen","eingang zur mondlichtung"}},{q="Warum können Horde und Allianz hier friedlich nebeneinander wandeln?",a="Der Zirkel des Cenarius regiert die Mondlichtung und dient der Natur statt der Politik. Die Wächter der Mondlichtung in ganz Nachthafen greifen jeden an, der Gewalt gegen jemanden beginnt, der beim Zirkel in gutem Ansehen steht.",al={"warum ist die mondlichtung neutral","pvp in der mondlichtung","können horde und allianz hier kämpfen"}},{q="Welchen Zweck erfüllt Nachthafen?",a="Nachthafen ist die Hauptsiedlung der Mondlichtung, in der der Zirkel des Cenarius lebt und wirkt. Ausbilder, Pfleger und Heiligtümer bieten kaldoreiischen und taurischen Druiden Orte, um sich über den Zustand der wilden Länder Azeroths auszutauschen.",al={"zweck von nachthafen","was ist nachthafen","ort in der mondlichtung"}},{q="Wer führt die Mondlichtung, wenn Malfurion Sturmgrimm abwesend ist?",a="Hüter Remulos wacht vom Schrein von Remulos über die Mondlichtung, solange Malfurion Sturmgrimm abwesend ist. Zusammen mit erfahrenen Mitgliedern des Zirkels wie Dendrite Sternenschauer pflegt er die heiligen Lande und leitet die Bemühungen, die Welt zu heilen.",al={"anführer der mondlichtung","wer führt den zirkel des cenarius","wer ist remulos"}},{q="Was ruht unter den Sturmgrimms Grabhügeln?",a="Die Sturmgrimms Grabhügel sind tiefe Kammern, in denen Druiden eine lange Zwiesprache mit dem Smaragdgrünen Traum hielten. Ihre tiefen Flügel bewahren weiterhin mächtige Verbindungen zum Traum, doch jüngste Störungen lassen darauf schließen, dass beunruhigende Albträume darin erwachen.",al={"lore der grabhügel","zweck der sturmgrimms grabhügel","wo schlafen die druide"}},{q="Warum haben Druiden besondere Flugrouten von Nachthafen aus?",a="Silva Fil'naveth, die Hippogryphenmeisterin, und Bunthen Plainswind, der Wind Rider-Hüter, bieten Druiden direkte Flüge von Nachthafen nach Rut'theran und Donnerfels an. Diese Routen helfen dem Orden, zwischen seinem heiligen Hain und den Heimatlanden seiner Völker zu reisen.",al={"flugmeister von nachthafen","druiden-flugmeister in der mondlichtung","kostenlose flüge in der mondlichtung"}}},fp="9,207,15.457.0,18.412.0,29.447.1,43.274.0,57.197.0,34.215.0,53.223.0,45.241.0,58.258.0"}
P.entries["zone:mulgore"] = {n="Mulgore",s="Unter dem Steinkrallengebirge liegt Mulgore, die grüne, geschützte Heimat der Tauren. Zwischen hohen Hochebenen breiten sich Grasland und Die wogenden Ebenen aus, umringt von hohen Bergwänden. Mulgore ist das Herz der vereinten Stämme, die von Donnerfels aus über das Land wachen.",h="Unter dem Steinkrallengebirge liegt Mulgore, die grüne, geschützte Heimat der Tauren.",kw={"bael'dun","baine bluthuf","dorf der bluthufe","cairne bluthuf","camp narache","erdenmutter","kodo","mulgore","die hochwolkenebene","teufelsfelsen","donnerfels","venture company"},ang={["class:Druid"]="Mulgores wogende Ebenen und unberührte Haine zählen zu den reinsten Naturschutzgebieten Kalimdors. Hier studieren Taurendruiden das Gleichgewicht und die Gaben der Natur.",["class:Hunter"]="Auf Mulgores Ebenen gedeiht die Große Jagd. Pumas, Wölfe und wilde Kodos stellen Euer Geschick und Eure Geduld als Fährtenleser auf die Probe.",["faction:Horde"]="Mulgore ist das Herz der Spiritualität und Landwirtschaft der Horde im Zentrum Kalimdors. Ein Blutschwur gegenseitiger Verteidigung verbindet das Land mit Thralls Volk.",["race:Tauren"]="Dieses Tal ist Eure angestammte Heimat, durch Opfer und Einigkeit zurückerobert. Im Dienst der Erdenmutter müsst Ihr seine Quellen bewahren und seine heiligen Stätten reinigen."},sec={{t="Ein Land zurückerobert",b="Über Generationen lebten die Tauren als Nomaden und wurden von Zentauren-Kriegsbanden über die Ebenen gejagt. Ihr Schicksal wendete sich, als Oberhäuptling Cairne Bluthuf Thrall und dessen Orcs traf. Sie teilten Ideale von Ehre, Schamanismus und Stärke, und so schlossen sich die Tauren der jungen Horde an. Mit der Hilfe der Orcs brach Cairne die Vorherrschaft der Zentauren und führte sein Volk nach Mulgore. Hier errichteten sie zum ersten Mal seit Jahrhunderten dauerhafte Heimstätten und krönten die nördlichen Mesas mit ihrer Hauptstadt."},{t="Die Prüfungen der Erdenmutter",b="Um in Mulgore erwachsen zu werden, müssen junge Tauren dem Ruf der Großen Jagd folgen und die Erdenmutter ehren. Ihre Ausbildung beginnt in Camp Narache unter Häuptling Falkenwind. Von dort steigen sie hinab ins Dorf der Bluthufe und nehmen die Rites of the Earthmother auf sich. Sie lernen, mit den Geistern der Ahnen zu sprechen und einheimische Kräuter zu sammeln. Außerdem lernen sie, die Herden von Kodos und Schreiteern zu achten, die ihr Volk ernähren."},{t="Bedrohungen ringsum",b="Trotz seiner Ruhe ist Mulgore von allen Seiten bedroht. Vertriebene Stacheleber haben sich in der Dornrankenklamm verschanzt und die heiligen Grabstätten der Teufelsfelsen geschändet. In den Bergen fallen Windfurienharpyien über das Wild her, und Bleichmähnen-Gnolle schlagen aus verborgenen Höhlen zu.\n\nAuch Fremde sind gekommen, um aus dem Land Gewinn zu schlagen. Die Goblins der Venture Company verschmutzen die heiligen Quellen und brechen im Osten Stein. Zwergenforscher aus Bael Modan haben die Grabungsstätte von Bael'dun eröffnet. Dort graben sie trotz des Protests der Tauren nach uralten Titanenrelikten."}},faq={{q="Warum haben sich die Tauren dauerhaft in Mulgore niedergelassen?",a="Die Tauren ließen sich dauerhaft in Mulgore nieder, nachdem sie sich mit Thralls Horde verbündet hatten. Zentaurenmarodeure hatten das Nomadenvolk lange durch Kalimdor gejagt. Doch Cairne Bluthuf gewann die Kraft, sie zu vertreiben und das angestammte Tal zurückzuerobern. Die Tauren errichteten dauerhafte Siedlungen, darunter das Dorf der Bluthufe und Donnerfels. So erhielten alle Stämme eine gemeinsame Heimat, in der sie in Frieden gedeihen konnten.",al={"warum leben tauren hier","geschichte der taurenheimat","warum donnerfels besiedeln"}},{q="Wie verlasst Ihr Mulgore zu Fuß?",a="Ihr könnt Mulgore zu Fuß durch den einzigen Pass in der südöstlichen Bergwand verlassen. Folgt der Hauptstraße nach Osten, vorbei am Dorf der Bluthufe und Morin Wolkenpirschers Außenposten, durch den Gebirgskorridor und hinein in die trockenen Ebenen des Brachlands.",al={"ausgang aus mulgore","wie kommt man von mulgore ins brachland","straße aus mulgore"}},{q="Wer ist die Venture Company und warum ist sie hier?",a="Die Venture Company ist ein von Goblins geführtes Handelskartell, das nach den Naturschätzen Kalimdors strebt. In Mulgore baut sie in den östlichen Bergen Erz ab und hat die wichtigen Wasserbrunnen Donnerhorn, Wildmähne und Winterhuf besetzt. Damit entweiht sie das Land und bedroht die Wasserversorgung der Region.",al={"venture company in mulgore","warum sind goblins hier","mine der venture company"}},{q="Warum graben Zwerge im Gebiet der Tauren?",a="Zwerge der Expedition Bael Modan graben in der Grabungsstätte von Bael'dun in Mulgores westlichen Ausläufern. Die Forscherliga schickte sie, um Relikte ihrer Titanenschöpfer auszugraben. Sie graben ohne Erlaubnis auf Taurenland, obwohl die Tauren protestieren, dass ihre Arbeit die Erdenmutter verletzt.",al={"grabungsstätte von baeldun","warum sind zwerge in mulgore","bael dun"}},{q="Was sind die Rites of the Earthmother?",a="Die Rites of the Earthmother sind heilige Prüfungen, denen sich junge Tauren beim Eintritt ins Erwachsenenalter unterziehen. Dabei beweisen sie ihre Hingabe an das Land und die Traditionen ihrer Ahnen. Die Prüfungen verlangen Jagdgeschick, Fährtenlesen, die Zwiesprache mit Visionen und Wissen um das Gleichgewicht der Natur. Sie finden im Dorf der Bluthufe und auf den Goldenen Ebenen statt.",al={"rites of the earthmother","prüfung zum erwachsenwerden der tauren","rite of the earthmother"}},{q="Wer herrscht über Mulgore?",a="Oberhäuptling Cairne Bluthuf herrscht von Donnerfels auf den nördlichen Mesas aus über alle Lande der Tauren. Sein Sohn Baine Bluthuf regiert das Dorf der Bluthufe und kümmert sich unter Cairnes weiser Führung um die täglichen Belange der unteren Ebenen.",al={"führer von mulgore","wer ist der häuptling von mulgore","cairne bluthuf anführer"}}},fx={["145a41be"]={q="Was ist Mulgore?",a="Mulgore ist die grüne, geschützte angestammte Heimat der Tauren, eingebettet in einen Ring aus schützenden Bergen im zentralen Kalimdor. Seine sanften goldenen Graslandschaften und hoch aufragenden, windgepeitschten Plateaus bieten erstklassige Jagdgründe und einen friedlichen Zufluchtsort, der zu Fuß nur durch einen einzigen Gebirgspass im Osten zugänglich ist, der in das Brachland führt.",al={"was ist das für ein gebiet","erzähle mir von mulgore","überblick mulgore"}},bf98c20a={q="Ist Mulgore gefährlich?",a="Obwohl Mulgore weitaus friedlicher ist als das Brachland, steht es vor wachsenden Problemen. Aggressive Borstennacken-Stacheleber dringen in heilige Gebiete ein, Bleichmähnen-Gnolle lauern in südlichen Höhlen und Windfurien-Harpyien nisten entlang der Bergrücken. Darüber hinaus beutet die Venture Company unberührte Wasserquellen und Berghänge aus, während Zwergenausgräber im Westen angestammtes Land entweihen.",al={"ist mulgore sicher","bedrohungen in mulgore","gefahr hier"}},["148e56bf"]={q="Wer sind die Tauren und wie sind sie in Mulgore gelandet?",a="Die Tauren, oder Shu'halo, sind ein altes, nomadisches Volk, das der Erdenmutter ergeben ist. Über Generationen hinweg wanderten sie durch das Brachland, unaufhörlich gejagt und bis an den Rand der Ausrottung getrieben von marodierenden Zentaurenstämmen. Nachdem sie während des Dritten Krieges ein Band der Ehre mit Thrall und den neu angekommenen Orcs geschmiedet hatten, führte Häuptling Cairne Bluthuf sein vereintes Volk zurück in ihr angestammtes Tal von Mulgore, um ein dauerhaftes Zuhause zu beanspruchen.",al={"woher kamen die tauren","geschichte der tauren in mulgore","wie kamen die tauren hierher"}},["24d564cd"]={q="Was ist das Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist eine bedeutende Siedlung am klaren Wasser des Stonebullsees im zentralen Mulgore. Benannt zu Ehren von Cairnes Stamm und regiert von seinem Sohn Baine, dient sie als primärer Handels-, Handwerks- und Sammelpunkt, wo sich junge Jäger und Krieger nach ihrer Reise von der Hochwolkenebene versammeln.",al={"lore zu bloodhoof","was ist bloodhoof","dorf in mulgore"}},dbff83eb={q="Was ist Donnerfels?",a="Donnerfels ist die prächtige Hauptstadt der Taurennation, die hoch oben auf einer Reihe von windgepeitschten, verteidigbaren Plateaus über dem nördlichen Mulgore errichtet wurde. Gegründet von Cairne Bluthuf nach dem Dritten Krieg, bieten ihre erhöhten Plateaus und Seilbrücken Tauren aller Stämme Schutz und eine sichere Bastion gegen Zentauren-Invasoren.",al={"lore zu donnerfels","tauren-hauptstadt","stadt auf den plateaus"}},["69b40be7"]={q="Was machen die Bleichmähnen-Gnolle in Mulgore?",a="Der Bleichmähnenstamm der Gnolle hat sich Höhlen um den Bleichmähnenfels gegraben und Lager entlang der südlichen Berge von Mulgore verstreut. Während die Philosophie der Tauren das Teilen der Gaben der Erdenmutter schätzt, belästigen diese aggressiven Gnolle Reisende, überfallen nahe gelegene Jagdgründe und greifen jeden Krieger an, der in die Nähe ihres Territoriums kommt.",al={"bleichmähnen-gnolle in mulgore","warum sind gnolle hier","bleichmähnenfels"}},["7f5f34f0"]={q="Wie bin ich in Mulgore gelandet?",a="Wenn Ihr ein Taure seid, seid Ihr hier unter den nomadischen Stämmen aufgewachsen, die kürzlich unter Häuptling Cairne Bluthuf vereint wurden. Nach dem Dritten Krieg siedelte sich Euer Volk auf diesen grünen angestammten Ebenen an, um den Zentauren zu entkommen und eine dauerhafte Heimat aufzubauen, beginnend mit Eurem Training auf dem südlichen Plateau der Hochwolkenebene. Reisende anderer Völker kommen durch den einsamen, befestigten Gebirgspass vom östlichen Brachland oder per Wyvernflug direkt zur ausgedehnten Plateaustadt Donnerfels.",al={"wie bin ich hierhergekommen","warum bin ich in mulgore","wie bin ich nach mulgore gekommen"}},a8ac99e7={q="Was soll ich in Mulgore tun?",a="Junge Tauren müssen die Rites of the Earthmother bestehen, um ihren Wert zu beweisen, angestammte Traditionen zu ehren und die Wege des Landes zu lernen. Über Eure Riten hinaus steht Mulgore vor drohenden Gefahren, die seinen Frieden bedrohen: Aggressive Borstennacken-Stacheleber schwärmen durch die östlichen Schluchten, Bleichmähnen-Gnolle lauern in den Hügeln und die von Goblins geführte Venture Company entweiht heilige Wasserquellen und reißt für Erz in die Berge. Ob Ihr nun dem Ruf von Häuptling Falkenwind folgt oder Baine Bluthuf im Dorf der Bluthufe unterstützt, Eure Pflicht ist es, die Stämme zu schützen und die neue Heimat zu verteidigen.",al={"was mache ich hier","was sollte ich hier tun","was ist mein ziel in mulgore"}},dd86ecd9={q="Wer ist Cairne Bluthuf?",a="Cairne Bluthuf ist der ehrwürdige High Chieftain der vereinten Taurenstämme, Anführer der Bloodhoof und Herrscher über Donnerfels. Als unvergleichlicher Krieger und weiser Ältester verbündete Cairne sein Volk mit Thralls Horde und führte es durch gefährliche Kriege gegen die Zentauren, um auf den Tafelbergen eine dauerhafte Zuflucht zu gründen.",al={"cairne bluthuf hintergrundgeschichte","wer ist der high chieftain","tauren anführer"}},["96a44cf3"]={q="Ist Baine sein Sohn?",a="Ja, Baine Bluthuf ist Cairnes Sohn. Baine ist für seinen Mut im Kampf und seine diplomatische Zurückhaltung bekannt und führt als Häuptling das Dorf der Bluthufe im Herzen Mulg ores, während sein Vater ihn darauf vorbereitet, eines Tages das Amt des Oberhäuptlings zu übernehmen.",al={"ist baine cairnes sohn","baine bluthuf verwandtschaft","baine bluthuf"}}},fp="7,276,16.464.0,29.422.0,19.560.0,49.395.0,33.247.0,50.273.0,44.275.0,38.319.0,18.219.0"}
P.entries["zone:orgrimmar"] = {n="Orgrimmar",s="Aus den roten Schluchten im Norden Durotars erhebt sich Orgrimmar, die Festung der Orcs. Die Stadt ist das Herz von The New Horde. Trolle, Tauren und Verbündete der Verlassenen haben Schutz hinter ihren Mauern gefunden.",h="Aus den roten Schluchten im Norden Durotars erhebt sich Orgrimmar, die Festung der Orcs.",kw={"die kluft der schatten","the drag","durotar","grommash hold","orgrim schicksalshammer","orgrimmar","der flammenschlund","thrall","tal der geister","tal der stärke","tal der weisheit","kriegshäuptling"},ang={["class:Shaman"]="Als Schamane folgt Ihr Thralls Wiederbelebung des Schamanismus im Herzen der Horde-Führung. Im friedvollen Tal der Weisheit studieren die Schamanen die Elemente und stehen mit den Geistern der Ahnen in Verbindung.",["class:Warlock"]="Als Hexenmeister findet Ihr in der Kluft der Schatten einen unsicheren Zufluchtsort. Thrall behält Euch im Auge, während Ihr abgeschieden von öffentlicher Verurteilung Eure dunklen Künste verfeinert.",["faction:Horde"]="Als Champion der Horde findet Ihr Waffenmeister, Klassenmentoren und Handelsplätze in ihrem militärischen und kulturellen Zentrum. Auch Kriegshäuptling Thrall empfängt hier Besucher.",["race:Orc"]="Als Orc seht Ihr in Orgrimmar die hart erkämpfte Freiheit von dämonischer Trägheit und Internierung. Zugleich ist die Stadt die stolze Ahnenfestung Eures Volkes auf dem Boden Durotars.",["race:Troll"]="Als Dunkelspeertroll habt Ihr nach dem Verlust der Darkspear Isles an der Seite der Orcs dauerhafte Zuflucht gefunden. Das Tal der Geister ist Eure sichere spirituelle Heimat."},sec={{t="Ein aus Stein gehauenes Zuhause",b="Die Orcs kamen hierher, um eine Heimat zu finden. Nach dem Dritten Krieg führte Kriegshäuptling Thrall sie an die trockenen Küsten Kalimdors. Dort sollten sie endlich frei sein von dämonischer Verderbnis und menschlichen Ketten. Er nannte das Land nach seinem Vater Durotar. Die Stadt benannte er nach Orgrim Schicksalshammer, seinem gefallenen Mentor.\n\nDie Festung wurde mit Blut und Schweiß errichtet. Tauren standen an der Seite der Orcs, ebenso Dunkelspeertrolle und Gobliningenieure. Auch der Champion Rexxar kämpfte an ihrer Seite. Gemeinsam schlugen sie Zentauren, Harpyien und die wilden Donnerechsen der Schluchten zurück."},{t="Täler der Horde",b="Zerklüftete Berge umringen die Stadt. Sie halten sowohl fremde Feinde als auch Durotars schneidende Winde fern. Im Inneren öffnet sich der Fels zu Höhlen, und jedes Tal erfüllt eine eigene Aufgabe im Leben der Horde.\n\nIm Tal der Stärke steht das Torhaus. Von dort führt eine Straße tiefer hinein zum Markt von The Drag. Taurendruiden und Schamanen versammeln sich an den Teichen im Tal der Weisheit. Im Tal der Geister leben die Schattenjäger und Hexendoktoren der Dunkelspeere zwischen ihren Stelzenpavillons."},{t="Schatten im roten Fels",b="Unter dem Tal der Ehre und den Höhen von Grommash Hold regt sich ein anderes Leben unter Orgrimmar. Hexenmeister und Schurken üben in der Höhle namens Kluft der Schatten. Thrall behält sie genau im Auge und duldet ihre Künste nur widerwillig. Noch tiefer windet sich Der Flammenschlund durch vulkanische Tunnel unter dem Schluchtboden. Finsterer Kultisten und unterirdische Bestien wüten dort und bedrohen die Festung aus ihren eigenen Fundamenten heraus."}},faq={{q="Wer herrscht über Orgrimmar?",a="Kriegshäuptling Thrall herrscht von Grommash Hold aus über Orgrimmar. An seiner Seite führen Dunkelspeerhäuptling Vol'jin und der erfahrene Kommandant Varok Saurfang The New Horde. Dabei hat Thrall Ehre, Überleben und das schamanistische Erbe im Sinn.",al={"anführer von orgrimmar","wer herrscht über orgrimmar","aktueller kriegshäuptling"}},{q="Warum heißt die Stadt Orgrimmar?",a="Thrall benannte Orgrimmar nach Orgrim Schicksalshammer, dem legendären früheren Kriegshäuptling. Orgrim brach den Einfluss des Shadow Council auf die Old Horde und übergab Thrall vor seinem Tod im Kampf seine Kriegsrüstung und den Doomhammer.",al={"ursprung des namens orgrimmar","nach wem ist orgrimmar benannt"}},{q="Wer lebt außer Orcs in Orgrimmar?",a="Orgrimmar ist die Heimat des Dunkelspeerstamms, dessen Mitglieder im Tal der Geister leben. In der Stadt sind außerdem Taurenbotschafter im Tal der Weisheit willkommen. Auch eine Gruppe von Abgesandten der Verlassenen ist in der Stadt vertreten, nachdem sie sich vor Kurzem der Horde angeschlossen haben.",al={"völker in orgrimmar","wer lebt hier","trolle in orgrimmar"}},{q="Was ist die Kluft der Schatten?",a="Die Kluft der Schatten ist ein düsterer Felsspalt unter den Schluchtenhängen, abseits von The Drag. Die Schurken- und Hexenmeistergilden der Stadt haben dort ihr Zuhause. So bleiben illegaler Handel und gefährliche dämonische Beschwörungen vor den Wohnvierteln verborgen.",al={"die kluft der schatten","unterirdisches orgrimmar","hexenmeisterviertel von orgrimmar"}},{q="Welche Gefahren gibt es in der Stadt?",a="Der Flammenschlund liegt direkt unter der Kluft der Schatten. In seinen vulkanischen Spalten wimmelt es von Troggs, sengenden Elementaren und verräterischen Hexenmeistern, die Thralls Herrschaft aus der Tiefe untergraben wollen.",al={"gefahren in orgrimmar","bedrohung durch den flammenschlund","kultisten in orgrimmar"}},{q="Wie reist man von Orgrimmar auf andere Kontinente?",a="Von Türmen außerhalb des Haupttors Orgrimmars starten von Goblins konstruierte Zeppeline. Sie fliegen regelmäßig über Das große Meer nach Tirisfal, nahe der Unterstadt, und südwärts zum Basislager Grom'gol im Schlingendorntal.",al={"zeppelinflüge von orgrimmar","von orgrimmar nach tirisfal reisen","reisen von orgrimmar"}}},fx={["34960c6e"]={q="Was ist Orgrimmar?",a="Orgrimmar ist die Kriegerhauptstadt der Orcs und der primäre Sitz der The New Horde. Gehauenen in die hoch aufragenden roten Felsschluchten des nördlichen Durotar, steht sie als befestigtes Refugium, das von Kriegshäuptling Thrall nach dem Dritten Krieg erbaut wurde. Sie dient als Herz von Handel, militärischer Stärke und Kultur für Orcs, Dunkelspeere, Tauren und ihre Verbündeten, die Verlassenen.",al={"was ist das für eine stadt","überblick orgrimmar","über orgrimmar"}},["8dcd1cbd"]={q="Warum ist Orgrimmar hier draußen in der Wüste?",a="Thrall führte sein Volk bewusst in die rauen, sonnenverbrannten Lande von Durotar, um sich durch Arbeit und Beharrlichkeit eine Heimat zu schaffen. Der rote Boden und die schroffen Felsen erinnerten die Orcs an ihre angestammte Heimat Draenor, während sie natürliche Verteidigungstäler und Schluchten boten, um ihre hart erkämpfte Unabhängigkeit zu schützen.",al={"warum bauen in durotar","warum steht die stadt in einer wüste","warum hier siedeln"}},["2df9c1bd"]={q="Wo ist Thrall?",a="Thrall hält Hof innerhalb von Grommash Hold, hoch oben im Tal der Weisheit gelegen. Vor seiner kalten Steinfestung steht ein alter Baumstamm, der den zertrümmerten Schädel und die Rüstung von Mannoroth zeigt – ein klares Denkmal zu Ehren von Grom Höllschreis Opfer und der Befreiung der Horde von dämonischer Verderbnis.",al={"wo findet man thrall","aufenthaltsort von thrall","wo ist der kriegshäuptling"}},["6bde2c20"]={q="Wer ist Nazgrel?",a="Nazgrel ist ein erfahrener Orc-Krieger und vertrauenswürdiger Leutnant, der Thrall direkt innerhalb von Grommash Hold dient. Er ist dem Kriegshäuptling fest ergeben und hilft, die Verteidigung und die militärische Einsatzbereitschaft der Stadt an der Seite des Oberkommandos der Horde zu beaufsichtigen.",al={"wer ist dieser krieger bei thrall","rolle von nazgrel","thrall-berater nazgrel"}},["19245cb0"]={q="Ist Orgrimmar gefährlich?",a="Während die hoch aufragenden Tore und erfahrenen Grunzer der Stadt Eindringlinge fernhalten, lauern im Inneren immer noch Gefahren. Hinterhältige Kultisten und Schurken-Zirkel treiben ihr Unwesen in den schattigen Abgründen unter den Klippen, wilde Razorwinds fegen durch die Täler und beschädigen unachtsame Konstruktionen, und der unterirdische Der Flammenschlund strotzt nur so vor Troggs und dunkler elementarer Verderbnis direkt unter den Straßen.",al={"ist es hier sicher","orgrimmar gefahr","gefahren in orgrimmar"}},f5c45f78={q="Was ist in Orgrimmar passiert?",a="Nach dem Dritter Krieg führte Thrall die Orcs nach Kalimdor, um der dämonischen Verderbnis zu entkommen, die ihr Volk zerrüttet hatte. Mit Hilfe der Tauren, Trolle und Rexxar meißelten sie diese Festung aus den Canyons von Durotar, während sie einheimische Stacheleber, Zentauren und Harpyien bekämpften, und verwandelten so ein karges Grenzland in die dauerhafte Zitadelle der The New Horde.",al={"orgrimmar geschichte","vergangenheit von orgrimmar","wie wurde orgrimmar gegründet"}},f55ec44b={q="Wie bin ich in Orgrimmar gelandet?",a="Wenn Ihr ein Orc oder ein Dunkelspeer-Troll seid, seid Ihr dem Ruf Eurer Ältesten gefolgt. Nachdem Ihr Euch in den Prüfungen von Durotar bewiesen habt, wiesen Euch Eure Ausbilder den Weg nach Norden entlang der roten Lehmstraßen, damit Ihr die großen befestigten Tore der Hauptstadt passieren konntet. Wenn Ihr von weit her gekommen seid – als Tauren aus den Ebenen von Mulgore oder als Verlassene-Reisender, der das große Meer mit einem Zeppelin von Tirisfal aus überquert hat –, dann seid Ihr im Herzen der The New Horde angekommen, dem Ruf von Kriegshäuptling Thrall folgend, um ihre verstreuten Völker unter einem Banner zu vereinen.",al={"wie kam ich hierher","wie bin ich hier angekommen","warum kam ich nach orgrimmar"}},["07461c2e"]={q="Was soll ich in Orgrimmar tun?",a="Ihr seid hier, um Euer Handwerk zu verfeinern, Euch bei Euren Anführern zu melden und die wachsende Horde zu unterstützen. Sucht die Klassenlehrer und Berufslehrer in den Tälern der Stadt auf, handelt an den Auktionshäusern oder stellt Euch Kriegshäuptling Thrall in Grommash Hold vor. Das junge Reich ist von Bedrohungen umgeben – von Zentauren-Kriegstrupps und Stacheleber-Plünderern, die über die Grenzen eindringen, bis hin zu niederträchtigen Kultisten, die sich in den unterirdischen Tiefen von Der Flammenschlund verstecken. Beweist Euren Wert bei der Verteidigung Eurer Verbündeten.",al={"was soll ich hier tun","warum bin ich hier","was ist meine aufgabe in orgrimmar"}},["2f0bb5cb"]={q="Wer hat Orgrimmar erbaut?",a="Kriegshäuptling Thrall und seine Orcs gründeten die Festung kurz nach der Schlacht am Hyjal und stellten sie in bemerkenswert kurzer Zeit fertig. Dabei halfen ihnen die gerissenen Dunkelspeertrolle, die edlen Tauren aus Mulgore, Goblinarbeiter und Ingenieure sowie Rexxar, der umherwandernde Halb-Oger und Bestienmeister.",al={"wer hat orgrimmar erbaut","wie wurde orgrimmar erbaut","bau von orgrimmar"}}},fp="9,189,26.559.0,20.491.0,23.432.1,20.206.0,32.211.0,36.267.0,28.236.0,35.193.0,53.213.0"}
P.entries["zone:ragefire"] = {n="Der Flammenschlund",s="Unter Orgrimmar bedrohen Troggs und ein Dämonenkult die junge Horde. Die Searing Blade schmiedet Pläne in Vulkankavernen unter der Kluft der Schatten, während darüber die Hauptstadt liegt.",h="Unter Orgrimmar bedrohen Troggs und ein Dämonenkult die junge Horde.",kw={"bazzalan","schlund","die kluft der schatten","jergosh","neeru fireblade","orgrimmar","flammenschlund","searing blade","taragaman"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr die dunkle Magie der Searing Blade in den Ritualen und Dämonenfolianten von Jergosh dem Herbeirufer und Bazzalan aus nächster Nähe erleben.",["faction:Horde"]="Für die Horde bietet die Säuberung des Schlunds unter Orgrimmar jungen Champions eine Kraftprobe und die Gelegenheit, die Hauptstadt zu schützen.",["race:Tauren"]="Als Tauren wisst Ihr, dass Maur Grimmtotems Tod durch die Ragefiretroggs die Jagd auf die Bestien zu einer Frage der Ehre und Vergeltung für Donnerfels macht."},sec={{t="Gefahr aus der Tiefe",b="Ragefiretroggs brechen tief unter Orgrimmar hervor und dringen in gewundene Vulkangänge und Lavagruben ein. Während orcische Baumeister oben ihre neue Heimat errichten, werden die Troggs immer aggressiver. Magatha Grimmtotem schickt Maur Grimmtotem als Gesandten von Donnerfels, doch die Troggs schalten ihn ab. Sie weichen nur der Gewalt."},{t="Die Searing Blade",b="Die Searing Blade, ein Dämonenkult, ist eine größere Gefahr als die Troggs. Ihre Fanatiker sind dem Schattenrat treu ergeben und schmieden in Kavernen neben Magmaströmen Pläne zum Untergang der jungen Horde. Jergosh der Herbeirufer, ein listiger Hexenmeister, führt den Kult gemeinsam mit Bazzalan, einem Satyr, und Taragaman der Hungerleider, einer grausamen Teufelswache. Taragaman wacht über einen Altar im Lavasee."},{t="Das Spiel des Kriegshäuptlings",b="Neeru Feuerklinge scheint Hexenmeister neben dem Eingang des Schlunds in der Kluft der Schatten auszubilden. Heimlich führt er dort die Burning Blade an. Er schickt Abenteurer der Horde als Loyalitätsprüfungen in die Tiefe und hofft, schwache Kultisten auszusortieren und Thralls Unterstützer zu töten.\n\nThrall weiß von Neerus Täuschung. Der Kriegshäuptling nutzt diese Vorstöße, um gefährliche Kultführer wie Jergosh und Bazzalan auszuschalten. Neeru lässt er an Ort und Stelle, damit er die weitreichenderen Pläne des Schattenrats überwacht."}},faq={{q="Wo befindet sich der Eingang zum Flammenschlund?",a="Der Eingang liegt in Orgrimmar, im unterirdischen Stadtteil Kluft der Schatten. Er befindet sich nahe Neeru Fireblades Zelt, des Hexenmeisterlehrers.",al={"lage des flammenschlunds","wo liegt der flammenschlund?","eingang zum flammenschlund"}},{q="Warum gibt es Troggs unter Orgrimmar?",a="Ragefiretroggs gruben sich aus unterirdischen Hohlräumen unter Durotar nach oben. Diplomatie konnte ihr plötzliches Auftauchen unter der Hauptstadt nicht eindämmen. Dort stellen sie eine große Gefahr dar.",al={"herkunft der ragefiretroggs","warum gibt es hier troggs?","troggs in orgrimmar"}},{q="Wer führt die Kultisten im Schlund an?",a="Jergosh der Herbeirufer, ein Hexenmeister, und Bazzalan, ein Satyr, führen die Searing Blade an. Taragaman der Hungerleider, eine herbeigerufene Teufelswache, unterstützt sie.",al={"bosse im flammenschlund","anführer der searing blade","wer herrscht im flammenschlund?"}},{q="Was bewirkt der Tod von Bazzalan und Jergosh für die Geschichte?",a="Der Tod von Bazzalan und Jergosh zerschlägt die aktive Führung der Searing Blade unter Orgrimmar. Ihr Tod zeigt die Widerstandskraft der Horde und ermöglicht Thrall, eine Dämonen anbetende Zelle unter seinem Thron zu vereiteln.",al={"bedeutung der bazzalan-lore","warum bazzalan töten?","ausgang von hidden enemies"}},{q="Können Abenteurer der Allianz den Flammenschlund betreten?",a="Jeder Abenteurer kann durch das Portal hineingehen. Ein Abenteurer der Allianz muss hochstufigen Wachen der Horde und feindseligen Verteidigern in ganz Orgrimmar ausweichen, um die Kluft der Schatten zu erreichen.",al={"kann die allianz den flammenschlund besuchen?","allianz im flammenschlund"}},{q="Warum lässt Thrall Neeru Feuerklinge nicht einfach hinrichten?",a="Thrall duldet jene, die in der Kluft der Schatten dunkle Magie praktizieren. Er behält sie in seiner Nähe und unter seiner Aufsicht, statt sie aus seinem Blickfeld zu vertreiben.",al={"thrall und neeru fireblade","warum lässt man neeru leben?"}}},fx={f4fa764c={q="Was ist Der Flammenschlund?",a="Der Flammenschlund ist ein unterirdisches Netzwerk aus feurigen vulkanischen Kavernen, das direkt unter der Orc-Hauptstadt Orgrimmar verläuft. Während es sich direkt unter den belebten Straßen darüber befindet, beherbergen seine geschmolzenen Tiefen bösartige Troggs und eine versteckte Kabale von Searing Blade-Kultisten, die gegen die Horde intrigieren.",al={"was ist der flammenschlund","über den flammenschlund","rfc hintergrundgeschichte"}},["947efccf"]={q="Warum gibt es eine Höhle unter Orgrimmar?",a="Die Kavernen bildeten sich auf natürliche Weise als vulkanisches Netzwerk innerhalb der felsigen Erde unter Durotar. Als die Orcs diesen verteidigungsfähigen Canyon wählten, um Orgrimmar zu errichten, lag der feurige Schlund bereits unter der Erde, ausgehöhlt von uralten unterirdischen Magmaströmen.",al={"warum eine höhle unter orgrimmar","wie entstand der flammenschlund","höhlen unter orgrimmar"}},["9252a3ac"]={q="Haben die Orcs sie ausgegraben?",a="Nein. Die Orcs haben Der Flammenschlund nicht ausgehoben. Es war bereits ein natürliches Labyrinth aus geschmolzenem Gestein und Lavaschloten, lange bevor Thrall sein Volk dazu führte, sich in Durotar niederzulassen und die Mauern von Orgrimmar darüber zu errichten.",al={"haben orcs rfc gegraben","hat die horde den flammenschlund gegraben"}},b0dedca2={q="Warum hat Thrall mich hierher geschickt?",a="Thrall entdeckte Gerüchte über Kultistenaktivitäten, die direkt unter seiner Stadt schwärten. Anstatt einen offenen militärischen Überfall zu starten, der die Verräter alarmieren würde, entsandte er vielversprechende Abenteurer in die Tiefen, um die Bedrohung zu untersuchen und die schattenhaften Anführer der Searing Blade zu eliminieren.",al={"warum schickte thrall mich in den rfc","grund für thralls rfc quest","warum bin ich im flammenschlund"}},["0d5305cc"]={q="Wer ist Thrall?",a="Thrall ist der Kriegshäuptling der Horde und Gründer der Nation Durotar. Geboren als Go'el, Sohn des Häuptlings Durotan vom Frostwolfklan, entkam er der menschlichen Knechtschaft und den Gladiatorenarenen, um die zersplitterten Orc-Klane zu vereinen, ihr vergessenes schamanisches Erbe wiederzubeleben und eine neue, ehrenhafte Horde zu schmieden.",al={"wer ist kriegshäuptling thrall","thrall hintergrundgeschichte","wer ist thrall"}},["09eb01d5"]={q="Wie wurde er Kriegshäuptling?",a="Thrall kämpfte an der Seite von Orgrim Schicksalshammer, um nach dem Zweiter Krieg inhaftierte Orcs aus den Internierungslagern der Allianz zu befreien. Als Schicksalshammer im Kampf fiel, vermachte er seine legendäre schwarze Rüstung und seinen Kriegshammer an Thrall und ernannte ihn zum neuen Kriegshäuptling, der ihr Volk nach Kalimdor führen sollte.",al={"wie thrall kriegshäuptling wurde","ursprung von thralls führung","wie bekam thrall schicksalshammer"}},c23e3fbc={q="Ist Thrall ein Schamane?",a="Ja. Geleitet von den Geistern und dem alten Eremiten Drek'Thar vom Frostwolfklan, wurde Thrall der erste neue Orc-Schamane seit einer Generation, der die korrumpierende dämonische Teufelsmagie, die einst seine Rasse versklavt hatte, zugunsten der Harmonie mit den Elementen ablehnte.",al={"ist thrall schamane","thralls klasse","kann thrall zaubern"}},["833fd6a3"]={q="Was sind die Hidden Enemies, von denen Thrall spricht?",a="Die Hidden Enemies sind dämonische Kultisten und Sympathisanten, die heimlich in Durotar leben und planen, Thralls junge Gesellschaft zu stürzen. Sie operieren aus dem Schatten und versteckten Tunneln heraus, dienen dunklen Mächten aus der Vergangenheit der Orcs und untergraben aktiv den Frieden der Horde von innen heraus.",al={"hidden enemies thrall","wer sind die hidden enemies","was sind die hidden enemies"}},["606e7173"]={q="Warum gibt es Dämonen unter Orgrimmar?",a="Die Kultisten der Searing Blade brachten Dämonen wie Taragaman der Hungerleider in die Tiefen, um ihre dunklen Rituale zu verankern. Sie lauern unter Die Kluft und nutzen dämonische Macht, um unvorsichtige Bürger anzulocken und Initianden zu prüfen, die der Brennende Legion dienen wollen.",al={"dämonen im flammenschlund","warum dämonen unter orgrimmar","taragaman im rfc"}},["0ca922e2"]={q="Was ist der Schattenrat?",a="Der Schattenrat war eine geheime Kabale von Hexenmeistern, die ursprünglich auf Draenor von Gul'dan gegründet wurde, um die Orc-Klane zu manipulieren und sie an die Brennende Legion zu binden. Obwohl sie während des Erster Krieg und Zweiter Krieg zerschlagen wurde, arbeiten verbliebene Sekten wie die Burning Blade weiterhin auf die Ziele ihrer dämonischen Meister hin.",al={"schattenrat hintergrundgeschichte","was ist der schattenrat","geschichte des schattenrats"}},be4be4e7={q="Was sind die Ragefire-Troggs?",a="Die Ragefire-Troggs sind ein gewalttätiger, unterirdischer Klan von primitiven Troggs, die die oberen Bereiche des Schlunds befallen. Barbarenhaft und aggressiv brechen sie aus unterirdischen Spalten in die Kavernen ein und greifen sofort jeden an, der ihr Territorium betritt.",al={"ragefire-troggs","was sind die troggs im rfc","rfc troggs"}},["608f7b0a"]={q="Warum ich, ich bin doch noch kein Held?",a="Thrall kann seine Elite-Kor'kron-Wachen nicht einsetzen, ohne die Verschwörer zu alarmieren und sie tiefer in den Untergrund zu treiben. Indem er eifrige neue Abenteurer einsetzt, unternimmt er einen leisen, abstreitbaren Schlag, der die unmittelbaren Leutnants des Kults eliminiert, während er seine eigenen Gegenuntersuchungen diskret hält.",al={"warum schickte man mich in den rfc","warum abenteurer für ragefire","warum ich ragefire"}},cbc9ae06={q="Was passiert, nachdem ich den Hexenmeister und den Satyr getötet habe?",a="Sobald Jergosh der Herbeirufer und Bazzalan gefallen sind, sind ihre Pläne im Schlund gelähmt. Ihr meldet Euren Triumph an Thrall zurück, der die Existenz eines größeren Netzwerks des Verrats bestätigt, das über die Kavernen hinaus in die Welt an der Oberfläche reicht.",al={"nach dem töten von bazzalan und jergosh","jergosh getötet nächster schritt","was tun nach rfc"}},e02585d8={q="Führt das zurück zu Thrall?",a="Ja. Thrall erwartet, dass Ihr Euch direkt in seinem Thronsaal im Tal der Weisheit meldet. Die Tötung der Feldkommandanten des Kults beweist Eure Loyalität und informiert den Kriegshäuptling über das wahre Ausmaß der Subversion, die direkt unter seinen Füßen braut.",al={"führt rfc zurück zu thrall","rückkehr zu thrall nach rfc","bericht an thrall"}},["02870934"]={q="Wie bin ich in Der Flammenschlund gelandet?",a="Ihr seid durch die schattigen Tunnel unter Orgrimmar in Die Kluft hinabgestiegen, wo sich die Ausgestoßenen der Stadt und dunklere Praktizierende versammeln. Neben dem Zelt des Hexenmeisters Neeru Feuerklinge liegt die tiefste Schwelle der Kluft: ein rauchender Torbogen, der direkt in das vulkanische Unterinnere von Durotar führt. Ob von Kriegshäuptling Thrall hierher geschickt, um versteckte Verräter aufzuspüren, von Tauren-Gesandten aus Donnerfels entsandt oder von dunklen Flüsterern hierher gelenkt, die Eure Standhaftigkeit prüften – Ihr seid durch dieses Tor in die unterirdischen Magmatunnel gegangen.",al={"wie kam ich hierher","wie kam ich zum flammenschlund","warum bin ich in diesen kavernen"}},["9382a7ef"]={q="Was soll ich in Der Flammenschlund tun?",a="Ihr seid hier, um eine schwärende Fäulnis zu beseitigen, die das Herz der Horde bedroht. In diesen vulkanischen Kavernen haben sich wilde Troggs aus den Tiefen nach oben gekrallt, lehnen Frieden gewaltsam ab und schlachten Gesandte ab. Schlimmer noch, die Searing Blade – ein verdeckter Splitter des dämonischen Schattenrats – plant Orgrimmars Ruin aus der Dunkelheit. Eure Pflicht ist es, Euch durch die Troggs zu schneiden, den bulligen Teufelswache Taragaman der Hungerleider zu konfrontieren und die sterblichen Kommandeure des Kults, Jergosh der Herbeirufer und den Satyr Bazzalan, zu eliminieren und ihr unterirdisches Netzwerk zu zertrümmern, bevor es die Stadt darüber überrennt.",al={"was mache ich hier","was ist mein ziel in ragefire","warum wurde ich hierher geschickt"}}},fp="14,165,18.299.0,17.349.0,19.465.1,40.152.0,31.176.0,40.138.0,64.199.1,46.186.0,50.149.1"}
P.entries["zone:razorfenkraul"] = {n="Kral der Klingenhauer",s="Im äußersten Süden des Brachlands verteidigen Borstennacken das heilige Dornengestrüpp des Kral der Klingenhauer. Sie verehren das Dickicht als Ruhestätte ihres Ahnen Agamaggan, während Charlga Klingenflankes Herrschaft die Region bedroht.",h="Im äußersten Süden des Brachlands verteidigen Borstennacken das heilige Dornengestrüpp des Kral der...",kw={"agamaggan","brachland","charlga","halmgar","kral","borstennacken","ramtusk","razorfen","klingenflanke","geißel"},ang={["class:Shaman"]="Als Schamane erkennt Ihr, wie die Geomantie der Borstennacken Erde und Elemente rund um Agamaggans Blut verdreht und Urkräfte für wilde Zwecke einsetzt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Versorgungskarren und junge Siedlungen im südlichen Brachland zu schützen, indem Ihr die Aggression des Kral der Klingenhauer eindämmt.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Borstennacken seit Langem um die Grenzen Mulgors streiten. Ihre dunklen Bündnisse und die Schändung der Erde machen den Kral der Klingenhauer zu einer Frage des Stammesverteidigung.",["race:Undead"]="Als Untoter interessiert Ihr Euch vielleicht für seltsame Reagenzien, Fledermausguano und Berichte über Vorstöße der Geißel zwischen den Dornenranken."},sec={{t="Blut des Ebergottes",b="Vor zehntausend Jahren kämpfte Agamaggan im Krieg der Ahnen gegen die Brennende Legion. Der kolossale wilde Gott fiel, doch sein Opfer bewahrte das Leben auf Azeroth. Legenden erzählen, dass überall dort, wo sein Blut in die Erde drang, dornenbedeckte Ranken emporwuchsen und dichte Wehrwälle in den südlichen Ebenen bildeten. Die Borstennacken verehren Agamaggan als ihren göttlichen Ahnen und beanspruchen das Dickicht als heiligen Boden. Die größten unter ihnen wurden zum Razorfen."},{t="Die Ambitionen der Greisin",b="Charlga Klingenflanke herrscht mit despotischer Gewalt über den Kral der Klingenhauer. Unter der Ältestengreisin haben die schamanistischen Borstennacken ihre üblichen Scharmützel beigelegt und greifen nun gemeinsam rivalisierende Stämme, regionale Handelswege und junge Siedlungen der Horde an. Gerüchte und Späherberichte sprechen von untoten Unholden, die nahe dem Dornengestrüpp umherstreifen. Charlga verhandelt möglicherweise mit Abgesandten der Geißel und hofft, ihren Stamm mit verbotener Nekromantie zu stärken."}},faq={{q="Was ist der Kral der Klingenhauer?",a="Der Kral der Klingenhauer ist ein weitläufiges Gewirr aus dornigen Ranken im südlichen Brachland. Die Borstennacken betrachten ihn als ihr spirituelles Zentrum und ihre Heimat der Ahnen.",al={"was ist rfk","kral der klingenhauer erklärt","überblick zum kral der klingenhauer"}},{q="Wie entstanden die riesigen Dornen?",a="Die gewaltigen Dornengestrüppe wuchsen vor zehntausend Jahren während des Krieges der Ahnen aus der Erde, dort, wo das Blut des gefallenen Eberhalbgotts Agamaggan vergossen wurde.",al={"warum gibt es riesige dornen","woher stammt das dornengestrüpp","agamaggans dornen"}},{q="Wer herrscht über den Kral der Klingenhauer?",a="Charlga Klingenflanke, eine erbarmungslose Greisin und Schamanin der Borstennacken, herrscht über den Kral der Klingenhauer. Sie befehligt den Stamm der Razorfen und führt Angriffe auf benachbarte Dörfer und Reisende.",al={"wer ist der boss von rfk","charlga klingenflanke","greisin des krals"}},{q="Warum sorgt sich die Horde um den Kral der Klingenhauer?",a="Angriffe der Borstennacken bedrohen junge Siedlungen der Horde im Brachland, und Späher haben Untote nahe dem Dickicht gesehen. Ihre Anwesenheit weckt die Befürchtung, dass Charlga mit der Geißel zusammenarbeitet.",al={"warum interessiert sich die horde dafür","interesse der horde an rfk","bedrohung im brachland"}},{q="Warum interessieren sich Truppen der Allianz für den Kral?",a="Charlgas Stamm bedroht Außenposten nahe Feralas und Tausend Nadeln. Befehlshaber und Späher der Allianz in Thalanaar wollen sie besiegen, um die Grenze zu sichern.",al={"allianzquests für rfk","warum geht die allianz hierher","thalanaar quest"}},{q="Was bedeutet die Niederlage von Earthcaller Halmgar für die Geschichte?",a="Earthcaller Halmgar ist ein seltener und einflussreicher Geomant tief im Dickicht. Seine Niederlage schwächt die Erdformungspriester der Borstennacken, stört Charlga Klingenflankes Verteidigung und mindert ihre Macht, Agamaggans heiliges Dornengestrüpp zu formen.",al={"was passiert nach earthcaller halmgars tod","hintergrund zu earthcaller halmgar","halmgar besiegt"}}},fx={["59c8bcc4"]={q="Wer hat all diese Dornen im Kral der Klingenhauer erschaffen?",a="Niemand hat sie von Hand erschaffen. Vor zehntausend Jahren, während des Krieges der Ahnen, fiel der kolossale Eberhalbgott Agamaggan im Kampf gegen die Brennende Legion. Wo sein göttliches Blut in den Boden sickerte, brachen massive, undurchdringliche, dornenbewachsene Gebüsche aus der Erde hervor und bildeten das labyrinthartige Dickicht, das Ihr heute seht.",al={"wer hat die dornen erschaffen","wer baute die dornen","ursprung der dornen im kral der klingenhauer"}},["4843f165"]={q="Was sind Stacheleber?",a="Stacheleber sind primitive, aggressive, eberähnliche Humanoide, die in Kalimdor beheimatet sind. Sie haben muskulöse, gebeugte Rücken, die mit scharfen, defensiven Stacheln übersät sind. Es wird angenommen, dass sie die sterblichen Nachkommen des Halbgottes Agamaggan sind; sie verehren seine Ruhestätten und verteidigen ihre dornigen Gebiete erbittert gegen alle Außenstehenden.",al={"was sind stacheleber","wer sind die stacheleber","stacheleber hintergrundgeschichte"}},ea4583b3={q="Warum leben die Stacheleber in einem riesigen Dornenlabyrinth?",a="Das Dornenlabyrinth ist direkt aus dem Blut ihres gefallenen Gottes Agamaggan hervorgegangen. Für die Stacheleber ist der Kral der Klingenhauer heiliger Boden und seine tatsächliche Ruhestätte. Das Gestrüpp bietet ihnen sowohl heilige Verehrung als auch natürliche, nahezu undurchdringliche Festungen gegen ihre regionalen Feinde.",al={"warum in dornen leben","warum leben stacheleber hier","stacheleber dornenlabyrinth"}},b1fd1d2b={q="Ist Charlga Klingenflanke die Anführerin aller Stacheleber?",a="Nicht aller Stacheleber, aber sie beherrscht den mächtigen Stamm der Klingenhauer, der sich im Kral verschanzt hat. Als gerissene Matrone und Geomantin vertrieb sie die dortigen Tauren aus dem südlichen Brachland und übt weitreichende Autorität aus, obwohl rivalisierende Stacheleberstämme, die über ganz Kalimdor verstreut sind, sich selbst regieren.",al={"charlga klingenflanke anführerin","wer führt alle stacheleber an","hat charlga das sagen über alle"}},["8ed48c28"]={q="Wer ist Agathelos der Tobende?",a="Agathelos ist ein massiver, wilder Eber, der im Kral der Klingenhauer haust. Stacheleber verehren Eber als lebende Symbole ihres Gottes Agamaggan und betrachten besonders große und beharrliche Bestien wie Agathelos als direkte Segnungen und heilige Manifestationen der ursprünglichen Macht des Großen Ebers.",al={"wer ist agathelos","hintergrundgeschichte von agathelos der tobende","agathelos rieseneber"}},["4f663063"]={q="Spioniert die Horde auch im Kral der Klingenhauer herum?",a="Ja. Die Plünderer von Charlga Klingenflanke verüben ständig brutale Angriffe auf Siedlungen der Horde im gesamten Brachland und haben die Tauren aus ihren angestammten südlichen Gebieten vertrieben. Sowohl die Orcs als auch die Tauren entsenden aktiv Krieger, um die Macht der Matrone zu brechen und die Bedrohung durch die Stacheleber zu beenden.",al={"ist die horde hier","präsenz der horde im kral der klingenhauer","horde im kral der klingenhauer"}},["5328604f"]={q="Wer ist Agamaggan?",a="Agamaggan, der Große Eber, war ein Uralter Wächter und einer der ersten und mächtigsten Wilden Götter, die Azeroth durchstreiften. Die Stacheleber verehren ihn als ihren Schöpfer, huldigen seinem Andenken und beziehen spirituelle sowie geomantische Kraft aus seinem Blut und den riesigen Dornenclustern, die aus seinem Opfer hervorgegangen sind.",al={"wer ist agamaggan","agamaggan der große eber","agamaggan hintergrundgeschichte"}},bc4e6730={q="Starb Agamaggan im Krieg der Ahnen?",a="Ja. Vor zehntausend Jahren folgte Agamaggan dem Ruf von Cenarius, Azeroth vor der Brennende Legion zu verteidigen. Er wütete über den Kontinent und zermalmte Tausende von Dämonen, bevor er schließlich im Kampf gegen eine überwältigende dämonische Armee fiel und sein Leben opferte, damit Malfurion Sturmgrimm den Brunnen der Ewigkeit erreichen konnte.",al={"wie starb agamaggan","agamaggan krieg der ahnen","ist agamaggan gestorben"}},e47b7687={q="Verehren die Stacheleber Agamaggan immer noch?",a="Das tun sie, mit fanatischer Hingabe. Schamanen und Geomanten der Stacheleber beten zu Agamaggan um Stärke im Kampf, verehren riesige Eber als seinen Segen und horten Blutedelsteine, die aus seinem versteinerten Blut geformt wurden. Sie glauben, dass seine physischen Überreste sie und ihre heilige Heimat beschützen.",al={"verehren die stacheleber noch immer agamaggan","stacheleber religion","verehrung von agamaggan"}},["7583b13a"]={q="Wer sind die Typen vom Totenschädel?",a="Der Totenschädel ist eine militante Fraktion der Stacheleber, die auf dem Schlachtfeld von Oberanführer Rammhauer angeführt wird und an der Seite des Stammes der Klingenhauer operiert. Rammhauer leitet ihre disziplinierten, kampferprobten Truppen an, um das Dornenlabyrinth fest im Griff zu halten und bösartige Kriege gegen ihre Nachbarn zu führen.",al={"stamm des totenschädels","wer sind die vom totenschädel","totenschädel-stacheleber"}},["4bc36485"]={q="Werden die Stacheleber hier Siedlungen im Brachland angreifen?",a="Das tun sie bereits. Unter dem Kommando der Matrone Charlga Klingenflanke schwärmen aggressive Plünderer ständig aus den Dornen in die umliegenden Ländereien aus. Sie haben Reisende in der Nähe des großen Aufzugs belästigt, rivalisierende Stämme überfallen und Siedlungen sowie Karawanen der Horde an den Rand eines offenen Krieges gedrängt.",al={"werden stacheleber das brachland angreifen","brachland unter angriff durch stacheleber","stacheleber-überfälle im brachland"}},ed4c33ec={q="Was ist der Unterschied zwischen dem Kral und den Hügeln?",a="Beide sind massive Dornennetzwerke, die durch den Fall von Agamaggan entstanden sind, aber sie erfüllen unterschiedliche Rollen. Kral der Klingenhauer ist das angestammte Herz, wo Charlga Klingenflanke lebende Stacheleberplünderer versammelt. Hügel der Klingenhauer, weiter südöstlich in der Nähe des riesigen skelettierten Mauls des Halbgottes gelegen, ist unter den dunkleren Einfluss der Geißel gefallen.",al={"unterschied zwischen kral und hügeln","kral der klingenhauer gegen hügel der klingenhauer","kral oder hügel"}},["974f5634"]={q="Ist die Geißel im Kral der Klingenhauer involviert?",a="Ja. Beunruhigende Berichte und abgefangene Schreiben enthüllen, dass Charlga Klingenflanke begonnen hat, mit Agenten der Geißel zu verhandeln. Späher haben Untote in der Nähe des Kral der Klingenhauer gesichtet, was die ernste Sorge aufkommen lässt, dass die Schergen des Lichkönigs versuchen, durch diese ahnungslosen Stämme einen Fuß auf Kalimdor zu fassen.",al={"geißel im kral der klingenhauer","gibt es untote im kral der klingenhauer","präsenz der geißel im kral"}},a384c7af={q="Wer ist Amnennar?",a="Amnennar der Kältebringer ist ein mächtiger Agent der Geißel, der sich in den benachbarten Hügel der Klingenhauer niedergelassen hat. Er arbeitet hinter den Kulissen, manipuliert die Führung der Stacheleber und befehligt die Streitkräfte des Totenschädels, um das südliche Gestrüpp in eine Festung der Untoten zu verwandeln.",al={"wer ist amnennar","amnennar der kältebringer","amnennar hintergrundgeschichte"}},af015f4e={q="Wie bin ich im Kral der Klingenhauer gelandet?",a="Ihr seid in die südlichsten Ausläufer des Brachlandes gereist, in die Nähe der hoch aufragenden Klippen mit Blick auf Tausend Nadeln. Während Ihr Euch durch das umkämpfte Buschland vorkämpftet, fandet Ihr das riesige Dickicht aus blutgenährtem Gestrüpp, das aus dem Kadaver des uralten Eber-Gottes Agamaggan entsprang. Direkt in diese massiven, versteinerten Dornenranken gehauen liegt der westliche Eingang zum Kral, wo Verteidiger der Stacheleber den Zugang gegen jeden bewachen, der es wagt, in ihr heiliges Territorium einzudringen.",al={"wie bin ich hierher gekommen","wie erreicht man den kral der klingenhauer","wo ist der kral der klingenhauer"}},["141f6ea5"]={q="Was soll ich im Kral der Klingenhauer tun?",a="Ihr seid hier, um die feindselige Macht des Stammes der Klingenhauer zu brechen und ihre aggressive Expansion über das Brachland aufzuhalten. Unter der Führung ihrer Matrone Charlga Klingenflanke haben diese fanatischen Stacheleber ihre gewaltsamen Übergriffe auf benachbarte Siedlungen und Karawanen verstärkt. Euer Ziel ist es, Euch durch die verschlungenen Dornengänge zu kämpfen, die Führung des Totenschädels zu zerschmettern und Charlga zur Strecke zu bringen, bevor ihre dunkle Geomantie und ihre mutmaßlichen Geschäfte mit finsteren Mächten der Untoten einen umfassenden Krieg entfachen.",al={"was ist meine mission hier","warum bin ich im kral der klingenhauer","was mache ich hier"}}},fp="14,218,21.427.0,20.423.1,23.142.0,34.156.0,25.170.0,48.182.0,48.157.0,59.248.0"}
P.entries["zone:redridge"] = {n="Rotkammgebirge",s="Das Rotkammgebirge wird nun von Schattenfellgnollen und Schwarzfelsorcs der Dunklen Horde angegriffen. Reißende Flüsse durchziehen die bewaldeten Hänge rund um den Immerruhsee, während Seenhain mit umherziehenden Söldnern die Stellung hält und Sturmwinds Truppen mit Unruhen in der Heimat ringen.",h="Das Rotkammgebirge wird nun von Schattenfellgnollen und Schwarzfelsorcs der Dunklen Horde angegriffen.",kw={"schwarzfelsorcs","der immerruhsee","seenhain","magistrat solomon","marschall marris","rotkammgebirge","renders tal","schattenfell","steinwacht","burg steinwacht","verner gutmark"},ang={["faction:Alliance"]="Als Soldat der Allianz könnt Ihr in Seenhain Eure Fähigkeiten schärfen. Der Ort ist ein Außenposten an der Front und muss sich organisierten Orcs und Gnollen stellen.",["faction:Horde"]="Die im Rotkammgebirge verschanzen Schwarzfelsorcs gehören zur feindseligen Dunklen Horde. Sie sind Feinde von Thralls Horde ebenso wie der Menschen in Seenhain.",["profession:Herbalism"]="An den gemäßigten Berghängen gedeihen Wilddornrose, Beulengras, Maguskönigskraut und Flitzdistel.",["profession:Mining"]="In den felsigen Klüften und Tälern rund um den Immerruhsee findet Ihr Kupfer, Zinn und seltene Silberadern, besonders nahe den Rethbanhöhlen."},sec={{t="Eine belagerte Bastion",b="Das Rotkammgebirge gehörte einst zu den friedlichsten Regionen des Königreichs. Seine Wälder lieferten Sturmwind Bauholz, während seine Gewässer und Felder das Königreich mit Fisch und Feldfrüchten versorgten. Nun ist Seenhain gegen wiederholte Angriffe befestigt. Burg Steinwacht, einst eine stolze Festung des Königreichs, ist an abtrünnige Schwarzfelsorcs gefallen. Ihre Stellung sperrt Straßen und bedroht die östlichen Täler."},{t="Das geteilte Gebirge",b="Diese Gipfel sind Teil des Rückgrats, das sich über den Subkontinent Azeroth erstreckt. Vor Jahrhunderten reichte das Gebirge viel weiter nach Norden. Dann beschwor der Dunkeleisenklan versehentlich den Feuerlord Ragnaros herauf, und die Erde riss auf. So entstand der feurige Krater des Schwarzfels. Die Katastrophe trennte die nördlichen Gipfel ab, aus denen die ascheverhangene Brennende Steppe wurde. Nur die südlichen Täler des Rotkammgebirges blieben üppig und grün, den Angriffen von den Hängen oberhalb ausgesetzt."},{t="Vom Königreich vernachlässigt",b="Magistrat Solomon und Marschall Marris flehen um Verstärkung, doch Sturmwinds Regentschaftsrat überlässt Seenhain sich selbst. Bitten an Späherkuppe und Dunkelhain bringen keine Hilfe; beide Siedlungen sind durch eigene Krisen geschwächt. Da keine Verstärkung in Sicht ist, heuern die örtlichen Magistrate jeden fähigen Söldner an, der bereit ist, den Uferpfad zu wagen, die Gnolllager zu säubern und die Gefahr jenseits des Immerruhsees zurückzudrängen."},{t="Die verborgenen Bündnisse",b="Morganth, ein abtrünniger Hexenmeister, verbündete sich zunächst mit den Schwarzfelsorcs, um Burg Steinwacht einzunehmen. Später verriet er sie und unterwarf die Schattenfellgnolle vom Turm von Ilgalar aus seinem Willen. Bei den Ermittlungen zu den Schwarzfelsorcs gefundene Berichte enthüllen zudem ein Bündnis zwischen den Orcs und dem Schwarzen Drachenschwarm."}},faq={{q="Warum schickt Sturmwind keine Soldaten, um Seenhain zu helfen?",a="Nach dem Fall von Burg Steinwacht sind die verbliebenen königlichen Soldaten in Seenhain zahlenmäßig deutlich unterlegen. Magistrat Solomon hat um Truppen, Waffen, Nahrung und Vorräte gebeten, doch Sturmwinds Streitkräfte sind stark beansprucht, und auch die Siedlungen in der Nähe haben eigene Probleme. Die Garnison ist auf Abenteurer angewiesen, die helfen, die Region zu halten.",al={"warum keine sturmwinder wachen","warum ist das rotkammgebirge verlassen","wo ist sturmwinds armee"}},{q="Wer kontrolliert Burg Steinwacht?",a="Schwarzfelsorcs der Dunklen Horde kontrollieren Burg Steinwacht. Von der Bergfestung aus bedrohen sie die östlichen Täler und Reisende auf dem Uferpfad. Ihre Verbindungen zu anderen Gefahren der Gegend kommen bei den Ermittlungen ans Licht.",al={"wer ist in burg steinwacht","feinde in burg steinwacht","was geschah mit burg steinwacht"}},{q="Welche Gefahren lauern im Immerruhsee?",a="Feindselige Murlocstämme bevölkern den Immerruhsee und überfallen nahegelegene Anlegestellen und Ruinen. Räuberische Schwimmhäuter jagen ebenfalls unter der Oberfläche und schüren Gerüchte über Wassermonster in der Tiefe.",al={"monster im immerruhsee","gefahren im see des rotkammgebirges","murlocs im immerruhsee"}},{q="Gibt es Außenposten der Horde im Rotkammgebirge?",a="Im Rotkammgebirge gibt es keine Siedlungen, Händler oder Flugrouten der Horde. Reisende der Horde durchqueren die Gegend meist auf dem Weg von der Brennenden Steppe im Norden zu den Sümpfen des Elends im Südosten. Dabei nutzen sie Straßen unter Kontrolle der Allianz und durchqueren feindselige Wildnis.",al={"hordenstädte im rotkammgebirge","ist das rotkammgebirge horde oder allianz","flugroute der horde im rotkammgebirge"}},{q="Was sind die Drei Ecken?",a="Die Drei Ecken sind eine Kreuzung im Südwesten des Rotkammgebirges. Dort trifft der Uferpfad auf die östliche Grenze des Waldes von Elwynn und die Straße nach Dämmerwald. So entsteht ein wichtiger Durchgang, den umherziehende Gnolle und wilde Tiere oft zum Ziel haben.",al={"drei ecken","kreuzung der drei ecken","kreuzung im rotkammgebirge"}},{q="Warum ist der nördliche Weg zur Brennenden Steppe so gefährlich?",a="Der Pfad nach Norden führt hinter Render’s Camp direkt hinauf in die Brennende Steppe, ein ödes vulkanisches Ödland. Dort herrschen mächtige Schwarzfelsorcs, Feuerelementare und Drachkin. Die Gefahr nimmt dort plötzlich zu, weshalb der nördliche Gebirgspass zu den tödlichsten Aufstiegen im Süden Azeroths gehört.",al={"nördliche straße des rotkammgebirges","grenze zwischen rotkammgebirge und brennender steppe","nördlicher pass im rotkammgebirge"}}},fx={d1ce2561={q="Was soll ich im Rotkammgebirge tun?",a="Seenhain ist in einer verzweifelten Lage und wurde von der Krone so gut wie aufgegeben. Ihr seid hier, um auf die Bitten von Magistrat Solomon und Marschall Marris um Verteidigung zu antworten. Die Stadt ist schwer bedrängt von marodierenden Schattenhautgnollen entlang der Straßen und wilden Schwarzfelsorcs, die Burg Steinwacht eingenommen haben. Da die königliche Garnison zahlenmäßig unterlegen ist und The Everstill Bridge zerstört wurde, müsst Ihr die Gnolle zurückschlagen, die Vorhut der Orcs zurückdrängen und verhindern, dass dieser friedliche Zufluchtsort am See völlig zusammenbricht.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel im rotkammgebirge","was ist meine mission hier"}},bf444872={q="Ist das Rotkammgebirge gefährlich?",a="Trotz seines idyllischen Aussehens ist das Rotkammgebirge außerordentlich gefährlich. Die Orcs des Schwarzfels kontrollieren die östlichen Schluchten und die Burg, Shadowhide-Gnolle plündern die Wälder und Murlocs tummeln sich an den Ufern des Sees. Sogar die nördliche Straße grenzt an die sengenden Gipfel der Brennenden Steppe, wo monströse Bedrohungen, die weit über eine durchschnittliche Patrouille hinausgehen, direkt hinter den Talpässen lauern.",al={"ist das rotkammgebirge sicher","gefahrenstufe rotkammgebirge","wie gefährlich ist das rotkammgebirge"}},["1cc45818"]={q="Warum ist jeder in Seenhain so besorgt?",a="Seenhain befindet sich im aktiven Belagerungszustand. Die Orcs des Schwarzfels haben Burg Steinwacht direkt auf der anderen Seite des Sees eingenommen, Shadowhide-Gnolle bedrängen die Stadt von den Hügeln aus und Murlocs befallen die Wasserwege. Da die Brücke zerstört ist und keine Verstärkung aus Sturmwind eintrifft, befürchten die Stadtbewohner, dass ein umfassender Angriff sie jeden Moment auslöschen könnte.",al={"warum hat seenhain angst","bedrohung in seenhain","warum besorgnis in seenhain"}},["851f5e81"]={q="Steht Seenhain kurz vor dem Fall?",a="Ohne Eingreifen von außen ist die Lage von Seenhain düster. Die örtliche Stadtwache ist den Orc-Plünderern, Gnollrudeln und Seeungeheuern zahlenmäßig weit unterlegen. Ihre Festung in Steinwacht wurde leicht überrannt und die Verteidiger von Seenhain wurden an das westliche Ufer des Sees zurückgedrängt, wo sie mit Mühe einen Verteidigungswall entlang der zerstörten Brücke halten.",al={"wird seenhain fallen","ist seenhain dem untergang geweiht","kann seenhain überleben"}},["7ced12b0"]={q="Hat Sturmwind Hilfe nach Seenhain geschickt?",a="Seenhain hat Sturmwind, Westfall und Dunkelhain um Hilfe gebeten, doch die benachbarten Siedlungen sind mit ihren eigenen Krisen beschäftigt. General Marcus Jonathan wurde ebenfalls um Verstärkung gebeten. Die königlichen Soldaten, die Seenhain noch verteidigen, haben nach dem Fall von Burg Steinwacht weiterhin einen Mangel an Truppen und Vorräten.",al={"hat sturmwind seenhain geholfen","sturmwind hilfe für seenhain","hat sturmwind truppen ins rotkammgebirge geschickt"}},["3a3ab87f"]={q="Wer hat hier das Sagen?",a="Seenhain wird von Magistrat Solomon regiert, der zivile Angelegenheiten und städtische Belange vom Rathaus von Seenhain aus beaufsichtigt. Militärische und Verteidigungsoperationen unterstehen Marschall Marris, der die örtliche Wache leitet und Verteidigungsbemühungen nahe der Brücke koordiniert.",al={"wer führt das rotkammgebirge","wer regiert seenhain","anführer des rotkammgebirges"}},["1dd15680"]={q="Wer ist Magistrat Solomon?",a="Magistrat Solomon ist das gewählte Oberhaupt von Seenhain und oberster Richter des Gerichts von Seenhain. Gealtert und erschöpft trägt er die Last, die Stadt mit Nahrung zu versorgen, organisiert zu halten und politisch mit dem Königreich verbunden zu lassen, während er verzweifelt auswärtige und regionale Anführer um militärische Entlastung bittet.",al={"magistrat solomon","wer ist solomon","solomon rotkammgebirge"}},["0e63cf14"]={q="Untersteht Marschall Marris Magistrat Solomon?",a="Ja. Solomon repräsentiert die zivile Autorität und das Gericht des Königreichs in Seenhain, während Marschall Marris das dort stationierte Kontingent der Sturmwindgarde befehligt. Die beiden arbeiten eng zusammen, wobei Solomon die diplomatische und städtische Überlebenssicherung verwaltet, während Marris taktische Scharmützel und Truppeneinsätze handhabt.",al={"untersteht marris solomon","rang von marschall marris und solomon","wer steht im rang über wem in seenhain"}},["7b7fd7c0"]={q="Wer sind die Orcs des Schwarzfels und warum sind sie im Rotkammgebirge?",a="Der Clan des Schwarzfels ist ein rücksichtsloser Überrest der Alten Horde, der im Norden vom Schwarzfels aus operiert. Im Gegensatz zu Thralls Horde in Kalimdor lehnen diese Abtrünnigen jeden Frieden mit der Allianz ab. Sie sind von der Brennenden Steppe in das Rotkammgebirge herabgestiegen, um die Region zu erobern, und nutzen Burg Steinwacht als Stützpunkt, um Seenhain zu zerschlagen.",al={"orcs des schwarzfels im rotkammgebirge","warum sind orcs im rotkammgebirge","wer ist der clan des schwarzfels im rotkammgebirge"}},["114fb915"]={q="Woher kommen die Orcs des Schwarzfels?",a="Sie marschierten aus südlicher Richtung über die gezackten nördlichen Gebirgspässe direkt von der Brennenden Steppe und der Schwarzfelsspitze, ihrer alten Festung aus dem Zweiter Krieg, hierher. Sie errichteten Außenposten wie Render's Camp, bevor sie Burg Steinwacht überwältigten.",al={"woher kommen die orcs im rotkammgebirge","herkunft der orcs des schwarzfels","woher kommen die orcs"}},["9f02e3ae"]={q="Sind die Orcs des Schwarzfels dieselben Orcs aus den Kriegen?",a="Ja. Sie sind abgehärtete Veteranen und direkte Nachkommen des Clans des Schwarzfels aus dem Erster Krieg und Zweiter Krieg, die sich weigerten, sich zu ergeben oder Thralls neuem schamanistischen Pfad zu folgen. Sie behalten ihre ursprünglichen blutrünstigen Praktiken und ihre dunkle Magie bei und halten fest an ihrer ursprünglichen Mission, die menschlichen Königreiche auszulöschen.",al={"stammen die orcs des schwarzfels aus dem ersten krieg","orcs des schwarzfels aus dem zweiten krieg","sind das dieselben orcs aus den alten kriegen"}},["09fb7c4a"]={q="Was sind die Gnolle des Rotkammgebirges? Warum greifen sie an?",a="Die örtlichen Shadowhide-Gnolle sind wilde, hyänenartige Humanoide, die die Hügel und Täler des Rotkammgebirges bewohnen. Obwohl sie von Natur aus territorial und räuberisch sind, wird ihre derzeitige koordinierte Gewalt von dunklen Einflüssen angetrieben, die ihre verstreuten Rudel zu einer organisierten Armee vereint haben, die darauf aus ist, menschliche Siedlungen abzuschlachten.",al={"gnolle im rotkammgebirge","warum greifen gnolle das rotkammgebirge an","shadowhide-gnolle"}},ba7471d2={q="Arbeiten die Gnolle mit den Orcs zusammen?",a="Die Shadowhide-Gnolle dienen dem abtrünnigen Hexenmeister Morganth im Turm von Ilgalar. Ihre Beziehung zu den Orcs des Schwarzfels kann durch Berichte untersucht werden, die in der Region geborgen wurden.",al={"sind gnolle und orcs verbündet","arbeiten gnolle für den schwarzfels","arbeiten orcs und gnolle zusammen"}},["74e139ea"]={q="Wer ist Yowler?",a="Yowler ist der Anführer der Gnolle des Rotkammgebirges. Er haust in den Hügeln oberhalb von Seenhain und versammelt das Rudel gegen die Stadt. Verner Gutmark bittet Abenteurer, ihn zu besiegen und seine Pfote zurückzubringen.",al={"wer ist yowler","yowler gnollanführer","yowler rotkammgebirge"}},b25dfaa0={q="Warum ist die The Everstill Bridge kaputt und warum ist das wichtig?",a="Die The Everstill Bridge ist schwer beschädigt. Sie ist von enormer Bedeutung, da sie den schmalen Hals des Immerruhsees überspannt und als wichtigste Verkehrsverbindung von Seenhain zum östlichen Ufer und nach Steinwacht dient. Ihre Zerstörung behindert den Handel und die Verteidigung der Stadt und erschwert jeden Gegenangriff auf feindliche Lager.",al={"the everstill bridge zerstört","warum ist die brücke in seenhain zerstört","zerstörte brücke im rotkammgebirge"}},b35f81a4={q="Warum hat Sturmwind die The Everstill Bridge nicht repariert?",a="Sturmwind hat keine Gelder, Vorräte oder Steinmetze zur Unterstützung geschickt. Die Verantwortung liegt vollständig bei den Arbeitern vor Ort unter der Leitung von Großknecht Oslow, deren Reparaturarbeiten ständig durch Murloc-Überfälle und den Verlust von Vorräten unterbrochen und sabotiert werden.",al={"warum wurde die brücke nicht repariert","sturmwind brückenreparatur seenhain","wer repariert die brücke"}},["834d2ea2"]={q="Warum gibt es schwarze Drachenwelpen im Rotkammgebirge?",a="Schwarze Drachenwelpen sind durch die Pässe aus der Brennenden Steppe herabgeströmt und befallen den Uferpfad und die südlichen Schluchten. Sie schleichen durch die felsigen Bergrücken, kundschaften das Gebiet aus und lauern Passanten auf, was als düstere Warnung dient, dass die Brut von Deathwing in der Nähe aktiv ist.",al={"drachenwelpen im rotkammgebirge","schwarze drachen im rotkammgebirge","warum drachenwelpen im rotkammgebirge"}},ce7dd1a7={q="Arbeiten die Drachen mit den Orcs zusammen?",a="Die wachsende Präsenz des Schwarzfels und Sichtungen von schwarzen Drachenwelpen beunruhigen Seenhain. Magistrat Solomon bittet Reisende, seine Sorgen an Hochlord Bolvar Fordragon weiterzuleiten. Weitere Untersuchungen offenbaren die Art der Bedrohung.",al={"sind schwarze drachen mit dem schwarzfels verbündet","bündnis von orcs und drachen","arbeiten orcs des schwarzfels mit drachen"}},["7d7bd3f8"]={q="Warum kämpft hier ein Abenteurer statt der Wachen?",a="Die Wachen von Seenhain sind vollständig mit der Verteidigung des Stadtperimeters beschäftigt, sodass niemand für Offensivangriffe übrig bleibt. Da angeforderte Verstärkungen weiterhin nicht verfügbar sind, haben Magistrat Solomon und Marschall Marris keine andere Wahl, als reisende Abenteurer anzuheuern, um die Orcs zurückzudrängen, die Gnolle auszudünnen und den Uferpfad zu sichern.",al={"warum tue ich das im rotkammgebirge","warum abenteurer im rotkammgebirge","wo sind die wachen im rotkammgebirge"}},["839c7682"]={q="Wo ist die Armee von Sturmwind?",a="Die Streitkräfte von Sturmwind sind überdehnt. Königliche Soldaten verbleiben in Seenhain nach ihrer Niederlage bei Burg Steinwacht, aber die wiederholten Bitten der Stadt nach frischen Truppen und Vorräten haben nicht die Verstärkungen gebracht, die ihre Verteidiger benötigen.",al={"wo sind die soldaten von sturmwind","warum keine armee aus sturmwind","standort der armee von sturmwind"}},de572e98={q="Wie bin ich im Rotkammgebirge gelandet?",a="Ihr seid wahrscheinlich den Straßen von Wald von Elwynn aus nach Osten durch die Kreuzung Drei Ecken gefolgt oder über den Fluss aus den dunklen Wäldern von Dämmerwald im Südwesten gekommen. Als junger Champion, der die menschlichen Lande unterstützt, führen Eure Reisen natürlich hierher, sobald die abgelegenen Probleme rund um Sturmwind nach stärkeren Händen verlangen. Die Hilferufe von Seenhain erreichen die benachbarten Gebiete und ziehen reisende Abenteurer den Uferpfad hinauf in diese umkämpften Höhen.",al={"wie bin ich hierher gekommen","wie habe ich das rotkammgebirge erreicht","warum bin ich ins rotkammgebirge gekommen"}},["85c0e73f"]={q="Was ist das Rotkammgebirge?",a="Das Rotkammgebirge ist eine höhergelegene, malerische Region östlich des Wald von Elwynn und südlich der Brennende Steppe. Bekannt für seine reißenden Flüsse, hoch aufragenden Ulmen und den schimmernden Der Immerruhsee, galt es lange Zeit als eine der friedlicheren Ländereien im südlichen Azeroth. Heute wird seine stille Schönheit durch eindringende Schwarzfels-Orcs, gewalttätige Gnolle und feindselige Murlocs im See erschüttert.",al={"was ist das rotkammgebirge","zone rotkammgebirge","erzähl mir vom rotkammgebirge"}},["5d244582"]={q="Ist das Rotkammgebirge Teil des Königreichs Sturmwind?",a="Ja, das Rotkammgebirge steht unter dem Schutz und der Herrschaft des Königreichs Sturmwind, obwohl seine lokalen Anführer seit dem Zweiter Krieg die täglichen Angelegenheiten weitgehend unabhängig regiert haben. Der Magistrat Solomon aus Seenhain bittet den Thron von Sturmwind immer noch formell um Verteidigung und verlässt sich auf den Handel und die gegenseitige Loyalität der Allianz, selbst wenn königliche Truppen nirgendwo in Sicht sind.",al={"gehört das rotkammgebirge zu sturmwind","ist das rotkammgebirge allianz","ist seenhain teil von sturmwind"}},["8563150d"]={q="Warum gibt es einen See inmitten des Rotkammgebirges?",a="Der Immerruhsee sammelt auf natürliche Weise das Abflusswasser der umliegenden Gebirgszüge. Sein klares, ruhiges Wasser versorgte Seenhain einst mit reichlich Fisch und sauberem Wasser, obwohl es in letzter Zeit von bösartigen Murloc-Stämmen überrannt und von lauernden Dreschern unter der Oberfläche heimgesucht wurde.",al={"warum der immerruhsee","ursprung des sees im rotkammgebirge","was ist der see im rotkammgebirge"}},["8de34bfa"]={q="Was ist im Rotkammgebirge passiert?",a="Das Rotkammgebirge war einst eine friedliche Wiege menschlicher Gehöfte bis zum Erster Krieg, als Kriegshäuptling Schwarzfaust und die Hexenmeister des Schattenrats die Ritter von Sir Anduin Lothar besiegten und die Menschen ins Exil trieben. Nach dem Zweiter Krieg von der Allianz zurückerobert und wiederaufgebaut, wurde die Region kürzlich erneut belagert, nachdem Schwarzfels-Orcs aus den Bergen herabstiegen und Burg Steinwacht einnahmen.",al={"geschichte des rotkammgebirges","was passierte im rotkammgebirge","rotkammgebirge erster krieg"}}},fp="18,271,21.379.0,17.453.0,22.430.0,22.309.1,52.324.0,29.235.0,37.186.0,41.258.0,26.229.0,60.279.0"}
P.entries["zone:riverglades"] = {n="Flusslande",s="In den Flusslanden kämpfen menschliche Loyalisten und Horde-Außenposten noch immer um ein Tal östlich des Ödlands und der Brennenden Steppe. Einst beanspruchte Sturmwind die Region, doch die Alte Horde überrannte sie im Ersten Krieg. Das Rotkammgebirge liegt im Südwesten, die Sümpfe des Elends im Süden und Tanaris jenseits des Meeres.",h="In den Flusslanden kämpfen menschliche Loyalisten und Horde-Außenposten noch immer um ein Tal östlich des...",kw={"schwarzfelspass","bruderschaft des pferds","demar brant","burg farholde","feste krol'dok","hafen von powderfuse","rotkammpass","flusslande","rog'mar","sonnengrund"},ang={["faction:Alliance"]="Als Soldat der Allianz findet Ihr in den Flusslanden alte Wunden, die wieder aufgerissen werden. Überreste der Bruderschaft des Pferds setzen ihren stillen Kreuzzug fort, um Land zurückzuerobern, das Sturmwind während des Ersten Krieges aufgab.",["faction:Horde"]="Für die Horde sichern Außenposten wie Rog'mar einen Küstenstützpunkt und halten den Druck auf die alten menschlichen Festungen östlich des Rotkammgebirges aufrecht.",["race:Human"]="Als Mensch begegnet Ihr in Sonnengrund einem tragischen Kapitel Eurer Herkunft. Der Ort erinnert daran, welchen hohen Preis Euer Königreich im Ersten Krieg an seiner Ostgrenze zahlte."},sec={{t="Ein vergessenes Grenzland",b="Vor dem Ersten Krieg gehörten die Flusslande zum Königreich Sturmwind. Dann fegte die Alte Horde hindurch. Orcs plünderten Sonnengrund, verschonten aber den Magierturm, um menschliche Zauberei zu studieren. Die überlebenden Bewohner versklavten sie. Sturmwind-Soldaten versuchten, die Gefangenen zu befreien und den Ort wieder aufzubauen. Doch das Königreich erklärte das Tal für verloren und sandte seine Streitkräfte zur Verteidigung der Kernlande. Jahrelang erhielt die Krone die Flusslande kaum offiziell unterstützt."},{t="Der Kampf um Farholde",b="Sturmwinds Anführer ließen die Flusslande zurück, doch ihre menschlichen Verteidiger gaben ihre Heimat nie ganz auf. Ritterkommandant Demar Brant führt die verbliebenen Loyalisten der legendären Bruderschaft des Pferds an. Sie halten Burg Farholde gegen die Wildnis und feindliche Eindringlinge. In der Nähe unterhält die moderne Horde eine starke Präsenz an Außenposten wie Rog'mar und Bolder'ok. Der alte Kampf um die Lichtungen geht weiter."},{t="Landschaft und Wege",b="Die Flusslande erstrecken sich entlang der Küste des Verbotenen Meeres, zwischen Bergen und gewundenen Wasserläufen. Nach Westen gelangt Ihr durch den Schwarzfelspass zur Brennenden Steppe. Nach Südwesten führt der Weg durch den Rotkammpass zum Rotkammgebirge. Im Süden liegen die Sümpfe des Elends. Im Nordwesten führen Pfade am Zwielichtschleier vorbei ins Ödland. Vom Hafen von Powderfuse aus könnt Ihr ein Boot über das Meer zum Dampfdruckpier in Tanaris nehmen."}},faq={{q="Was sind die Flusslande?",a="Die Flusslande liegen östlich des Ödlands und der Brennenden Steppe, an der Küste des Verbotenen Meeres. Einst beanspruchte Sturmwind die Region. Heute hält die Allianz Burg Farholde, während die Horde Rog'mar besetzt.",al={"überblick über die flusslande","was ist dieses gebiet","über die flusslande"}},{q="Was geschah mit Sonnengrund?",a="Die Alte Horde überfiel und zerstörte Sonnengrund während des Ersten Krieges. Orcs versklavten die überlebenden Dorfbewohner, ließen aber einen örtlichen Magierturm stehen, um menschliche Magie zu studieren. Sturmwind-Soldaten versuchten, die Gefangenen zu befreien und den Ort wieder aufzubauen. Doch schließlich gab das Königreich das Gebiet auf, um seine Westgrenzen zu verteidigen.",al={"geschichte von sonnengrund","untergang von sonnengrund","was geschah mit dem ort"}},{q="Wer kontrolliert Burg Farholde?",a="Loyalisten der Allianz halten Burg Farholde unter dem Kommando von Ritterkommandant Demar Brant von der Bruderschaft des Pferds. Seine Streitkräfte kämpfen seit Jahren darum, die Flusslande zurückzuerobern, nachdem Sturmwind das Gebiet für verloren erklärt hatte.",al={"wer führt farholde an","allianz in den flusslanden","bruderschaft des pferds"}},{q="Wie gelangt Ihr von den Flusslanden nach Tanaris?",a="Vom Hafen von Powderfuse an der Ostküste der Flusslande fährt regelmäßig ein Küstenboot zum Dampfdruckpier in Tanaris. Es überquert direkt das Meer.",al={"boot nach tanaris","boot vom hafen von powderfuse","wie gelangt man nach tanaris"}},{q="Welche Pässe führen in andere Gebiete?",a="Nach Südwesten gelangt Ihr durch den Rotkammpass zum Rotkammgebirge. Oder Ihr zieht nach Süden zu den Sümpfen des Elends. Westwärts führt der Schwarzfelspass an den Borstenhügeln vorbei zur Brennenden Steppe. Pfade nördlich des Zwielichtschleiers führen direkt ins Ödland.",al={"wie gelangt man nach rotkammgebirge","pässe aus den flusslanden","ausgänge aus den flusslanden"}},{q="Was ist die Feste Krol'dok?",a="Die Feste Krol'dok ist ein befestigter Gewölbekomplex in den Flusslanden und ein bedeutender Sitz feindlicher Macht im umkämpften Gebiet.",al={"feste krol'dok","gewölbe in den flusslanden","welches gewölbe gibt es hier"}}},fp="11,291,22.431.0,25.415.0,20.414.0,24.187.0,28.295.0,27.212.0,46.146.0,34.266.0,28.127.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Ruinen von Lordaeron",s="Über der Unterstadt bergen die Ruinen von Lordaeron noch immer Schrecken aus der gefallenen Hauptstadt. Prinz Arthas und die Geißel brachten das Menschenreich während des Dritten Krieges zu Fall. Nun durchstreifen Allianz und Horde die Oberfläche, um Relikte der Vergangenheit zurückzuerobern oder ihre Bedrohungen zu beseitigen.",h="Über der Unterstadt bergen die Ruinen von Lordaeron noch immer Schrecken aus der gefallenen Hauptstadt.",kw={"bjork","lordaeron captain","new plague","rath'mael","ruinen von lordaeron","the abandoned","the baron","tirisfal","unterstadt","viktor the vile","witherfang"},ang={["class:Paladin"]="Als Paladin durchschreitet Ihr die entweihten Hallen von Lordaeron, der Wiege der Ritter der Silbernen Hand, um Schrecken zu bannen und ruhelose Captains im Dienste des Lichts zur Ruhe zu betten.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr an der Schwelle zur Hauptstadt der Verlassenen zuschlagen und zugleich den Geistern Eurer abgeschlachteten Brüder aus dem Norden Gerechtigkeit und Frieden bringen.",["race:Human"]="Als Mensch seht Ihr die zerstörte Hauptstadt vielleicht als geheiligten Boden, der durch Verrat geraubt wurde, und sucht nach verlorenen Erbstücken und einer Möglichkeit, gefallene Angehörige zu ehren.",["race:Undead"]="Für die Verlassenen sind die Ruinen darüber ihre frühere Heimat und ihr ewiger Friedhof. Sie zu säubern sichert ihre Haustür und versorgt die Apotheker mit Bestandteilen für die Entwicklung der New Plague."},sec={{t="Der Hof eines gefallenen Reiches",b="Capital City hielt einst die Krone der Östlichen Königreiche. König Terenas Menethil II. saß auf ihrem Thron, und die menschliche Zivilisation hatte dort ihren Mittelpunkt. Als Prinz Arthas aus Northrend zurückkehrte, tötete er seinen Vater im Thronsaal und hetzte die Untoten auf das Volk los.\n\nDie Verlassenen leben nun in den Katakomben darunter, in der Unterstadt. Über ihnen ist die Oberfläche eine verlassene Dämmerzone. Zerbrochene Torbögen und von Unkraut überwuchertes Pflaster bieten wilden Bestien wie Witherfang und geistesgestörten Überbleibseln der Vergangenheit Zuflucht."},{t="Qual und Seuche",b="Die ruhelosen Toten sind nicht die einzige Gefahr auf dem verwüsteten Gelände. Apotheker und finstere Gestalten wie Viktor the Vile erproben im Schatten neue Seuchen, während verdrehte Experimente wie The Abandoned frei umherstreifen.\n\nZornige Geister wie Rath'mael und verfluchte Gefolgsleute wie The Baron spuken durch die eingestürzten Hallen, gefangen in endloser Qual. Sie greifen jeden lebenden oder untoten Eindringling an, der ihren Weg kreuzt."},{t="Geister der königlichen Garde",b="Geisterhafte Verteidiger verweilen in den oberen Ruinen, darunter ein geisterhafter Lordaeron Captain. Noch immer an ihre zerbrochenen Eide gebunden, sehen diese Erscheinungen jeden, der sich dem Thron nähert, als Eindringling. Den Captain und seine Soldaten zur Ruhe zu betten, beendet eine bittere Wacht, die seit dem Fall der Hauptstadt andauert."}},faq={{q="Wo liegt der Dungeon Ruinen von Lordaeron?",a="Der Dungeon Ruinen von Lordaeron erstreckt sich über die Oberfläche von Capital City in Tirisfal, direkt über dem Eingangsnetz, das hinab zur Hauptstadt der Verlassenen, der Unterstadt, führt.",al={"lage der ruinen von lordaeron","wo liegt der dungeon lordaeron","eingang zum dungeon unterstadt"}},{q="Warum interessieren sich Horde und Allianz für diesen Ort?",a="Die Allianz wagt sich nach Lordaeron, um verlorene Familienerbstücke zu bergen, königliche Wappen zu sammeln und gefallenen Vorfahren Frieden zu bringen. Die Horde, insbesondere die Verlassenen, will den Umkreis der Unterstadt sichern und Forschungsproben für die neue Seuche der Königlichen Apothekervereinigung beschaffen.",al={"warum zu den ruinen von lordaeron","allianzquests in lordaeron","hordenquests in lordaeron"}},{q="Wer ist Viktor the Vile?",a="Viktor the Vile ist eine finstere Gestalt, die die Gesetzlosigkeit in den Ruinen für ihre üblen Experimente ausnutzt. Seine Arbeit trägt zur Verderbnis und zu den verdrehten Abscheulichkeiten bei, die die obere Hauptstadt verseuchen.",al={"lore zu viktor the vile","wer ist viktor the vile"}},{q="Was ist „The Abandoned“, dem man in den Ruinen begegnet?",a="The Abandoned ist ein groteskes untotes Ungeheuer, das in den Ruinen zurückgelassen wurde. Wie viele zusammengeflickte Schrecken, die während oder nach der Eroberung durch die Geißel erschaffen wurden, wandert es ziellos durch die verfallenen Gemächer und greift alles an, was ihm begegnet.",al={"boss the abandoned","wer ist the abandoned"}},{q="Was bedeutet es für die Geschichte, den Lordaeron Captain zu besiegen?",a="Der Sieg über den geisterhaften Lordaeron Captain befreit einen hochrangigen königlichen Verteidiger von einer ewigen, zermürbenden Pflicht. Seit dem ersten Massaker der Geißel an die Ehre gebunden, hat der Captain jahrelang ein zerstörtes Königreich bewacht, und diese Wacht dauert seit dem Fall der Hauptstadt an. Den Captain zur Ruhe zu betten, beendet einen qualvollen Kreislauf geisterhafter Knechtschaft und ermöglicht es, das blutbefleckte Abzeichen zurückzuerobern.",al={"lordaeron captain besiegen","bedeutung des lordaeron captain","was passiert, wenn der captain stirbt"}},{q="Sind die Ruinen von Lordaeron von der Unterstadt getrennt?",a="Ja. Die Verlassenen leben in den Höhlen der Unterstadt darunter, während die Ruinen an der Oberfläche eine aktive Kampfzone bleiben. Dort lauern ruhelose Geister, wilde Raubtiere und experimentelle Bedrohungen, die die Verlassenen noch nicht vollständig beseitigt haben.",al={"liegt die unterstadt in diesem dungeon","ruinen oder unterstadt"}}},fx={["1b77984b"]={q="Was ist dieser Ort, die Ruinen von Lordaeron?",a="Ihr steht in den zertrümmerten Überresten der Hauptstadt, einst das Juwel der menschlichen Zivilisation und das Herz des Königreichs Lordaeron. Während des Dritten Krieges verriet Prinz Arthas sein Königreich, schlachtete seinen Vater König Terenas im Thronsaal darüber ab und entfesselte die untote Geißel auf ihren Straßen. Heute liegen ihre zerbrochenen Bögen und versengten Türme über der unterirdischen Unterstadt und dienen als bitteres Denkmal für das gefallene Königreich.",al={"was sind die ruinen von lordaeron","hintergrundgeschichte ruinen von lordaeron","was war das für ein ort"}},eb89374f={q="Wer lebte hier, bevor es zerstört wurde?",a="Diese Stadt war die Heimat des größten nördlichen Königreichs der Menschheit, regiert von der Menethil-Dynastie. Adlige, Priester des Heiligen Lichts, Soldaten und Hunderttausende einfacher Leute gingen einst über diese gepflasterten Straßen. Tragischerweise haben viele dieser ehemaligen Bürger ihre Heimat nie wirklich verlassen; von der Pest dahingerafft, bilden ihre wiederbelebten Leichen sowohl die gedankenlose Geißel, die die Pestländer heimsucht, als auch die befreiten Verlassenen, die nun in den Höhlen darunter wohnen.",al={"wer lebte hier früher","ursprüngliche bewohner von lordaeron","wer war zuerst hier"}},["6e6195fd"]={q="Warum ist hier alles kaputt und verbrannt?",a="Als Prinz Arthas mit Frostgram zurückkehrte, erschlug er König Terenas und überließ die Stadt der Geißel. Untote Schrecken wüteten durch die Alleen, brannten Gebäude nieder und metzelten jeden nieder, der versuchte, Widerstand zu leisten. Später, während des Bürgerkriegs unter den Untoten, kämpften Sylvanas Windläufer und ihre Verlassenen gegen Schreckenslords und verbliebene Legionen der Geißel durch genau diese Innenhöfe und rissen nieder, was von der großartigen Architektur der Stadt übrig geblieben war.",al={"warum ist lordaeron zerstört","wie wurde lordaeron verbrannt","warum ist es in ruinen"}},dd470a5c={q="Wer hat Lordaeron zerstört?",a="Das Königreich wurde von innen heraus durch seinen eigenen Kronprinzen, Arthas Menethil, unter dem korrumpierenden Flüstern des Lichkönigs zertrümmert. Ausgesandt, um den Kult der Verdammten und ihre Pest der Untoten aufzuhalten, wurde Arthas rücksichtslos, nahm die verfluchte Runenklinge Frostgram im gefrorenen Norden an und ergab seine Seele. Als Todesritter zurückkehrend, schlug er seinen Vater nieder und lieferte die Stadt den Klauen der Geißel aus.",al={"wer hat lordaeron zerstört","wer brachte lordaeron zu fall","zerstörer von lordaeron"}},f5a9164f={q="Wo ist Arthas jetzt?",a="Arthas verließ den zerstörten Kontinent Lordaeron vor Jahren und segelte zurück über Das große Meer nach Nordend, als der Lichkönig vom Dämonenjäger Illidan Sturmgrimm bedroht wurde. Er kämpfte sich die eisige Spitze des Frostthrons hinauf und ist aus dem Blickfeld der Allgemeinheit in den gefrorenen Einöden verschwunden, wobei er ein Königreich hinterließ, das in rivalisierende Fraktionen von Untoten und Überlebenden zersplittert ist.",al={"wohin ist arthas gegangen","wo ist prinz arthas","arthas standort"}},["2fe0baef"]={q="Ist jemand aus der Stadt entkommen?",a="Ein paar Glückliche entkamen dem Gemetzel. Vor dem endgültigen Zusammenbruch achtete die Zauberin Jaina Prachtmeer auf die Warnungen eines mysteriösen Propheten und führte Tausende menschlicher Flüchtlinge über das Meer nach Kalimdor, wo sie den Hafen von Theramore gründeten. Andere flohen nach Süden in Richtung des Königreichs Sturmwind oder griffen zu den heiligen Waffen, um zurückzukämpfen, wobei sie den fanatischen Scharlachroten Kreuzzug und die wachsame Argentumdämmerung bildeten.",al={"haben bürger von lordaeron überlebt","hat jemand den fall von lordaeron überlebt","überlebende von lordaeron"}},["9cf7434f"]={q="Warum gibt es eine Stadt der Untoten unter den Ruinen?",a="Als die Macht des Lichkönigs schwand, brach Sylvanas Windläufer dessen mentale Kontrolle über eine Vielzahl von Untoten. Sie nannten sich die Verlassenen und stürzten die dämonischen Schreckenslords, die die Hauptstadt hielten. Die Ruinen darüber waren zu exponiert für feindliche Augen und ständige Angriffe des Scharlachroten Kreuzzugs, also entschied Sylvanas, die riesigen unterirdischen Krypten und Kanalisationen in eine schwer befestigte Festung zu verwandeln.",al={"warum existiert die unterstadt","warum ist die unterstadt unter lordaeron","untote stadt unter ruinen"}},["55ddf3da"]={q="Wer hat die Unterstadt gebaut?",a="Das Fundament begann unter der Hauptstadt als königliche Verliese, Kanalisationen und tiefe Krypten, die von den Menschen von Lordaeron erbaut wurden. Während des Dritten Krieges begannen Arthas und die Geißel, diese unterirdischen Korridore zu einem ausgeklügelten Netzwerk zu erweitern, das ein Zentrum der Macht der Geißel werden sollte. Nachdem sie dem Schreckenslord Varimathras die Kontrolle entrissen hatten, vollendeten Sylvanas und die Verlassenen den Ausbau der Unterstadt als ihre ständige Hauptstadt.",al={"wer erschuf die unterstadt","konstruktion der unterstadt","wer hat die unterstadt ausgegraben"}},c0ee4f6f={q="War die Unterstadt schon immer da unten?",a="Nicht in ihrem modernen, weitläufigen Zustand. Zu Zeiten von König Terenas bestand das Untergeschoss lediglich aus Schlossverliesen, Aquädukten, Abwasserkanälen und Familiengräbern. Erst nach dem Fall des Königreichs höhlten Abscheulichkeiten der Geißel und Arbeiter der Verlassenen die massiven Ringe und Viertel aus, die Ihr heute seht, und verwandelten Versorgungstunnel in eine weitläufige unterirdische Bastion der Toten.",al={"war die unterstadt schon immer da","existierte die unterstadt vorher","alte unterstadt"}},dc41e367={q="Wer hat hier das Sagen?",a="Fürstin Sylvanas Windläufer, die Banshee-Königin, befehligt diese Ruinen und die Unterstadt darunter. Einst die Waldläufergeneralin von Silbermond, wurde sie von Arthas erschlagen, als rachsüchtige Banshee wiedererweckt und holte sich schließlich ihre physische Leiche zurück. Durch reine Willenskraft und List befreite sie ihre untoten Brüder und Schwestern und schmiedete die Verlassenen, die sie mit rücksichtsloser Entschlossenheit von ihrem Thron im Royal Quarter aus führt.",al={"wer regiert die ruinen von lordaeron","anführer der unterstadt","wer kontrolliert diesen ort"}},["3d3094f9"]={q="Ist Sylvanas eine Königin oder etwas anderes?",a="Ihr Volk verehrt sie als Banshee-Königin und Fürstin der Verlassenen, aber sie ist kein erblicher Adel von Lordaeron. Der Titel spiegelt die tragische Natur ihres Todes durch die Hand von Prinz Arthas wider, der ihre Seele aus ihrem Körper riss, damit sie als wimmernde Banshee dienen konnte. Obwohl der Titel an Monarchie erinnert, entspringt ihre Autorität der Befreiung, dem Überleben und dem absoluten militärischen Kommando.",al={"ist sylvanas eine königin","titel banshee-königin","was ist sylvanas titel"}},ac534dbb={q="Antwortet Sylvanas Thrall gegenüber?",a="Auf dem Papier erkennt Sylvanas Kriegshäuptling Thrall als den obersten Befehlshaber der Horde an, und sie stimmte ihrer Zweckallianz zu. In der Realität behält die Banshee-Königin die vollständige Autonomie über die Verlassenen und ihre nördlichen Gebiete. Thralls Wort wird respektiert, und Gesandte der Verlassenen laufen in Orgrimmar umher, aber Fürstin Sylvanas antwortet in erster Linie ihrem eigenen Überleben und den Ambitionen ihres Volkes.",al={"beziehung sylvanas thrall","gehorcht sylvanas thrall","steht sylvanas unter thrall"}},["6b51523d"]={q="Was ist in diesem Thronsaal dort oben die Treppe hinauf passiert?",a="Der Thronsaal war der Ort des katastrophalen Verrats, der das Königreich beendete. Prinz Arthas, frisch zurückgekehrt aus Nordend, marschierte an willkommen heißenden Bürgern und läutenden Glocken vorbei in diese Kammer. Als sein Vater, König Terenas, sich vom Thron erhob, um ihn zu begrüßen, zog Arthas Frostgram, verkündete, dass er seinem Vater nachfolgen würde, und stieß die verfluchte Runenklinge durch das Herz des alten Königs.",al={"was passierte im thronsaal","geschichte thronsaal von lordaeron","thronsaal historisch"}},["6e83c082"]={q="Ist das die Stelle, an der Terenas getötet wurde?",a="Ja. Wenn Ihr direkt vor das zerbrochene Podest tretet, steht Ihr auf genau den Pflastersteinen, auf denen König Terenas Menethil II. seinen letzten Atemzug tat. Ein schwacher, dunkler Fleck ist auf dem Steinboden immer noch sichtbar, von dem es heißt, er sei das Blut des alten Königs, das in das Mauerwerk sickerte, als sein Sohn ihn niederschlug. Selbst jetzt hallen spektrales Flüstern und Glocken leise in der Kammer nach.",al={"wo wurde terenas getötet","ist das terenas blut","ort an dem könig terenas starb"}},ea8d978d={q="Was ist mit Terenas' Krone passiert?",a="Terenas' goldene Krone fiel zu Boden, als Arthas ihn im Thronsaal ermordete. Ihr Fall markiert das Ende seiner Herrschaft und die Katastrophe, die Lordaeron ereilte.",al={"warum liegt die krone auf dem boden","könig terenas krone ruinen","terenas krone blut"}},bb044bc8={q="Sind die Verlassenen tatsächlich Teil der Horde?",a="Ja, obwohl es größtenteils ein Pakt zum gegenseitigen Überleben ist. Umgeben vom Scharlachroten Kreuzzug, feindseligen Menschen und der verbleibenden Geißel sandten die Verlassenen Botschafter über das Meer, um Verbündete zu suchen. Die Horde, die einen Stützpunkt in den Östlichen Königreichen benötigte, um der Allianz entgegenzuwirken, stimmte zu, ihnen den Eintritt zu gewähren, was den Verlassenen dringend benötigte militärische Unterstützung und internationales Ansehen verschaffte.",al={"verlassene horde allianz","sind untote in der horde","warum sind die verlassenen bei der horde"}},["50000697"]={q="Warum hat Thrall Untote in die Horde aufgenommen?",a="Thrall wurde hauptsächlich durch die Fürsprache von Erzruide Hamuul Runetotem und den Tauren überzeugt, die glaubten, die Verlassenen seien tragische Opfer, die eines Tages Erlösung oder ein Heilmittel für ihr Leiden finden könnten. Darüber hinaus erkannte Thrall die strategische Notwendigkeit eines etablierten Stützpunkts in den Östlichen Königreichen, um zu verhindern, dass die Allianz den nördlichen Kontinent unangefochten dominiert.",al={"warum erlaubte thrall die untoten","thrall verlassene grund","warum nahm die horde die verlassenen auf"}},["9af0f393"]={q="Vertrauen ihnen die Orcs und Tauren?",a="Nicht vollständig. Während die Tauren sie mit tiefem Mitleid betrachten und hoffen, ihr Leiden zu heilen, hegen viele Orcs tiefe Bedenken gegenüber dunkler Magie, Nekromantie und der finsteren Natur der Unterstadt. Thrall behält Sylvanas' Handlungen genau im Auge, und stationierte Botschafter sind misstrauisch gegenüber dem, was in den Laboren der Royal Apothecary Society gebraut wird.",al={"vertrauen orcs den verlassenen","tauren verlassene vertrauen","vertraut die horde untoten"}},["849f698a"]={q="Ist es sicher für mich, hier zu stehen?",a="Das hängt ganz von Eurer Loyalität ab. Wenn Ihr für die Horde kämpft, erkennen die Verlassenen und ihre Abscheulichkeiten Euch als Verbündeten an, obwohl die Schatten darüber zwielichtige Kreaturen und verweilende Geister bergen. Wenn Ihr unter dem Banner der Allianz marschiert, befindet Ihr Euch tief im Feindesland; Wachen der Verlassenen und Schreckenswachen werden Euch auf Sicht niederschlagen.",al={"sind die ruinen von lordaeron sicher","bin ich hier sicher","gefahr in lordaeron stehen"}},aac358a1={q="Werden mich die Wachen angreifen?",a="Todeswachen der Verlassenen und königliche Monstrositäten, die rund um die Ruinen stationiert sind, werden Reisende der Horde ignorieren oder beschützen, doch sie sind gegenüber Champions der Allianz brutal feindselig. Zudem lauern in den isolierten Korridoren und Dungeon-Flügeln der Ruinen oben feindselige Abtrünnige und Monster, die jeden angreifen, der ihren Weg kreuzt, ungeachtet der Loyalität.",al={"greifen unterstadt-wachen an","sind ruinen-wachen feindselig","greifen mich wachen an"}},e9ec8c01={q="Gibt es immer noch Geißel in der Nähe?",a="Ja. Während Sylvanas den Großteil der Geißel aus der Hauptstadt vertrieben hat, ist die Geißel gleich hinter den Grenzen in den Westlichen Pestländern noch stark verschanzt. Selbst in den dunkleren Nischen und vergessenen Untergeschossen dieser Ruinen halten sich noch geistlose Untote und Überbleibsel der Geißel auf, die nur darauf warten, jedes lebende Fleisch zu zerfetzen, das sich zu weit vorwagt.",al={"geißel in ruinen von lordaeron","ist die geißel in der nähe der unterstadt","gibt es dort geißel"}},["0a975308"]={q="Was ist das für eine Seuche, von der alle reden?",a="Sie sprechen von der Seuche des Untodes, einem schrecklichen biomagischen Ansteckungsherd, der vom Lichkönig und seinen Nekromanten entwickelt wurde. Durch den Kult der Verdammten über infiziertes Getreide in ganz Lordaeron verteilt, tötete sie jeden, der es innerhalb weniger Stunden verzehrte, und belebte ihre Leichen sofort als gehorsame, verrottende Knechte der Geißel wieder.",al={"was ist die seuche des untodes","welche seuche ist gemeint","lordaeron-seuche"}},["290f94a8"]={q="Wer hat die ursprüngliche Seuche erschaffen?",a="Die ursprüngliche Seuche wurde von den Schreckenslords der Brennenden Legion entwickelt und vom Lichkönig, Ner'zhul, perfektioniert, während er auf dem Frostthron in Nordend gefangen war. Um sie in Lordaeron freizusetzen, rekrutierte er den abtrünnigen Dalaran-Erzmagier Kel'Thuzad, der den Kult der Verdammten gründete und die Getreidevorräte vergiftete.",al={"wer erschuf die seuche des untodes","schöpfer der ursprünglichen seuche","wer machte die seuche"}},["89f62638"]={q="Stellt Sylvanas eine neue her?",a="Ja. Lady Sylvanas hat die Königliche Apothekergesellschaft damit beauftragt, eine 'neue Seuche' zu brauen. Ihr Ziel ist es, eine Biowaffe zu erschaffen, die stark genug ist, um sowohl die Geißel als auch die Lebenden gleichermaßen auszulöschen, um so das Überleben der Verlassenen und die Rache an Arthas zu sichern. Ihre geheimen Tests finden genau jetzt im Apothekarium unter uns statt.",al={"erschafft sylvanas eine seuche","neue seuche der verlassenen","neue seuche unterstadt"}},dcb566d2={q="Wer ist der Lichkönig und was will er?",a="Der Lichkönig ist der oberste Herrscher der Geißel, erschaffen aus dem gequälten Geist des Orc-Schamanen Ner'zhul, der auf dem Frostthron in Eis eingeschlossen war. Sein Ziel war es, Azeroth für die Brennende Legion weichzuklopfen, aber er hegte seine eigenen schrecklichen Ambitionen: alles sterbliche Leben auszurotten und es durch ein ewiges, vereintes Imperium des Untodes unter seinem absoluten mentalen Befehl zu ersetzen.",al={"wer ist der lichkönig","was will der lichkönig","motive des lichkönigs"}},["3a9893a7"]={q="Wo ist der Lichkönig jetzt?",a="Er regiert vom Frostthron auf dem Eiskronengletscher auf dem fernen, gefrorenen Kontinent Nordend aus. Nach Illidans Angriff, der sein eisiges Gefängnis zum Bersten brachte, rief der Lichkönig Arthas nach Nordend zurück, um ihre Geister zu verschmelzen und seine Macht zu bewahren, weit weg vom zerstörten Königreich Lordaeron.",al={"wo ist der lichkönig","standort des lichkönigs","wo ist der frostthron"}},["0138c577"]={q="Kontrolliert er immer noch die Verlassenen?",a="Nein. Als der Frostthron durch Illidans Zauberei gespalten wurde, begann der telepathische Griff des Lichkönigs zu brechen. Sylvanas und viele andere Untote erlangten ihren freien Willen zurück und lösten sich aus seinem kollektiven Geist. Obwohl er versucht, sie zurückzugewinnen, widerstehen die Verlassenen nun gewaltsam seinem Flüstern und kämpfen erbittert, um ihre Autonomie zu wahren.",al={"kontrolliert der lichkönig die verlassenen","kann der lichkönig die verlassenen befehligen","freier wille der verlassenen"}},["6a523c60"]={q="Wer ist der Scharlachrote Kreuzzug und warum hassen sie Untote?",a="Der Scharlachrote Kreuzzug ist ein Orden religiöser, menschlicher Fanatiker, der aus den zerschlagenen Überresten der Ritter der Silbernen Hand und den Rittern von Lordaeron gebildet wurde. Traumatisiert von der Seuche, die ihre Heimat zerstörte, sind sie von Paranoia zerfressen. In ihren Augen sind alle Untoten ausnahmslos Abscheulichkeiten, und jeder Lebende, der mit ihnen verkehrt, gilt als befleckt und ist zur Hinrichtung markiert.",al={"wer ist der scharlachrote kreuzzug","warum hasst der scharlachrote kreuzzug untote","scharlachroter kreuzzug lore"}},b59db3a3={q="Sind sie dieselben wie die Argentumdämmerung?",a="Nein, sie sind bittere Rivalen mit gemeinsamen Wurzeln. Beide gingen aus der Asche der Ritter der Silbernen Hand hervor, doch als der Scharlachrote Kreuzzug blinder Fanatik und Fremdenfeindlichkeit verfiel, spalteten sich gemäßigte Paladine ab, um die Argentumdämmerung zu gründen. Die Dämmerung heißt alle Völker willkommen und konzentriert sich darauf, das Land gegen die Geißel zu verteidigen, statt wahllos zu säubern.",al={"scharlachroter kreuzzug gegen argentumdämmerung","sind scharlachrote und argentumdämmerung gleich","unterschied zwischen scharlachroten und argentum"}},ca88b6f6={q="Greifen sie auch lebende Spieler an?",a="Ja. Der Scharlachrote Kreuzzug glaubt, dass jeder, der nicht ihr purpurrotes Wappen trägt, insgeheim die Seuche in sich trägt oder mit den Untoten kollaboriert. Ob Ihr ein Orc, ein Taure, ein Nachtelf oder ein menschlicher Soldat aus Sturmwind seid, ihre Fanatiker werden Euch als Träger der Verderbnis brandmarken und auf Sicht angreifen.",al={"greift der scharlachrote kreuzzug die allianz an","greifen scharlachrote lebende an","scharlachroter kreuzzug feindselig gegenüber lebenden"}},["861c7602"]={q="Was macht die Königliche Apothekergesellschaft da unten?",a="Diese finstere Gilde aus Apothekern und ehemaligen Magiern der Verlassenen operiert vom Apothekarium in der Unterstadt aus und arbeitet unermüdlich unter Lady Sylvanas' Dekret. Ihr Hauptauftrag ist die Entwicklung einer katastrophalen 'neuen Seuche', die sowohl die Geißel als auch die lebenden Völker auslöschen kann, wobei sie rücksichtslose Experimente durchführen, um die Vorherrschaft der Verlassenen zu sichern.",al={"was macht die königliche apothekergesellschaft","zweck der königlichen apothekergesellschaft","apotheker unterstadt"}},["3c47ce18"]={q="Experimentieren sie an Menschen?",a="Ja. Tief im Apothekarium sind gefangene Kreuzfahrer des Scharlachroten Kreuzzugs, Ghule der Geißel und verschiedene Bestien in Eisenkäfigen eingesperrt. Die Apotheker unterziehen diese Gefangenen schmerzhaften chemischen Cocktails und bösartigen Seuchenstämmen, um auszuwerten, wie schnell Fleisch verrottet und wie die Ansteckung sowohl lebende als auch nekrotische Physiologie beeinflusst.",al={"experimentiert apotheker an menschen","experimente der königlichen apothekergesellschaft","foltern unterstadt-apotheker menschen"}},f7d23701={q="Ist Arthas noch am Leben, und könnte ich jemals gegen ihn kämpfen?",a="Arthas ist nicht im sterblichen Sinne tot, sondern vollständig zu einem Todesritter-Champion der Geißel korrumpiert. Er ist weit über das Meer in Nordend, außerhalb der Reichweite von jedem in Lordaeron. Euer Kampf findet genau jetzt gegen die Bedrohungen statt, die hier verweilen: die lokalen Kommandeure der Geißel, der Scharlachrote Kreuzzug und die abtrünnigen Bestien, die diese Ruinen befallen.",al={"kann ich gegen arthas kämpfen","ist arthas am leben","werden wir arthas gegenüberstehen"}},["9fc2648e"]={q="Ist er jetzt der Lichkönig?",a="Flüstereien aus dem Norden behaupten, dass Arthas die Turmspitze von Eiskrone bestieg, um den Lichkönig aus Illidans Belagerung zu befreien, das Eis zerschlug, um den Helm der Herrschaft aufzusetzen und seine Seele mit Ner'zhul zu verschmelzen. Für die Welt im Allgemeinen bleibt der genaue Zustand Nordends in eisiges Geheimnis gehüllt, aber seine dunkle Präsenz lastet über allen Untoten.",al={"ist arthas der lichkönig","wurde arthas zum lichkönig","identität von arthas als lichkönig"}},["89a21402"]={q="Wie bin ich in den Ruinen von Lordaeron gelandet?",a="Ihr seid durch die zerbröckelnden äußeren Tore der gefallenen Hauptstadt in Tirisfal gegangen, direkt über den Aufzügen, die in die Unterstadt hinabführen. Ob Ihr einem militärischen Ruf gefolgt seid, Gerüchten über ungezügelte Schrecken nachgegangen seid, die an der Leiche des Königreichs kleben, oder feindliches Gebiet durchquert habt, um heilige Überbleibsel der Vergangenheit zurückzuerobern – Eure Reise führte Euch in die versiegelten, umkämpften Innenhöfe, wo die Schatten der Geißel und die Geister der alten Menschheit noch immer verweilen.",al={"wie kam ich hierher","wie landete ich hier","warum bin ich in den ruinen von lordaeron","wie bin ich hier angekommen"}},bb4abd7f={q="Was soll ich in den Ruinen von Lordaeron tun?",a="Ihr seid hier, um die Schrecken zu säubern, die in den Ruinen an der Oberfläche über der Hauptstadt der Verlassenen eitern. Für die Horde bedeutet das, abtrünnige Bestien der Geißel zu jagen, verlorene Insignien zurückzuholen und tödliche Gebräue für die Königliche Apothekergesellschaft zu testen. Für die Allianz ist es ein verdeckter Schlag, um angestammten Boden zu reinigen, heilige Erbstücke wie das Crest of Lordaeron zurückzuholen und wandernden, gequälten Geistern Trost zu spenden, die noch keinen Frieden gefunden haben.",al={"was mache ich hier","was ist meine mission hier","was soll ich in den ruinen tun","was ist mein ziel hier"}}},fp="18,278,27.503.0,22.413.0,25.302.1,48.174.0,61.277.0,23.179.0,49.228.0,61.384.1,54.227.0"}
P.entries["zone:scarlet"] = {n="Das Scharlachrote Kloster",s="In den nordöstlichen Hügeln von Tirisfal bietet Das Scharlachrote Kloster dem Scharlachroten Kreuzzug hinter befestigten Mauern Schutz. Einst war es ein friedliches Heiligtum und ein Zentrum der Gelehrsamkeit für die Kirche des Heiligen Lichts. Heute beherbergen seine vier Flügel Eiferer, die trainieren, Gefangene foltern und Krieg gegen Außenstehende führen.",h="In den nordöstlichen Hügeln von Tirisfal bietet Das Scharlachrote Kloster dem Scharlachroten Kreuzzug hinter...",kw={"waffenkammer","kathedrale","doan","friedhof","herod","library","mograine","scharlachroter kreuzzug","das scharlachrote kloster","tirisfal","whitemane"},ang={["class:Mage"]="Der Flügel Library birgt seltene historische und theologische Werke. Arkanist Doan, der bedeutendste Arkanist des Kreuzzugs, bewacht sie.",["class:Paladin"]="Das Scharlachrote Kloster war einst ein heiliges Zentrum der Priesterschaft von Lordaeron und ein Ort der Gelehrsamkeit. Sein Fall an den scharlachroten Fanatismus zeigt, wie Hingabe in Wahnsinn umschlagen kann.",["class:Priest"]="Das Scharlachrote Kloster begann als Sitz der Kirche des Heiligen Lichts. Seine prächtigen Kapellen zeigen heilige Macht, die von Sterblichen eingesetzt wird, die von Hass und Rache verdorben sind.",["race:Undead"]="An der Grenze von Tirisfal bedroht Das Scharlachrote Kloster die Verlassenen. Seine Spione reichen bis nach Todesend, und in seinen Verliesen werden gefangene Untote gefoltert."},sec={{t="Ein gefallener Zufluchtsort",b="Vor dem Dritten Krieg war Das Scharlachrote Kloster ein stolzer Sitz der Priesterschaft von Lordaeron, die sich der Gelehrsamkeit und Erleuchtung verschrieben hatte. Dann verwüstete die Geißel das Land. Die überlebenden Kreuzfahrer säuberten die Hallen von Untoten und Spinnen und machten aus den Archiven und Innenhöfen eine befestigte Garnison.\n\nTrauer und Furcht verhärteten sich zu Misstrauen. Der Scharlachrote Kreuzzug begann, jeden Außenstehenden als Träger der Seuche zu sehen, ob lebendig oder untot, Mensch oder andersartig. In ihren Augen müssen solche Feinde mit Feuer geläutert werden."},{t="Die vier Flügel",b="Hinter dem Grand Vestibule liegen vier Flügel. Auf dem Friedhof erheben sich gefallene Kreuzfahrer als untote Scheusale, während Folterer Gefangenen Geständnisse abpressen. Die Library birgt theologische und historische Werke, bewacht vom abtrünnigen Magier Arkanist Doan und seinen Hunden.\n\nIn der Waffenkammer bilden Waffenmeister wie Herod Rekruten zu disziplinierten Kriegern aus. Tief in der Festung liegt die Kathedrale, das Herz des Kreuzzugs. Von dort lenken seine Anführer ihren Feldzug durch den verheerten Norden."},{t="Der Fall des Hochinquisitors",b="Scharlachroter Kommandant Mograine befehligt das innere Heiligtum der Kathedrale an der Seite der wahren Herrin des Klosters, Hochinquisitor Whitemane. Whitemane kanalisiert das Heilige Licht und kann gefallene Champions wiedererwecken. Für ihre Anhänger lässt diese Macht die Garnison unbesiegbar erscheinen.\n\nWhitemanes Niederlage trifft die Führung des Kreuzzugs in Tirisfal. Sie zerstört den Anschein göttlicher Autorität, der den Eifer des Klosters nährt. Die Anführer des Kreuzzugs sind sterblich, und ihr Feldzug gegen die Verlassenen und die benachbarten Lande wird stark geschwächt."}},faq={{q="Warum ist der Scharlachrote Kreuzzug lebenden Abenteurern der Allianz feindlich gesinnt?",a="Der Scharlachrote Kreuzzug ist dem Wahnsinn und der Paranoia verfallen. Seine Mitglieder sehen jeden ohne ein karmesinrotes Wappenrock als möglichen Träger der Seuche der Geißel. Sie unterscheiden nicht zwischen Freund und Feind und glauben, jeder Außenstehende sei verdorben und müsse geläutert werden, bevor er die Verderbnis verbreitet.",al={"warum greifen scharlachrote menschen an","scharlachroter kreuzzug feindlich gegenüber allianz","warum sind sie wahnsinnig"}},{q="Was geschieht, wenn Ihr Hochinquisitor Whitemane besiegt?",a="Hochinquisitor Whitemanes Niederlage versetzt der Führung des Scharlachroten Kreuzzugs im Westen einen schweren Schlag. Als geistliche Führerin des Klosters erweckt sie die Gefallenen wieder und hält Kommandant Mograine an ihrer Seite im Kampf. Ihr Tod bringt die Garnison aus dem Gleichgewicht und schwächt ihre Bedrohung für die umliegende Region.",al={"was bedeutet whitemanes tod","lore zu whitemanes niederlage","ende der kathedrale"}},{q="Was ist der Scarlet Key und wo findet Ihr ihn?",a="Arkanist Doan bewahrt den Scarlet Key in seiner Geldkassette tief im Flügel Library hinter seinem Studierzimmer auf. Der Schlüssel öffnet die äußeren Tore der Flügel Waffenkammer und Kathedrale.",al={"wo ist der scarlet key","waffenkammer und kathedrale öffnen","klosterschlüssel"}},{q="Warum ist Arkanist Doan im Scharlachroten Kloster?",a="Arkanist Doan ist ein mächtiger menschlicher Magier, der dem Scharlachroten Kreuzzug dient. Er glaubt, dass arkane Magie nötig ist, um die Geißel aus Lordaeron zu tilgen. In seinem Studierzimmer bewacht er die Library des Klosters und den Scarlet Key.",al={"wer ist arkanist doan","doan lore","magier in der library"}},{q="Wer war Alexandros Mograine und wie hängt er mit diesem Ort zusammen?",a="Alexandros Mograine, der berühmte Aschenbringer, war ein legendärer Paladin der Silbernen Hand und einer der Gründer des Scharlachroten Kreuzzugs. Er gründete ihn gemeinsam mit Hochgeneral Abbendis und Großinquisitor Isillien. Sein Sohn Renault befehligt nun gemeinsam mit Hochinquisitor Whitemane die Kathedrale.",al={"mograine klostergeschichte","aschenbringer kloster","renault mograines vater"}},{q="Was unterscheidet den Flügel Friedhof so sehr vom Rest des Klosters?",a="Der Friedhof offenbart den Fanatismus des Klosters in einem noch düstereren Licht. Befrager Vishas leitet dort die Folterkammern. In vernachlässigten Krypten ernten oder manipulieren gefallene Zauberwirker wie Blutmagier Thalnos die ruhelosen Toten.",al={"warum sind die untoten auf dem friedhof","thalnos lore","befrager vishas"}}},fx={["0c05301c"]={q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist ein fanatischer militärischer Orden aus menschlichen heiligen Kriegern und Priestern, der aus den Überresten der Ritter der Silbernen Hand gebildet wurde. Verzehrt von Trauer und Hass nach der Geißelung von Lordaeron, haben sie sich ganz der Ausrottung der Untoten verschrieben und setzen ihre Mission mit extremer Rücksichtslosigkeit und Paranoia durch.",al={"wer ist der scharlachrote kreuzzug","was ist der scharlachrote kreuzzug","lore scharlachroter kreuzzug"}},b0ef06b1={q="Sind die Mitglieder des Scharlachroten Kreuzzugs Menschen?",a="Ja, ihre Ränge bestehen ausschließlich aus Menschen aus dem gefallenen Reich Lordaeron. Sie hegen eine heftige Intoleranz gegenüber allen nicht-menschlichen Völkern, ungeachtet von Bündnissen oder früheren Bindungen, und erachten Außenstehende als unwürdig oder von Natur aus durch die Seuche befleckt.",al={"nur menschen im kreuzzug","volk des kreuzzugs","ist der scharlachrote kreuzzug menschlich"}},["1402011d"]={q="Warum greife ich eine Kirche voller Paladine an?",a="Obwohl sie die Insignien heiliger Orden tragen und das Licht führen, sind die Kommandanten des Klosters in gewalttätigen Extremismus verfallen. Ob Ihr dem Ruf von Raleigh the Devout folgt, um die korrupte Führung des Ordens zu säubern, oder im Namen von Varimathras in der Unterstadt zuschlagt, um einen aggressiven Nachbarn vor seiner Haustür zu neutralisieren, Ihr seid dort, um ihre militärische Macht zu brechen.",al={"warum scharlachrotes kloster angreifen","warum paladine dort töten","grund für kampf im kloster"}},["18e8d4ac"]={q="Ist der Scharlachrote Kreuzzug tatsächlich böse?",a="Sie begannen mit einer edlen Sache – Lordaeron von der Geißel der Untoten zu befreien. Doch Trauma und Paranoia haben ihren Zweck völlig verzerrt. Sie foltern nun unschuldige Reisende, brandmarken jeden Außenstehenden als verseucht und schlachten jeden ab, der nicht ihren Wappenrock trägt, wodurch sie im Streben nach Läuterung jeden moralischen Verstand verlieren.",al={"ist scharlachroter kreuzzug böse","sind das die bösen","sind kreuzzügler böse"}},fe2faadd={q="Unterstützt die Allianz den Scharlachroten Kreuzzug?",a="Nicht offiziell. Während manche in Sturmwind Sympathien für die überlebenden heiligen Krieger von Lordaeron hegen mögen, hat die unterschiedslose Feindseligkeit des Kreuzzugs formelle Bindungen zerrissen. Abenteurer und Persönlichkeiten der Allianz wie Raleigh the Devout betrachten ihre derzeitigen Kommandanten als wahnsinnige Eiferer, deren Gräueltaten die Ehre des Lichts beschmutzen.",al={"unterstützt die allianz den kreuzzug","gehört kreuzzug zur allianz","allianz bindungen zum kreuzzug"}},ae07147f={q="Befindet sich die Anführerin des Klosters in der Kathedrale?",a="Ja. Sowohl der Scharlachrote Kommandant Mograine als auch Hoher Inquisitor Whitemane residieren in der Kapelle der Kreuzzügler tief im Flügel der Kathedrale, bewacht von einer inneren Garde eifriger Verteidiger.",al={"wo ist whitemane","ist whitemane in der kathedrale","ort des kathedralenbosses"}},["11700a05"]={q="Warum hasst der Scharlachrote Kreuzzug die Verlassenen so sehr?",a="Für den Kreuzzug sind alle Untoten Abscheulichkeiten, die aus der Seuche hervorgegangen sind, welche ihre Familien und ihre Heimat auslöschte. Sie machen keinen Unterschied zwischen den willenlosen Schergen der Geißel und den freien Verlassenen, die die Hauptstadt besetzt halten; beide werden als verrottende Usurpatoren angesehen, die in heiligem Feuer vollständig gereinigt werden müssen.",al={"kreuzzug gegen verlassene","warum hasst kreuzzug untote","fehde zwischen kreuzzug und verlassenen"}},["38169c8a"]={q="Waren die Scharlachroten Kreuzzügler und die Verlassenen einst dasselbe Volk?",a="Ja. Die meisten Kreuzzügler und Verlassenen waren Bürger, Soldaten oder Priester des Königreichs Lordaeron vor dem Dritten Krieg. Als die Seuche durch das Land fegte, wurden diejenigen, die starben und wieder auferstanden, zu Untoten, während die traumatisierten Lebenden flohen oder sich zusammenschlossen, wodurch ehemalige Nachbarn und Verwandte zu erbitterten, geschworenen Feinden wurden.",al={"kannten sich kreuzzügler und verlassene","waren beide bürger von lordaeron","überreste von lordaeron"}},["80c0e472"]={q="Woher kam der Scharlachrote Kreuzzug?",a="Der Kreuzzug entstand aus den überlebenden Rittern der Silbernen Hand und Soldaten Lordaerons, die von Hochlord Alexandros Mograine und General Abbendis angeführt wurden. Überwältigt vom Verlust ihres Königreichs, spalteten sich die überlebenden Anführer: Diejenigen, die unerbittlichen, kompromisslosen Fanatismus befürworteten, bildeten den Scharlachroten Kreuzzug, während Gemäßigte sich abspalteten, um die Argentumdämmerung zu gründen.",al={"ursprung des scharlachroten kreuzzugs","wie wurde kreuzzug gegründet","wer gründete kreuzzug"}},c4a70323={q="Was war die Silberne Hand?",a="Die Ritter der Silbernen Hand waren der legendäre heilige Orden der Paladine, der während des Zweiten Kriegs von Erzbischof Alonsus Faol und Uther der Lichtbringer gegründet wurde. Sie dienten als vorderste Vorkämpfer der Allianz und Lordaerons, bis Prinz Arthas ihre Reihen während der Invasion der Geißel zerschlug.",al={"was war die silberne hand","ritter der silbernen hand","paladine der silbernen hand"}},d5472427={q="Warum tötet der Scharlachrote Kreuzzug auch lebende Menschen?",a="Tiefe Paranoia hat den Bezug des Kreuzzugs zur Realität untergraben. Sie glauben, dass jeder Außenstehende ein heimlicher Träger der Untotenseuche sein könnte. Jeder, der nicht ihre Uniform trägt und sich ihrer starren Autorität unterwirft, wird als korrumpiert gebrandmarkt und zu Folter oder Tod verurteilt.",al={"warum lebende menschen töten","kreuzzug tötet menschen","warum töten sie ihresgleichen"}},b6568619={q="Ist der Scharlachrote Kreuzzug eine Bedrohung für Sturmwind?",a="Nicht direkt im Sinne einer geografischen Eroberung, da ihre Bemühungen in den nördlichen Ruinen von Lordaeron verankert sind. Ihr Wahnsinn und ihre Bereitschaft, jeden Reisenden zu ermorden, machen sie jedoch zu einer aktiven Gefahr für Bürger, Botschafter und Abenteurer der Allianz, die sich in die Nähe ihrer Gebiete wagen.",al={"ist kreuzzug eine bedrohung für die allianz","kreuzzug gegen sturmwind","bedrohung durch den kreuzzug"}},["6889160e"]={q="Warum will jeder, dass ich in Das Scharlachrote Kloster gehe?",a="Beide Fraktionen haben wichtige Interessen in Tirisfal. Die Verlassenen können eine schwer bewaffnete Festung voller Eiferer direkt vor ihrer Hauptstadt nicht dulden, während Vertreter der Allianz versuchen, heilige Texte zu bergen, gefährliche Abtrünnige zu unterdrücken und der wahnsinnig gewordenen Führung Gerechtigkeit widerfahren zu lassen.",al={"warum werde ich ins kloster geschickt","wer will das kloster tot","grund für kloster quests"}},["0c6b4a7d"]={q="Wofür ist Scarlet Monastery Library da?",a="Die Library, die das Athenaeum und die Gallery of Treasures umfasst, beherbergt alte Schriften aus Lordaeron, historische Aufzeichnungen und arkanes Wissen. Sie dient sowohl als intellektuelles Archiv als auch als abgeschiedenes Forschungsheiligtum, dem Arkanist Doan vorsteht.",al={"zweck des bibliotheksflügels","was machen sie in der bibliothek","athenaeum des scharlachroten klosters"}},["29dc31ee"]={q="Wofür werden die Flügel der Waffenkammer und der Kathedrale genutzt?",a="Die Waffenkammer dient als militärisches Herz des Kreuzzugs und beherbergt Trainingsgelände, Kasernen und Waffenlager, die von Herod dem Scharlachroten Champion beaufsichtigt werden. Die Kathedrale steht als höchstes geistiges Heiligtum und Befehlsstand, wo Mograine Elitetruppen drillt und Whitemane Predigten hält und die Präsenz des Kreuzzugs in Tirisfal koordiniert.",al={"wozu waffenkammer und kathedrale","zweck waffenkammer","zweck kathedrale"}},f04a1b7f={q="Wie bin ich im Scharlachroten Kloster gelandet?",a="Ihr seid in die weit nordöstlichen Hügel von Tirisfal gereist und durch das neblige Land zum befestigten Sitz des Scharlachroten Kreuzzugs vorgedrungen. Ob Ihr im Auftrag der Horde aus der Unterstadt heraufgekrochen seid, um eine Bedrohung durch Eiferer vor ihrer Haustür zu beseitigen, oder vom Vorgebirge des Hügellands nach Norden marschiert seid, um dem Ruf enttäuschter Kreuzzügler zu folgen, die die fanatische Führung des Klosters stürzen wollten, der Weg führte Euch unweigerlich vor diesen schwer bewachten Komplex.",al={"wie bin ich hierhergekommen","weg zum scharlachroten kloster","warum bin ich hier"}},be779d1d={q="Was soll ich im Scharlachroten Kloster tun?",a="Ihr seid hier, um die vier Flügel des Kreuzzugs zu durchbrechen und ihren Halt über die Region zu brechen. Je nachdem, wer Euch geschickt hat, jagt Ihr vielleicht gefallene Anführer wie den Scharlachroten Kommandanten Mograine und Hoher Inquisitor Whitemane, entdeckt verlorene Bände und Wissen in der Bibliothek, sammelt Herzen des Eifers für die Apothekervereinigung oder bergt heilige Artefakte und erschlagt korrupte Anführer, die jeden außerhalb ihrer Ränge als verseuchte Untote brandmarken.",al={"was mache ich hier","warum bin ich hier","meine mission hier"}},["3ffc247b"]={q="Was ist das Scharlachrote Kloster?",a="Das Scharlachrote Kloster liegt in den nordöstlichen Tirisfal und ist ein befestigtes Heiligtum sowie die wichtigste Bastion des Scharlachroten Kreuzzugs in der Region. Einst ein friedlicher Kathedralenkomplex, der dem Heiligen Licht und klerikalem Lernen gewidmet war, wurde die Festung in ein schwer bewaffnetes Hauptquartier, Trainingsgelände und ideologisches Bollwerk für den fanatischen Feldzug des Kreuzzugs gegen das Untodtum umgewandelt.",al={"was ist das scharlachrote kloster","scharlachrotes kloster lore","über das scharlachrote kloster"}},fd7417a7={q="War das Scharlachrote Kloster schon immer ihres?",a="Nein. Vor dem Fall von Lordaeron war es einfach als das Alte Kloster bekannt. Ursprünglich vom adligen Haus Godwyn gefördert, diente es als Erzbischofssitz und Priesterseminar unter Erzbischof Alonsus Faol. Nach der Verwüstung des Dritten Krieges befreiten überlebende Paladine seine Hallen von den verweilenden Geißel-Infestationen und benannten es in Scharlachrotes Kloster um.",al={"war das scharlachrote kloster immer kreuzzug","geschichte des scharlachroten klosters","wem gehörte das scharlachrote kloster früher"}},e7b85043={q="Wer hat das Scharlachrote Kloster erbaut?",a="Das Alte Kloster wurde als Zufluchtsort der Kirche des Heiligen Lichts unter der Schirmherrschaft des adligen Hauses Godwyn errichtet. Seine Bibliotheken und Archive wurden über Generationen von Archivaren wie Blake Godwyn kuratiert und standen bis zum Zusammenbruch des Königreichs als stolzes Zentrum des Priestertums und der Paladinausbildung in Lordaeron.",al={"wer baute das kloster","ursprünge des klosters"}},fbd0569e={q="Wer hat das Kommando über das Scharlachrote Kloster?",a="Die militärische Garnison der Festung untersteht Scharlach-Kommandant Renault Mograine, der eine ergebene Streitmacht von Kriegern befehligt. Die wahre geistliche und doktrinäre Herrscherin des Komplexes ist jedoch Hochinquisitorin Weißsträhne, eine mächtige Priesterin, die imstande ist, die Gefallenen wiederzuerwecken, damit sie in ihrem Namen kämpfen.",al={"wer fuehrt das scharlachrote kloster an","wer leitet das kloster","anfuehrer des scharlachroten klosters"}}},fp="17,291,18.495.0,14.492.0,31.517.1,66.284.0,55.301.1,46.170.0,46.213.0,57.280.1,74.218.0"}
P.entries["zone:searinggorge"] = {n="Sengende Schlucht",s="In der Sengenden Schlucht schürft der Dunkeleisenzwergen-Klan in einem Land, das einst mit dem grünen Rotkammgebirge verbunden war. Ragnaros der Feuerfürst versengte es, als er vor über zwei Jahrhunderten beschworen wurde. Nun überwacht die Thoriumbruderschaft die Sklavenminen des Klans im Kessel.",h="In der Sengenden Schlucht schürft der Dunkeleisenzwergen-Klan in einem Land, das einst mit dem grünen...",kw={"der schwarzfels","kessel","dunkeleisenzwergen-klan","ragnaros","sengende schlucht","die schlackengrube","steinwerkpass","thoriumbruderschaft","thoriumspitze"},ang={["class:Rogue"]="Als Schurke könnt Ihr mit Eurer geschulten Fingerfertigkeit das Tor des Steinwerkpasses zwischen Loch Modan und der Schlucht öffnen.",["faction:Alliance"]="Als Reisender der Allianz findet Ihr den Steinwerkpass versperrt, damit die Dunkeleisenzwerge von den friedlichen Zwergensiedlungen in Loch Modan getrennt bleiben. Die Allianz entsendet tapfere Abenteurer zu Angriffen in die Schlucht.",["faction:Horde"]="Als Reisender der Horde könnt Ihr Kargath als Stützpunkt nutzen. Die Horde hat eine Überlandroute in die Schlucht geschlagen, um Informationen über den Schwarzfels zu sammeln und die Unternehmungen der Dunkeleisenzwerge in Khaz Modan zu stören.",["profession:Mining"]="Als Bergbauer könnt Ihr in der vulkanischen Ödnis und den tiefen Ausgrabungen der Schlackengrube nach reichen Adern aus Mithril, Echtsilber und begehrtem Dunkeleisenerz suchen.",["race:Dwarf"]="Als Zwerg aus Eisenschmiede seht Ihr in der Sengenden Schlucht eine bittere Erinnerung an den Krieg der drei Hämmer und den verhängnisvollen Leichtsinn des Dunkeleisenzwergen-Klans. Dessen Ausgrabungen bedrohen nun die südlichen Zugänge nach Khaz Modan."},sec={{t="Eine versengte Ödnis",b="Vor dem Krieg der drei Hämmer war die Sengende Schlucht ein grüner, hügeliger Teil der Rotkammgebirgskette. Dieses Land ging vor über zweihundertdreißig Jahren verloren. Zauberer-Thane Thaurissan beschwor Ragnaros aus den Tiefen unter der Welt herauf, in der Hoffnung, eine Niederlage in einen Sieg zu verwandeln. Der Feuerfürst riss die Erde entzwei, türmte den Schwarzfels auf und legte die große Dunkeleisenstadt Thaurissan in rauchende Trümmer. Asche, Schwefel und Vulkanglas bedeckten das nördliche Tal."},{t="Der Kessel und die Schlackengrube",b="Nach dem Fall ihrer alten Hauptstadt bemächtigten sich die Dunkeleisenzwerge der Schlucht, um die Rohstoffe für ihre Kriegsmaschinerie zu gewinnen. Im Herzen des Tals gräbt sich der Kessel als gewaltiger Tagebau tief in den Fels. In seinen unteren Bereichen bildet die Schlackengrube einen brutalen unterirdischen Minenkomplex.\n\nAufseher der Dunkeleisenzwerge und schwerfällige Kriegsgolems zwingen gefangene Feinde zur Sklavenarbeit. Sie fördern Eisen, Mithril und seltenes Dunkeleisenerz aus glühendem Gestein. Aufsteigende Lava und umherstreifende Bestien bedrohen die Minenarbeiter auf Schritt und Tritt."},{t="Thoriumbruderschaft und umkämpfte Pfade",b="Die Thoriumspitze thront auf den nördlichen Klippen über der Ausgrabung. Die Thoriumbruderschaft hält diesen befestigten Außenposten, seit sie sich von ihren Verwandten im Schwarzfels losgesagt hat. Ihre Meisterhandwerker bieten Reisenden neutrale Zuflucht, wenn sie die Unternehmungen der Dunkeleisenzwerge untergraben oder seltene Schmelzkomponenten beschaffen.\n\nDer Zugang zur Schlucht bleibt streng kontrolliert. Die Allianz versperrt den Steinwerkpass nach Loch Modan mit schweren Eisentoren, während Expeditionen der Horde aus dem nahen Kargath einen schmalen Pfad durch das östliche Ödland geschlagen haben, um das Gebiet auszukundschaften."}},faq={{q="Warum ist die Sengende Schlucht verbrannt und mit Asche bedeckt?",a="Vor über zweihundertdreißig Jahren versuchte der Dunkeleisen-Zauberer-Thane Thaurissan während des Kriegs der drei Hämmer, eine übernatürliche Macht zu beschwören, um einer Niederlage zu entgehen. Stattdessen rief er Ragnaros den Feuerfürsten herbei. Der Ausbruch zerschmetterte den südlichen Teil des Rotkammgebirges, türmte den Schwarzfels auf und verbrannte die umliegenden Täler zu Sengender Schlucht und Brennender Steppe.",al={"warum ist es verbrannt","geschichte der sengenden schlucht","wie entstand die sengende schlucht"}},{q="Welche Zwerge leben an der Thoriumspitze?",a="Die Zwerge an der Thoriumspitze gehören zur Thoriumbruderschaft, einer unabhängigen Fraktion von Dunkeleisenzwergen, die sich von ihren Verwandten im Reich unter dem Schwarzfels losgesagt haben. Von ihrem Lager auf der Thoriumspitze aus arbeiten sie als Meisterschmiede und Kunsthandwerker. Sie tauschen Wissen und Handwerksgeheimnisse mit Reisenden, die ihnen gegen die Dunkeleisenstreitkräfte weiter unten helfen.",al={"zwerge an der thoriumspitze","wer ist die thoriumbruderschaft","geschichte der thoriumbruderschaft"}},{q="Was geschieht im Kessel?",a="Der Dunkeleisenzwergen-Klan kontrolliert den Kessel, einen gewaltigen Tagebau, in dem sich die unterirdische Schlackengrube befindet. Aufseher und Kriegsgolems zwingen gefangene Gefangene zur Sklavenarbeit und lassen sie wertvolle Erze abbauen, darunter Dunkeleisenerz, für die großen Schmieden im Schwarzfels.",al={"was ist der kessel","geschichte der schlackengrube","was bauen die dunkeleisenzwerge ab"}},{q="Wie gelangt Ihr von Loch Modan in die Sengende Schlucht?",a="Der Steinwerkpass von Loch Modan ist durch ein schweres, verschlossenes Tor versperrt, das von Gebirgsjägern aus Eisenschmiede bewacht wird. Ihr könnt den Schlüssel zur sengenden Schlucht durch einen offiziellen Auftrag für Kurator Thorius erhalten, einen erfahrenen Schurken bitten, das Schloss zu knacken, oder das Tor umgehen, indem Ihr den offenen Pfad südlich von Kargath im Ödland nehmt.",al={"tor des steinwerkpasses","wie öffnet man das tor zur sengenden schlucht","schlüssel zur sengenden schlucht"}},{q="Warum interessiert sich die Horde für die Sengende Schlucht?",a="Die Horde nutzt das nahe Kargath im Ödland als Stützpunkt. Ihre Befehlshaber haben einen Gebirgspass in die Schlucht geschlagen, um die Truppenbewegungen der Dunkeleisenzwerge auszukundschaften und Wege zum strategisch wichtigen Schwarzfels zu sichern.",al={"warum ist die horde hier","verbindung zwischen kargath und der schlucht","horde presence"}},{q="Gibt es in der Sengenden Schlucht Eingänge zu Dungeons oder Schlachtzügen?",a="In der Sengenden Schlucht gibt es keine direkten Instanzportale, doch ihr südlicher Eingang führt in den Schwarzfels. Im Berg liegen die Schwarzfelstiefen, die Schwarzfelsspitze und die tiefen Gänge zum Geschmolzenen Kern.",al={"instanzen in der sengenden schlucht","dungeons in der sengenden schlucht","wo ist der geschmolzene kern"}}},fp="13,249,20.456.0,29.498.0,39.549.0,51.376.0,44.359.0,33.260.0,50.303.0,45.225.0,62.207.0"}
P.entries["zone:shadowfang"] = {n="Burg Shadowfang",s="Im südlichen Silberwald bietet Burg Shadowfang Erzmagier Arugal und den von ihm beschworenen Worgen Schutz. Das alte Anwesen der Silberleins ist von wilden Bestien überrannt, und die ermordeten Verteidiger spuken dort. Das nahe Lohenscheit bleibt an einen schrecklichen Fluch gebunden.",h="Im südlichen Silberwald bietet Burg Shadowfang Erzmagier Arugal und den von ihm beschworenen Worgen Schutz.",kw={"arugal","fenrus","lohenscheit","sfk","shadowfang","silberlein","silberwald","grüntal","worgen"},ang={["class:Mage"]="Als Magier mahnt Euch die Tragödie von Burg Shadowfang, was geschehen kann, wenn ein Zauberer der Kirin Tor Wesen von jenseits dieser Welt beschwört und sich damit über jede sterbliche Kontrolle hinwegsetzt.",["class:Paladin"]="Als Paladin könnt Ihr in Kommandant Grüntals ruhelosem Geist eine traurige Erinnerung an gefallene Paladin-Verteidiger sehen, deren heilige Schwüre durch den Tod verdreht wurden.",["class:Warlock"]="Als Hexenmeister könnt Ihr Euch von den dunklen Energien der Burg, den Leerwandlern und den dämonischen Zaubern angezogen fühlen, ebenso wie von der Suche nach uralten Relikten wie der Kugel von Soran'ruk.",["faction:Horde"]="Die Verlassenen sehen in Arugals vorrückenden Rudeln eine unmittelbare Gefahr für ihr junges Gebiet im Silberwald. Todespirscher und die Königliche Apothekervereinigung machen die Burg zu einem vorrangigen Ziel."},sec={{t="Der Fall der Dynastie Silberlein",b="Burg Shadowfang gehörte einst der Familie Silberlein, und der fromme Kommandant Grüntal sollte sie verteidigen. Während des Dritten Krieges fegte die Geißel durch Lordaeron, und Dalarans Zauberer fielen in Scharen. Um die Toten aufzuhalten, widersetzte sich Erzmagier Arugal verzweifelt der Führung der Kirin Tor und nutzte die Forschungen des Magiers Ur.\n\nEr beschwor Worgen von jenseits dieser Welt, um das Blatt zu wenden. Die Bestien fielen über die Untoten her, entzogen sich dann jeder sterblichen Kontrolle und stürmten den südlichen Silberwald. Baron Silberlein und sein Hofstaat wurden niedergemetzelt und dazu verdammt, neben den Monstern, die ihre Heimat überrannten, durch die steinernen Hallen zu spuken."},{t="Arugals Kinder",b="Schuld und Wahnsinn trieben Arugal hinter die blutbefleckten Zinnen. Er nannte die gefräßigen Wolfsmenschen seine geliebten Kinder und gab der Burg den Namen Burg Shadowfang. Wolfsrudel und Schattenhunde gedeihen in ihren steinernen Lagern unter Züchtern wie Wolfsmeister Nandos. Arugals gewaltige Wolfsbestie, Fenrus der Verschlinger, wacht über sie.\n\nDer Fluch reichte über die Mauern hinaus. Das nahe Lohenscheit bleibt in einem schrecklichen Kreislauf gefangen: Tagsüber gehen die Bewohner als Menschen umher, nachts jagen sie als gefräßige Worgen unter dem Mond. Sie sind an den verrückten Erzmagier auf den Höhen gebunden."},{t="Der Schlag der Verlassenen",b="Fürstin Sylvanas Windläufer sah in Arugal eine ernste Bedrohung für ihre Herrschaft im Silberwald. Sie entsandte die Königliche Apothekervereinigung und Elite-Todespirscher, um den Ursprung des Worgenfluchs zu finden. Infiltrationstrupps erlitten in den Kerkern brutale Verluste. Schließlich drangen Helden der Horde, die dem Ruf aus dem Grabmal folgten, in den höchsten Turm ein und streckten Arugal nieder.\n\nMit Arugals Tod verlor das Rudel seinen Herrn. Der Geist, der die Ausbreitung der Bestien in der Wildnis lenkte, war gebrochen. Sein Kopf wurde zum Beweis für Lordaerons Vergeltung."}},faq={{q="Was geschieht, wenn Erzmagier Arugal besiegt wird?",a="Arugals Tod beseitigt die Macht, die die Worgenrudel im südlichen Silberwald kontrolliert. Auf Befehl von Fürstin Sylvanas Windläufer bringen Abenteurer der Horde seinen abgetrennten Kopf zu Dalar Morgenweber im Grabmal. Wilde Bestien und geisterhafte Überreste in der Burg und den umliegenden Wäldern bleiben eine Gefahr für Reisende.",al={"folgen von arugals tod","lore zu arugals tod","was geschieht nach arugals tod"}},{q="Warum beschwor Arugal die Worgen?",a="Während des Dritten Krieges erlitten Dalarans Armeen verheerende Niederlagen gegen die Geißel. Gefallene Zauberer erhoben sich als untote Soldaten für den Lichkönig. Auf der Suche nach einer Waffe, die das Blatt wenden konnte, nutzte Arugal die Forschungen des Magiers Ur, um Worgen von jenseits dieser Welt zu beschwören. Er glaubte, ihre Wildheit könne die Geißel aufhalten.",al={"warum wurden worgen beschworen","arugals motivation","dalaran beschwört worgen"}},{q="Wer war Baron Silberlein?",a="Baron Silberlein war der menschliche Adlige, der vor dem Dritten Krieg die Burg beherrschte und über das nahe Lohenscheit wachte. Als Arugals beschworene Bestien außer Kontrolle gerieten, stürmten sie die Festung und töteten den Baron, seine Familie und seine Wachen. Silberleins rachsüchtiger Geist spukt noch immer in den großen Speisesälen und ist dazu verdammt, neben den Monstern zu wandeln, die ihn erschlugen.",al={"lore zu baron silberlein","ursprünglicher herr von burg shadowfang"}},{q="Warum sind die Bewohner von Lohenscheit tagsüber freundlich?",a="Arugals dunkle Magie ließ die Bewohner des nahen Lohenscheit tagsüber als Menschen zurück, klaren Verstandes und friedlich gegenüber Reisenden der Allianz. Bei Sonnenuntergang setzt der Fluch ein und verwandelt die gesamte Bevölkerung in wilde Worgen, die dem verrückten Erzmagier in der Burg treu ergeben sind.",al={"menschen aus lohenscheit","fluch von lohenscheit","warum verwandelt sich lohenscheit in worgen"}},{q="Wer ist Kommandant Grüntal?",a="Kommandant Grüntal war ein Paladin und der Offizier, der für die Verteidigung von Burg Silberlein verantwortlich war. Als die Worgen die Festung überrannten, kämpfte er bis zum Tod. Sein ruheloser Geist patrouilliert noch immer durch die oberen Gänge und hält selbst im Untod an seiner Pflicht als Soldat fest.",al={"lore zu grüntal","geisterhafter paladinboss"}},{q="Was ist Das Buch von Ur?",a="Das Buch von Ur enthält die Forschungen Urs, eines Erzmagiers aus Dalaran, der Wesen von jenseits dieser Welt untersuchte, darunter die Worgen. Arugal nutzte die Schriften für seine verhängnisvollen Beschwörungen. Die Königliche Apothekervereinigung in der Unterstadt sucht das Buch, um die wolfartigen Kreaturen und ihre seltsame Magie zu verstehen.",al={"quest um das buch von ur","lore zu ur"}}},fx={["4bfedcc6"]={q="Was ist Burg Shadowfang?",a="Burg Shadowfang ist eine heimgesuchte Burg, die auf den hohen Klippen des südlichen Silberwalds thront und auf Lohenscheit hinabblickt. Ursprünglich als Silberleins Burg bekannt, diente sie einst als Festung der Allianz, die die Grenzen nahe Gilneas bewachte. Heute steht sie korrumpiert und in dunkle Nebel gehüllt als Festung für Erzmagier Arugal und seine wilden Worgen-Nachkommen.",al={"was ist burg shadowfang","erzähle mir von shadowfang","lore burg shadowfang"}},["1d3b32c5"]={q="Wer hat Burg Shadowfang erbaut?",a="Die Festung war der Sitz von Baron Silberlein, einem Adligen, dessen Familie lange vor dem Dritten Krieg die Herrschaft über die umliegenden Ländereien und Lohenscheit innehatte. Unter seiner Herrschaft stand sie als stolze Bastion der Menschen, bewacht von Kommandant Grüntal und vereidigten Soldaten des Reiches.",al={"wer baute burg shadowfang","ursprung von shadowfang","wer schuf shadowfang"}},["7c8f83a0"]={q="War der Silberwald ein Gebiet von Lordaeron?",a="Ja. Der Silberwald bildete den rauen westlichen Rand des Königreichs Lordaeron und grenzte im Süden an Gilneas. Seine Anwesen und Siedlungen waren an die Allianz gebunden, bevor die Seuche das Königreich zerschlug.",al={"war dies lordaeron","geschichte von silberwald und lordaeron","gehörte der silberwald zu lordaeron"}},["91da6ffd"]={q="Warum ist der Silberwald heute so verlassen?",a="Zwischen der Invasion der Geißel, dem Schließen des großen Walls durch Gilneas und Arugals tobendem Worgenfluch wurde die lebende Bevölkerung abgeschlachtet, verflucht oder floh ins Ausland. Die wenigen, die geblieben sind, klammern sich verzweifelt an umkämpfte Weiler wie Lohenscheit.",al={"warum ist der silberwald leer","verlassener silberwald","warum ist der silberwald eine ruine"}},["2ee73ad9"]={q="Warum hat Arugal überhaupt Worgen in den Silberwald gebracht?",a="Als die untote Geißel nach Süden marschierte, starben die Zauberer von Dalaran in Scharen, nur um im Dienst des Lichkönigs wieder aufzuerstehen. Arugal glaubte, dass durch extra-dimensionale Beschwörungen herbeigerufene Verbündete die Untoten dort überwältigen könnten, wo konventionelle sterbliche Armeen gescheitert waren.",al={"warum worgen in den silberwald bringen","grund für arugals worgenbeschwörung","warum hier worgen beschwören"}},["671a79f5"]={q="Wen wollte Arugal aufhalten?",a="Er beschwor sie speziell, um die untoten Armeen der Geißel zu vernichten, die anschwollen, indem sie jeden Soldaten und Zauberer, der in der Schlacht fiel, abschlachteten und wiedererweckten.",al={"gegen wen kämpfte arugal","arugals feind","gegen wen beschwor arugal worgen"}},eeb57b84={q="Hat Arugals Plan gegen die Geißel funktioniert?",a="Taktisch ja – die Worgen zerfleischten die Untoten mühelos. Aber strategisch war es eine Katastrophe. Die wilden Wolfsmenschen ließen sich nicht kontrollieren, wandten sich gegen menschliche Soldaten und Zauberer gleichermaßen und verbreiteten einen tödlichen Fluch in der gesamten Region.",al={"besiegten worgen die geißel","funktionierte die beschwörung","worgenerfolg gegen geißel"}},["2bfe7e75"]={q="Sind die Worgen in der Burg dieselben, die Lohenscheit überrannt haben?",a="Ja. Arugals Rudel, einschließlich der Rudel von Shadowfang und Moonrage, haben denselben verfluchten Ursprung. Die Bestien, die durch die Hallen der Burg streifen, sind Arugals eigene Brut und eng mit dem Fluch verbunden, der die Dorfbewohner unterhalb plagt.",al={"stammen shadowfang worgen aus lohenscheit","lohenscheit worgen shadowfang","dasselbe worgenrudel"}},b78b86f3={q="Was ist mit den Dorfbewohnern von Lohenscheit passiert?",a="Die Dorfbewohner überlebten den Dritten Krieg nur, um von Arugals dunkler Magie gefangen genommen zu werden. Obwohl sie bei Tageslicht wie normale Menschen erscheinen, verwandelt der Sonnenuntergang sie in wilde, blutrünstige Worgen, die dem wahnsinnigen Erzmagier treu ergeben sind.",al={"was passierte mit den leuten aus lohenscheit","schicksal von lohenscheit","stadtbewohner von lohenscheit"}},["39fbc1b5"]={q="Sind die Dorfbewohner von Lohenscheit auch verflucht?",a="Ja. Sie sind Opfer des lykanthropischen Worgenfluchs. Bei Tag bewahren sie ihren Verstand und handeln friedlich mit Wanderern der Allianz; bei Nacht raubt ihnen der Fluch ihre Menschlichkeit und macht sie zu reißenden Bestien.",al={"ist lohenscheit verflucht","fluch von lohenscheit","sind dorfbewohner infiziert"}},d6e89a88={q="Wer sind die Geister in Burg Shadowfang?",a="Es sind die ruhelosen Geister von Baron Silberlein, Kommandant Grüntal und der ehemaligen Dienerschaft der Burg. Sie wurden während des überraschenden Worgenangriffs erschlagen und ihre Seelen sind durch Qual und Gram an die zerstörten Steine gebunden.",al={"geister in shadowfang","wer sind die geister in burg shadowfang","gespenster in shadowfang"}},["0a399272"]={q="Sind die Geister die alten Diener der Burg?",a="Ja. Von geisterhaften Köchen und schattenhaften Begleitern bis hin zu ehemaligen Wachen sind die spektralen Verteidiger, die durch die Hallen wandern, die abgeschlachteten Bediensteten, die Baron Silberlein einst zu Lebzeiten dienten.",al={"sind geister ehemalige diener","geister der burghofdiener","silberleins diener"}},["3f532512"]={q="Warum können die Geister nicht ruhen?",a="Das pure Entsetzen ihres Massakers in Verbindung mit der schweren Schattenmagie, die die Burg durchdringt, verhindert ihre Erlösung. In ihrer ewigen Qual schlagen sie mit unheiliger Wut gegen jeden lebenden Eindringling, der ihre Gräber stört.",al={"warum sind geister ruhelos","warum spuken geister in shadowfang","ruhelose geister shadowfang"}},["59c03d52"]={q="Arbeitet Arugal für die Geißel?",a="Nein. Arugal verachtet die Geißel; er beschwor die Worgen gerade deshalb, um sie zu vernichten. Obwohl er wahnsinnig geworden ist, gilt seine Loyalität seinen 'Kindern' und nicht dem Lichkönig.",al={"ist arugal geißel","arbeitet arugal für die geißel","dient arugal der geißel"}},["99eb22e3"]={q="Kontrolliert der Lichkönig Arugal?",a="Nein. Arugals Wahnsinn ist völlig selbstverschuldet und entspringt Schuldgefühlen und Magie, nicht dem telepathischen Griff des Frostthrons. Er agiert unabhängig als Herr seines eigenen dunklen Reiches.",al={"kontrolliert der lichkönig arugal","lichkönig arugal","arugal gedankenkontrolle"}},["501c4a9b"]={q="Endet der Fluch, nachdem Arugal tot ist?",a="Nein. Arugals Tod enthauptet zwar die Führung von Burg Shadowfang, aber der Worgenfluch hat bereits das Blut der Sterblichen im gesamten Wald infiziert. Das Leiden besteht noch lange fort, nachdem der Erzmagier gefallen ist.",al={"endet der worgenfluch","verschwindet der worgenfluch","ist lohenscheit geheilt"}},["6cb01af1"]={q="Werden die Verlassenen Burg Shadowfang einnehmen?",a="Momentan begnügen sich die Verlassenen damit, die Bedrohung für ihre südliche Grenze zu beseitigen und das Buch von Ur wiederzuerlangen. Die Ruine bleibt eine düstere, heimgesuchte Hülle, die über die Wälder blickt, statt ein befestigter Außenposten zu werden.",al={"werden verlassene shadowfang einnehmen","erobern verlassene shadowfang","wer kontrolliert shadowfang danach"}},["3f22b397"]={q="Wie bin ich in Burg Shadowfang gelandet?",a="Ihr seid der Spur des Schreckens durch den Silberwald bis zu den Klippen oberhalb von Lohenscheit gefolgt. Wenn Ihr der Horde dient, wurdet Ihr wahrscheinlich vom Grabmal oder der Unterstadt nach Süden geschickt, um die Worgenplage zu untersuchen, die die Region erstickt. Wenn Ihr für die Allianz kämpft, haben Euch Gerüchte über die verfluchten Wälder, verlorene heilige Relikte oder den gefallenen Kirin Tor tief in das feindliche Gebiet der Verlassenen geführt. Ihr seid die windigen Klippen hinter den Toren von Lohenscheit hinaufgestiegen, seid an reißenden Wolfsbestien vorbeigedrungen und durch das uralte Tor der Burg gebrochen, um das Versteck des wahnsinnigen Erzmagiers zu betreten.",al={"wie kam ich hierher","wie erreiche ich burg shadowfang","wie fand ich diesen ort"}},["31a8c552"]={q="Was soll ich in Burg Shadowfang tun?",a="Euer oberstes Ziel ist es, Euch durch die heimgesuchten Hallen zu kämpfen und Erzmagier Arugal niederzustrecken, um seine verdrehte Herrschaft über den Silberwald zu beenden. Unterwegs müsst Ihr die Worgen niedermetzeln, die durch die Höfe streifen, und die ruhelosen Geister von Baron Silberlein und seiner erschlagenen Dienerschaft zur Ruhe betten. Wenn Ihr im Namen der Verlassenen handelt, habt Ihr die Aufgabe, das Buch von Ur zu bergen und das Schicksal der vermissten Todespirscher zu entdecken, die hineingeschickt wurden. Helden, Paladine und Hexenmeister der Allianz suchen nach verlorenen Artefakten der Macht, heiligen Waffen und Vergeltung für die dunkle Magie, die das Land vergiftet.",al={"was mache ich hier","warum bin ich hier","was ist mein ziel in burg shadowfang"}},efb02893={q="Warum ist Burg Shadowfang voller Worgen?",a="Als die heraufbeschworenen Worgen sich aus der Kontrolle der Kirin Tor befreiten, wüteten sie durch den Wald und belagerten die Burg. Sie metzelten Baron Silberlein und seinen gesamten Haushalt nieder. Vom Schuldgefühl über das, was er entfesselt hatte, in den Wahnsinn getrieben, adoptierte Erzmagier Arugal die Bestien als seine eigenen 'Kinder', beanspruchte die Ruine für sich und benannte sie in Burg Shadowfang um.",al={"warum sind hier worgen","burg shadowfang worgen grund","warum worgen drinnen"}},["7d419eb0"]={q="Warum interessiert sich die Horde für diese Burg?",a="Die Worgen, die aus der Burg streifen, sind eine unkontrollierte Plage, die den Griff der Verlassenen über den Silberwald bedroht. Von ihrer Basis im Grabmal aus erkannten die Anführer der Verlassenen, dass die umliegenden Lande niemals sicher sein werden, solange Arugal seine wolfsartigen Schrecken von den Burgzinnen aus befehligt.",al={"warum interessiert sich die horde für burg shadowfang","interesse der horde an burg shadowfang","warum nach burg shadowfang"}},d6cbfc07={q="Wer hat Euch hierher geschickt?",a="Kommandeure der Verlassenen im Grabmal ordneten den Angriff an, um Arugal zu eliminieren und das Schicksal ihrer vermissten Späher aufzudecken. Währenddessen entsandte die Königliche Apothekervereinigung in der Unterstadt Agenten, um Urs magische Forschungen aus der Library des Erzmagiers zu bergen.",al={"wer schickte mich nach burg shadowfang","questgeber für burg shadowfang","wer will arugal tot sehen"}},a794fece={q="Ist dies jetzt Land der Verlassenen?",a="Die Verlassenen beanspruchen den nördlichen Silberwald, doch ihr Griff nach dem Süden ist heiß umkämpft. Burg Shadowfang bleibt fest unter Arugals Herrschaft, während verbliebene Geißel, wilde Bestien und überlebende menschliche Siedlungen der Dunklen Fürstin die Herrschaft über die Region streitig machen.",al={"ist silberwald land der verlassenen","gehört dies sylvanas","gebiet der verlassenen burg shadowfang"}},b918d1de={q="Wer hat in Burg Shadowfang das Sagen?",a="Die Burg untersteht vollständig Erzmagier Arugal. Wahnsinnig geworden durch den Dritten Krieg, herrscht er über die oberen Türme, flankiert von seinen monströsen Worgen und seinem gewaltigen Schoßworg, Fenrus, und befehligt die Burg durch dunkle Hexerei.",al={"wer herrscht in burg shadowfang","wer hat drinnen das sagen","meister von burg shadowfang"}},ecad974c={q="Ist Arugal der Boss der Burg?",a="Ja. Arugal ist der Meister von Burg Shadowfang. Er orchestriert den Worgenbefall im gesamten Silberwald und thront an der Spitze des Burgturms als dessen höchste Autorität.",al={"ist arugal der boss","endboss burg shadowfang","meister arugal"}},["3b086809"]={q="Hatte jemand vor ihm das Sagen?",a="Baron Silberlein herrschte über die Burg, als sie noch ein Stützpunkt der Allianz war. Er und seine Familie regierten die Burg, bis Arugals Worgen während des Dritten Krieges die Mauern durchbrachen und jeden darin niedermetzelten.",al={"wer herrschte vor arugal","früherer meister von burg shadowfang","früherer herr der burg"}},["7f02160f"]={q="Woher kommen die Worgen?",a="Es handelt sich um gefräßige, extra-dimensionale Wesen, die aus einer anderen Ebene gerissen wurden. Verzweifelt versucht, die Geißel während des Dritten Krieges aufzuhalten, wandte Arugal sich der verbotenen Forschung des Magiers Ur aus Dalaran zu und beschwor diese jenseitigen Bestien nach Azeroth.",al={"woher kamen die worgen","ursprung der worgen","quelle der worgen"}},["4fa8e666"]={q="Hat Arugal die Worgen alleine beschworen?",a="Arugal führte die Beschwörung gegen den ausdrücklichen Rat seiner Gefährten in Dalarans Kirin Tor durch. Sich stark auf die Schriften im Buch von Ur verlassend, zwang er die Entitäten über die Ebenengrenzen hinweg.",al={"handelte arugal allein","wer half beim beschwören der worgen","beschwörung arugal"}},a6a018be={q="Können die Worgen kontrolliert werden?",a="Kaum, und nur durch dunkle Magie. Obwohl beschworen, um als Verbündete gegen die Untoten zu dienen, wandten sie sich sofort gegen ihre Beschwörer. Arugal schafft es nur, einige von ihnen zu lenken, weil sein gebrochener Verstand sie als Familie betrachtet und er Verzauberungen nutzt, um zerbrechlichen Gehorsam zu erzwingen.",al={"können worgen kontrolliert werden","kontrolle der worgen","sind worgen zahm"}},["24ed31c3"]={q="Was ist mit den The Todespirscher Adamant und Vincent passiert?",a="Die The Todespirscher Adamant und Vincent schlichen auf Befehl aus dem Grabmal in Burg Shadowfang, um Arugals Stärke auszukundschaften. Sie wurden von den Verteidigern der Burg gefangen genommen; Vincent wurde eingekerkert und im Innenhof hingerichtet, während Adamant in den Kerkern gefangen auf Rettung wartet.",al={"adamant und vincent","was ist mit den the deathstalkers passiert","späher der verlassenen burg shadowfang"}},cc7bdeae={q="Warum wurden die The Todespirscher in die Burg Shadowfang geschickt?",a="Das Kommando der Verlassenen benötigte präzise Informationen über den tierischen Befall, der ihre südliche Front bedrohte. Adamant und Vincent erhielten den Auftrag, die Burg zu infiltrieren, Arugals wahre Truppenstärke zu bestimmen und den Weg für einen entscheidenden Schlag zu ebnen.",al={"warum the deathstalkers schicken","auskundschaften von burg shadowfang","mission der the deathstalkers"}},["4cfa60a4"]={q="Leben die The Todespirscher noch?",a="Vincent ist tot, er wurde nach seiner Gefangennahme erschlagen. Adamant jedoch bleibt tief in den unteren Haltezellen der Burg eingekerkert, lebendig genug, um jedem Horde-Abenteurer zu helfen, der zu ihm durchdringt.",al={"leben vincent und adamant noch","überlebten die the deathstalkers","schicksal der the deathstalkers"}},c6ee2849={q="Was sind The Todespirscher?",a="Die The Todespirscher sind die elitären verdeckten Assassinen und Schurken der Verlassenen. Spezialisiert auf Verstohlenheit, Spionage und plötzlichen Tod, agieren sie als die stillen Dolche der Unterstadt an den Grenzen von Lordaeron.",al={"was ist ein the deathstalker","wer sind die the deathstalkers","the deathstalkers der verlassenen"}},["40c5e48b"]={q="Wem unterstehen die The Todespirscher?",a="Sie unterstehen einer strikten Befehlskette, die von Offizieren und Kommandeuren der Verlassenen geleitet wird, welche in den Gebieten stationiert sind, und dienen letztlich dem Willen des herrschenden Rats der Unterstadt.",al={"führung der the deathstalkers","wer befehligt die the deathstalkers","wer führt die the deathstalkers"}},["63a10ab0"]={q="Arbeiten die The Todespirscher direkt für Sylvanas?",a="Ja. Jeder The Deathstalker ist der Banshee-Königin, Fürstin Sylvanas Windläufer, verschworen. Sie bilden ihr persönliches Geheimdienstnetzwerk und spüren Bedrohungen für ihre untoten Anhänger mit freiem Willen in ganz Lordaeron auf.",al={"dienen the deathstalkers sylvanas","sylvanas the deathstalkers","the deathstalkers banshee-königin"}},f68cd02f={q="Warum schickt mich jeder in die Burg Shadowfang?",a="Weil die anfängliche Aufklärung der Verlassenen mit der Gefangennahme ihrer elitären The Todespirscher völlig zusammengebrochen ist. Arugals Versteck ist zu tückisch für normale Infanterie, es erfordert bewährte Abenteurer, die sich sowohl durch Bestien als auch durch rachsüchtige Geister kämpfen können.",al={"warum schickt man mich nach burg shadowfang","warum mache ich das","warum held in burg shadowfang"}},ebbfbfb0={q="Bin ich der Einzige, der das tun kann?",a="Die Ressourcen der Verlassenen im Silberwald sind extrem knapp, da sie gegen Faulhufgnolle, Geißel-Versprengte und Patrouillen aus Dalaran kämpfen müssen. Da ihre eigenen Vorauskommandos kompromittiert sind, sind Ihr und Eure Verbündeten die einzige Streitmacht, die in der Lage ist, die Burg zu stürmen.",al={"bin ich der einzige","niemand sonst zur säuberung von burg shadowfang","einzige wahl"}},["0f7e4add"]={q="Haben andere vor mir versucht, die Burg zu stürmen?",a="Ja. Neben den gescheiterten The Deathstalker-Spähern betraten Kirin Tor-Ermittler wie Zauberer Ashcrombe die Burg, um Arugal zu beurteilen, nur um gefangen genommen oder in ihren verfluchten Hallen eingesperrt zu werden.",al={"haben andere burg shadowfang versucht","frühere versuche burg shadowfang","wer hat es vorher versucht"}},["13386e7c"]={q="Was ist mit dem Silberwald passiert?",a="Der Silberwald war einst ein grünes Reich mit hoch aufragenden, silbern borkigen Kiefern, das von der Allianz bewacht wurde. Als die Geißel während des Dritten Krieges über Lordaeron hinwegfegte, ließ die Plage die Wälder verwelken, Ernten wurden verbrannt und die Bevölkerung massakriert oder hinter den Greymane-Wall getrieben.",al={"geschichte silberwald","was geschah mit silberwald","warum ist der silberwald so"}}},fp="15,249,31.608.0,17.575.0,19.531.1,46.300.1,33.314.0,26.353.0,59.258.0,28.263.0,23.300.0"}
P.entries["zone:shendralas"] = {n="Shen'dralas",s="Zentauren, Ausgestoßene und Stacheleber kämpfen um Shen'dralas, südöstlich von Desolace. Zwischen Feralas und Mulgore erheben sich uralte Ruinen inmitten schroffer Felsen.",h="Zentauren, Ausgestoßene und Stacheleber kämpfen um Shen'dralas, südöstlich von Desolace.",kw={"rückzugsort der borstennacken","desolace","evenshade overlook","feralas","lake dumont","front der magram","mulgore","zuflucht der ausgestoßenen","shen'dralas","tal der knochen"},ang={["faction:Alliance"]="Als Reisende der Allianz durchquert Ihr eine abgelegene, umkämpfte Wildnis mit alternativen Routen zwischen Feralas und dem zentralen Kalimdor. Auf der Reise ist große Wachsamkeit geboten.",["faction:Horde"]="Als Mitglied der Horde findet Ihr Shen'dralas gleich hinter den südlichen Ausläufern Mulgore. Wenn Ihr die Magram und die Stacheleber dort in Schach haltet, schützt Ihr die Grenzen der Horde.",["race:NightElf"]="Als Nachtelf erinnert Shen'dralas' Name an die alte Überlieferung der Hochgeborenen von Eldre'Thalas. Wächterinnen, die im südlichen Kalimdor vor leichtfertigem Umgang mit arkaner Magie auf der Hut sind, beobachten das Gebiet mit Interesse.",["race:Tauren"]="Als Tauren grenzt Shen'dralas an Mulgore und Desolace. Die Angriffe der Stacheleber und Zentauren entlang seiner Höhen bedrohen nahegelegene, angestammte Jagdgründe."},sec={{t="Ein Grenzland in Aufruhr",b="Shen'dralas liegt in den Höhen südöstlich von Desolace, zwischen Mulgore und Feralas. Seine zerklüfteten Pässe und verborgenen Enklaven bieten Gruppen Schutz, die fern der großen Hauptstädte der Fraktionen ums Überleben kämpfen. Am Evenshade Overlook halten manche von abgelegenen Höhen aus Wache. In der Zuflucht der Ausgestoßenen suchen andere Schutz, wo sie in Vergessenheit geraten können."},{t="Zentauren, Stacheleber und uralte Ruinen",b="Uralte Ruinen erinnern an das Erbe der Hochgeborenen, das hinter Shen'dralas' Namen steht, doch das Land ist alles andere als friedlich. Fehden der Zentauren greifen auf die Front der Magram über und halten altes Blutvergießen entlang der Grenzen am Leben. Stacheleber der Borstennacken halten befestigtes Gebiet am Rückzugsort der Borstennacken. Reisende treffen in den Schluchten auf umkämpftes Gebiet."},{t="Das Tal der Knochen",b="Das Tal der Knochen führt nach Nordwesten in Richtung Desolace und bietet den wichtigsten Überlandweg nach Shen'dralas. Sonne und Wind haben den Durchgang gebleicht. Seine Knochen erinnern an die gewaltsamen Kämpfe, die noch immer durch diese Felsen ziehen."}},faq={{q="Wo liegt Shen'dralas?",a="Shen'dralas liegt südöstlich von Desolace, zwischen Feralas und Mulgore. Reisende zu Fuß gelangen gewöhnlich von Desolace aus durch das Tal der Knochen hinein.",al={"wo liegt shen'dralas","shen'dralas lage","wie kommt man nach shen'dralas"}},{q="Wird Shen'dralas von der Allianz oder der Horde kontrolliert?",a="Weder die Allianz noch die Horde beherrscht Shen'dralas. Umherziehende Zentauren, feindselige Stacheleber, Ausgestoßene und abgelegene Lager machen es zu einem umkämpften Grenzland.",al={"ist shen'dralas von der horde kontrolliert","ist shen'dralas von der allianz kontrolliert","wem gehört shen'dralas"}},{q="Welche wichtigen Siedlungen oder Wahrzeichen gibt es hier?",a="Die wichtigsten Wahrzeichen sind das Tal der Knochen, der Rückzugsort der Borstennacken, der Evenshade Overlook, die Front der Magram, die Zuflucht der Ausgestoßenen und Shen'dralas' zentrale Weite.",al={"teilgebiete von shen'dralas","wahrzeichen in shen'dralas","sehenswürdigkeiten in shen'dralas"}},{q="Warum gibt es hier Zentauren?",a="Die Gebietskriege der Zentauren reichen von den Ebenen Desolaces entlang der Front der Magram bis nach Shen'dralas. Dort gerät der Klan mit örtlichen Verteidigern und rivalisierenden Fraktionen aneinander.",al={"zentauren in shen'dralas","front der magram","warum sind die magram hier"}},{q="Was ist der Rückzugsort der Borstennacken?",a="Der Rückzugsort der Borstennacken ist ein befestigter Außenposten, den Stacheleber der Borstennacken halten. Sie haben sich an den Rändern der Zone einen erbittert umkämpften Stützpunkt gesichert.",al={"rückzugsort der borstennacken","stacheleber in shen'dralas"}},{q="Welche Verbindung besteht zwischen dieser Zone und Lake Dumont?",a="Es ist keine Verbindung bekannt. Shen'dralas hat eigene Wahrzeichen, etwa das Tal der Knochen und die Zuflucht der Ausgestoßenen.",al={"lake dumont","geschichte der karte von shen'dralas"}}},fp="11,141,23.322.0,36.313.0,19.222.0,29.144.0,55.152.0,45.155.0,27.159.0,28.132.0,57.114.0"}
P.entries["zone:silithus"] = {n="Silithus",s="Silithus liegt unter sich ausbreitenden Silithidenschwärmen, die der Zirkel des Cenarius im Auge behält. Die Wüste birgt die uralten Ruinen von Ahn'Qiraj, die vor tausend Jahren hinter dem Skarabäuswall versiegelt wurden. Druiden halten die Schwärme und die Kultisten des Hammer des Zwielichts in Schach.",h="Silithus liegt unter sich ausbreitenden Silithidenschwärmen, die der Zirkel des Cenarius im Auge behält.",kw={"ahn'qiraj","burg cenarius","bau des ashischwarms","bau des regalschwarms","bau des zoraschwarms","die skarabäushöhe","der skarabäuswall","silithiden","silithus","hammer des zwielichts"},ang={["class:Druid"]="Als Druide werdet Ihr nach Silithus gerufen, wo der Zirkel des Cenarius seine südlichen Operationen in Kalimdor unterhält. Helft dabei, die Verderbnis des Landes einzudämmen, und stellt Euch den unnatürlichen Brutstätten, die das Gleichgewicht der Natur bedrohen.",["profession:Herbalism"]="Trotz der rauen Wüste von Silithus gedeihen seltene Pflanzen: Bergsilberweisling, Traumblatt, Sonnengras und der begehrte Schwarze Lotus.",["profession:Mining"]="In den trockenen Felsen und Insektentunneln von Silithus lagern einige der reichsten Thoriumvorkommen der Welt. Seltene, von Schlamm bedeckte Adern verbergen sich tief in den Bauten der Silithiden.",["race:NightElf"]="Als Nachtelf wandelt Ihr auf dem düsteren Boden, auf dem Eure Vorfahren im Krieg der Sandstürme bluteten. Tausende opferten ihr Leben, um die Tore von Ahn'Qiraj zu versiegeln."},sec={{t="Die Wüstengrenze",b="Ihr betretet Silithus vom Krater von Un'Goro aus durch einen breiten, felsigen Pass in dessen nordwestlicher Ecke. Der Dschungel weicht Dünen, zerklüftetem Gestein und hoch aufragenden Bauten. Wasser ist knapp, und der Wind trägt das Summen von Insektenflügeln über den Sand. Nahe der Mitte der Wüste bietet die Burg Cenarius Reisenden, Forschern und Kriegern Schutz. Der Zirkel des Cenarius unterhält diesen Außenposten als einzigen Zufluchtsort in der feindseligen Einöde."},{t="Echos des Wandelsands",b="Vor tausend Jahren kämpften Nachtelfen und die großen Drachenschwärme verzweifelt, um die Qiraji im Krieg der Sandstürme zurückzudrängen. Die Qiraji waren ein insektenartiges Imperium, das aus der uralten Aqiri-Zivilisation hervorging.\n\nAls sich der Sieg als unerreichbar erwies, sperrten die Verteidiger die Schwärme mit dem Skarabäuswall und der verzauberten Skarabäushöhe in ihrer Festung ein. Die Tore hielten stand, doch Silithiden gruben sich durch Tunnel darunter hindurch und bildeten in der ganzen Wüste gewaltige Kolonien, darunter den Bau des Ashischwarms, den Bau des Zoraschwarms und den Bau des Regalschwarms."},{t="Ein Sturm zieht auf",b="Der Hammer des Zwielichts hat mehrere Außenposten in Silithus befestigt. Seine Kultisten beschwören elementare Schrecken und verehren die dunkle Macht unter Ahn'Qiraj. Beobachter des Zirkels des Cenarius verfolgen die Ausbreitung der Silithidenkolonien und halten Wache gegen die uralte Bedrohung hinter dem Skarabäuswall."}},faq={{q="Wie komme ich zu Fuß nach Silithus?",a="Reist durch den Krater von Un'Goro bis in seine nordwestliche Ecke. Nahe einer Biegung des gewundenen Flusses führt eine ansteigende Schotterstraße zwischen zwei markanten Felssäulen hindurch und durch die Kraterwand nach Silithus.",al={"eingang nach silithus","wie kommt man nach silithus","weg durch silithus"}},{q="Was ist der Skarabäuswall?",a="Der Skarabäuswall ist eine gewaltige verzauberte Barriere im Süden von Silithus. Vor tausend Jahren errichteten Nachtelfen und die Drachenschwärme ihn während des Krieges der Sandstürme, um das Qiraji-Imperium in Ahn'Qiraj einzuschließen.",al={"tor von ahn'qiraj","der skarabäuswall","die große mauer in silithus"}},{q="Wer leitet die Burg Cenarius?",a="Der Zirkel des Cenarius hat die Burg Cenarius gegründet und leitet sie. Seine Druiden und verbündeten Wächter beobachten die Silithidenschwärme, untersuchen uralte Ruinen und heißen neutrale Reisende von Allianz und Horde willkommen.",al={"wer ist in der burg cenarius","fraktion der burg cenarius","burg cenarius freundlich"}},{q="Was sind die riesigen Insektenhügel in der ganzen Region?",a="Die gewaltigen Hügel sind die großen unterirdischen Bauten der Silithiden: der Bau des Ashischwarms, der Bau des Zoraschwarms und der Bau des Regalschwarms. Jeder birgt ein weitläufiges Tunnelsystem und eigene insektenartige Kasten, die dem Willen der Mächte hinter Ahn'Qiraj dienen.",al={"bauten in silithus","insektenbauten silithus","bau des ashischwarms bau des zoraschwarms"}},{q="Was treibt der Hammer des Zwielichts hier?",a="Der Hammer des Zwielichts unterhält mehrere befestigte Lager in Silithus, darunter das Basislager der Twilight und den Twilight-Posten. Seine Kultisten vollziehen finstere Riten, um Elementare zu beschwören, und verehren die uralten, bösartigen Wesen, die hinter dem Skarabäuswall begraben liegen.",al={"kultisten des hammer des zwielichts in silithus","twilight-außenposten silithus","warum ist der hammer des zwielichts in silithus"}}},fp="8,245,19.408.0,28.509.0,18.272.0,33.207.0,24.219.0,23.205.0,49.212.0,41.243.0"}
P.entries["zone:silverpine"] = {n="Silberwald",s="Patrouillen der Verlassenen halten den Silberwald, wo rivalisierende Mächte die Wälder an Lordaerons Westküste bedrohen. Die Seuche der Geißel hat den Wald gezeichnet, und Worgen, verseuchte Gnolle sowie feindselige menschliche Enklaven gefährden Reisende.",h="Patrouillen der Verlassenen halten den Silberwald, wo rivalisierende Mächte die Wälder an Lordaerons...",kw={"mühlenbern","arugal","insel fenris","der greymane-wall","lohenscheit","rot hide","das grabmal","shadowfang","silberwald"},ang={["class:Mage"]="Mühlenbern und der Abstieg des Erzmagiers Arugal in den wolfsartigen Wahnsinn machen den Silberwald zu einer düsteren Warnung vor Magie des Kirin Tor, die katastrophal fehlgeht.",["faction:Alliance"]="Entdecker der Allianz finden einen feindseligen Wald vor. Mühlenbern beherbergt nur eine schwache Garnison aus Dalaran, und die Bewohner von Lohenscheit sind verflucht.",["race:Undead"]="Der Silberwald ist die Frontlinie der Verlassenen südlich von Tirisfal. Die Königliche Apothekervereinigung testet hier neue Mixturen, während die Deathguard gegen verbliebene Agenten der Geißel kämpft."},sec={{t="Eine verwunschene Grenze",b="Der Silberwald erstreckt sich zwischen Tirisfal und dem versiegelten Greymane-Wall. Einst ein üppiges Wunder Lordaerons, ist er seit dem Dritten Krieg dahingewelkt. Geisterhafte Nebel ziehen zwischen sterbenden Kiefern mit silberner Rinde hindurch, während verfallene Gehöfte verlassen in der Wildnis liegen.\n\nIm Norden grenzt Tirisfal an den Wald, und im Osten erstreckt sich der Lordameresee entlang seiner Küste. Im Süden schirmt der Greymane-Wall Gilneas vom Chaos jenseits davon ab. Die Verlassenen halten ihren zentralen Außenposten beim Grabmal und kämpfen darum, die Wälder gegen Feinde von allen Seiten zu sichern."},{t="Rivalisierende Enklaven und die Geißel",b="Der Anspruch der Verlassenen auf den Silberwald wird von lebenden und untoten Mächten angefochten. Auf der Insel Fenris im Osten führt Thule Rabenklaue Überreste der Geißel an und befehligt seuchenverwirrte Rot Hide-Gnolle, die den nördlichen Ackerbaugebieten zusetzen. Im Süden halten menschliche Magier aus Dalaran Mühlenbern, eine befestigte Siedlung, in der sie mystische Forschungen betreiben und sich der Expansion der Verlassenen widersetzen.\n\nBeim Grabmal führen die Königliche Apothekervereinigung und Hochexekutor Hadrec einen brutalen Feldzug gegen diese Bedrohungen. Sie testen auch neue, hoch ansteckende Seuchen."},{t="Die Worgen und Shadowfang",b="Burg Shadowfang ragt über den südwestlichen Wäldern des Silberwalds auf und wird vom wahnsinnigen Dalaran-Erzmagier Arugal gehalten. Einst war sie der Sitz von Baron Silberlein. Während des Dritten Krieges beschwor Arugal Wolfsbestien aus einer anderen Dimension, um die Geißel zurückzuschlagen. Die Bestien wandten sich gegen ihre Beschwörer und verbreiteten einen lykanthropischen Fluch in den südlichen Wäldern.\n\nBei Tageslicht wirken die menschlichen Dorfbewohner von Lohenscheit gewöhnlich und gehen ihren Pflichten nach. Unter dem Nachthimmel verwandeln sie sich in wilde Worgen."}},faq={{q="Was ist der Greymane-Wall an der Südgrenze?",a="Der Greymane-Wall ist eine gewaltige Steinbarriere, die König Genn Greymane errichten ließ, um Gilneas vom übrigen Lordaeron abzuschotten. Als die Geißel während des Dritten Krieges den Kontinent verwüstete, verschloss Gilneas seine Tore und verweigerte Hilfe von außen. Die Gebiete nördlich der Mauer, darunter der südliche Silberwald, mussten allein zurechtkommen.",al={"warum gibt es eine riesige mauer","geschichte des greymane-walls","tor nach gilneas"}},{q="Warum greifen die Dorfbewohner von Lohenscheit nachts an?",a="Der Worgenfluch des Erzmagiers Arugal befällt die Bewohner von Lohenscheit. Tagsüber behalten sie ihre menschliche Gestalt und gehen ihrem Alltag nach; der Allianz gegenüber bleiben sie freundlich. Mit dem Aufgang des Mondes verwandelt der Fluch sie in wilde, blutdürstige Worgen, die jeden in ihrer Nähe angreifen.",al={"geheimnis von lohenscheit","worgen in lohenscheit","warum sind die menschen in lohenscheit nachts feindselig"}},{q="Wer ist Thule Rabenklaue?",a="Thule Rabenklaue ist ein mächtiger Nekromant im Dienst der Geißel. Von Burg Fenris auf der Insel Fenris im Lordameresee aus befehligt er Legionen von Untoten und beeinflusst die verseuchten Rot Hide-Gnolle im östlichen Silberwald. Sie bedrohen die Ostflanke der Verlassenen.",al={"wer führt die insel fenris","geschichte von thule ravenclaw","geißel auf der insel fenris"}},{q="Warum besetzt Dalaran Mühlenbern?",a="Magier aus Dalaran halten Mühlenbern unter der Führung von Erzmagier Ataeric. Von dem Dorf aus überwachen die menschlichen Magier die Bewegungen der Verlassenen, erforschen die magischen Leiden des Waldes und versuchen, den nahegelegenen Worgenausbruch einzudämmen, der sich von Burg Shadowfang ausbreitet.",al={"magier in mühlenbern","warum ist die allianz in mühlenbern","dalaran im silberwald"}},{q="Was ist das Grabmal?",a="Das Grabmal ist der wichtigste militärische Außenposten und Verkehrsknotenpunkt der Verlassenen im Silberwald. Unter Hochexekutor Hadrec dient es als Basis für Deathguard-Patrouillen, Deathstalker-Späher und die Königliche Apothekervereinigung, während sie darum kämpfen, den Wald zu sichern.",al={"hordenstadt im silberwald","wo ist der flugpunkt","geschichte des grabmals"}},{q="Können Allianzspieler im Silberwald Quests erledigen?",a="Im Silberwald gibt es keine Sammelplätze der Allianz und keine befreundeten Städte; die örtlichen Aufgaben sind allein für die Horde bestimmt. Abenteurer der Allianz kommen gewöhnlich auf dem Weg von Süderstade hierher, um Burg Shadowfang zu erkunden oder feindliche Streitkräfte der Verlassenen zu bekämpfen.",al={"ist der silberwald nur für die horde","allianzquests im silberwald","kann die allianz in den silberwald"}}},fx={["21fc6836"]={q="Was ist der Silberwald?",a="Der Silberwald ist ein riesiges, uraltes Waldgebiet entlang der rauen Westküste von Lordaeron, direkt südlich von Tirisfal und im Osten begrenzt durch den Lordameresee. Einst ein üppiger und grüner Wald, geschützt von der Allianz, ist er heute in geisterhafte Nebel, krankhaft blasse Kiefern und eine unheimliche Stille gehüllt, die nur durch entferntes Heulen unterbrochen wird. Die Verlassenen halten den Norden vom Grabmal aus, aber ihr Anspruch wird ständig von den Überresten der Geißel, wilden Rotkamm-Gnollen, Zauberern aus Dalaran und den verfluchten Worgen von Burg Shadowfang bestritten.",al={"was ist der silberwald","erzähl mir vom silberwald","silberwald lore"}},["01503e92"]={q="Was ist im Silberwald passiert?",a="Der Silberwald ähnelte einst der unberührten Wildnis des Hinterlands, aber der Dritte Krieg ruinierte ihn. Als die Geißel des Lichkönigs nach Süden zog, brannten untote Armeen Gehöfte nieder, schlachteten die ländliche Bevölkerung ab und verseuchten das Land mit der Seuche des Untods. König Genn Greymane schloss Gilneas hinter seiner massiven Mauer ab und gab nördliche Gebiete wie Lohenscheit und Mühlenbern auf. Um die Geißel abzuwehren, entfesselte Erzmagier Arugal wilde Worgen, doch der Fluch breitete sich außer Kontrolle aus. Mit dem Zusammenbruch von Lordaeron wurden die verseuchten Wälder zu einem umkämpften Schlachtfeld.",al={"silberwald geschichte","was passierte im silberwald","untergang des silberwalds"}},b9edb2aa={q="Wer lebte hier vor den Verlassenen?",a="Vor dem Dritten Krieg wurde der Silberwald von menschlichen Bauern, Bergleuten und Soldaten aus Lordaeron und Gilneas bewohnt. Südliche Siedlungen wie Lohenscheit und Mühlenbern blieben draußen, als sich Gilneas hinter dem Greymane-Wall verschanzte. Die Insel Fenris beherbergte eine geschäftige Militärgarnison von Lordaeron in Burg Fenris. Die meisten dieser ehemaligen Bewohner kamen während der Invasion der Geißel ums Leben, flohen nach Süden hinter den versiegelten Wall oder erlagen dem Untod und dem Worgenfluch.",al={"wer lebte früher im silberwald","ehemalige bewohner des silberwalds","frühere einwohner des silberwalds"}},["5b2addb4"]={q="Warum sieht der Wald so tot aus?",a="Der Wald trägt die tiefen, bleibenden Narben des Dritten Krieges. Silberwald markiert das südlichste Ausmaß, in dem die Seuche der Untoten der Geißel die Flora sichtbar verdarb, die Lebenskraft aus dem Boden zog und die uralten Kiefern mit ihrer silbernen Rinde bleich, kränklich und ihre verdorbenen Nadeln abwerfend zurückließ. Da Lordaeron zerstört und Gilneas abgeriegelt wurde, blieben keine Pfleger zurück, um die verwüsteten Haine zu heilen oder die verbrannten Äcker zu bestellen, wodurch kalte Nebel und Fäulnis über die Wälder zogen.",al={"warum stirbt der silberwald","warum sieht der silberwald tot aus","verdorrte bäume silberwald"}},["67376895"]={q="Ist der Silberwald gefährlich?",a="Äußerst gefährlich. Wilde Raubtiere wie verseuchte Bären, riesige Spinnen und grausame Worgs schleichen unter den Bäumen. Die seuchenbefallenen Rotkammgnolle schlachten Reisende entlang der Straßen brutal ab, während menschliche Magier aus Dalaran Mühlenbern gegen das Eindringen der Horde befestigen. Im Süden terrorisieren die wilden Mondzorn-Worgen unter dem Einfluss von Erzmagier Arugal die Täler. Außerhalb des befestigten Zufluchtsorts Das Grabmal erfordert das Überleben ständige Wachsamkeit.",al={"wie gefährlich ist der silberwald","bedrohungen im silberwald","ist es hier sicher"}},["6dcc337b"]={q="Warum hat die Horde mich in den Silberwald geschickt?",a="Ihr wurdet von Tirisfal aus nach Süden geschickt, um die Grenze der Verlassenen zu verstärken. Die Unterstadt betrachtet den Silberwald als entscheidend für die Sicherung ihrer Südgrenze, doch ihr Halt ist zerbrechlich und überdehnt. Hochexekutor Hadrec und die Todeswache benötigen fähige Recken, um eindringende Nekromanten der Geißel zurückzuschlagen, feindselige Gnolle zu eliminieren, Dalarans verdeckte Manöver zu überwachen und die blutrünstigen Worgen einzudämmen, die zu überrennen drohen.",al={"warum bin ich im silberwald","horde ankunft silberwald","warum hierher geschickt"}},ab9ff98b={q="Ist dies noch Land der Verlassenen?",a="Die Verlassenen beanspruchen den Silberwald als souveränes Territorium der Unterstadt, doch ihre Kontrolle ist stark umstritten. Während sie im nördlichen Silberwald und im befestigten Zufluchtsort Das Grabmal festen Besitzstand wahren, haben sie keine unbestrittene Herrschaft über den gesamten Wald. Feindselige Rotkammgnolle beherrschen die östlichen Gewässer, Dalaran-Zauberer besetzen Mühlenbern und Arugals wilde Worgen dominieren die südwestlichen Regionen.",al={"gehört silberwald den verlassenen","wer kontrolliert den silberwald","territorium der verlassenen silberwald"}},["858ebaa5"]={q="Wer hat Das Grabmal erbaut?",a="Vor dem Dritten Krieg war Das Grabmal einfach ein großer, ruhiger menschlicher Friedhof mit einer Krypta am Straßenrand, die von den Bewohnern Lordaerons errichtet wurde, um ihre Toten entlang der westlichen Hauptstraße beizusetzen. Nach dem Fall von Lordaeron beschlagnahmten die überlebenden Verlassenen das Bestattungsgelände und bauten die Krypta zu einem befestigten Militäraußenposten, einer Karawanenstation und einem logistischen Hauptquartier für ihre südlichen Operationen um.",al={"wer hat das grabmal gebaut","ursprung das grabmal","geschichte das grabmal"}},f51f7d3d={q="Warum haben die Verlassenen ihre Basis im Grabmal?",a="Das Grabmal liegt verteidigungstechnisch günstig in den westlichen Hügeln und bietet den Verlassenen einen natürlichen Aussichtspunkt über die Küste und die Hauptstraße. Positioniert zwischen der Geißel im Osten, Dalaran im Südosten und wilden Worgen im Süden, dient es als einziger sicherer Außenposten, von dem aus Patrouillen der Todeswache und Forscher der Königlichen Apothekervereinigung die Verteidigung koordinieren und die Route nach Tirisfal schützen können.",al={"warum sind verlassene im das grabmal","basis der verlassenen das grabmal warum","bedeutung von das grabmal"}},["0581536d"]={q="Wer ist Hochexekutor Hadrec?",a="Hochexekutor Hadrec ist der militärische Kommandant der Operationen der Verlassenen im Silberwald und im Grabmal stationiert. Streng und pragmatisch leitet er die Todeswache und die Späher der Todespirscher bei der Befriedung der Wildnis an, deckt versteckte Bedrohungen auf und koordiniert Angriffe gegen feindselige Kräfte wie Thule Rabenklaue und die Rotkammgnolle.",al={"hadrec","wer ist hadrec","hochexekutor hadrec silberwald"}},ff53d58c={q="Wem ist Hochexekutor Hadrec unterstellt?",a="Hadrec ist direkt Fürstin Sylvanas Windläufer, der Banshekönigin der Verlassenen, und ihrem Oberkommando in der Unterstadt unterstellt. Als hochrangiger Offizier der Todeswache besteht sein Mandat darin, die Grenzen ihres neugeborenen Königreichs zu sichern und jede Macht zu eliminieren, die die Souveränität der Verlassenen gefährden könnte.",al={"wer ist hadrecs chef","hadrecs vorgesetzter","wem berichtet hadrec"}},["6c73f41e"]={q="Wer sind die Rotkammgnolle und warum sind sie hier?",a="Die Rotkammgnolle sind ein bösartiger Gnollklan, der den Silberwald bewohnt, hauptsächlich von Insel Fenris aus operiert und die Ufer des Lordameresee durchstreift. Im Gegensatz zu gewöhnlichen Gnollen sind sie von der Seuche der Untoten befallen, haben fleckiges graues Fell und trübe, gelbe Augen. Sie führen einen brutalen Guerillakrieg gegen die Verlassenen, plündern Schlachtfelder und greifen jeden, der sich ihren Lagern nähert, heftig an.",al={"rotkammgnolle","warum sind gnolle im silberwald","rotkammgnoll silberwald"}},ad054bc9={q="Wer kontrolliert die Rotkammgnolle?",a="Die Rotkammgnolle stehen unter dem Bann von Thule Rabenklaue, einem verräterischen Nekromanten, der sich der Geißel angeschlossen hat. Von seiner Festung auf Insel Fenris aus nutzt Thule dunkle Magie, um diese verdorbenen Bestien zu manipulieren und sie zu ausgehobenen Schlachtfeldern zu schicken, um frische Leichen für seine wachsenden Legionen von Untoten zu ernten.",al={"wer befehligt die rotkammgnolle","meister der rotkammgnolle","wer führt die rotkammgnolle"}},["97f89d60"]={q="Was sind Das Todesfeld?",a="Das Todesfeld ist eine verdorbene landwirtschaftliche Fläche im zentralen Silberwald, entlang der Straße, die zum Lordameresee führt. Einst ein friedliches Gehöft, wurde es während des Dritten Krieges zu einem Massenmordplatz, als die Geißel Lordaeron überrannte. Heute ist es ein offener Friedhof, übersät mit flachen Gräbern und aufgewühlter Erde.",al={"das todesfeld silberwald","das todesfeld","was ist das todesfeld"}},d487a8f2={q="Warum graben die Gnolle in Das Todesfeld?",a="Die Rotkammgnolle graben Das Todesfeld um, um die während des Dritten Krieges dort begrabenen menschlichen Leichen auszugraben. Auf Befehl von Thule Rabenklaue graben sie Körper und konservierte Überreste aus, um den Nekromanten mit Rohmaterial für den Bau von Konstrukten der Geißel und zur Verstärkung seiner untoten Armee auf Insel Fenris zu versorgen.",al={"warum graben die rotkammgnolle","gnolle das todesfeld warum","gnoll gräbt nach leichen"}},["3bca491d"]={q="Was befindet sich auf Insel Fenris?",a="Insel Fenris ist eine große Insel, die im Lordameresee vor der Ostküste des Silberwaldes liegt. Sie wird von Burg Fenris dominiert, einer ehemaligen Militärfestung von Lordaeron, die in einen dunklen Verfall geraten ist. Heute dient die Insel als schwer befestigte Zuflucht, die von Rotkammgnollen und den untoten Schergen von Thule Rabenklaue wimmelt.",al={"insel fenris","was ist auf insel fenris","burg fenris"}},bd044bca={q="Warum will Hadrec, dass Insel Fenris angegriffen wird?",a="Hadrec erkennt Insel Fenris als das schlagende Herz der Bedrohung durch die Geißel im östlichen Silberwald. Thule Rabenklaue in Burg Fenris verschanzt zu lassen, gibt der Geißel einen unangreifbaren Aufmarschpunkt, um untote Gnolle zu erheben, Versorgungskarawanen zu überfallen und den östlichen Zugang nach Tirisfal zu bedrohen. Der Angriff auf die Insel ist entscheidend, um Thules Macht zu brechen und den See zu sichern.",al={"warum insel fenris angreifen","hadrec insel fenris motiv","angriff auf insel fenris grund"}},["574e415e"]={q="Arbeiten die Dalaran-Zauberer in Mühlenbern mit der Allianz zusammen?",a="Ja. Während Dalaran sich stark auf den Wiederaufbau seiner zerstörten Stadt konzentriert, bleiben die in Mühlenbern stationierten Streitkräfte der Kirin Tor der Allianz gegenüber offen freundlich gesinnt und der Horde gegenüber erbittert feindselig. Dalaran schickt häufig Unterstützung an die überlebenden menschlichen Enklaven im Silberwald, widersetzt sich der Expansion der Verlassenen und arbeitet eng mit den südlichen Überresten zusammen.",al={"mühlenbern dalaran allianz","ist dalaran hier bei der allianz","kirin tor allianz silberwald"}},fd7851b2={q="Wer ist Arugal und was ist 'Arugals Torheit'?",a="Erzmagier Arugal war ein Zauberer aus Dalaran, der in seiner Verzweiflung, sich während des Dritten Krieges gegen die Geißel zu verteidigen, zu verbotener Magie griff und monströse Wolfbestien, bekannt als Worgen, beschwor. Die wilden Bestien wandten sich jedoch gegen die Zauberer der Kirin Tor und unschuldige Einheimische gleichermaßen und verbreiteten einen gefräßigen Lykanthropie-Fluch im südlichen Silberwald. Getrieben vom Wahnsinn durch Schuldgefühle und Entsetzen über das, was er entfesselt hatte, zog sich Arugal in Burg Shadowfang zurück und nahm die Worgen als seine 'Kinder' an.",al={"arugal","arugals torheit","wer war arugal","erzmagier arugal lore"}},f38b73fd={q="Woher kamen die Worgen?",a="Die Worgen sind außerweltliche Wolfbestien, die von Erzmagier Arugal durch Dimensionen gezogen wurden. Auf der Suche nach einer Waffe, um Dalaran während des Dritten Krieges gegen die Geißel zu stärken, beschwor Arugal diese Kreaturen in den Silberwald, wo sie sich schnell gegen ihre Beschwörer wandten und einen transformierenden Fluch verbreiteten.",al={"woher kamen die worgen","worgen ursprung silberwald","wie kamen worgen hierher"}},fc903f13={q="Ist Arugal noch am Leben?",a="Ja, Erzmagier Arugal ist sehr wohl am Leben. Umhüllt von Wahnsinn residiert er hoch oben in den Türmen von Burg Shadowfang und überblickt Lohenscheit. Von seiner Festung aus lenkt er sein Rudel Shadowfang-Worgen und bewacht seine verdrehte lupine Domäne vor jedem, der mutig genug ist, seine Tore zu durchbrechen.",al={"ist arugal am leben","wo ist arugal jetzt","arugal status"}},["5dc043c6"]={q="Was ist Lohenscheit?",a="Lohenscheit ist eine menschliche Siedlung im südwestlichen Silberwald, direkt unter den imposanten Klippen von Burg Shadowfang. Sie blieb draußen, als Gilneas vor dem Dritten Krieg den Greymane-Wall versiegelte. Die überlebenden Bewohner kämpfen darum, tagsüber einen Anschein von normalem Leben aufrechtzuerhalten, obwohl eine uralte Dunkelheit sie verzehrt, sobald die Sonne untergeht.",al={"lohenscheit lore","was ist lohenscheit","stadt lohenscheit"}},["20eec241"]={q="Wo führt das alles nach dem Silberwald hin?",a="Sobald Ihr den Silberwald stabilisiert habt, indem Ihr Thule Rabenklaue konfrontiert und Arugal in Burg Shadowfang beseitigt, führt Eure Reise normalerweise nach Osten über die Berge in das Vorgebirge des Hügellands, um die Verlassenen bei Tarrens Mühle zu unterstützen. Alternativ nehmen viele Reisende der Horde einen Zeppelin nach Kalimdor, um durch die weiten Ebenen im Brachland zu kampieren.",al={"wohin nach dem silberwald","nächstes gebiet nach silberwald","silberwald nächster schritt"}},da147569={q="Wie bin ich im Silberwald gelandet?",a="Ihr seid wahrscheinlich der Straße nach Süden aus Tirisfal gefolgt und habt den Gebirgspass südwestlich der Ruinen von Unterstadt durchquert. Charaktere der Verlassenen sichern ihre nördliche Heimat in Tirisfal und stoßen dann ganz natürlich nach Süden in den Silberwald vor, um das junge Reich zu erweitern. Alternativ kommen Reisende der Horde von anderen Kontinenten per Zeppelin vor der Unterstadt an, bevor sie die Küste hinunterwandern, während seltene Abenteurer aus dem Süden möglicherweise das Vorgebirge des Hügellands durchqueren, um diese verseuchten Wälder zu erreichen.",al={"wie bin ich hierher gekommen","wie erreiche ich den silberwald","weg zum silberwald"}},["97a9302a"]={q="Was soll ich im Silberwald tun?",a="Ihr seid hier, um den Verlassenen dabei zu helfen, ihre südliche Grenze gegen wachsende Gefahren zu sichern. Meldet Euch bei Hochexekutor Hadrec und den Todespirschern am Grabmal. Ihr müsst die krankheitsbefallenen Rotpelzgnolle aufhalten, die aus den Todesfeldern und von der Insel Fenris plündern, die Nekromanten der Geißel wie Thule Rabenklaue ausrotten und die Zauberer von Dalaran im Auge behalten, die sich in Mühlenbern verschanzt haben. Weiter südlich werdet Ihr außerdem die gefräßigen Wolfsbestien untersuchen, die Lohenscheit terrorisieren, sowie den Schatten, der von Burg Shadowfang ausgeht.",al={"was ist meine mission hier","warum wurde ich in den silberwald geschickt","was tun wir im silberwald"}}},fp="17,230,18.551.0,30.531.1,25.482.1,49.319.0,57.270.1,23.261.1,35.243.0,22.247.0,48.232.0"}
P.entries["zone:stockade"] = {n="Das Verlies",s="Eine gewaltsame Rebellion hat Das Verlies unter den Kanälen von Sturmwind nahe dem Magierviertel erfasst. Das Verlies wurde als Hochsicherheitsgefängnis für Halsabschneider, politische Aufrührer und gefangene Staatsfeinde erbaut, doch nun herrscht dort Anarchie unter gefährlichen Gefangenen. Aufseher Thelwasser wurde zum Eingang zurückgedrängt und sucht Hilfe, bevor der Aufstand die Hauptstadt erreicht.",h="Eine gewaltsame Rebellion hat Das Verlies unter den Kanälen von Sturmwind nahe dem Magierviertel erfasst.",kw={"bazil thredd","bruegal eisenfaust","canals","defias","dextren ward","hamhock","kam tiefenzorn","aufstand","verlies","sturmwind","targorr","aufseher thelwasser"},ang={["class:Mage"]="Das Gefängnis liegt am Kanalufer des Magierviertels, wo körperliche Schläger anfällig für Verlangsamungszauber sind. Der Oger-Magier Hamhock kann Kettenblitz entfesseln.",["class:Rogue"]="Das verwinkelte Netz aus verschlossenen Eisenzellen und Verbindungen zu den Defias bietet einzigartige Möglichkeiten, Schlösserknacken zu üben und Einblicke in Bazil Thredds Unterwelt-Syndikat zu gewinnen.",["faction:Alliance"]="Die Rebellion bedroht Sturmwinds innere Sicherheit und das Herz der Hauptstadt. Sie niederzuschlagen schützt diese Sicherheit und erfüllt geheime Kopfgelder aus dem Rotkammgebirge, dem Dämmerwald und der Eisenschmiede.",["race:Dwarf"]="Kam Tiefenzorn in Sturmwinds Zellen zu wissen, ist eine Beleidigung für Dun Modr. Das Königreich Eisenschmiede fordert seinen Kopf, um die im Sumpfland verlorenen Zwergenleben zu rächen."},sec={{t="Ein Gefängnis unter Belagerung",b="Unter den Kanälen von Sturmwind ist Das Verlies zum Kriegsgebiet geworden. Als die reguläre Armee an ferne Fronten zog, mussten die unterbesetzten Gefängniswachen auf unerfahrene Jugendliche zurückgreifen, darunter vierzehnjährige Rekruten. Sie konnten die Ordnung nicht aufrechterhalten. Die Insassen begannen eine blutige, koordinierte Rebellion, zerrissen ihre Wolldecken zu Gangschals und metzelten die verbliebenen Wachen nieder. Aufseher Thelwasser kann den Eingang kaum halten, während die Sträflinge Zellen, Flure und Haftblöcke kontrollieren."},{t="Adlige und Assassinen",b="Der Aufstand legte Sturmwinds politische Machenschaften offen. Die Gebiete außerhalb der Stadt waren zunehmend frustriert über das Haus der Nobles, das Hinrichtungen aussetzte, um die Gefangenen als politisches Druckmittel einzusetzen. Wache Berton aus dem Rotkammgebirge wollte den gefangenen Orc Targorr der Schreckliche wegen seiner Gräueltaten hinrichten lassen, doch die Adligen setzten sein Urteil aus.\n\nRatsherr Mühlenstein aus Dunkelhain musste mitansehen, wie der Grabräuber Dextren Ward dem Galgen entging, obwohl er für den Nekromanten Morbent Fel Gräber geschändet hatte. Auch die Zwerge von Dun Modr forderten den Tod des Dunkeleisensaboteurs Kam Tiefenzorn. Als im Verlies das Chaos ausbrach, heuerten die örtlichen Behörden im Stillen Abenteurer an, um die Hinrichtungen auszuführen, welche die Gerichte der Hauptstadt nicht vollstrecken wollten."},{t="Der Drahtzieher und die Aufrührer",b="Bazil Thredd, ein gerissener Verbrecher mit Verbindungen zur Bruderschaft der Defias, organisierte den Aufstand aus seiner Zelle. Bruegal Eisenfaust gehört zu den Aufrührern und ist ein gefährlicher zwergischer Schläger. Er ist einer von mehreren hartgesottenen Sträflingen, denen Abenteurer begegnen könnten, während sie Thelwasser helfen, das Gefängnis zurückzuerobern."}},faq={{q="Warum ist im Verlies eine offene Rebellion ausgebrochen?",a="Die Bruderschaft der Defias organisierte einen Aufstand im ganzen Gefängnis, während es stark unterbesetzt war. Da die Armee von Sturmwind an ferne Fronten entsandt worden war, bewachten jugendliche Freiwillige hartgesottene Mörder. Die Sträflinge überfielen das Personal, bemächtigten sich der Waffen und drängten Aufseher Thelwasser aus den Zellenblöcken.",al={"warum der aufstand","was geschah im verlies","ursache des aufstands im verlies"}},{q="Wer führt den Aufstand im Gefängnis an?",a="Bazil Thredd, ein einflussreicher Defias-Verbrecher im östlichen Zellenblock, plante den Aufstand. Zu den weiteren gefährlichen Gefangenen zählen Bruegal Eisenfaust, Hamhock und Kam Tiefenzorn.",al={"bosse im verlies","wer führt den aufstand an","wer kontrolliert das verlies"}},{q="Warum leben Gefangene wie Targorr und Dextren Ward noch?",a="Beide waren zum Tode verurteilt, doch korrupte Politiker im Haus der Nobles ließen ihre Hinrichtungen bürokratisch aufschieben, um die Gefangenen als politisches Druckmittel einzusetzen. Diese Einmischung empörte Verbündete in Seenhain und Dunkelhain, die Abenteurer schickten, um sie während des Chaos zu töten.",al={"warum wurde targorr nicht hingerichtet","dextren ward vor gericht","korruption im haus der nobles"}},{q="Was bedeutet es für das Gefängnis, Bruegal Eisenfaust zu besiegen?",a="Bruegal Eisenfaust ist ein gefährlicher zwergischer Schläger unter den Aufrührern. Ihn zu besiegen beseitigt eine Bedrohung, während Abenteurer den Aufstand niederschlagen.",al={"bruegal eisenfaust hintergrund","bruegal töten","wer ist bruegal"}},{q="Warum sind Dunkeleisenzwerge und Orcs in einem Menschgefängnis?",a="Das Verlies ist ein Hochsicherheitsgefängnis für besonders wichtige Kriegsgefangene. Targorr der Schreckliche führte Angriffe der Schwarzfelsorcs im Rotkammgebirge an, während Kam Tiefenzorn das Sumpfland für den Dunkeleisenklan sabotierte. Beide wurden gefangen genommen und in die Hauptstadt gebracht.",al={"warum sind dunkeleisenzwerge hier","kam tiefenzorn hintergrund","targorr im verlies"}},{q="Können Spieler der Horde das Verlies betreten?",a="Ja, aber der Zutritt ist äußerst gefährlich. Das Verliesportal befindet sich in Sturmwind nahe den Kanälen des Magierviertels. Infiltratoren der Horde müssen sich an den Stadtwachen und den Verteidigern der Hauptstadt vorbeischleichen, um es zu erreichen.",al={"können hordespieler ins verlies","horde im gefängnis von sturmwind"}}},fx={["07af5e0b"]={q="Was ist das Verlies?",a="Das Verlies ist Sturmwinds Hochsicherheitsgefängnis, das unter dem Kanalviertel der Hauptstadt errichtet wurde. Es dient als Verwahrungsort für Kleinkriminelle, Halsabschneider, politische Aufständische und hochkarätige Feinde des Königreichs, die auf ihr Urteil warten.",al={"was ist das verlies","gefängnis das verlies","sturmwind gefängnis"}},["2fc364a6"]={q="Ist das Verlies nur für die Defias?",a="Nein. Während die Bruderschaft der Defias den Kern des Aufstands bildet, beherbergen die Zellen auch Kleinkriminelle, Grabräuber wie Dextren Ward, gefangene Schwarzfels-Orcs wie Targorr der Schreckliche und sogar Dunkeleisensabotöre wie Kam Tiefenzorn.",al={"ist das verlies nur für defias","wer ist im verlies","sind alle gefangenen defias"}},["0d433487"]={q="Warum sind hier so viele Defias eingesperrt?",a="Sturmwinds Behörden haben Agenten der Bruderschaft in ganz Westfall, dem Wald von Elwynn und in der Stadt selbst gefasst. Anstatt sie sofort hinzurichten, hat die Krone sie in das Verlies verfrachtet und damit ein gefährliches Netzwerk von Aufständischen direkt unter den Dielen der Stadt konzentriert.",al={"warum so viele defias hier","warum defias im verlies","gefangene der bruderschaft der defias"}},e96a18b2={q="Wer leitet dieses Gefängnis?",a="Aufseher Thelwasser leitet die Einrichtung. Als der Aufstand ausbrach, wurden seine Wachen überwältigt und aus den Zellentrakten vertrieben. Thelwasser konnte gerade noch den Eingangsbereich halten, was ihn dazu zwang, verzweifelt nach fähigen Abenteurern zu suchen, um die Korridore zurückzuerobern.",al={"wer leitet das verlies","aufseher des verlieses","aufseher thelwasser"}},["06cbacdc"]={q="Warum können Aufseher Thelwassers Wachen den Aufstand nicht bewältigen?",a="Die Gefängniswache war bereits extrem dünn besetzt, sodass man sogar Freiwillige im Alter von nur vierzehn Jahren einsetzte, um gefährliche Sträflinge zu bewachen. Als die Defias sich zusammenschlossen und angriffen, wurde das Personal völlig unvorbereitet erwischt, niedergemetzelt oder zur Flucht in die Eingangshalle gezwungen.",al={"warum können wachen aufstand nicht stoppen","wo sind die gefängniswachen","wachen im verlies"}},["7c158547"]={q="Warum schickt Sturmwind mich hinein und nicht die Armee?",a="Ein Großteil von Sturmwinds Militär ist an weit entfernten Fronten im Einsatz, und die korrupte Bürokratie im Haus der Adligen lähmt schnelles kommunales Handeln. Zudem sind Stadtbeamte verzweifelt bemüht, den Aufstand geheim zu halten, um eine offene Panik in den Straßen zu vermeiden.",al={"warum abenteurer schicken","warum nicht die armee ins verlies","wo ist die armee von sturmwind"}},a2006c52={q="Wissen die Wachen draußen, was im Inneren vor sich geht?",a="Die Wachen halten die Aufständischen an der Schwelle des Kerkers auf, und Aufseher Thelwasser sucht Hilfe, um die Ordnung im Inneren wiederherzustellen. Die Stadtbeamten halten den Vorfall geheim, um die normalen Bürger nicht zu beunruhigen.",al={"wissen wachen draußen bescheid","weiß sturmwind vom aufstand","geheimnis des verlieses"}},b1798127={q="Was ist der Unterschied zwischen den Gefangenen, Sträflingen und Aufständischen hier drin?",a="Die Insassen reichen von gewöhnlichen Gaunern und Taschendieben, die von den Straßen aufgelesen wurden, bis hin zu verurteilten Schwerverbrechern und kompromisslosen Defias-Aufständischen. Während gewöhnliche Sträflinge die Gelegenheit nutzten, zu randalieren und zu plündern, erhalten die Aufständischen aktiv Befehle von Bazil Thredd, um das Gefängnis zu übernehmen.",al={"sträflinge aufständische gefangene","gegnerarten im verlies","wer sind die insassen"}},["378bbf14"]={q="Wie kamen die Insassen an Waffen und wie haben sie sich organisiert?",a="Der Aufstand wurde akribisch vom Defias-Anführer Bazil Thredd geplant. Unter seiner Regie zerrissen die Gefangenen ihre Wolldecken zu roten Bandenschals, überfielen die unterbesetzten Wachen, stahlen deren Waffen und Schlüssel und befreiten methodisch die Zellen in jedem Flügel.",al={"wie kamen gefangene an waffen","wie haben sich defias organisiert","wer hat die gefangenen bewaffnet"}},["855deb71"]={q="Warum baut man ein Gefängnis direkt unter die Stadt?",a="Der Gefängniskomplex liegt unter den Kanälen von Sturmwind. Die ursprüngliche Platzierung wird nicht erklärt.",al={"warum gefängnis unter sturmwind","standort des verlieses warum","gefängnis unter den kanälen"}},caa2e4bf={q="Wie bin ich im Verlies gelandet?",a="Ihr seid durch die schweren Eisentüren von den nördlichen Kanälen in Sturmwind eingetreten. Unter den Straßen brach ein massiver Aufstand aus, und die verbliebenen Wachen von Aufseher Thelwasser wurden bis zur Schwelle zurückgedrängt, wodurch die Sträflinge die Kontrolle übernahmen. In der Verzweiflung, das Chaos vor den Bürgern oben geheim zu halten, heuerte der Aufseher fähige Abenteurer an, um direkt in die Zellentrakte zu marschieren und die Einrichtung mit Gewalt zurückzuerobern.",al={"wie bin ich hierher gekommen","warum bin ich hier","wie habe ich das verlies betreten"}},["45edc40e"]={q="Was soll ich im Verlies tun?",a="Eure Hauptmission ist es, den Aufstand niederzuschlagen und seinem Anführer, dem Drahtzieher der Defias Bazil Thredd, ein Ende zu setzen. Verbündete im ganzen Königreich haben diesen Moment des Chaos jedoch genutzt, um überfällige Schulden zu begleichen: Dunkelhain sucht Vergeltung für den Grabräuber Dextren Ward, Seenhain will den rücksichtslosen Orc Targorr der Schreckliche tot sehen, und Eisenschmiede fordert den Kopf des Saboteurs Kam Tiefenzorn.",al={"was ist meine mission hier","was tue ich hier","warum bin ich hier"}}},fp="12,345,20.476.0,20.680.1,30.277.1,38.302.0,35.174.0,60.285.0,60.151.0,61.253.0,37.213.0"}
P.entries["zone:stonetalon"] = {n="Steinkrallengebirge",s="Im Steinkrallengebirge treffen heilige Höhen auf Rauch, gefällte Wälder und verwüstete Erde. Nachtelfen und Tauren verehren das Gebirge, während an seinen Grenzen Spannungen schwelen.",h="Im Steinkrallengebirge treffen heilige Höhen auf Rauch, gefällte Wälder und verwüstete Erde.",kw={"das verbrannte tal","gerenzo wrenchwhistle","malaka'jin","steinkrallengebirge","der steinkrallengipfel","sonnenfels","talondeep pass","scherwind"},ang={["class:Druid"]="Die Entweihung der Scherwindklippe und die versengte Verderbnis des Verbrannten Tals rufen Druiden herbei, die erzürnte Naturgeister besänftigen und heilige Rastplätze schützen sollen.",["class:Shaman"]="Goblinbohrer greifen die Berggeister an, deren Schreie bis nach Orgrimmar dringen. Schamanen folgen dem Ruf, um tobende Felselementare zu bändigen und das Gleichgewicht auf den Gipfeln wiederherzustellen.",["faction:Alliance"]="Vom Steinkrallengipfel und aus versteckten Lagern rund um die Scherwindklippe verteidigt die Allianz uralte Kaldorei-Grabhügel gegen Goblinmaschinen und Rivalen, die ihr Gebiet beanspruchen.",["faction:Horde"]="Reisende der Horde verlassen sich auf Sonnenfels und Malaka'jin, den südlichen Trollaußenposten, um die Verschmutzung durch die Venture Company einzudämmen und Grimtotem-Gesetzlose aufzuspüren."},sec={{t="Die Bösen Winde und die Gipfel",b="Das Steinkrallengebirge erhebt sich im zentralen Kalimdor unter den Bösen Winden. Feuchtigkeit von den westlichen Meeren bringt plötzliche Wolkenbrüche, die die Sandsteinpfade glitschig machen. Heftige Böen fegen durch die tiefer gelegenen Täler, blenden Reisende mit Sand und reißen Unachtsame manchmal von den Klippen.\n\nAuf den höheren Graten wachsen immergrüne Wälder rund um den Steinkrallengipfel. Nachtelfen pflegen dort die Grabhügel ihrer Ahnen und die Haine. Außerdem bewachen sie heilige Rastplätze von Wyvern und Hippogryphen entlang des Mirkfallonsees."},{t="Industrie und Eindringlinge",b="Die Venture Company hat die Stille des Gebirges mit Holzfällercamps und Tagebauen in der Scherwindklippe gebrochen. Mit Unterstützung des wahnsinnigen Lepragnoms Gerenzo Pfeifzang haben die Goblins uralte Wälder gefällt und den Himmel mit Ofenrauch gefüllt. Ihr Industrieschlamm verschmutzt das abfließende Bergwasser.\n\nÖrtliche Schamanen aus Orgrimmar erhörten die Schreie der Berggeister. Auch kleine Lager der Allianz in der Nähe leisten den Entweihten Widerstand und versuchen, die verbliebenen Hochländer zu schützen."},{t="Narben der Vergangenheit",b="Im Süden liegt das Verbrannte Tal, einst eine blühende Wildnis und heute eine aschebedeckte Ödnis. Schurken-Feuerelementare, schwarze Drachenbrut und Harpyien bevölkern seine Ruinen. Während des Dritten Krieges schlossen Horde und Allianz unter der Führung des geheimnisvollen Orakels einen brüchigen Waffenstillstand auf diesen Gipfeln.\n\nSeitdem haben sich die Beziehungen verschlechtert. Abtrünnige Grimtotem-Tauren halten besetzte Lager, während Dunkelspeertrolle in Malaka'jin mit Streitkräften der Allianz zusammenstoßen, die aus dem Brachland und Eschental vordringen."}},faq={{q="Wie komme ich ins Steinkrallengebirge?",a="Die meisten Reisenden erreichen das Steinkrallengebirge über den Talondeep Pass, einen Gebirgspfad aus dem Südwesten Eschentals. Hohe Pfade führen nach Süden in Desolace, während Wege nach Osten ins nördliche Brachland hinabführen.",al={"eingang zum steinkrallengebirge","weg ins steinkrallengebirge","straße im steinkrallengebirge"}},{q="Warum ist das Verbrannte Tal verbrannt und verwüstet?",a="Das Verbrannte Tal war einst ein üppiges Refugium, doch eine katastrophale Verwüstung verzehrte es in Flammen. Heute ist es eine aschebedeckte Ruine voller aggressiver Feuerelementare, Schurkendrachen und tödlicher Harpyien.",al={"feuer im verbrannten tal","was geschah mit dem verbrannten tal","warum brannte das verbrannte tal"}},{q="Was macht die Venture Company in der Scherwindklippe?",a="Die Venture Company fällt Holz und gräbt tief in der Scherwindklippe nach wertvollen Mineralien. Ihre Aktivitäten haben den Felskesselsee mit Motorenschmiere verschmutzt, die Täler kahl geschlagen und die örtlichen Geister und Bewohner erzürnt.",al={"venture company im steinkrallengebirge","goblins an der scherwindklippe","warum fällen goblins bäume"}},{q="Wo befinden sich die wichtigsten Flugmeister?",a="Helden der Allianz nutzen den Flugmeister beim hoch gelegenen Heiligtum am Steinkrallengipfel im Norden. Reisende der Horde verlassen sich auf das zentrale Bergdorf Sonnenfels.",al={"flugroute im steinkrallengebirge","wo ist der flugpunkt im steinkrallengebirge","flugpunkt im steinkrallengebirge"}},{q="Was geschah während des Dritten Krieges am Steinkrallengipfel?",a="Während des Dritten Krieges folgten Thrall und Jaina Prachtmeer Visionen des Propheten Medivh durch die Höhlen des Steinkrallengipfels, um das Orakel zu suchen. Dort schlossen sie am Hyjal ein vorübergehendes Bündnis gegen die Brennende Legion.",al={"geschichte des steinkrallengipfels","das orakel im steinkrallengebirge","dritter krieg im steinkrallengebirge"}},{q="Wer sind die Grimtotem im Steinkrallengebirge?",a="Die Grimtotem sind ein abtrünniger Taurenstamm, der fremden Einfluss bekämpft. Im Steinkrallengebirge besetzen sie einen Außenposten nahe der Grenze zum Brachland, terrorisieren Reisende und nehmen Gefangene.",al={"posten der grimmtotem","grimtotem im steinkrallengebirge"}}},fx={["4946a833"]={q="Was ist das Steinkrallengebirge?",a="Das Steinkrallengebirge ist eine raue, vom Wind geformte Gebirgskette im Zentrum von Kalimdor, gelegen westlich des Brachlands, südlich des Eschentals und nördlich von Desolace. Bekannt für extreme Winde, tiefe Schluchten und steile Sandsteingipfel, die während des Großen Bruchs entstanden, bildet die Region ein historisches Grenzland, in dem Nachtelfen und Tauren seit Generationen koexistieren. Die hohen, heiligen Gipfel sind immer noch üppig mit Nadelbäumen bewachsen, während die tiefer gelegenen Täler trocken, felsig und durch die Industrie schwer gezeichnet sind.",al={"gebiet steinkrallengebirge","was ist steinkrallengebirge","über das steinkrallengebirge"}},["4e995438"]={q="Ist das Steinkrallengebirge gefährlich?",a="Ja, Reisende sind sowohl natürlichen Gefahren als auch erbitterten Feinden ausgesetzt. Heftige Stürme und plötzlicher Regen können die hohen Sandsteinklippen so glatt machen, dass Menschen in den Tod stürzen. Jenseits des Wetters wimmelt es in den Bergen von aggressiven Blutwutharpien, räuberischen Wyvern, Spinnen, Kobolden und aufgebrachten Elementaren. Zudem machen die rücksichtslosen Maschinen und bewaffneten Vollstrecker der Venture Company umkämpfte Täler wie die Scherwindklippe außergewöhnlich gefährlich.",al={"gefahr im steinkrallengebirge","ist das steinkrallengebirge sicher","gefahren des steinkrallengebirges"}},["9d849e11"]={q="Wer lebt im Steinkrallengebirge?",a="Die Region beherbergt eher verstreute Fraktionen als eine einzelne herrschende Macht. Die Nachtelfen halten den Steinkrallengipfel und bewachen heilige Stätten auf den Höhen, während die Horde Siedlungen am Sonnenfels und das Trodorf Malaka'jin unterhält. Einheimische Blutwutharpien nisten in den Klippen, feindselige Grimtotemtauren besetzen nahegelegene Posten und die Venture Company der Goblins besetzt abgeholzte Landstriche um die Scherwindklippe.",al={"wer lebt im steinkrallengebirge","fraktionen im steinkrallengebirge","bewohner des steinkrallengebirges"}},a4f73e64={q="Warum betreibt die Venture Company Holzwirtschaft in der Scherwindklippe?",a="Die Venture Company ist ein rücksichtsloser Handelskonzern, der durch unbegrenzten Ressourcenabbau Profit sucht. In der Scherwindklippe roden sie mithilfe schwerer Maschinen wie dem Super Reaper 6000 alte Wälder und sprengen die Erde nach wertvollem Erz auf. Ihre Missachtung der Natur erfüllt die Luft mit Ruß und vergiftet lokale Gewässer mit Schlamm und Öl, was ihnen den wütenden Widerstand sowohl der örtlichen Druiden als auch der Horde einbringt.",al={"abholzung durch venture company","warum fällen goblins bäume","holzfällerei venture company steinkrallengebirge"}},["66935983"]={q="Wer leitet die Venture Company in der Scherwindklippe?",a="Die örtlichen Abholzungs- und Minenarbeiten in der Scherwindklippe werden von einem aussätzigen Gnom namens Gerenzo Pfeifzang geleitet. Gerenzo überwacht die Rodungen von einer Plattform hoch über dem Felskesselsee aus und setzt sein technisches Fachwissen ein, um die Zerstörung zu maximieren. Seine schurkischen Operationen haben sogar den Zorn rivalisierender Goblintüftler der Tüftlergewerkschaft auf sich gezogen, die versuchen, ihn auszuschalten.",al={"wer leitet die scherwindklippe","gerenzo wrenchwhistle","anführer der venture company im steinkrallengebirge"}},ff0da62d={q="Wer sind die Blutwutharpien?",a="Die Blutwutharpien sind ein bösartiger Stamm von Vogelmenschen, die im Steinkrallengebirge heimisch sind. Historisch gesehen war dieses Gebirge ihr angestammtes Kernland, bevor sie sich in das Brachland und darüber hinaus ausbreiteten. Sie verteidigen ihr Territorium aggressiv gegen Eindringlinge, fangen lokale Bestien und geraten gewaltsam mit sowohl Taurenpilgern als auch eindringenden Goblinmaschinen an Orten wie dem verbrannten Tal aneinander.",al={"blutwutharpien","harpien im steinkrallengebirge","wer sind die harpien hier"}},["66599fe7"]={q="Was ist der Sonnenfels?",a="Der Sonnenfels ist eine friedliche Siedlung der Horde, eingebettet in ein abgelegenes Bergtal südlich des Mirkfallonsees. Er dient als primäre Basis für Tauren und Orcs in der Region und beherbergt Schamanen und Druiden, die sich der Wiederherstellung des Landes von der Verschmutzung durch die Venture Company und der Bekämpfung der Bedrohungen widmen, die in die heiligen Berge eindringen.",al={"hintergrund zum sonnenfels","was ist der sonnenfels","tauren am sonnenfels"}},["5a5a6e9c"]={q="Warum haben sich die Tauren am Sonnenfels niedergelassen?",a="Seit Generationen verehren die Tauren dieses Tal als einen Ort mit einer tiefen Verbindung zur Geisterwelt. Alte Legenden besagen, dass der Sonnengott An'she den Gipfel küsste, auf dem sich die Zuflucht befindet. Die Tauren unternahmen hier lange Zeit heilige Pilgerreisen, um mit Geistern in Kontakt zu treten und große rituelle Freudenfeuer zu entzünden, um die schattigen Berge zu erhellen.",al={"warum siedelten tauren am sonnenfels","geschichte des sonnenfelses","an'she sonnenfels"}},["51d42c77"]={q="Was ist die Scherwindklippe?",a="Die Scherwindklippe war einst ein üppiger Urwald, wurde aber durch industrielle Ausbeutung verwüstet. Die Venture Company rodete das Tal zu einer kargen Ausdehnung aus Baumstümpfen, Erde und rauchenden Maschinen. Zwischen der Entwaldung durch die Venture Company, dem fauligen Abfluss im Felskesselsee und Kobolden, die die örtliche Mine befallen, steht sie als ruiniertes Denkmal ungezügelter Gier.",al={"über die scherwindklippe","gebiet scherwindklippe","hintergrund zur scherwindklippe"}},d850bc0a={q="Was befindet sich in der Scherwindmine?",a="Die Scherwindmine, die sich in den südöstlichen Klippen der Scherwindklippe befindet, ist von aggressiven Scherwindkobolden überrannt. Die Kobolde, die von den regulären Bergleuten vertrieben wurden oder von ihnen verlassen wurden, graben nun wütend nach Adern von Rauchigen Eisenerzbarren und greifen jeden heftig an, der versucht, in ihre unterirdischen Grabungen einzudringen.",al={"kobolde der scherwindmine","was gibt es in der scherwindmine","rauchiges eisenerz scherwindmine"}},d3863c46={q="Was ist der Krallenbau auf dem Steinkrallengipfel?",a="Der Krallenbau ist ein alter Nachtelfen-Barrow-Bau, der in die Höhen des Steinkrallengipfels gehauen wurde. Er wird von Cenariondruiden unterhalten, die mit den Geistern der Natur und dem Smaragdgrünen Traum kommunizieren. Tief im Inneren haben Druiden traditionell in heiliger Kontemplation geschlafen, bewacht von Dryaden, Hütern und den magischen Schutzzaubern des Gipfels.",al={"krallenbau","der bau am steinkrallengipfel","barrow-bau steinkrallengebirge"}},a547ffd6={q="Verbindet das Eschental das Steinkrallengebirge?",a="Ja. Der raue Steinkrallenpfad verbindet das südwestliche Eschental direkt mit dem nordöstlichen Steinkrallengebirge durch einen höhlenartigen Gebirgspass. Reisende und Abenteurer gelangen häufig zwischen den unberührten, umkämpften Wäldern des Eschentals und den kargen Höhen des Steinkrallengebirges, während sie Bedrohungen durch die Venture Company oder die anhaltenden Fraktionskonflikte verfolgen.",al={"wie verbindet das eschental das steinkrallengebirge","steinkrallenpfad eschental","eschental grenze steinkrallengebirge"}},a5c2784c={q="Wie bin ich im Steinkrallengebirge gelandet?",a="Die meisten Reisenden erreichen diese zerklüfteten Höhen über den Steinkrallenpfad, einen alten Gebirgstunnel, der in das südwestliche Eschental gehauen wurde. Andere Wanderer klettern die rauen Pfade hinauf, die westlich aus dem Brachland führen, und steigen die windgepeitschten Pässe hinauf in die felsigen Klippen. Ob von Nachtelfenkommandanten in Astranaar nach Süden geschickt oder westwärts über die verbrannte Grenze vom Wegekreuz aus entsandt, die hohen Schluchten und heulenden Ill Winds begrüßen jeden, der die beschwerliche Reise in das Gebirge unternimmt.",al={"wie bin ich hierher gekommen","wie komme ich ins steinkrallengebirge","ankunft im steinkrallengebirge"}},["4abc7ef6"]={q="Was soll ich im Steinkrallengebirge tun?",a="Ihr seid hier, um den wachsenden Bedrohungen entgegenzutreten, die diese heiligen Höhen entweihen. An der Scherwindklippe reißen die rücksichtslosen Goblins der Venture Company alte Wälder nieder und verschmutzen die Flüsse mit Maschinen, was den Zorn beider Fraktionen auf sich zieht. Unterdessen stiftet der Grimtotemstamm Unruhe entlang der östlichen Grenze, während bösartige Harpien und wütende Feuerelementare das versengte Becken des verbrannten Tals befallen. Ihr müsst Eure Verbündeten dabei unterstützen, diese Umweltverschmutzer und Monster zurückzudrängen, um das Land zu schützen.",al={"was soll ich hier tun","warum bin ich hier","was ist meine mission im steinkrallengebirge"}}},fp="20,167,27.462.0,22.461.0,17.474.0,41.202.0,42.194.0,52.224.0,42.161.0,54.229.0,36.181.0"}
P.entries["zone:stormwind"] = {n="Sturmwind",s="Das weiß ummauerte Sturmwind ist der größte Zufluchtsort der Menschen und das Herz der Allianz. Doch sein König ist verschollen. Die Krone ruht nun auf dem Haupt eines zehnjährigen Jungen.",h="Das weiß ummauerte Sturmwind ist der größte Zufluchtsort der Menschen und das Herz der Allianz.",kw={"anduin","bolvar","kathedrale","tiefenbahn","prestor","steinmetze","sturmwind","vancleef","wrynn"},ang={["class:Paladin"]="Als Paladin findet Ihr die Kathedrale des Lichts, das wichtigste Heiligtum Eures Glaubens im Süden. Dort werden Ritter der Silbernen Hand ausgebildet und die Gerechtigkeit hochgehalten.",["class:Rogue"]="Als Schurke findet Ihr das Hauptquartier von SI:7 unter den steinernen Straßen der Altstadt. Von dort aus leitet die Organisation das wichtigste Geheimdienst- und Spionagenetzwerk der Allianz.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr in Sturmwind auf Seemacht, spirituellen Halt und wichtige diplomatische Führung zählen. Es ist die bevölkerungsreichste Metropole der Großen Allianz.",["race:Dwarf"]="Als Zwerg könnt Ihr mit der Tiefenbahn zu Euren Verwandten im Zwergendistrikt reisen. Sie pflegen enge Handels- und Militärbeziehungen zum Menschenreich.",["race:Human"]="Als Mensch ist Sturmwind der letzte große Sitz souveräner Macht Eures Volkes, nachdem Lordaeron, Alterac und Dalaran im Norden gefallen sind."},sec={{t="Aus der Asche auferstanden",b="Sturmwind ist alt. Vor mehr als tausend Jahren gründeten die Nachfahren der Arathi die Stadt. Viele Generationen lang blühte sie als Reich, das niemandes Hilfe brauchte. Dann kam die Horde durch das Dunkle Portal. Der südliche Kontinent wurde verwüstet, und im Ersten Krieg wurde die Stadt dem Erdboden gleichgemacht.\n\nDie Überlebenden folgten Sir Anduin Lothar nach Norden, über das große Meer nach Lordaeron. Als die Horde im Zweiten Krieg besiegt wurde, bezahlten König Terenas Menethil II und die Allianz für den Wiederaufbau Sturmwinds. Die Steinmetzgilde errichtete die Stadt mit glänzendem weißen Stein neu, mit Kanälen, die durch ihre Viertel fließen."},{t="Ein gespaltener Hof",b="Doch der weiße Stein verbirgt ein zerrüttetes Haus. Das Haus der Edlen stritt mit der Steinmetzgilde über die Löhne, und der Streit stürzte das Königreich in lähmende Schulden. Die Arbeiter der Gilde erhoben sich zum Aufstand. Sie wurden ausgerechnet aus der Stadt vertrieben, die sie erbaut hatten.\n\nDann verschwand König Varian Wrynn auf dem Weg zu einem Gipfeltreffen. Damit sich keine Panik ausbreitete, ging die Krone an seinen Sohn, Prinz Anduin Wrynn. Er ist zehn Jahre alt. Hochlord Bolvar Fordragon regiert nun als Regent und Befehlshaber des Heeres. An seiner Seite steht die königliche Beraterin Lady Katrana Prestor."},{t="Herz der Großen Allianz",b="Seit Lordaeron von der Geißel überrannt wurde, richten die Menschen ihren Blick mehr als auf jede andere Stadt auf Sturmwind. Die Gläubigen versammeln sich in der Kathedrale des Lichts. Und im Tal der Helden ehren hohe Statuen die Söhne Lothars. Sie zogen durch das Dunkle Portal und wurden nie wieder gesehen."},{t="Wohin die Steinmetze gingen",b="Die Steinmetze versammelten sich unter ihrem Gildenmeister Edwin van Cleef erneut in Westfall. Dort wurden sie zur Bruderschaft der Defias, rot maskierten Banditen, die nun das Ackerland des Königreichs strangulieren. Die Erbauer von Sturmwinds weißen Mauern haben geschworen, das Haus der Edlen für jeden Stein bezahlen zu lassen."},{t="Ein Freund am Hof",b="Die Bruderschaft der Defias fand Hilfe in Burg Sturmwind. Lord Gregor Lescovar vom Haus der Edlen verhandelte heimlich mit der Bruderschaft und gab ihr die Pläne des Königreichs weiter. Dabei saß er unter den Lords, die die Steinmetze betrogen hatten."},{t="Schatten in der Burg",b="Lady Katrana Prestor hat heimlich die Entscheidungen des Hauses der Edlen gelenkt. Sie schürte dessen Konflikt mit den Steinmetzen und ignorierte Bitten um militärische Hilfe aus Siedlungen wie Westfall und dem Rotkammgebirge. Außerdem flüsterte sie Hochlord Bolvar Gift ins Ohr und hielt Sturmwinds Legionen untätig und gespalten, während Unruhen jenseits der Stadtmauern den Thron bedrohen."}},faq={{q="Wer regiert gerade über Sturmwind?",a="Der zehnjährige Prinz Anduin Wrynn trägt Sturmwinds Krone, während Hochlord Bolvar Fordragon als Regent regiert und das Heer befehligt. Bolvar verlässt sich auf den Rat der königlichen Beraterin Lady Katrana Prestor, während König Varian Wrynn weiterhin vermisst wird.",al={"aktueller könig","wer ist der könig","wer führt sturmwind","könig von sturmwind"}},{q="Was ist König Varian Wrynn zugestoßen?",a="König Varian verschwand unter verdächtigen Umständen, als er zu einem diplomatischen Gipfeltreffen in Theramore segelte. Sein Verschwinden wurde geheim gehalten, um die Stabilität zu wahren, doch Gerüchte verbreiteten sich in den Straßen und auf dem Land.",al={"wo ist varian","vermisster könig","varian verschwunden","varian wrynn vermisst"}},{q="Warum wurde die Stadt wiederaufgebaut, und von wem?",a="Die Orcische Horde brannte die ursprüngliche Stadt im Ersten Krieg nieder. Nach dem Zweiten Krieg finanzierte die Allianz von Lordaeron den Wiederaufbau, und der Meisterhandwerker Edwin van Cleef führte die Steinmetzgilde an, um die Hauptstadt aus weißem Stein neu zu errichten.",al={"wer hat sturmwind wiederaufgebaut","steinmetzgilde","neues sturmwind","wiederaufbau der stadt"}},{q="Warum rebellierten die Steinmetze gegen die Krone?",a="Das Haus der Edlen machte hohe Schulden, als es Sturmwinds Heer ausbaute, weigerte sich dann aber, der Steinmetzgilde die versprochenen Löhne zu zahlen. Als Edwin van Cleef die Bezahlung forderte, lösten die Edlen die Gilde auf. Die Arbeiter randalierten und wurden aus der Stadt vertrieben.",al={"ursprung der defias","warum sind die defias wütend","aufstand der steinmetze"}},{q="Wen stellen die riesigen Statuen im Tal der Helden dar?",a="Das Tal der Helden ehrt die Söhne Lothars: General Turalyon, Waldläuferhauptmann Alleria Windläufer, Erzmagier Khadgar, Kurdran Wildhammer und Danath Trollbann. Die Statuen erinnern an jene Helden, die durch das Dunkle Portal nach Draenor gingen, um den Riss zu versiegeln und Azeroth zu beschützen.",al={"statuen am stadteingang","statuen im tal der helden","statuen der söhne lothars"}},{q="Wie ist Sturmwind mit Eisenschmiede verbunden?",a="Die Tiefenbahn, eine unterirdische Eisenbahn, verbindet Sturmwind mit Eisenschmiede. Hochschrauber Gelbin Mekkadrill ließ sie auf Wunsch von König Magni Bronzebart erbauen, damit die Hauptstädte rasch Handel treiben und sich im Krieg gegenseitig Verstärkung schicken können.",al={"die tiefenbahn","zug nach eisenschmiede","wie kommt man nach eisenschmiede"}},{q="Warum schickt Sturmwind keine Truppen, um Westfall und dem Rotkammgebirge zu helfen?",a="Der königliche Hof erklärt unter dem Einfluss von Lady Katrana Prestor, Sturmwind könne keine Truppen von seinen Mauern und den nahen Grenzen abziehen. Die Finanzen des Königreichs sind angespannt, und politische Machtkämpfe haben das Haus der Edlen gelähmt. So sind die Städte der Region auf ihre örtlichen Milizen angewiesen.",al={"sturmwinds fehlendes heer","warum keine hilfe für westfall","verstärkung verweigert"}}},fx={["9beefbfb"]={q="Was ist Sturmwind?",a="Sturmwind ist die Hauptstadt des Menschenkönigreichs Sturmwind und die größte Bastion der Menschheit, die in Azeroth noch steht. Erbaut nördlich des Waldes von Elwynn entlang der Küste, dient sie als pulsierendes Herz, primärer Hafen und kulturelles Zentrum der Großen Allianz. Wiederaufgebaut aus der Asche des Ersten Krieges, bieten ihre befestigten Steinmauern Handwerkern, Gelehrten, Soldaten und Flüchtlingen Schutz, die die Stadt als Symbol menschlicher Ausdauer betrachten.",al={"über sturmwind","hauptstadt sturmwind","was ist sturmwind"}},edb1c1aa={q="Was ist in der Vergangenheit mit Sturmwind passiert?",a="Ursprünglich vor über tausend Jahren von Nachkommen der Arathor-Blutlinie gegründet, florierte das Königreich jahrhundertelang durch Konflikte mit Gnollen und Dschungeltrollen. Während des Ersten Krieges belagerte jedoch die Orcische Horde die Hauptstadt. Nach der tragischen Ermordung von König Llane Wrynn wurde die Stadt durchbrochen, geplündert und bis auf die Grundmauern niedergebrannt. Sir Anduin Lothar führte die überlebenden Flüchtlinge nach Norden über das Meer nach Lordaeron und kehrte erst nach dem Zweiten Krieg zurück, um ihre Heimat zurückzuerobern und wiederaufzubauen.",al={"geschichte von sturmwind","zerstörung von sturmwind","sturmwind erster krieg"}},d0a4b7c8={q="Ist Sturmwind gefährlich?",a="Hinter ihren kolossalen Toren und der wachsamen Stadtwache ist Sturmwind eines der am stärksten befestigten Refugien der Welt. Dennoch lauern unsichtbare Gefahren im Inneren. Das nahe gelegene Gefängnis war Schauplatz gewaltsamer Aufstände, Kultisten und Diebe schleichen durch die schattigen Canals, und politische Unruhen, geschürt von der Bruderschaft der Defias, lassen das Haus der Adligen nervös werden. Während offener Krieg selten die Mauern durchbricht, flüstern Korruption, Verrat und verborgene Verschwörungen durch die Burg und die Gassen gleichermaßen.",al={"ist sturmwind sicher","gefahr in sturmwind","bedrohungen für sturmwind"}},["163d181d"]={q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine rücksichtslose Gilde von Gesetzlosen, Briganten, Dieben und Piraten, die die Stabilität des Königreichs offen bedrohen. Sie sind an ihren charakteristischen roten Bandanas zu erkennen, die das Blut symbolisieren sollen, das für ihre Sache vergossen wurde. Obwohl sie stark von Westfall, dem Rotkammgebirge und den Todesminen aus operieren, reicht ihr Einfluss direkt bis nach Sturmwind, wo ihre Spione und Sympathisanten die Autorität der Krone untergraben und Zwietracht unter der Arbeiterklasse säen.",al={"bruderschaft der defias","wer ist die defias","defias-bande"}},b1d432aa={q="Was ist die Kathedrale des Lichts?",a="Die Kathedrale des Lichts, die über dem Kathedralenplatz thront, ist das herausragende geistige Zentrum für die Menschheit und die Große Allianz. Nach dem Zweiten Krieg unter Erzbischof Alonsus Faol und dem damaligen Bischof Benedictus wiederaufgebaut, dient sie als Sitz der Kirche des Heiligen Lichts und als Hauptquartier des Ordens der Silbernen Hand. Paladine und Priester reisen aus allen Teilen der Reiche an, um zu trainieren, Weisheit zu suchen und in ihren großen, friedlichen Hallen zu meditieren.",al={"kathedrale des lichts","kathedrale von sturmwind","kirche des lichts sturmwind"}},["3414b788"]={q="Wie bin ich in Sturmwind gelandet?",a="Wenn Ihr Eure Reise in Nordhain begonnen und Euch durch den Wald von Elwynn gearbeitet habt, führte Euch die Hauptstraße direkt durch das Tal der Helden und in die befestigten Tore der Hauptstadt. Wenn Ihr aus Dun Morogh oder Eisenschmiede stammt, seid Ihr wahrscheinlich mit der Tiefenbahn gefahren, dem Wunderwerk gnomischer Ingenieurskunst, das die Zwergenfestung direkt mit dem Zwergendistrikt unter den Bergen verbindet. Reisende aus anderen Teilen von Azeroth erreichen die Tore von Sturmwind nach langen Märschen durch die südlichen Königreiche, auf der Suche nach dem letzten großen Bollwerk der Menschheit.",al={"wie bin ich hierhergekommen","wie komme ich nach sturmwind","wie gelange ich nach sturmwind"}},["68c43aeb"]={q="Was soll ich in Sturmwind tun?",a="Sturmwind ist das schlagende Herz der Allianz und ein Zufluchtsort, um sich auszuruhen, zu trainieren und sich zu versorgen. Unter den glänzend weißen Stadtmauern ist das Königreich jedoch tief gespalten. König Varian Wrynn ist unter mysteriösen Umständen verschwunden, was den jungen König Anduin und Hochlord Bolvar Fordragon in der Festung mit politischer Lähmung kämpfen lässt. Währenddessen rufen die umliegenden Grenzgebiete in Westfall und dem Rotkammgebirge nach Hilfe gegen grassierendes Banditentum, und die The Defias Brotherhood schmiedet Pläne aus den Schatten heraus. Ihr seid hier, um Euer Handwerk zu verfeinern, Euren Fraktionsführern Bericht zu erstatten und einem bedrängten Reich Euer Schwert zu leihen.",al={"warum bin ich hier","was soll ich hier tun","was ist meine aufgabe in sturmwind"}}},fp="14,142,19.590.0,15.532.0,27.258.0,21.287.1,17.236.1,19.351.2,30.238.0,35.216.0,38.251.1,48.261.1,50.272.0,40.223.0,65.267.0"}
P.entries["zone:stranglethorn"] = {n="Schlingendorntal",s="Trolle, Goblins, Piraten und Soldaten ringen um das Schlingendorntal. Südlich des Dämmerwalds ist das alte Kernland der Gurubashi zu einem Labyrinth aus Ruinen, wilden Tieren und rivalisierenden Lagern geworden.",h="Trolle, Goblins, Piraten und Soldaten ringen um das Schlingendorntal.",kw={"blutsegel","beutebucht","grom'gol","gurubashi","kurzen","nesingwary","revilgaz","schlingendorntal","venture company","zul'gurub"},ang={["class:Hunter"]="Als Jäger könnt Ihr den berühmten Großwildjäger Hemet Nesingwary am nördlichen Flussufer treffen. Er fordert Scharfschützen auf, die gefährlichsten Raptoren, Panther und Krokilisken des Dschungels aufzuspüren.",["faction:Alliance"]="Als Allianzangehörige erbt Ihr Sturmwinds kostspielige Bemühungen, den Dschungel zu erobern und zu befrieden. Nun verteidigen bedrängte Meuterer im Rebellenlager die Interessen des Königreichs.",["faction:Horde"]="Als Hordeangehörige könnt Ihr Euch auf das Basislager Grom'gol als strategische Festung auf dem südlichen Kontinent verlassen, das Zeppeline aus Durotar und der Unterstadt versorgen.",["profession:Herbalism"]="Als Kräuterkundige könnt Ihr an den Flussufern und Küsten des feuchten Blätterdachs nach Wildstahlblume, Fadeleaf, Golddorn und Lila Lotus suchen.",["race:Troll"]="Als Troll liegt Eure angestammte Heimat in der Wiege der Dschungeltrolle, dem Schlingendorntal. Auf die Verehrung Hakkars des Seelenschinders durch das Gurubashi-Imperium folgte ein Bürgerkrieg, der Stämme wie die Dunkelspeer über die Meere trieb."},sec={{t="Ruinen eines Imperiums",b="Zul'Gurub herrschte einst als Hauptstadt des Gurubashi-Imperiums über das Tal. Diese Herrschaft endete, als radikale Priester Hakkar den Seelenschinder beschworen und ein Bürgerkrieg die Region zerriss. Die Zandalari schlugen den Aufstand des Blutgottes nieder, doch das Imperium erholte sich nie davon. Nun kämpfen Nachfolgefraktionen im ganzen Dschungel. Die Bloodscalp halten den Nordwesten, während die Schädelspalter den Osten besetzen. Beide Stämme metzeln Außenstehende nieder, während sie ihre angestammte Heimat zurückfordern."},{t="Piraten und Profitjäger",b="Beutebucht prägt die Südspitze des Tals mit Handel und Seeverkehr. Das Steamwheedle Cartel gründete den Hafen, und die Blackwater Raiders führen ihn unter Baron Revilgaz. Blutsegelbukaniere, die entlang der Küste ankern, bedrohen den Hafen ständig. Weiter im Landesinneren holzt die Venture Company Bäume ab und baut in den Hügeln seltene singende Kristalle ab."},{t="Umkämpfte Wildnis",b="Rivalisierende Mächte treffen im gefährlichen Grenzland des Tals aufeinander. Die Horde hält das Basislager Grom'gol an der Westküste, und Goblin-Zeppeline verbinden es mit Durotar und Tirisfal. Allianz-Loyalisten im Rebellenlager suchen den abtrünnigen Colonel Kurzen. Im dichten Dschungel führt der berühmte Jäger Hemet Nesingwary Großwildexpeditionen an. Wanderer, die sich von seinen Jagden anziehen lassen, begegnen lauernden Panthern, riesigen Affen und feindlichen Soldaten."},{t="Der Wahnsinn im Dschungel",b="Colonel Kurzen führte eine Expedition aus Sturmwind in den nördlichen Dschungel, verfiel dann dem Wahnsinn und errichtete eine tyrannische Söldnerfestung. Das Gedankenauge, geführt von Mai'Zoth, einem Ogerzauberer vom nahe gelegenen Ogerhügel der Mosh'Ogg, verfing Kurzens Geist in Zauberei. Die Expedition verfiel dem Wahnsinn, und Kurzens ehemalige Männer spalteten sich ab und gründeten das Rebellenlager."}},faq={{q="Wer kontrolliert das Schlingendorntal?",a="Keine einzelne Macht kontrolliert das Schlingendorntal. Trolle der Bloodscalp und Schädelspalter, Kurzens Truppenlager, die Venture Company sowie militärische Stützpunkte der Horde und der Allianz halten rivalisierende Gebiete. Beutebucht ist die größte Siedlung und wird von Baron Revilgaz und den Blackwater Raiders regiert.",al={"wem gehört das schlingendorntal","wer herrscht über das schlingendorntal","fraktionen im schlingendorntal"}},{q="Was ist Beutebucht?",a="Beutebucht ist eine Hafenstadt auf den südlichen Klippen des Kap des Schlingendorntals. Einst war sie die menschliche Siedlung Schwarzmeerbucht, wurde von Trollen erobert und später vom Steamwheedle Cartel gesichert. Baron Revilgaz und Flottenmeister Seehorn führen sie als neutralen Handelshafen, der Reisende über das große Meer mit Ratschet verbindet.",al={"was ist beutebucht","hafen von beutebucht","wer führt beutebucht"}},{q="Warum wurde Colonel Kurzen abtrünnig?",a="Colonel Kurzen wurde abtrünnig, nachdem Mai'Zoth, ein Ogerzauberer, der das Gedankenauge führte, seinen Geist verstrickt hatte. Kurzen hatte eine Expedition aus Sturmwind in den Dschungel geführt, wurde jedoch unberechenbar und despotisch. Lieutenant Doren und loyale Soldaten spalteten sich ab, gründeten das Rebellenlager und stellten sich ihm entgegen.",al={"warum ist kurzen böse","was geschah mit kurzen","kurzens hintergrundgeschichte"}},{q="Was ist Zul'Gurub?",a="Zul'Gurub ist die zerstörte Hauptstadt des Gurubashi-Imperiums im Nordosten des Schlingendorntals. Vor fünfzehn Jahrhunderten beschworen radikale Priester dort Hakkar den Seelenschinder und lösten damit den Bürgerkrieg aus, der das Imperium beendete. Ranken und Ruinen bedecken die verlassene Stadt, doch dunkle Rituale bedrohen noch immer ihre Hallen.",al={"was ist zul'gurub","geschichte von zul'gurub","hauptstadt der gurubashi"}},{q="Was war der Stein der Gezeiten?",a="Der Stein der Gezeiten ist ein legendäres Relikt aus der alten Geschichte der Gurubashi, das ein Trollkrieger an der Küste fand. Er verlieh seinem Träger die Kontrolle über Wasser und Elementarbeschwörungen wie ein mächtiger Magier und brachte ihm so den Namen Tidebearer ein. Sein Fluch zog jeden Träger langsam aus der körperlichen Welt, bis er ins Meer ging und verschwand.",al={"stein der gezeiten","legende des tidebearers","gurubashi-wasserstein"}},{q="Wie reise ich ins Schlingendorntal?",a="Ihr könnt von Dämmerwald aus nach Süden über die Flussgrenze ins nördliche Schlingendorntal laufen. Zeppeline der Horde verbinden das Basislager Grom'gol mit Durotar und Tirisfal. Von Kalimdor aus nehmt Ihr das Handelsschiff, das zwischen Ratschet im Brachland und Beutebucht verkehrt.",al={"wie kommt man ins schlingendorntal","reise ins schlingendorntal","reise zum schlingendorntal"}}},fp="18,166,18.455.0,22.346.0,22.414.0,25.340.1,32.270.0,18.322.0,32.268.1,18.294.0,32.328.0,38.256.0"}
P.entries["zone:swampofsorrows"] = {n="Sümpfe des Elends",s="Grüne Drachenbrut bewacht den versunkenen Tempel von Atal'Hakkar unter dem Tränenteich. Zwischen dem Gebirgspass der Totenwinde und den Verwüsteten Landen liegt dieses salzverkrustete Moor mit gefährlichen Wildtieren und der Garnison der Horde in Steinard. Die Allianz hat hier keinen sicheren Zufluchtsort.",h="Grüne Drachenbrut bewacht den versunkenen Tempel von Atal'Hakkar unter dem Tränenteich.",kw={"schwarzer morast","zerschlagene","der sichere hafen","verirrte","tränenteich","sorgendunkel","steinard","versunkener tempel","sümpfe des elends","der tempel von atal'hakkar"},ang={["faction:Alliance"]="Ohne einen Außenposten, hinter dem Ihr Euch sammeln könnt, steht Euch eine einsame und feindselige Reise durch den Sumpf bevor. Bereitet Euch sorgfältig in Dunkelhain oder Burg Nethergarde vor, bevor Ihr aufbrecht.",["faction:Horde"]="Steinard ist Euer wichtiger vorgeschobener Stützpunkt auf dem südlichen Kontinent. Wyvernrouten verbinden die Siedlung direkt mit Kargath, Flammenkamm, Basislager Grom'gol, Beutebucht und Rog'mar in den Flusslanden.",["profession:Blacksmithing"]="An den Gebirgskämmen am nördlichen und südlichen Rand des Sumpfs könnt Ihr Eisen, Gold, Mithril und Echtsilber sammeln.",["profession:Herbalism"]="Das Moor ist eine der wenigen ergiebigen Quellen für Blindkraut in Azeroth. Außerdem findet Ihr dort reichlich Lebenswurz, Fadeblatt und Würgetang.",["race:Troll"]="Die versunkenen Ruinen von Atal'Hakkar erinnern an die dunkle Blutmagie, die das Gurubashi-Reich spaltete und den Zorn der Drachenaspekte auf sich zog."},sec={{t="Eine versunkene Geschichte",b="Die Sümpfe des Elends waren einst die nördliche Hälfte des gewaltigen Schwarzen Morasts. Nach dem Zerfall des Gurubashi-Reiches flohen fanatische Atal'ai-Trolle in das Moor und errichteten den Tempel von Atal'Hakkar. Sie wollten Hakkar den Seelenschinder beschwören, ihren blutdürstigen Loa. Der Aspekt Ysera spürte die Gefahr und versenkte die verfluchte Pyramide unter dem Tränenteich. Wächter des grünen Drachenschwarms unter Eranikus wurden zu ihrer Bewachung abgestellt.\n\nSpäter versengte der Kataklysmus des Dunklen Portals den südlichen Morast zu den Verwüsteten Landen. Das nördliche Moor erhielt seinen klagenden Namen."},{t="Außenposten und gebrochene Verbannte",b="Steinard ist der wichtigste Stützpunkt sesshafter Bewohner im Sumpf. Während des Ersten Krieges neben Rockard und Kyross gegründet, die heute beide in Ruinen liegen, wurde es unter Thrall wiederaufgebaut und zum südlichsten Aufmarschgebiet der Horde in den Östlichen Königreichen.\n\nJenseits seiner Palisaden durchqueren seltsame Wanderer das Moor. Auf Azeroth gestrandete Draenei wurden von Heimweh und Wahnsinn befallen und zu wilden Verirrten. Im Sicheren Hafen ist eine kleine Gemeinschaft klar denkender Zerschlagener Verbannter geblieben. Sie ist vorsichtig, aber bereit, friedlich mit Reisenden zu handeln."},{t="Das versinkende Moor",b="Raubtiere machen jede Durchquerung der Sümpfe des Elends gefährlich. Tiefe Moore verbergen hervorschnellende Krokilisken, giftige Spinnen, umherstreifende Sumpfjaguare und mit Sumpfschutt bedeckte Moorbestien. Bösartige Murlocs kriechen durch Küstenhöhlen und entlang des Nebelschilfstrands.\n\nSalzhaltige Gezeiten dringen landeinwärts und überziehen verrottete Baumstämme mit Salzkrusten. Weiter östlich bewacht aggressive Elite-Drachenbrut im Sorgendunkel die Zugänge zum Versunkenen Tempel. Sie greift jeden an, der sich ihrer Wacht nähert."}},faq={{q="Wie erreiche ich die Sümpfe des Elends?",a="Die übliche Landroute führt von Dunkelhain im Dämmerwald nach Osten, durch den Spukenden Gebirgspass der Totenwinde und hinab in den Sumpf. Aus dem Süden folgt Ihr der Hauptstraße von den Verwüsteten Landen nach Norden.",al={"wie komme ich zu den sümpfen des elends","straße durch die sümpfe des elends","nach steinard gelangen"}},{q="Warum liegt der Tempel von Atal'Hakkar unter Wasser?",a="Vor Jahrhunderten versuchte die Priesterschaft der Atal'ai, Hakkar den Seelenschinder nach Azeroth zu beschwören. Ysera, Aspekt des grünen Drachenschwarms, entdeckte ihre dämonischen Blutrituale und versenkte den Tempel im Moor, um eine Katastrophe abzuwenden. Grüne Drachenbrut bewacht seine versunkenen Hallen.",al={"warum ist der versunkene tempel versunken","wer versenkte den tempel","geschichte des versunkenen tempels"}},{q="Was ist Steinard?",a="Steinard war eine der ersten Siedlungen der orcischen Horde, nachdem sie während des Ersten Krieges das Dunkle Portal durchquert hatte. Kämpfe verwüsteten den Außenposten, doch Thrall ließ ihn vor Kurzem zurückerobern und wiederaufbauen, um die Logistik der Horde nahe den Verwüsteten Landen zu sichern.",al={"geschichte von steinard","orcischer stützpunkt im sumpf","wer gründete steinard"}},{q="Gibt es hier Siedlungen der Allianz?",a="In den Sümpfen des Elends gibt es keine Siedlungen, Wachen oder Flugrouten der Allianz. Wenn Ihr durch das Moor reist, nutzt Dunkelhain im Westen oder Burg Nethergarde im Süden als Stützpunkt.",al={"allianzstützpunkt in den sümpfen des elends","flugroute der allianz im sumpf","wo ist das lager der allianz"}},{q="Wer sind die seltsamen mutierten Humanoiden im Sumpf?",a="Diese seltsamen Humanoiden sind Draenei, die nach dem Einsturz des Dunklen Portals auf Azeroth gestrandet sind. Von ihrer Heimat abgeschnitten, verfielen die meisten der Verzweiflung und dem Wahnsinn und wurden zu feindseligen Verirrten. Eine kleine Gruppe geistig gesunder Zerschlagener Verbannter fand im Nordwesten Zuflucht im Sicheren Hafen und entschied sich für neutrales Überleben statt sinnloser Wut.",al={"wer sind die verirrten","was ist der sichere hafen","draenei im sumpf"}},{q="Was ist Sorgendunkel?",a="Sorgendunkel ist das dichte Sumpfgebiet östlich des Tränenteichs. Elite-Drachenbrut und Jungtiere des grünen Drachenschwarms patrouillieren dort und halten Sterbliche mit Gewalt fern, um die Geheimnisse des Versunkenen Tempels zu schützen.",al={"drachengebiet in den sümpfen des elends","drachen im sorgendunkel","grüne drachenbrut im sumpf"}}},fp="16,249,17.556.0,26.487.0,16.475.0,36.188.0,44.259.0,16.248.0,40.179.0,51.307.0,19.185.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="In Tanaris handeln Goblins unter sengender Sonne, während sich Gefahren im Sand regen. Gadgetzan heißt Allianz und Horde willkommen, während Sandfury-Trolle, Silithiden und uralte Mächte die Dünen jenseits der Stadt beherrschen.",h="In Tanaris handeln Goblins unter sengender Sonne, während sich Gefahren im Sand regen.",kw={"die höhlen der zeit","wüste","freibeuter","gadgetzan","nozdormu","sandfury","silithiden","steamwheedle","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="Als Reisender der Allianz findet Ihr zwischen den Düstermarschen und Feralas keine größeren Stützpunkte der Allianz. Das neutrale Gadgetzan bietet Euch einen wichtigen Ausgangspunkt für Reisen durch das südliche Kalimdor.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Gadgetzan als Handelszentrum nutzen, das die Routen vom Freiwindposten und Camp Mojache mit den von Silithiden befallenen Ödlanden im äußersten Süden verbindet.",["profession:Herbalism"]="Die trockene Hitze Tanaris' lässt Feuerblüte auf den wandernden Dünen gedeihen. Schattige Ruinen und feuchte Oasen bergen wertvollen Lila Lotus.",["profession:Mining"]="In den trockenen Klippen und Felsvorsprüngen Tanaris' finden sich Adern von Mithril, Truesilver, Iron und Gold. Vereinzelte Vorkommen von Small Thorium liegen tiefer in der Wüste.",["race:Troll"]="Als Troll zeigen Euch die Sandfury-Trolle von Zul'Farrak uralte Vettern, die in der Abgeschiedenheit der Wüste eine brutale Kultur erschufen."},sec={{t="Ein Meer aus Dünen",b="Tanaris liegt unter sengender Sonne, und Sand bedeckt einen Großteil des Landes. Innerhalb der Mauern von Zul'Farrak bewachen die Sandfury-Trolle ihr abgeschiedenes Zuhause. Hyänen, Basilisken und Skorpide durchstreifen den Wüstenboden. Tunnel ziehen sich unter der heißen Erde entlang."},{t="Goblin-Geschäfte",b="Nahe der Inselheimat der Goblins, Kezan, ist Tanaris zu einem Handelsplatz des Dampfdruckkartells geworden. Von der ummauerten Stadt Gadgetzan bis zu den Docks des Dampfdruckpiers heißen die Goblins Münzen von Allianz und Horde gleichermaßen willkommen. Schläger sorgen für Frieden, doch die Südmeerfreibeuter setzen Schiffen und Ausgrabungsstätten entlang der Küste weiterhin zu."},{t="Uralte Geheimnisse und neue Gefahren",b="Tanaris birgt Mächte, die älter sind als die Reiche der Sterblichen. Im Osten gehören die Höhlen der Zeit Nozdormu und dem bronzenen Drachenschwarm. Ihre Drachen nutzen manchmal die thermischen Aufwinde der Wüste.\n\nWeiter südlich markieren gewaltige Steintore den Titankomplex Uldum. Silithidenschwärme graben sich von Nestern wie der Klaffenden Schlucht und dem Giftigen Unterschlupf aus nach außen."}},faq={{q="Wie reise ich nach Tanaris?",a="Durchquert Tausend Nadeln zu Fuß, um die Schimmernde Ebene zu erreichen. Am südlichen Ende der Salzwüste führt ein Gebirgspass hinab nach Tanaris, und Gadgetzans Mauern sind sofort zu sehen. Schiffe fahren auch vom Hafen von Powderfuse in den Flusslanden zum Dampfdruckpier an der Ostküste.",al={"wie kommt man nach tanaris","reise nach tanaris","eingang nach tanaris"}},{q="Warum ist Gadgetzan beiden Fraktionen gegenüber neutral?",a="Das Dampfdruckkartell herrscht über Gadgetzan und ist dem Profit verpflichtet. Um den Handel zu schützen und Geschäfte anzuziehen, setzen die Goblins Neutralität durch. Ihre Schläger greifen jeden an, der innerhalb der Stadtmauern einen Fraktionskampf beginnt.",al={"warum ist gadgetzan neutral","können horde und allianz nach gadgetzan","neutralität der goblins in gadgetzan"}},{q="Was ist Zul'Farrak?",a="Zul'Farrak ist die ummauerte Wüstenhauptstadt der Sandfury-Trolle. Abgeschieden in der Wüste wurde der Stamm Außenstehenden gegenüber feindselig und bewacht seine heiligen Becken und geheimnisvollen Schreine.",al={"was ist zul'farrak","wer lebt in zul'farrak","stadt der sandtrolle"}},{q="Was sind die Insektenwesen, die überall in der Wüste nisten?",a="Die insektenartigen Bestien sind Silithiden, monströse Gräber, die gewaltige Bauten wie die Klaffende Schlucht und den Giftigen Unterschlupf errichten. Ihr Auftauchen in Tanaris beunruhigt den Leitenden Feldmesser Rutenwünschels und erinnert ihn an die uralten Schrecken des Kriegs der Sandverschiebung.",al={"was sind die käfer in tanaris","insektennester in tanaris","silithiden in tanaris"}},{q="Was liegt hinter den gewaltigen Steintoren im Süden?",a="Die gewaltigen Tore im Tal der Behüter markieren den Eingang zu Uldum, einer Forschungseinrichtung der uralten Titanen. Kolossale steinerne Wächter bewachen den versiegelten Eingang, während Gelehrte und Goblins aus der Ferne zusehen.",al={"riesige tore im südlichen tanaris","tore der ruinen von uldum","titantor in tanaris"}},{q="Wer lebt in den Höhlen der Zeit?",a="Die Höhlen der Zeit sind die angestammte Heimat des bronzenen Drachenschwarms und seines Aspekts Nozdormu. Aus verborgenen, gewundenen Tiefen beobachten die zeitlosen Drachen den Lauf der Geschichte. Manchmal patrouillieren sie am Himmel über den südlichen Dünen.",al={"lore der höhlen der zeit","was ist in den höhlen der zeit","drachen in tanaris"}}},fp="7,203,14.233.0,17.333.0,35.335.0,27.288.0,42.224.0,19.175.0,56.255.0,52.219.0,38.232.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Vor Kalimdors Nordwestküste erhebt sich Teldrassil, der Weltbaum, in dessen Krone Darnassus liegt. Die Druiden zogen ihn nach dem Dritten Krieg heran. Doch sein Wachstum ist beeinträchtigt.",h="Vor Kalimdors Nordwestküste erhebt sich Teldrassil, der Weltbaum, in dessen Krone Darnassus liegt.",kw={"rat der urahnen","crown of the earth","darnassus","dolanaar","fandral hirschhaupt","rut'theran","laubschattental","teldrassil","weltbaum"},ang={["class:Druid"]="Während Malfurion im Smaragdgrünen Traum gefangen ist, führt Erzdruide Fandral Hirschhaupt hier den Zirkel des Cenarius. Viele Druiden befürchten, dass Teldrassil überstürzt herangezogen wurde.",["faction:Alliance"]="Teldrassil ist die nördlichste Hochburg der Allianz in Kalimdor und ermöglicht den Schiffsverkehr und Handel zwischen Darnassus und den Königreichen auf dem Festland.",["profession:Herbalism"]="Teldrassil hat keine Mineralien oder Erze, doch auf seinem Blätterdach wachsen Friedensblumen, Silberblatt und Erdwurzel im Überfluss.",["race:NightElf"]="Als Nachtelf seht Ihr in Teldrassil den Neuanfang Eures Volkes nach der Verwüstung des Hyjal. Ohne den Segen der Aspekte muss der Baum dringend verteidigt werden."},sec={{t="Ein Blätterdach über dem Meer",b="Weit erstrecken sich Teldrassils Äste, tief unter ihnen liegt das verhüllte Meer. Auf seinen Zweigen finden sich Hügel, uralte Lichtungen und neblige Seen. Morgentau speist seine Flüsse. Am westlichen Rand liegt Darnassus, die Stadt der Kaldorei.\n\nWeit unten, am Fuß des Stammes, liegt Rut'theran. Es ist der Hafen der Insel. Ein Portal voller Magie verbindet den Ort mit der Krone."},{t="Die Weigerung der Aspekte",b="Im Dritten Krieg wurde Nordrassil geopfert. Shan'do Malfurion Sturmgrimm begab sich in den Smaragdgrünen Traum. In seiner Abwesenheit trat Erzdruide Fandral Hirschhaupt vor den Rat der Urahnen. Er bewegte sie dazu, an seiner Stelle einen weiteren Baum heranzuziehen. Denn er hoffte, den Kaldorei das unsterbliche Leben zurückzugeben, das sie verloren hatten.\n\nDoch Nozdormu und die Drachenaspekte hielten dies für ein Werk des Hochmuts. Sie verweigerten ihren Segen. So wuchs Teldrassil ohne Schutz. Mit ihm wuchsen Fehler, die nicht der Natur entsprangen."},{t="Ein schleichendes Leiden",b="Unter Teldrassils Wildtieren hat sich Gewalt ausgebreitet. Friedliche Furbolgstämme sind dem Wahnsinn verfallen, verzerrte Grells vermehren sich in den Grabhügeln, und Satyrn vollziehen dunkle Riten an Orten wie dem Teufelsfels. An den Gestaden der Dunkelküste stranden Meeresriesen, Drescher und Schildkröten, um den verderbten Gewässern rings um den Baum zu entkommen. Naturforscher und Schildwachen suchen auf den Ästen nach dem Schatten, der ihre neue Heimat langsam erdrosselt."}},faq={{q="Warum wurde Teldrassil herangezogen?",a="Nachdem Nordrassil am Ende des Dritten Krieges verwüstet worden war, verloren die Nachtelfen ihre Unsterblichkeit. Erzdruide Fandral Hirschhaupt drängte den Rat der Urahnen und die Druiden des Zirkels des Cenarius, einen neuen Weltbaum im Meer zu pflanzen. Er hoffte, so wiederherzustellen, was sein Volk verloren hatte.",al={"warum herangezogen","wer erschuf teldrassil","ursprung teldrassils"}},{q="Warum stellte Teldrassil die Unsterblichkeit der Nachtelfen nicht wieder her?",a="Nozdormu, der Zeitlose, segnete Nordrassil und verlieh den Nachtelfen die Unsterblichkeit. Als Teldrassil herangezogen wurde, hielt er ihr Verlangen für anmaßend und verweigerte dem neuen Baum seinen Segen.",al={"unsterblichkeit","warum nicht unsterblich","nozdormus segen"}},{q="Wie verlasst Ihr Teldrassil?",a="Geht durch Darnassus zum rosafarbenen Portal in den Tempelgärten. Es bringt Euch hinunter nach Rut'theran am Fuß des Stammes. Von dort nehmt Ihr ein Schiff über das Meer nach Auberdine auf dem Festland der Dunkelküste oder nutzt eine der verfügbaren Hippogryphenrouten.",al={"wie hinausgelangen","den baum verlassen","teldrassil schiff"}},{q="Warum gibt es in Teldrassil keine Erzadern?",a="Teldrassil wächst aus den lebenden Ästen und dem Holz eines gewaltigen Weltbaums, nicht aus kontinentalem Gestein. Ohne steinige Erdkruste im Untergrund gibt es in diesem Gebiet keine Metalladern oder Erzvorkommen, dafür wachsen Kräuter im Überfluss.",al={"wo gibt es kupfer","kein erz","bergbau in teldrassil"}},{q="Warum werden die Furbolgs und Tiere wahnsinnig?",a="Eine finstere Präsenz sickert in Teldrassils ungesegnete Wurzeln ein, und eine Krankheit hat das örtliche Wasser und die Pflanzenwelt verdorben. Sie treibt die friedlichen Holzlinge und den Furbolgstamm der Gnarlpine zur Aggression, während Überreste der Satyrn die Verderbnis gezielt nähren.",al={"verdorbene furbolgs","gnarlpine wahnsinnig","was ist die verderbnis"}},{q="Was ist Laubschattental?",a="Laubschattental ist ein geschütztes Tal auf Teldrassils östlichen Ästen, umgeben vom großen Baum Aldrassil. Junge Nachtelfen beginnen ihre Ausbildung in diesem friedlichen Zufluchtsort, bevor sie in die weite Welt hinausziehen.",al={"laubschattental","startgebiet","gebiet aldrassil"}}},fx={["11a6d5e5"]={q="Was ist Teldrassil?",a="Teldrassil ist ein riesiger Weltenbaum, der auf einer Insel vor der nordwestlichen Küste von Kalimdor gewachsen ist. Sein gigantischer Stamm ragt aus dem Nebelmeer empor und breitet sich in Äste aus, die so gewaltig sind, dass sie ein ganzes bewaldetes Reich mit Seen, Flüssen und der Hauptstadt Darnassus auf ihrem Blätterdach tragen.",al={"was ist das für ein ort","über teldrassil","erzähl mir von teldrassil"}},["313cd5a2"]={q="Was ist auf Teldrassil passiert?",a="Nach dem Dritten Krieg und dem Schaden, der am Nordrassil des Hyjal entstanden war, verschwand der Druide Malfurion Sturmgrimm. In seiner Abwesenheit überzeugte Erzdruide Fandral Hirschhaupt den Zirkel der Ältesten, einen neuen Weltenbaum zu züchten, um das Verlorene zu ersetzen. Obwohl er erfolgreich gewachsen ist, hat seitdem eine schleichende Verderbnis begonnen, seine Äste zu befallen.",al={"geschichte von teldrassil","wie entstand teldrassil","ereignisse auf teldrassil"}},c5e34e84={q="Wer lebt auf Teldrassil oder verwaltet es?",a="Teldrassil ist der angestammte Zufluchtsort und die heutige Heimat der Nachtelfen. Spirituell und zivil leiten die Hohepriesterin Tyrande Wisperwind und Erzdruide Fandral Hirschhaupt ihr Volk von der Hauptstadt Darnassus aus, unterstützt von der Schwesternschaft der Elune, den cenarischen Druiden und den Wächterinnen, die die Waldsiedlungen schützen.",al={"wer führt teldrassil an","anführer von teldrassil","wer lebt hier"}},b86e706e={q="Ist Teldrassil gefährlich?",a="Obwohl Teldrassil von Wächterinnen geschützt wird, wird es zunehmend gefährlicher. Ein dunkles Leiden hat die einheimischen Bestien und lokalen Furbolgs in den Wahnsinn getrieben, während bösartige Satyrn, blutrünstige Harpyien und umherstreifende Holzschlinger die Siedlungen jenseits der patrouillierten Straßen bedrohen.",al={"ist es hier sicher","bedrohungen auf teldrassil","gefahren auf teldrassil"}},["2863bed2"]={q="Warum heißt es Teldrassil?",a="In der darnassischen Sprache der Nachtelfen lässt sich Teldrassil direkt mit 'Krone der Erde' übersetzen. Es wurde zu Ehren seiner Rolle als monumentaler Weltenbaum benannt, der dazu bestimmt ist, ihre Zivilisation zu behüten und zu beschützen.",al={"was bedeutet teldrassil","bedeutung des namens teldrassil"}},["514d23b0"]={q="Wer ist Fandral Hirschhaupt?",a="Fandral Hirschhaupt ist der Erzdruide, der nach Malfurion Sturmgrimms Verschwinden in den Smaragdgrünen Traum die Führung der nachtelfischen Druiden übernahm. Leidenschaftlich, stur und aggressiv, setzte sich Fandral für die Pflanzung von Teldrassil ein und gerät häufig mit der Hohepriesterin Tyrande Wisperwind über die Politik aneinander.",al={"wer ist der erzdruide","fandral hirschhaupt geschichte","hirschhaupt"}},["52c333ac"]={q="Wer ist Tyrande Wisperwind?",a="Tyrande Wisperwind ist die Hohepriesterin der Göttin Elune und das oberste Oberhaupt des nachtelfischen Volkes. Nachdem sie ihr Volk zehntausend Jahre lang durch die lange Mahnwache und den Dritten Krieg geführt hat, leitet sie nun vom The Temple of the Moon in Darnassus aus die Geschicke.",al={"wer ist tyrande","hohepriesterin tyrande","wer führt die nachtelfen an"}},["29b1e9e4"]={q="Wie bin ich auf Teldrassil gelandet?",a="Wenn Ihr ein Nachtelf seid, ist dieser kolossale Weltenbaum die neue Heimat Eures Volkes. Nachdem Ihr Nordrassil und Eure uralte Unsterblichkeit auf dem Hyjal geopfert habt, um die Brennende Legion zu besiegen, siedelten die Kaldorei vor der Nordwestküste von Kalimdor um. Erzdruide Fandral Hirschhaupt und der Zirkel der Ältesten ließen Teldrassil im Nebelmeer wachsen, um Eurer Rasse einen neuen Zufluchtsort zu geben, und Ihr begann Eure Reise in seinen grünen Ästen im Laubschattental. Wenn Ihr von außerhalb hierher gereist seid, seid Ihr wahrscheinlich von der Dunkelküste zum Hafen von Rut'theran am Fuße des Baumes gesegelt und dann durch das leuchtende Portal geschritten, das Reisende direkt in die Krone befördert.",al={"wie gelange ich nach teldrassil","wie bin ich hierhergekommen","warum fange ich hier an"}},["8381279f"]={q="Was soll ich auf Teldrassil tun?",a="Ihr seid dazu berufen, den jungen Weltenbaum zu beschützen und das dunkle Leiden aufzudecken, das seine Äste beunruhigt. Trotz seiner üppigen Wälder greift eine finstere Verderbnis um sich: Holzschlinger werden aggressiv, friedliche Furbolgs des Gnarlpine-Stammes verfallen dem Wahnsinn und abscheuliche Satyrn lauern in schattigen Dickichten wie dem Teufelsfels. Angefangen im Laubschattental und bei der Hilfe für Siedlungen wie Dolanaar müsst Ihr den Wächterinnen und Druiden helfen, das Gleichgewicht wiederherzustellen. Ihr werdet die heiligen Mondbrunnen auffüllen, verdorbenes Ungeziefer ausrotten und die Geschichte Eures Volkes lernen, bevor Ihr Euch in die Hauptstadt Darnassus und über das Meer zum Festland von Kalimdor begebt.",al={"was soll ich auf teldrassil tun","warum bin ich hier","was ist meine mission hier"}}},fp="10,168,21.379.0,26.466.0,17.410.1,25.260.0,52.182.0,28.253.0,44.210.0,52.248.0,19.205.0"}
P.entries["zone:thousandneedles"] = {n="Tausend Nadeln",s="Im Süden Kalimdors erstrecken sich die Tausend Nadeln über einen trockenen Canyon mit Sandsteinsäulen. Tauren halten die Tafelberge, während Gnome und Goblins Raketenwagen über die Schimmernde Ebene jagen.",h="Im Süden Kalimdors erstrecken sich die Tausend Nadeln über einen trockenen Canyon mit Sandsteinsäulen.",kw={"klippenbehüter langhorn","düsterwolkengipfel","fizzel kupferbolz","freiwindposten","der große aufzug","grimmtotem","kravel kohlebart","illusionenrennbahn","pozzik","die schimmernde ebene","tausend nadeln"},ang={["faction:Horde"]="Der Große Aufzug verbindet das Brachland mit Eurer Festung am Freiwindposten und markiert eine strategische Südgrenze gegen Zentaurenklans und aufständische Tauren.",["profession:Engineering"]="Die Salzpfannen locken Tüftler an, die auf der Illusionenrennbahn Raketentreibstoff, Fahrzeugteile und Hochgeschwindigkeitsantriebe erforschen wollen.",["race:Gnome"]="An der Illusionenrennbahn in der Schimmernden Ebene könnt Ihr die Präzision und Eleganz gnomischer Ingenieurskunst neben den windschiefen Goblinkonstruktionen zeigen.",["race:Tauren"]="Als Tauren könnt Ihr sehen, wie hoch Euer Volk kletterte, um dem Gemetzel der Zentauren zu entkommen. Der Freiwindposten dient auch als Sammelpunkt für Angriffe auf die verräterischen Grimmtotem am Düsterwolkengipfel."},sec={{t="Ein Wald aus Stein",b="Vor der Großen Zerschlagung speisten Binnengewässer einen üppigen Flusscanyon, der zum Meer führte. Die Katastrophe zerriss das alte Kalimdor, hob das Flussbett über den Grundwasserspiegel und änderte den Lauf des Flusses. Trockener Fels und Sandsteinspitzen blieben zurück. Dutzende schlanke, zylindrische Säulen ragen wie ein versteinerter Wald aus dem Canyonboden empor.\n\nTauren errichteten Dörfer auf den Säulen und verbanden die Gipfel durch waghalsige Seilbrücken. Sie suchten Schutz vor feindseligen Zentaurenplünderern, die den schattenverhangenen Grund unter ihnen durchstreiften."},{t="Gefahren auf den Tafelbergen",b="Das Leben auf den nadelartigen Spitzen ist alles andere als friedlich. Am Freiwindposten stellen sich Tauren, die der Horde die Treue halten, räuberischen Windnattern und Wyvern vom Steilhang sowie verräterischen Verwandten des kriegerischen Grimmtotemklans entgegen, der sich auf dem Düsterwolkengipfel verschanzt hat. Klippenbehüter Langhorn leitet die Verteidigung des Plateaus. Er sucht mutige Kämpfer, die gegen Grimmtotem-Aufwiegler vorgehen und die zerbrechlichen Brücken zwischen den Gipfeln sichern.\n\nIm Norden bringen gewaltige mechanische Winden am Großen Aufzug Reisende aus dem südlichen Brachland hinab. Die Durchquerung des Canyonbodens bleibt ein tödliches Wagnis."},{t="Die Illusionenrennbahn",b="Im Südosten öffnen sich die Canyonwände zur Schimmernden Ebene, einer gewaltigen, ausgetrockneten Salzpfanne unter dem Meeresspiegel. In dieser rauen, blendenden Weite wahren Gnome und Goblins rund um die Illusionenrennbahn eine brüchige Neutralität. Die rivalisierenden Ingenieure Pozzik und Fizzel Kupferbolz lassen experimentelle Raketenwagen über das harte Salz rasen. Jeder will beweisen, dass sein Volk technologisch überlegen ist.\n\nDer Boxenstopp lockt Schurken, Schwindler wie Kravel Kohlebart und Jäger an, die den zähen Skorpionen, Schildkröten und Basilisken nachstellen, welche das glühend heiße Becken durchstreifen."}},faq={{q="Wie kamen die Tausend Nadeln zu ihrem Namen?",a="Die Tausend Nadeln verdanken ihren Namen den Dutzenden gewaltigen, zylindrischen Sandsteinsäulen, die aus dem Canyonboden ragen. Reißende Flüsse formten sie vor der Großen Zerschlagung. Heute gleichen sie einem Wald aus riesigen Nadeln.",al={"warum heißt es tausend nadeln","ursprung der nadelsäulen","geschichte der felsspitzen"}},{q="Wie gelangt man vom Brachland hinab in die Tausend Nadeln?",a="Reisende nehmen den Großen Aufzug, einen gewaltigen Doppelaufzug, der von Horde-Wachen an der Südgrenze des Brachlands betrieben wird. Ein Sturz von der Kante ist tödlich, wartet also auf die Plattform. Reisende der Allianz können auch von Westen aus durch Thalanaar in Feralas wandern.",al={"wie gelangt man zu den tausend nadeln","eingang zum großen aufzug","aufzug zu den tausend nadeln"}},{q="Warum leben die Tauren auf den Tafelbergen?",a="Zentaurenkriegsrudel trieben die nomadischen Tauren einst beinahe bis zur Auslöschung. Außenposten wie der Freiwindposten auf unzugänglichen Felssäulen schützten sie vor den Sturmangriffen der Zentauren. Hölzerne Hängebrücken verbanden die Tafelberge und ermöglichten den Tauren, hoch über den Raubtieren und Plünderern unter ihnen zu reisen.",al={"warum stehen tauren auf säulen","geschichte des freiwindpostens","tauren auf höher gelegenem gelände"}},{q="Was ist die Illusionenrennbahn?",a="Die Illusionenrennbahn ist ein Erprobungsgelände für Ingenieure auf der Salzpfanne der Schimmernden Ebene. Gnomische und goblinische Tüftler lassen experimentelle Raketenwagen über das flache Salz rasen, um ihren Streit darüber auszutragen, welches Volk die beste Maschinerie baut.",al={"salzpfannenrennstrecke","gnomen-goblin-rennen","raketenwagen-rennstrecke"}},{q="Wie präsent ist der Grimmtotemklan im Canyon?",a="Der Grimmtotemklan besetzt den Düsterwolkengipfel, eine befestigte Ansammlung von Felsspitzen direkt gegenüber dem Freiwindposten. Anders als die anderen Taurenstämme, die der Horde die Treue schworen, greifen die Grimmtotem ihre Verwandten an und schmieden Pläne, um die Tafelberge zu beherrschen.",al={"grimmtotem in den tausend nadeln","tauren am düsterwolkengipfel","böse tauren in den tausend nadeln"}},{q="Was ist die Schimmernde Ebene?",a="Die Schimmernde Ebene ist ein riesiger, ausgetrockneter Seeboden östlich der Tafelberge des Canyons. Ihre Salzkruste entstand, als das uralte Binnenmeer nach der Zerschlagung verdunstete. Glühende Hitze, blendend weißes Salz und gefährliche Raubtiere machen sie zu einer unwirtlichen Wüste, die vor allem für Hochgeschwindigkeitstests genutzt wird.",al={"salzpfanne","weiße wüste der tausend nadeln","östliche wüste"}}},fx={["0eee4587"]={q="Warum fahren Goblins und Gnome in der Wüste mit Raketenautos?",a="Der flache, offene Salzuntergrund der schimmernden Ebene bietet das perfekte Testgelände für den Test von Hochgeschwindigkeitsmotoren. Gnome und Goblins gründeten die Illusionenrennbahn, um den langjährigen Streit darüber, welche Rasse die bessere Technik besitzt, endgültig beizulegen.",al={"warum rennwagen","goblin gnom rennen","raketenauto rivalität"}},e421f132={q="Was hat es mit dem Düsterwolkengipfel und diesen geheimen Notizen auf sich?",a="Der Düsterwolkengipfel ist die schwer bewachte Festung des Stammes der Grimtotem auf den Tafelbergen östlich des großen Aufzugs. Dort gefundene geheime Korrespondenz enthüllt geheime Kontakte zwischen den Anführern der Grimtotem, wie Arnak Grimtotem, und einer unbekannten dunklen Macht, was auf verräterische Ambitionen weit jenseits einfacher Stammesfehden hindeutet.",al={"düsterwolkengipfel notizen","grimtotem notizen","düsterwolkengipfel geheimnis"}},["7b560411"]={q="Was planen die Grimtotem?",a="Die Grimtotem lehnen die Führung von Cairne Bluthuf und die kulturellen Veränderungen, die der Beitritt zur Horde mit sich brachte, grundlegend ab. Sie trachten danach, Cairne zu stürzen, die Autorität der Horde zu untergraben und verbünden sich sogar mit finsteren Mächten und beschwören Wesen der Vergeltung, um ihre Vorherrschaft durchzusetzen.",al={"grimtotem plan","was wollen grimtotem","grimtotem verschwörung"}},["853c4dd1"]={q="Was ist der Steilhang und warum wollen wir Wyverneier?",a="Der Steilhang ist der angestammte Nistplatz wilder Wyverns in Tausend Nadeln. Tauren aus dem Freiwindposten klettern zu diesen hohen Felsvorsprüngen hinauf, um befruchtete Wyverneier zu sammeln, damit diese sorgfältig aufgezogen und als treue Flugreittiere für die Horde ausgebildet werden können.",al={"steilhang wyverns","warum wyverneier sammeln","steilhang eier"}},dc3189d8={q="Wie bin ich in Tausend Nadeln gelandet?",a="Die meisten Reisenden kommen von Norden, indem sie durch das Brachland an Camp Taurajo vorbeireiten, bis sie schließlich den steilen Abhang erreichen, wo der massive, von Tauren konstruierte Der große Aufzug einen direkt auf den Boden des Canyons hinablässt. Alternativ können Abenteurer, die durch die dichten Wälder von Feralas nach Osten wandern, die westliche Schlucht zu Fuß betreten, während wagemutige Entdecker, die den Gefahren der Düstermarschen trotzen oder nach Theramore segeln, durch die umkämpften Lücken schlüpfen. Ein langer Marsch über Land nach Norden von den Wüsten von Tanaris bringt einen ebenfalls direkt in die weitläufige Salzfläche der schimmernden Ebene.",al={"wie kam ich hierher","wie erreiche ich tausend nadeln","nach tausend nadeln kommen"}},["16801326"]={q="Was soll ich in Tausend Nadeln tun?",a="Ihre Anwesenheit hier hängt von Ihren Loyalitäten und Ambitionen ab. Champions der Horde haben die Aufgabe, den Freiwindposten zu unterstützen: die Galak-Zentaurenhorden, die den Schluchtenboden durchstreifen, zurückzudrängen, Harpyienhorste zu überwachen, Wyverneier vom Steilhang zu sammeln und den verräterischen Grimtotem-Stamm zu bekämpfen, der sich auf dem Düsterwolkengipfel verschanzt hat. Für unabhängige Wanderer und Reisende der Allianz dient die dramatische Weite als gefährliche Überlandkreuzung zwischen dem zentralen und südlichen Kalimdor, die zur schimmernden Ebene führt, wo Goblin- und Gnom-Waghälse gutes Gold für Teile, Treibstoff und Hilfe bei ihrer ewigen Raketenauto-Rivalität zahlen.",al={"warum bin ich hier","was ist mein zweck hier","was mache ich in tausend nadeln"}},d1fb42e2={q="Was sind die Tausend Nadeln?",a="Tausend Nadeln ist ein riesiger, arider Canyon, der das zentrale und südliche Kalimdor teilt. Sein Canyonboden ist übersät mit hoch aufragenden Sandsteinfelsen, die sich wie ein versteinerter Wald in den Himmel strecken und oben durch zarte Seil- und Holzbrücken verbunden sind. Im Osten geht der Canyon in die schimmernde Ebene über, eine blendend weiße Salzpfanne.",al={"was ist das für ein ort","über tausend nadeln","erzähl mir von tausend nadeln"}},["98fcff4e"]={q="Warum ist hier alles aus Canyons und Säulen?",a="Vor langer Zeit, vor dem Großen Zerwürfnis, war diese Region ein grüner Fluss-Canyon, der von reißenden Wassern geformt wurde, die von Feralas nach Osten in ein Binnenmeer flossen. Als die Welt zerbrach, stieß das Kataklysmus das Flussbett in die Höhe und veränderte den Lauf des Flusses. Ohne Wasser trocknete das Land aus und hinterließ hoch aufragende Sandsteinsäulen und ein vertrocknetes Salzbett.",al={"warum gibt es felsnadeln","wie entstanden die nadeln","warum sandsteinsäulen"}},["05d5c74f"]={q="Sind die Tausend Nadeln gefährlich?",a="Es ist ziemlich gefährlich. Barbarische Galak-Zentauren patrouillieren in Raubzügen auf dem Canyonboden, während räuberische Geier, Skorpide und abtrünnige Harpyien die Klippen heimsuchen. Selbst die Seilbrücken zwischen den hohen Felsnadeln bergen Gefahren, da Raubvögel häufig auf unachtsame Reisende herabstürzen oder die Spannweiten beschädigen.",al={"wie gefährlich sind die tausend nadeln","gefahren hier","ist es sicher"}},["1b8e8bea"]={q="Warum hat die Horde mich in die Tausend Nadeln geschickt?",a="Die Horde unterhält hier eine wichtige Präsenz, um den lokalen Tauren-Stämmen zu helfen, die unter unerbittlichen Angriffen stehen. Der Freiwindposten ist ein wichtiges Bollwerk, das das Brachland mit den südlichen Wüsten verbindet, und die Horde braucht mutige Helden, um marodierende Zentauren zurückzudrängen und interne Bedrohungen zu unterdrücken.",al={"horde mission tausend nadeln","warum bin ich hier horde","was will die horde hier"}},a7c3b539={q="Ist das Land der Tauren?",a="Ja. Die kargen Canyons und hohen Mesas der Tausend Nadeln sind seit unzähligen Generationen traditionell das angestammte Gebiet mehrerer Tauren-Stämme, obwohl bösartige Zentaurenclans sie an den Rand des Überlebens drängten, bevor die Horde eintraf.",al={"gehören die tausend nadeln den tauren","gebiet der tauren","ist das land der shu'halo"}},fef8bf7c={q="Was ist der Freiwindposten?",a="Der Freiwindposten ist der primäre Außenposten der Horde in den Tausend Nadeln. Er wurde auf einer massiven Mesa hoch über dem Talboden errichtet und verfügt über hölzerne Aufzüge, einen Flugturm und ein Netzwerk von Hängebrücken, die zu benachbarten Felsnadeln führen.",al={"freiwindposten","was ist freiwindposten"}},["6ac472b0"]={q="Wer sind die Galak-Zentauren und warum greifen sie uns an?",a="Der Stamm der Galak sind die lokalen Zentauren, die den Canyonboden für sich beanspruchen. Wie alle Zentauren sind sie extrem territorial, nomadisch und gewalttätig. Sie jagen jeden Reisenden, der durch die Schluchten zieht, und versuchen, die Siedlungen der Tauren vollständig auszulöschen.",al={"galak-zentauren","warum greifen zentauren an","stamm der galak"}},["9f0b1de8"]={q="Warum hassen sie die Tauren?",a="Die Feindschaft zwischen Tauren und Zentauren ist uralt und unerbittlich. Über Generationen hinweg jagten umherziehende Zentauren auf den Ebenen von Kalimdor Tauren zum Zeitvertreib und führten brutale, grundlose Kriege, die die friedlichen Stämme ständig auf der Flucht hielten.",al={"warum hassen zentauren tauren","zentauren tauren fehde","zentauren groll"}}},fp="16,179,17.529.0,18.553.0,18.535.0,38.222.0,59.251.0,43.279.0,27.248.0,45.235.0,30.284.0"}
P.entries["zone:thunderbluff"] = {n="Donnerfels",s="Hoch über den Graslanden von Mulgore erhebt sich Donnerfels auf windgepeitschten roten Felsplateaus. Die Stadt ist die Hauptstadt der Tauren und das Herz ihres Geistes, ihrer Kultur und ihres Handels. Schwankende Hängebrücken und hölzerne Aufzüge verbinden die Höhen. Fern der marodierenden Zentauren ist sie ein friedlicher Ort für Reisende aus ganz Kalimdor.",h="Hoch über den Graslanden von Mulgore erhebt sich Donnerfels auf windgepeitschten roten Felsplateaus.",kw={"cairne bluthuf","die anhöhe der ältesten","aufzüge","hamuul runetotem","die anhöhe der jäger","magatha grimmtotem","mulgore","die teiche der visionen","die anhöhe der geister","donnerfels"},ang={["class:Druid"]="Auf der Anhöhe der Ältesten leitet Erzdruide Hamuul Runetotem das bedeutendste Heiligtum der Horde für Naturmagie. Er ist der erste Taurendruide seit Jahrtausenden, der in dieser Kunst unterrichtet wurde.",["class:Shaman"]="Auf der Anhöhe der Geister bieten die Teiche der Visionen einen stillen Ort, um die Elementargeister und die Geister Eurer Tauren-Vorfahren zu ehren und zu hören.",["faction:Horde"]="Donnerfels bringt eine ländliche Atmosphäre in den südlichen Teil von The New Horde in Kalimdor und ist viel friedlicher als Orgrimmars rauhe Wehrmauern.",["race:Tauren"]="Donnerfels steht für die hart erkämpfte Einigkeit und den Neubeginn Eures Volkes nach Generationen des Umherziehens und der Angriffe der Zentauren unter Oberhäuptling Cairne Bluthuf."},sec={{t="Eine dauerhafte Zuflucht",b="Unzählige Generationen lang durchstreiften die Tauren Kalimdor und kämpften ums Überleben gegen die Zentauren. Diese Zeit endete im Dritten Krieg, als sich Oberhäuptling Cairne Bluthuf mit Kriegshäuptling Thrall verbündete. Gemeinsam brachen Orcs und Tauren die Angriffe der Zentauren und gewannen die Weidegründe von Mulgore. Dann führte Cairne die verbündeten Stämme hinauf auf diese steinernen Bastionen und gründete Donnerfels. Es war das erste dauerhafte Zuhause, das die vereinten Stämme seit Jahrhunderten gekannt hatten."},{t="Eine Stadt in den Wolken",b="Auf den zentralen Felsplateaus liegen die Märkte, die Bank und das Gasthaus sowie ein hoch aufragender Horst für die Windreiter. Drei weitere Plateaus erstrecken sich über dem Abgrund, jedes mit seiner eigenen Aufgabe. Späher und Fährtenleser leben auf der Anhöhe der Jäger. Die Hüter der Überlieferungen leben auf der Anhöhe der Ältesten, zusammen mit dem Zirkel des Cenarius unter Erzdruide Hamuul Runetotem.\n\nDie Anhöhe der Geister ist den Geistern vorbehalten. Dort leben Schamanen und Priester. Tief unter ihnen liegen die Höhlen, die als die Teiche der Visionen bekannt sind."},{t="Ein brüchiger Zusammenhalt",b="Cairne Bluthuf genießt den Respekt fast aller Stämme, doch unter den erst kürzlich sesshaft gewordenen Tauren herrscht nicht überall Einigkeit. Der Stamm der Grimmtotem, angeführt von der Ältesten Magatha Grimmtotem, lebt auf der Anhöhe der Ältesten. Magatha stellt Cairnes versöhnliche Art und seine Treue zu den fremden Völkern der Horde infrage. Unter Cairnes wachsamen Augen herrscht Frieden, doch an den Ratsfeuern über den Ebenen bestehen weiterhin Spannungen."}},faq={{q="Wer herrscht über Donnerfels?",a="Oberhäuptling Cairne Bluthuf herrscht über Donnerfels und führt die vereinten Taurenstämme an. Seine Weisheit, Geduld und Stärke werden verehrt. Er gründete die Stadt, nachdem er sich mit Thralls Horde verbündet und die Zentauren aus Mulgore vertrieben hatte. So vereinte er die nomadischen Stämme unter The New Horde.",al={"anführer von donnerfels","wer hat das sagen","häuptling von donnerfels","cairne"}},{q="Wie gelangt Ihr nach Donnerfels hinauf?",a="Wenn Ihr zu Fuß oder auf einem Kodo ankommt, nehmt einen der großen hölzernen Plattformaufzüge an der Südwest- oder Nordostseite des zentralen Plateaus. Ihr könnt auch mit einem Wind Rider über Kalimdor fliegen.",al={"aufzug in donnerfels","wie kommt man hinein","eingang von donnerfels","hinaufkommen"}},{q="Warum errichteten die Tauren ihre Stadt auf hohen Felsplateaus statt am Boden?",a="Jahrhundertelang setzten Zentaurenstämme den Tauren während ihres nomadischen Lebens zu. Die steilen Klippen der Felsplateaus schützen ihre Heimat, Schmieden und verehrten Ältesten vor Angriffen vom Boden aus und geben den Tauren einen Ort, an dem sie in Frieden siedeln können.",al={"warum felsplateaus","warum leben sie auf klippen","klippen von donnerfels","höhenlage der tauren"}},{q="Was sind die verschiedenen Anhöhen der Stadt?",a="Das zentrale Plateau hat eine untere, mittlere und obere Ebene, umgeben von drei äußeren Plateaus. Auf der Anhöhe der Jäger befinden sich Krieger, Jäger und Fährtenleserhütten. Druiden, Weise und der Stamm der Grimmtotem leben auf der Anhöhe der Ältesten. Auf der Anhöhe der Geister gibt es Schreine der Erdenmutter und Ausbilder für Schamanen, Priester und Magier. Darunter liegen die Teiche der Visionen, die Schamanen und Priestern, die der spirituellen Zwiesprache geweiht sind, Schutz bieten.",al={"gebiete von donnerfels","was sind die anhöhen","bezirke von donnerfels"}},{q="Was sind die Teiche der Visionen?",a="Die Teiche der Visionen sind heilige Höhlen unter der Anhöhe der Geister. Tauren-Seher, Geistwandler und Praktizierende der arkanen Künste versammeln sich an diesen stillen, nebelverhangenen Wassern, um mit den Elementen Zwiesprache zu halten und Vorzeichen über die Zukunft ihres Volkes zu deuten.",al={"die teiche der visionen","höhle auf der anhöhe der geister","höhle in donnerfels"}},{q="Wer ist Magatha Grimmtotem?",a="Magatha Grimmtotem ist die Matriarchin und Älteste des Grimmtotemstamms. Sie lebt auf der Anhöhe der Ältesten und nimmt an Cairnes Rat teil, misstraut jedoch Außenstehenden und stellt die offene Haltung des Bloodhoof tribe gegenüber der Horde infrage.",al={"magatha","älteste","wer ist anführer der grimmtotem"}}},fx={["6fa5b073"]={q="Was ist Donnerfels?",a="Donnerfels ist die Hauptstadt der Tauren, hoch oben auf den windgepeitschten Tafelbergen im nördlichen Mulgore gelegen. Sie wurde von Oberhäuptling Cairne Bluthuf gegründet, nachdem er die Zentauren mit Thralls Horde zurückgedrängt hatte, und bietet einen sicheren, dauerhaften Zufluchtsort für ein Volk, das über Generationen als umherziehende Nomaden lebte.",al={"was ist diese stadt","erzähl mir von donnerfels","donnerfels stadt"}},fc90632b={q="Ist Cairne Bluthuf ein König?",a="Nein. Cairne Bluthuf trägt den Titel eines Oberhäuptlings der vereinten Taurenstämme. Die Gesellschaft der Tauren krönt keine Monarchen; Cairne regiert durch den tiefen Respekt, die Weisheit und die Stärke, die er über Jahrzehnte bewiesen hat, und nicht durch ein erbliches, königliches Gottesgnadentum.",al={"cairne bluthuf könig","ist cairne ein könig","tauren könig"}},["047fa056"]={q="Steht Cairne Bluthuf unter Thralls Befehl?",a="Thrall ist der Kriegshäuptling der Horde, aber seine Bindung zu Cairne gründet auf gegenseitiger Ehre und Bündnis und nicht auf strikter Unterwerfung. Cairne verpflichtete sein Volk der Horde aus Dankbarkeit und einer gemeinsamen Vision und steht Thrall als einer seiner vertrauenswürdigsten Berater und als Gleichgestellter zur Seite.",al={"steht cairne unter thralls befehl","ist thrall cairnes boss","cairne und thrall"}},["85c1a10f"]={q="Warum sind die Tauren der Horde beigetreten?",a="Zentaurenplünderer hatten die nomadischen Tauren im Brachland an den Rand der Ausrottung getrieben. Als Kriegshäuptling Thrall und die Orcs in Kalimdor landeten, halfen sie Cairnes Volk, die Belagerung der Zentauren zu brechen und Mulgore zu sichern, wodurch ein unzerbrechliches Band zwischen ihren Kulturen geschmiedet wurde.",al={"warum der horde beitreten","tauren horde allianz","wie traten die tauren bei"}},["3180b5ca"]={q="Was hat es mit dem Stamm der Grimtotem auf sich?",a="Die Grimtotem sind ein wilder und aggressiver Clan unter der Führung der Elder Crone Magatha. Im Gegensatz zum friedlichen Stamm der Bluthuf hegen sie tiefes Misstrauen gegenüber Außenstehenden und stellen offen Cairnes friedliche Führung in Frage, da sie glauben, die Tauren sollten Kalimdor erobern und die anderen Rassen vertreiben.",al={"grimtotem stamm","wer sind die grimtotem","grimtotem tauren"}},ca8246e8={q="Sind die Grimtotem Feinde von Cairne?",a="Offiziell bleiben sie Teil der vereinten Taurennation, und Magatha wohnt sogar auf Die Anhöhe der Ältesten. Unter der Oberfläche jedoch brodelt eine bittere politische Rivalität, da Magatha ständig Ränkespiele betreibt und glaubt, dass sie allein die rechtmäßige Vision hat, die Tauren zu regieren.",al={"sind grimtotem böse","grimtotem gegen cairne","magatha gegen cairne"}},["54829977"]={q="Ist Donnerfels gefährlich?",a="Innerhalb der Stadt sorgen die tapferen Wachen für Ordnung und Sicherheit vor den Bestien und Stachelebern, die auf den Ebenen darunter schleichen. Die größte unmittelbare Gefahr für Besucher ist der steile Abgrund – ein unvorsichtiger Schritt von den Rändern der Tafelberge oder den Holzbrücken aus endet tödlich.",al={"ist donnerfels sicher","bedrohungen in donnerfels","gefahr hier"}},["7db56847"]={q="Wie bin ich in Donnerfels gelandet?",a="Wenn Ihr ein junger Taure seid, begann Eure Reise im Süden auf dem geschützten Grasland der Hochwolkenebene und führte durch das Dorf der Bluthufe, bevor Ihr hierher kamt. Der Weg führt zum Fuß dieser gewaltigen Tafelberge, wo große hölzerne Seilaufzüge Reisende hunderte Fuß in den Himmel hieven. Alternativ reisen Besucher aus fernen Ländern über Kalimdor oft mit einem Wind Rider zum zentralen Wind Rider Roost auf den Felsen.",al={"wie kam ich hierher","wie kam ich nach donnerfels","wie erreiche ich donnerfels"}},["347b5cac"]={q="Was soll ich in Donnerfels tun?",a="Donnerfels ist das spirituelle und kulturelle Herz der vereinten Taurenstämme. Hier könnt Ihr fortgeschrittene Ausbildung von den Ältestenschamanen, Druiden, Jägern und Kriegern suchen, die sich auf den Anhöhen versammelt haben. Oberhäuptling Cairne Bluthuf und die Stammesältesten verlassen sich ebenfalls auf fähige Champions, um Mulgore vor anhaltenden Bedrohungen zu schützen – einschließlich marodierender Zentauren, der vordringenden Venture Company, Harpyien und rebellischen Stachelebern –, bevor sie Euch nach Osten in die größeren Prüfungen der Horde senden.",al={"was sollte ich in donnerfels tun","warum bin ich hier","was ist mein zweck hier"}}},fp="13,326,17.466.0,20.453.0,12.391.1,24.277.0,35.194.0,61.212.0,41.395.0,29.239.0,25.233.0"}
P.entries["zone:tirisfal"] = {n="Tirisfal",s="Tirisfal im Norden Lordaerons ist die Heimat von Fürstin Sylvanas Windläufer und ihren Verlassenen. Unter verdorbenen Himmeln umgeben gefallene Anwesen und ruhende Krypten ihre gewaltige Hauptstadt unter der Erde, die Unterstadt. Die hirnlose Geißel schnürt sie ein, ebenso wie die Eiferer des Scharlachroten Kreuzzugs. Hier kämpfen die Toten mit freiem Willen ums Überleben.",h="Tirisfal im Norden Lordaerons ist die Heimat von Fürstin Sylvanas Windläufer und ihren Verlassenen.",kw={"agamand","balnir","brill","todesend","verlassene","lichtungen","lordaeron","scharlachroter kreuzzug","sylvanas","tirisfal","unterstadt"},ang={["class:Priest"]="Heilige historische Stätten wie Faols Ruheplatz – das Grab von Erzbischof Alonsus Faol, dem Gründer der Silver Hand – liegen hier. Der Tod hat sie entstellt, und Eiferer und Schattenpriester streiten um sie.",["faction:Alliance"]="Für die überlebenden Völker der Allianz ist Tirisfal ein tragisches Denkmal für den Fall Lordaerons, voller entweihter Gräber einstiger Brüder und Schwestern im Glauben.",["faction:Horde"]="Tirisfal ist die lebenswichtige Bastion der Horde in den nördlichen Östlichen Königreichen. Es festigt die diplomatischen Bande zu den Verlassenen und wehrt menschliche Extremisten und die Geißel ab.",["race:Undead"]="Dies ist Euer angestammtes Heimatland gleich zweimal: das Königreich, das Ihr im Leben erbaut habt, und das unsichere Schutzgebiet, das Ihr im Untod unter Fürstin Sylvanas verteidigen müsst."},sec={{t="Ein Land im Zwielicht",b="Einst war Tirisfal die fruchtbare Wiege der Menschheit, bevor die Seuche des Lichkönigs seine Bewohner dahinraffte. Nun bricht die Sonne nur selten durch die Düsternis, über sterbenden Wäldern und kalten Küstenhügeln. Alte Gehöfte wie Agamands Mühlen stehen noch, doch die meisten ihrer Herren liegen in Massengräbern oder wandeln als ruhelose Tote. Dennoch hält sich in Städten wie Brill eine dunkle Widerstandskraft. Und in Todesend lernen die frisch erwachten Verlassenen, ihr zweites Leben zu ertragen."},{t="Ein Krieg an zwei Fronten",b="Fürstin Sylvanas herrscht nun unter den Ruinen von Lordaeron über die Region, doch ihr Volk ist von allen Seiten bedrängt. Diener der Geißel befallen noch immer Senken, Felder und bröckelnde Krypten und sind vollständig an den Frostthron in Nordend gebunden. Im Osten hält der Scharlachrote Kreuzzug das nördliche Tirisfal, von seiner Festung im Scharlachroten Kloster aus. Ihre Patrouillen haben geschworen, alle untoten Kreaturen zu vernichten, und führen einen ständigen Guerillakrieg gegen Kundschafter und Reisende der Verlassenen."},{t="Echos der uralten Vergangenheit",b="Die Geschichte der Lichtungen reicht weiter zurück als jede menschliche Krone. Vor langer Zeit wollten Hochelfen im Exil sich in diesen Wäldern niederlassen. Doch schattenhafte Mächte tief unter der Erde begannen, sie in den Wahnsinn zu treiben, und sie zogen weiter nach Norden. Jahrhunderte später erwählte der geheime Rat von Tirisfal diese schattigen Haine. Hier stärkte er seine einsamen Wächter, die Azeroth vor den Dämonen beschützten."}},faq={{q="Warum sind der Himmel grün und das Land verfault?",a="Während des Dritten Krieges entfesselten Prinz Arthas und die Geißel die Seuche der Untoten über dem Königreich Lordaeron. Die magische Verderbnis vergiftete nicht nur die Bevölkerung, sondern auch den Boden, die Bäume und das Wasser und ließ die Lichtungen in ewigem, unheimlichem und krankhaftem Verfall zurück.",al={"warum ist tirisfal verseucht","was geschah mit tirisfal","warum stirbt tirisfal"}},{q="Was unterscheidet hier die Verlassenen von der Geißel?",a="Die Verlassenen sind Untote, die sich nach der Schlacht am Hyjal aus der telepathischen Beherrschung des Lichkönigs befreiten und sich aus eigenem Willen Fürstin Sylvanas Windläufer anschlossen. Die Geißel, die auf den Gehöften und in den Ruinen umherstreift, bleibt eine hirnlose Sklavenschaft, gebunden an die Befehle des Lichkönigs.",al={"verlassene gegen geißel","warum greifen zombies untote an","sind alle untoten böse"}},{q="Wer sind die rot gepanzerten Soldaten, die Reisende angreifen?",a="Sie gehören zum Scharlachroten Kreuzzug, einem kompromisslosen abgespaltenen Orden aus früheren Paladinen der Silver Hand und Überlebenden. In der Überzeugung, alle Untoten seien unverbesserliche Abscheulichkeiten, die mit Schwert und Feuer gereinigt werden müssten, töten sie mit fanatischem Hass sowohl hirnlose Sklaven als auch die Verlassenen mit freiem Willen.",al={"scharlachroter kreuzzug","rote menschen","menschen im kloster"}},{q="Woher stammt der Name Tirisfal?",a="Der Name ist älter als jedes menschliche Königreich, und sein wahrer Ursprung ist in Vergessenheit geraten. Bekannt ist er vor allem durch den Rat von Tirisfal, den geheimen Orden der Magier, der die Wächter stärkte, damit sie Azeroth vor Dämonen beschützten.",al={"bedeutung von tirisfal","ursprung von tirisfal"}},{q="Wo beginnt die Reise der frisch erwachten Verlassenen?",a="Frisch erwachte Verlassene erheben sich aus den Krypten des Schattengrabes in Todesend, einer abgeschiedenen Ortschaft im Südwesten Tirisfals. Dort beurteilen Verwalter und Vollstrecker, ob die Auferstandenen bei Verstand und treu genug sind, um der Dunklen Fürstin zu dienen.",al={"startgebiet der untoten","wo liegt todesend","startgebiet der verlassenen"}},{q="Wie verlassen Reisende Tirisfal, um andere Kontinente zu erreichen?",a="Auf dem Hügel südlich von Brill, direkt außerhalb der Ruinen von Lordaeron, steht ein großer, von Goblins betriebener Zeppelin-Turm. Diese Luftschiffe bieten regelmäßige Direktverbindungen über das Meer nach Orgrimmar in Kalimdor und zum Basislager Grom'gol im Schlingendorntal.",al={"zeppeline in tirisfal","wie kommt man nach orgrimmar","wie kommt man ins schlingendorntal"}}},fx={["6c272224"]={q="Was ist Tirisfal?",a="Tirisfal ist das Kernland der Verlassenen an der Nordküste von Lordaeron. Einst das friedliche, fruchtbare Herz eines stolzen Menschenkönigreichs, wurde es während des Dritter Krieg von der Pest des Untodes der Geißel verwüstet. Heute bedecken verseuchte Wälder und ein ewiges grünes Zwielicht die Hügel, eingerahmt von den Ruinen von Lordaeron und umgeben von feindseligen Eiferern, wilden Bestien und verbliebenen Untoten.",al={"was ist tirisfal","erzähl mir von tirisfal","tirisfal gebietsüberlieferung"}},["342b65f9"]={q="War dies schon immer das Land der Untoten?",a="Nein. Über tausende von Jahren war Tirisfal die Wiege der menschlichen Zivilisation und das blühende Herz des Königreichs von Lordaeron. Friedliche Gehöfte, wohlhabende Mühlen und kleine Weiler florierten unter König Terenas Menethil. Diese Ära endete gewaltsam während des Dritter Krieg, als Prinz Arthas und der Kult der Verdammten mit der Pest durch das Land fegten und die Bewohner in untote Sklaven verwandelten, bevor Sylvanas Windläufer sie befreite.",al={"war tirisfal immer untot","wer lebte hier vorher","tirisfal vor der pest"}},["4790468d"]={q="Wer lebt oder herrscht in Tirisfal?",a="Die Verlassenen beanspruchen Tirisfal unter der Herrschaft von Königin Sylvanas Windläufer aus der Unterstadt. Ihr Griff ist jedoch ständig umkämpft. Der fanatische Scharlachroter Kreuzzug befehligt Befestigungen und sein großes Kloster im Nordosten, während geistlose Geißel-Kreaturen verlassene Farmen durchstreifen. An der östlichen Grenze beim Bollwerk koordinieren die Verlassenen ihre Aktionen mit der Argentumdämmerung, um die Schrecken der Westliche Pestländer einzudämmen.",al={"wer regiert tirisfal","wer kontrolliert tirisfal","tirisfal fraktionen"}},["97ffdb73"]={q="Ist Tirisfal gefährlich?",a="Extrem gefährlich. Außerhalb der Mauern der Außenposten der Verlassenen begegnet Ihr geistlosen Resten der Geißel, wilden Gnollen, riesigen Arachniden und bösartiger Tierwelt, die von der Pest verseucht wurde. Noch schlimmer sind die Eiferer des Scharlachroter Kreuzzug, die jeden Untoten auf Sicht hinrichten. Im fernen Osten liegen die Westliche Pestländer, wo Monster, die weitaus tödlicher sind als alles in Tirisfal, die Unvorsichtigen zerfleischen werden.",al={"wie gefährlich ist tirisfal","tirisfal bedrohungen","ist es hier sicher"}},["30e6283a"]={q="Wer hat in Brill das Sagen?",a="Magistrat Sevren beaufsichtigt die zivile Verwaltung von Brill und leitet den Wiederaufbau und das tägliche Überleben der Stadt. Die militärische Autorität und die taktischen Operationen, insbesondere der Feldzug gegen den nahegelegenen Scharlachroter Kreuzzug, werden von Exekutor Zygand befehligt.",al={"brill anführer","wer führt brill","das sagen in brill"}},["3fc3649e"]={q="Wem untersteht Magistrat Sevren?",a="Sevren dient der Dunklen Fürstin, Königin Sylvanas Windläufer. Als Magistrat von Brill vertritt er die zivile Autorität der Krone der Verlassenen in der Region und arbeitet dabei direkt mit den königlichen Exekutoren und der Royal Apothecary Society mit Sitz in der Unterstadt zusammen.",al={"vorgesetzter von sevren","wem untersteht sevren","führungskette in brill"}},["381a9b46"]={q="Wo befindet sich die Bansheekönigin?",a="Fürstin Sylvanas Windläufer residiert im Royal Quarter der Unterstadt, tief unter den Ruinen von Capital City, direkt südlich von Brill. Von ihrem Thronsaal aus leitet sie die Verlassenen in ihrem Krieg gegen die Geißel und den The Scarlet Crusade.",al={"wo ist sylvanas","sylvanas finden","standort der bansheekönigin"}},e7993821={q="Was ist Brill?",a="Brill ist die wichtigste Siedlung der Verlassenen im zentralen Tirisfal, gelegen an der Kreuzung nördlich von Capital City. Einst eine lebende Siedlung unter der Barov-Herrschaft, wurde sie nach dem Dritten Krieg wiederaufgebaut, um neu erweckten Untoten einen Ort der Ruhe, des Handels und der Organisation zu bieten, bevor sie in die Welt hinausziehen.",al={"über brill","was für eine stadt ist brill","hintergrundgeschichte von brill"}},["529e09c8"]={q="Lebten hier früher einmal lebende Menschen?",a="Ja. Brill war einst eine ruhige menschliche Gemeinde innerhalb des Königreichs Lordaeron. Es wurde zum Ausgangspunkt früher Experimente mit der Seuche, die von Kel'Thuzad orchestriert wurden, was zu Massenopfern und riesigen Massengräbern führte, noch bevor Prinz Arthas jemals eintraf, um Nachforschungen anzustellen.",al={"lebten menschen in brill","lebendige geschichte von brill","wer lebte in brill"}},["7b7ff5e2"]={q="Was ist die Taverne Zur Galgenschlinge?",a="Die Taverne Zur Galgenschlinge ist der zentrale Treffpunkt und das Gasthaus von Brill. Sie bietet Schutz, üble Getränke und eine Atempause vor den düsteren Wäldern außerhalb. In ihren dunkleren Ecken halten die Verlassenen gefangene Feinde – wie etwa die Eiferer des The Scarlet Crusade – für finstere Versuche der Apotheker gefangen.",al={"taverne zur galgenschlinge","gasthaus von brill","was ist die taverne zur galgenschlinge"}},["0d8014ee"]={q="Was hat es mit Agamands Mühlen auf sich?",a="Agamands Mühlen war einst das wohlhabendste und produktivste landwirtschaftliche Anwesen in Tirisfal, berühmt für Mehl und Getreide. Als die Seuche zuschlug, wurde der gesamte Komplex überrannt und ein Gemetzel folgte. Heute steht es als eine verrottende, von Windmühlen gesäumte Ruine da, die von den untoten Dienern der Geißel heimgesucht wird.",al={"hintergrundgeschichte von agamands mühlen","was geschah mit agamands mühlen","agamands mühlen"}},["001d4abe"]={q="Wer waren die Agamands?",a="Die Agamands waren eine adelige, wohlhabende menschliche Dynastie, die die weitläufigen Mühlen entwickelte und Grundbesitz in ganz Tirisfal hielt, einschließlich Brill. Während des Dritten Krieges konnte ihr Reichtum sie nicht retten; die Familie fiel der Geißel zum Opfer und ihre reanimierten Patriarchen suchen weiterhin das Anwesen heim.",al={"familie agamand","wer lebte in agamands mühlen","die agamands"}},eeb96a2c={q="Warum sind sie uns gegenüber feindselig, wenn sie auch Untote sind?",a="Die Untoten, die Agamands Mühlen heimsuchen, haben ihren freien Willen nie wiedererlangt. Im Gegensatz zu den Verlassenen, die sich von der mentalen Kontrolle des Lichkönigs befreit haben, bleiben diese Kreaturen als gedankenlose Sklaven der Geißel gefangen, gezwungen, jeden Lebenden oder abtrünnigen Toten zu vernichten, der ihr Gebiet betritt.",al={"warum greifen die agamands uns an","warum sind die untoten der agamands feindselig","warum gegen andere untote kämpfen"}},a357af07={q="Wohin führt das alles nach Tirisfal?",a="Die meisten Verlassenen reisen durch den Gebirgspass nach Süden in den Silberwald, um bei der Sicherung der südlichen Grenze zu helfen und gegen Agenten von Dalaran und Rot Hide-Gnolle zu kämpfen. Alternativ bieten Zeppeline südlich von Brill eine Passage nach Orgrimmar oder zum Basislager Grom'gol auf der anderen Seite des Meeres.",al={"wohin nach tirisfal","nächstes gebiet nach tirisfal","nach tirisfal"}},["50336b90"]={q="Was ist die Unterstadt?",a="Die Unterstadt ist die weitläufige unterirdische Hauptstadt der Verlassenen, erbaut innerhalb der alten Abwasserkanäle, Krypten und Katakomben unter den zerstörten Ruinen von Lordaeron. Sie dient als Festung von Königin Sylvanas und als Command Center für die Operationen der Verlassenen in ganz Azeroth.",al={"was ist die unterstadt","hintergrundgeschichte der unterstadt","über die unterstadt"}},ddddba9f={q="Ist die Grenze zum Silberwald als Nächstes dran?",a="Ja. Wenn Ihr der Straße nach Süden aus Tirisfal folgt, gelangt Ihr direkt in den Silberwald. Dies ist die natürliche Fortsetzung Eures Dienstes für die Verlassenen, wo Ihr Euch der wachsenden Bedrohung entlang der südlichen Grenzen von Lordaeron stellt.",al={"als nächstes in den silberwald","gehe ich als nächstes in den silberwald","grenze zum silberwald"}},["789ead4d"]={q="Wie bin ich in Tirisfal gelandet?",a="Wenn Ihr ein neu erweckter Verlassener seid, seid Ihr während des Falls von Lordaeron an die Geißel gestorben und hier begraben worden. Da der Griff des Lichkönigs gebrochen ist, kehrte Euer freier Wille zurück und Ihr habt Euch aus dem Grab im abgelegenen Tal von Todesend herausgekämpft. Wenn Ihr zu den anderen Völkern der Horde gehört, seid Ihr wahrscheinlich über die Zeppeltürme zwischen Brill und der Unterstadt angekommen, die dieses verseuchte Reich direkt mit Orgrimmar und dem Basislager Grom'gol verbinden.",al={"wie bin ich hierher gekommen","wie bin ich nach tirisfal gekommen","wie bin ich angekommen"}},["89135166"]={q="Was soll ich in Tirisfal tun?",a="Euer Ziel ist es, den Verlassenen dabei zu helfen, ihren brüchigen Halt über die verseuchten Herzlande von Lordaeron zu sichern. Von den Krypten von Todesend in Richtung Brill müsst Ihr die gedankenlose Geißel ausmerzen, die verlassene Bauernhöfe heimsucht, die fanatischen Eiferer des The Scarlet Crusade ausschalten, die aus dem Norden vordringen, und die verseuchten Bestien ausdünnen, die durch die verrottenden Wälder streifen. Dies beweist Euren Wert für Fürstin Sylvanas und bereitet Euch darauf vor, ihrem wachsenden Königreich unter den Ruinen von Capital City zu dienen.",al={"was soll ich hier tun","warum bin ich in tirisfal","was ist mein ziel hier"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Unterstadt",s="Unter den zerschlagenen Ruinen der Hauptstadt Lordaerons liegt Unterstadt, die dunkle Festung der Verlassenen. Fürstin Sylvanas Windläufer entriss sie der Geißel und machte sie zu einem Zufluchtsort, den kein Feind durchdringen kann. Heute ist sie der Sitz der Macht der Verlassenen. Und sie ist die große Bastion der Horde im Norden der Östlichen Königreiche.",h="Unter den zerschlagenen Ruinen der Hauptstadt Lordaerons liegt Unterstadt, die dunkle Festung der Verlassenen.",kw={"das apothekarium","arthas","verlassene","lordaeron","geißel","sylvanas","terenas","tirisfal","unterstadt","varimathras"},ang={["faction:Horde"]="Als wichtigster Stützpunkt der Horde in den Östlichen Königreichen sichert Unterstadt Zeppelinstrecken direkt nach Durotar und zum Basislager Grom'gol.",["race:Human"]="Unter dem Boden Eures gefallenen Stammesreiches liegt eine düstere Verkehrung der königlichen Krypten Lordaerons, bevölkert von den wandelnden Leichen Eurer einstigen Brüder.",["race:Orc"]="Tief in eben diesen Kerkern war einst der legendäre Kriegshäuptling Orgrim Schicksalshammer von der Allianz von Lordaeron eingekerkert, bevor ihm seine geschichtsträchtige Flucht gelang.",["race:Undead"]="Unterstadt ist Euer eigenes Herrschaftsgebiet und Eure Heimat, von Euch selbst ausgehoben, nachdem Ihr Euch aus dem eisernen Griff des Lichkönigs befreit habt."},sec={{t="Von königlichen Krypten zur Geißelfestung",b="Lange vor der Seuche nannte man die Katakomben und Abwasserkanäle unter dem Palast bereits Unterstadt. Dort lagen Adlige begraben, neben den ärmsten Menschen des Reiches. Auch die tiefsten Kerker des Königreichs befanden sich dort. Selbst Orgrim Schicksalshammer, der ehemalige Kriegshäuptling, wurde dort gefangen gehalten, bevor er entkam.\n\nIm Dritten Krieg ermordete Arthas Menethil König Terenas und verwüstete die Hauptstadt. Dann ließ der Prinz seine untoten Diener graben. Sie erweiterten die alten Gänge zu einem befestigten Herrschaftssitz der Geißel. Doch die Geißel erlebte die Vollendung ihrer dunklen Hauptstadt nie."},{t="Der Aufstieg der Verlassenen",b="Als die Macht des Lichkönigs schwand, befreite sich Fürstin Sylvanas Windläufer von seinem Willen und nahm Tausende Untote mit sich. Sie überfiel Arthas aus dem Hinterhalt, und er floh nach Nordend zurück. Es folgte ein erbitterter Bürgerkrieg gegen die Überreste der Geißel, die Schreckenslords und den menschlichen Widerstand. Daraus ging Sylvanas mit den halbfertigen Katakomben hervor. Sie nannte ihr Volk die Verlassenen und beaufsichtigte jahrelange Arbeiten an der weitläufigen Stadt."},{t="Die Architektur der Verdammten",b="Die Stadt erstreckt sich in Ringen um das Handwerksviertel, und gewaltige Aufzüge verbinden sie mit den Palastruinen darüber. Ringsum liegen die anderen Viertel, darunter das giftige Apothekarium. Dort braut die Königliche Apothekervereinigung hochwirksame Seuchen, neben Kanälen voller grünen Schleims. Noch tiefer hält die Bansheekönigin im Königsviertel Hof, gemeinsam mit ihrem Schreckenslord-Kommandanten Varimathras. Legionen turmhoher Monstrositäten halten Wache."}},faq={{q="Was war Unterstadt, bevor die Untoten sie übernahmen?",a="Unter dem Palast von Lordaeron lagen die uralten Krypten der menschlichen Könige, dazu der Kerkerkomplex und das weitläufige Abwassernetz der Stadt. Dort waren Kriegsgefangene wie Orgrim Schicksalshammer untergebracht, ebenso mittellose Bürger, die in den unterirdischen Schatten lebten. Die Kerker unter dem Palast nannte man bereits Unterstadt. Nachdem Prinz Arthas die Hauptstadt geplündert hatte, begann er, diese Katakomben in eine Festung der Geißel zu verwandeln, bevor Sylvanas sie einnahm.",al={"ursprünge unterstadts","was war unterstadt ursprünglich","geschichte der kanalisation lordaerons"}},{q="Warum wurde die Stadt unterirdisch statt an der Oberfläche gebaut?",a="Die oberirdische Stadt Lordaeron wurde im Dritten Krieg völlig zerstört. Dadurch ließ sie sich nur schwer gegen den Scharlachroten Kreuzzug, die Streitkräfte der Geißel und überlebende Mitglieder der Allianz verteidigen. Die unterirdischen Tunnel boten natürlichen Schutz, Engpässe und Verborgenheit. So konnten die Verlassenen den ursprünglichen Bau der Geißel vollenden und unbemerkt gedeihen.",al={"warum unterirdisch leben","warum lordaeron nicht wiederaufbauen","warum unterstadt unter den ruinen liegt"}},{q="Wer herrscht über Unterstadt?",a="Die Stadt wird von Fürstin Sylvanas Windläufer beherrscht, der Bansheekönigin und Königin der Verlassenen. Sie regiert vom Königsviertel aus, bewacht von königlichen Wachen der Verlassenen und ihrem unterworfenen Schreckenslord-Leutnant Varimathras. Sylvanas befreite sich nach der Schlacht um Hyjal vom Willen des Lichkönigs. Die Stadt hat außerdem ein Kriegsviertel, ein Schurkenviertel und ein Magieviertel.",al={"wer ist der anführer von unterstadt","herrscher von unterstadt","wer regiert unterstadt"}},{q="Was ist das Denkmal für König Terenas in den Ruinen darüber?",a="Über den Hauptaufzügen der Stadt steht ein steinernes Denkmal für den ermordeten König Terenas Menethil II. Sein Leichnam liegt nicht darin, denn er wurde verbrannt und seine Asche während der Wiedererweckung von Kel'Thuzad verstreut. Überlebende Menschen der Allianz meißelten das Denkmal mutig inmitten der Ruinen, damit die Erinnerung an Lordaerons letzten wahren König fortbesteht.",al={"grab von könig terenas","grab im thronsaal von lordaeron","wer baute das grabmal über unterstadt"}},{q="Was sind die seltsamen Geräusche im Thronsaal von Lordaeron?",a="Im zerstörten Thronsaal über den Aufzügen von Unterstadt hallen die Echos der Vergangenheit noch immer nach. Besucher, die in der Mitte stehen, können leise geisterhafte Klänge hören: die Jubelglocken und Rosenblätter bei Arthas' Rückkehr, die warnenden Worte des Propheten Medivh und das letzte Gespräch zwischen König Terenas und seinem vatermörderischen Sohn.",al={"geistergeräusche im thronsaal","flüstern im thronsaal","stimmen im thronsaal von lordaeron"}},{q="Warum lassen die Verlassenen andere Mitglieder der Horde hierher?",a="Die Verlassenen schlossen sich aus Überlebensgründen mit der Horde des Kriegshäuptlings Thrall zusammen, denn sie sind von feindseligen Scharlachroten Fanatikern und Legionen der Geißel umzingelt. Die giftigen Dämpfe und alchemistischen Flüsse sind für die lebenden Völker der Horde erstickend, doch Abgesandte und Reisende dürfen die Stadt betreten, um diplomatische und militärische Verbindungen zu stärken.",al={"warum sind orcs in unterstadt","horde in unterstadt","warum gehört unterstadt zur horde"}}},fx={a590d153={q="Was ist die Unterstadt?",a="Die Unterstadt ist die unterirdische Hauptstadt der Verlassenen, die direkt unter den zerstörten Ruinen der Hauptstadt in Tirisfal erbaut wurde. Sie wurde aus alten königlichen Krypten, Abwasserkanälen und Katakomben herausgehauen und von Prinz Arthas als Festung der Geißel ausgebaut, bevor Fürstin Sylvanas Windläufer und ihre abtrünnigen Untoten sie während des Bürgerkriegs einnahmen. Heute dient sie als befestigter Zufluchtsort für Untote mit freiem Willen, durchzogen von giftigem Schlamm und wachsam bewacht gegen alle lebenden Eindringlinge.",al={"was ist die unterstadt","erzähl mir von der unterstadt","unterstadt hintergrundgeschichte"}},c51b16b2={q="Was geschah mit dem alten König von Lordaeron?",a="König Terenas Menethil II. wurde im Thronsaal direkt über dieser Stadt von seinem eigenen Sohn, Prinz Arthas, ermordet. Nachdem er aus Nordend zurückgekehrt war, verdorben durch die Runenklinge Frostgram, erschlug Arthas seinen Vater und ließ die Geißel über das Königreich hereinbrechen. Terenas' Asche wurde später vom Todesritter gestohlen, um Kel'Thuzad wiederzubeleben, wobei nur der Gedenkstein und die getrocknete Blutspur zurückblieben, die Ihr noch immer in der Nähe des zerstörten Throns sehen könnt.",al={"schicksal von könig terenas","was geschah mit könig terenas","wer tötete könig terenas"}},c11144c7={q="Wer war Arthas?",a="Arthas Menethil war der Kronprinz von Lordaeron und ein berühmter Paladin der Silbernen Hand. In seinem verzweifelten Versuch, die Plage des Untodes, die seine Heimat überrollte, aufzuhalten, wurde sein Kreuzzug rücksichtslos und fanatisch. In Nordend bemächtigte er sich der verfluchten Runenklinge Frostgram, die seine Seele verschlang und ihn zum schrecklichen Champion des Lichkönigs machte. Er kehrte nur nach Hause zurück, um seinen Vater abzuschlachten, Lordaeron dem Erdboden gleichzumachen und schließlich nach Norden zurückzukehren, um mit dem Frostthron zu verschmelzen.",al={"wer ist arthas","prinz arthas hintergrund","arthas menethil"}},["7f6bbd49"]={q="Wer ist Sylvanas Windläufer?",a="Fürstin Sylvanas Windläufer war einst die tapfere Waldläufergeneral von Silbermond, die Quel'Thalas während des Dritten Krieges gegen die Geißel verteidigte. Als sie fiel, riss Arthas ihre Seele aus ihrem Körper und verwandelte sie in eine Banshee, um sie zu quälen. Als der Griff des Lichkönigs schwächer wurde, brach sie frei, nahm ihre körperliche Form zurück und scharte andere unabhängige Untote um sich, die Verlassenen. Jetzt regiert sie als ihre Bansheekönigin vom Königsviertel aus.",al={"wer ist die bansheekönigin","sylvanas hintergrund","wer ist sylvanas"}},["2a8de90f"]={q="Warum wird Sylvanas die Dunkle Fürstin genannt?",a="Die Verlassenen ehren Sylvanas als die Dunkle Fürstin, weil sie sie aus der sinnlosen Knechtschaft des Lichkönigs befreit und ihnen Zuflucht gewährt hat, als der Rest von Azeroth nach ihrer totalen Ausrottung strebte. Der Beiname wird neben ihrem Titel als Bansheekönigin verehrt und spiegelt sowohl ihre schattenhafte Meisterschaft über den Tod als auch die wilde, unnachgiebige Hingabe ihrer untoten Untertanen wider.",al={"warum dunkle fürstin","titel dunkle fürstin sylvanas","bedeutung dunkle fürstin"}},["84f18f47"]={q="Warum sind die Verlassenen Teil der Horde?",a="Umgeben von feindseligen Scharlachroten Kreuzzüglern, der unerbittlichen Geißel und rachsüchtigen Überresten der Allianz, konnten die Verlassenen in Lordaeron nicht allein überleben. Fürstin Sylvanas nahm über das Meer Kontakt mit Kriegshäuptling Thrall auf und schmiedete ein pragmatisches Zweckbündnis. Die Horde gewann einen entscheidenden militärischen Stützpunkt in den Östlichen Königreichen, während die Verlassenen wesentliche Verstärkungen und politische Legitimität in ihrem Überlebenskampf sicherten.",al={"warum sind die verlassenen bei der horde","untote treten der horde bei","verlassene horde allianz"}},["71200045"]={q="Was ist die Geißel und sind sie noch in der Nähe?",a="Die Geißel ist die riesige, gefräßige Armee aus sinnlosen Untoten, die von der Brennenden Legion erschaffen wurde und vom Lichkönig aus Nordend regiert wird. Obwohl die Verlassenen die Unterstadt und Tirisfal ihrem Griff entrissen haben, bleibt die Geißel eine unmittelbare, tödliche Gefahr. Ihre Legionen unter dem Kommando von Kel'Thuzad ersticken noch immer die nahegelegenen Pestländer und befallen verlassene Gehöfte und Krypten in Tirisfal.",al={"ist die geißel in der nähe","was ist die geißel","geißel in lordaeron"}},["501548ab"]={q="Wo ist der Lichkönig jetzt?",a="Der Lichkönig residiert auf dem Frostthron in den fernen, eisigen Einöden von Nordend. Nach dem Bürgerkrieg in den Pestländern floh Prinz Arthas aus Lordaeron, um seinen schwächer werdenden Meister zu beschützen. Er bestieg den Gletscher und verschmolz ihre Essenzen zu einer einzigen schrecklichen Entität. Von dieser arktischen Bastion aus wacht sein eisiger Blick noch immer über Azeroth.",al={"wo ist der lichkönig","standort des lichkönigs","wo ist arthas jetzt"}},["4cc7f971"]={q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist ein fanatischer Orden menschlicher Eiferer, der aus den Ruinen der Verteidigung von Lordaeron hervorgegangen ist. Geblendet von ihrem rechtschaffenen Hass auf die Untoten, unterscheiden sie nicht zwischen der sinnlosen Geißel und den Verlassenen mit freiem Willen. Sie betrachten jeden, der vom Untod gezeichnet ist – sowie jeden lebenden Außenseiter, der sie toleriert – als abscheuliche Kreaturen, die nur auf den Scheiterhaufen gehören. Ihre Hauptbastion in Tirisfal ist das Scharlachrote Kloster.",al={"wer ist der scharlachrote kreuzzug","scharlachrote kreuzzügler","scharlachroter kreuzzug hintergrund"}},["271820ed"]={q="Ist die Unterstadt gefährlich?",a="Sie ist außerordentlich gefährlich, besonders für Lebende. Kanäle mit rohen alchemistischen Abfällen und giftigem Schlamm durchziehen die Straßen der Stadt und füllen die höhlenartigen Hallen mit giftigen Dämpfen, die das Atmen für Besucher aus Fleisch und Blut gefährlich machen. Unter den gepflasterten Vierteln liegen verseuchte Abwasserkanäle, und noch tiefer finden geheime Experimente statt, bei denen täglich dunkle Alchemie und rücksichtslose Attentate geplant werden.",al={"ist die unterstadt sicher","gefahr in der unterstadt","gefahren in der unterstadt"}},["2539a3c3"]={q="Wie bin ich in der Unterstadt gelandet?",a="Als ein Verlassener führte Euer Weg Euch natürlich hierher, nachdem Ihr in Todesend aus dem Tod erwacht seid und Eure Loyalität in Tirisfal bewiesen habt, indem Ihr den Straßen vorbei an Brill gefolgt seid, um unter die zerstörten Ruinen der Hauptstadt hinabzusteigen. Wenn Ihr aus Kalimdor oder fernen Ländern stammt, seid Ihr wahrscheinlich an Bord eines Zeppelins der Horde angekommen, der an den Türmen direkt außerhalb der Hauptstadt anlegt, oder Ihr seid durch die verheerte Landschaft gewandert. Die Unterstadt ist der wichtigste Stützpunkt der Horde im nördlichen Lordaeron und bietet Schutz und Bestimmung unter den alten Palastkatakomben.",al={"wie bin ich hierher gekommen","wie erreiche ich die unterstadt","wie kommt man in die unterstadt"}},b63c4cf2={q="Was soll ich in der Unterstadt tun?",a="Ihr seid hier, um die Verlassenen zu unterstützen und die Stärke der Horde gegen die Gefahren zu versammeln, die Lordaeron umgeben. Innerhalb der konzentrischen Viertel der Stadt könnt Ihr Klassenlehrer aufsuchen, Vorräte erwerben und die dunklen Forscher der Royal Apothecary Society konsultieren. Jenseits Eures Handwerks ist es Eure Pflicht, Aufträge für Fürstin Sylvanas Windläufer und ihre Leutnants anzunehmen. Die Verlassenen führen einen Krieg an mehreren Fronten: die Überreste der sinnlosen Geißel säubern, den fanatischen Scharlachroten Kreuzzug zurückschlagen und sicheren Boden für die Untoten mit freiem Willen sichern, damit sie überdauern können.",al={"was mache ich hier","was soll ich in der unterstadt tun","warum bin ich hier"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Krater von Un'Goro",s="Der Krater von Un'Goro lockt Reisende in ein üppiges Becken zwischen den Wüsten von Tanaris und Silithus. Unter einem zentralen Vulkan streifen Dinosaurier zwischen lebenden Elementaren und uralten Titanenrelikten umher. Über das Becken verstreut liegen farbige Machtkristalle, deren Ursprung ein Rätsel bleibt.",h="Der Krater von Un'Goro lockt Reisende in ein üppiges Becken zwischen den Wüsten von Tanaris und Silithus.",kw={"teufelssaurier","feuersäulengrat","götterländer","lakkari","marschalls zuflucht","machtkristalle","torwa pfadfinder","ungoro","krater von ungoro"},ang={["class:Druid"]="Als Druide könnt Ihr mit dem Zirkel des Cenarius Un'Goros abgeschiedenes Ökosystem erforschen und seine reiche Erde ernten, um Morgenkorn anzubauen. Der Zirkel will die reine, ungezähmte Lebenskraft verstehen, die die Caldera erhält.",["faction:Alliance"]="Als Naturforscher der Allianz könnt Ihr Euch in Marschalls Zuflucht mit Williden Marschall und J.D. Collie zusammentun. Naturforscher der Allianz wetteifern darum, die Titanenpylonen zu entschlüsseln und dabei die Forscher aus Darnassus zu schützen, die Bodenproben sammeln.",["faction:Horde"]="Als Abenteurer der Horde könnt Ihr durch Tanaris kommen, um Euch mit legendären Teufelssauriern zu messen. Ihr könnt auch den Kräuterkundigen aus Donnerfels helfen, aus Un'Goros urzeitlicher Erde Morgenkorn zu ziehen.",["profession:Herbalism"]="Dank der reichlichen Feuchtigkeit des Beckens gedeihen dort neben Feuerblüten an den Vulkanhängen auch Blindkraut, Traumblatt und Goldener Sansam. Nur an wenigen Orten in Kalimdor wachsen alle vier zusammen.",["profession:Mining"]="Mithrilvorkommen und reichhaltige Thoriumadern liegen dicht gedrängt an den Kraterwänden und den Felsklippen des Feuersäulengrats. Un'Goro ist ein herausragendes Ziel für hochwertige Erze."},sec={{t="Die Götterländer",b="Uralte Aufzeichnungen der Nachtelfen über den Krieg der Sandstürme berichten, dass die Qiraji am Rand des Kraters von Un'Goro zurückgeschlagen wurden. In ihrer Sprache nannten sie diesen Ort die „Götterländer“. Gelehrte vermuten, dass die Titanen die Caldera während der Formung Kalimdors als Testgelände oder Wohnstätte nutzten. An den Graten ragen steinerne Pylonen auf, die vor Energie summen. Blaue, rote, grüne und gelbe Kristalle treten aus der Urerde hervor."},{t="Ein wildes Ökosystem",b="Un'Goro hat keine Städte, Dörfer oder einheimischen humanoiden Gesellschaften. Hier gedeiht das Leben in einem wilden, urzeitlichen Zustand. Teufelssaurier durchstreifen die Ebenen der Terrorflucht, Blutblüten schlagen in den Marschen um sich, und Schleime kriechen über die Teergruben von Lakkari. Im Herzen des Kraters liegt der Feuersäulengrat, ein aktiver Vulkan voller feindseliger Feuerelementare, angeführt von Feuerläufer. Entdecker und Kürschner suchen nach seinen natürlichen Schätzen, darunter Teufelssaurierhäute, sofern sie die Nahrungskette überleben."},{t="Marschalls Zuflucht",b="Marschalls Zuflucht, ein erhöhtes Lager in den nördlichen Klippen, ist fast die gesamte besiedelte Präsenz in Un'Goro. Williden Marschall führte Wissenschaftler, Naturforscher und Glückssucher hierher, um die Schätze des Beckens zu katalogisieren.\n\nMonströse Wildtiere setzten der Expedition zu und trieben ihre Mitglieder auf höher gelegenes Gelände. Die Zuflucht bleibt ein umkämpfter Stützpunkt für Reisende, die die geheimnisvollen Machtkristalle erforschen, vulkanische Aktivität kartieren und beobachten, wie Silithidenschwärme über die südlichen Grate vordringen."}},faq={{q="Wie gelangt man in den Krater von Un'Goro?",a="Natürliche Rampen führen die Kraterwände hinab. Eine kommt aus dem Südwesten von Tanaris nahe dem Disteltal, eine weitere aus dem Nordosten von Silithus. Ohne magische Hilfe ist ein Sprung von den Klippen tödlich. Marschalls Zuflucht im Norden bietet Flugverbindungen nach Gadgetzan und zur Burg Cenarius.",al={"wie gelangt man nach ungoro","eingang nach ungoro","wie erreicht man den krater von ungoro"}},{q="Wozu dienen die farbigen Machtkristalle?",a="Rote, blaue, grüne und gelbe Machtkristalle liegen verstreut auf dem Dschungelboden. Die Gnom-Forscherin J.D. Collie in Marschalls Zuflucht kann Entdeckern erklären, wie sie an den nördlichen, östlichen und westlichen Pylonen verwendet werden. Kombiniert bestimmte Farben an den richtigen Pylonen, um schlummernde Titanenenergien zu nutzen und schützende oder heilende Talismane herzustellen.",al={"ungoro-kristalle","rote blaue grüne gelbe kristalle in ungoro","machtpylonen"}},{q="Warum ist Un'Goro üppig bewachsen, obwohl es von Wüsten umgeben ist?",a="Gelehrte glauben, die Titanen, die die Welt formten, hätten Un'Goros unnatürliche Üppigkeit geschaffen. Titanische Leitungen, die Wärme des Feuersäulengrats und uralte Leyenergie nähren sein abgeschiedenes, schnell wachsendes Ökosystem. Es trotzt den trockenen Bedingungen des benachbarten Tanaris und Silithus.",al={"warum ist ungoro ein dschungel","ungoro und die wüste","wie gibt es in ungoro pflanzen"}},{q="Warum nannten die Qiraji diesen Ort die „Götterländer“?",a="Übersetzte Tafeln über den Krieg der Sandstürme berichten, dass die Insektenschwärme an Un'Goros Grenze haltmachten. In ihrer Sprache nannten sie den Ort die „Götterländer“. Der Geologe Larksbane, der den Bericht übersetzte, bringt den Namen mit Theorien in Verbindung, nach denen die Titanen einst im Krater lebten, und fragt sich, ob Aman'Thul selbst über ihn wachte.",al={"bedeutung der götterländer","qiraji in ungoro","warum konnten die silithiden ungoro nicht einnehmen"}},{q="Wozu wird Un'Goro-Erde verwendet?",a="Über das Kraterbecken verteilt liegt reiche, kraftvolle Erde. Kombiniert geerntete Erde in einem Immergrünbeutel mit Tharlendris-Samen, um Morgenkorn anzubauen, ein mystisches Kraut, das bei Forschern in Donnerfels, Darnassus und dem Zirkel des Cenarius heiß begehrt ist.",al={"bodenprobe aus ungoro","wozu dient ungoro-erde","morgenkorn und erde"}},{q="Gibt es hier humanoide Siedlungen oder Dungeons?",a="Im Krater von Un'Goro liegt Die Terrasse des Formers, für jene um Stufe achtundfünfzig bis sechzig, aber es gibt keine einheimischen humanoiden Gesellschaften. Marschalls Zuflucht, ein kleiner Expeditionsaußenposten am nördlichen Rand, ist die einzige dauerhafte Siedlung. Abgesehen von vereinzelten Einsiedlerjägern oder verirrten Entdeckern ist die Caldera völlig wild.",al={"dungeons in ungoro","wer lebt in ungoro","humanoide in ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Die Höhlen des Wehklagens",s="Unter der Blühenden Oase im Brachland pfeift eingeschlossener Dampf durch Die Höhlen des Wehklagens. Quellen und Spalten sollten einst Kalimdors sonnengebleichte Savanne wiederbeleben. Heute bergen die Höhlen vergiftete Wasser, verdrehte Tiere und gefallene Jünger, gefangen in einem unnatürlichen Albtraum.",h="Unter der Blühenden Oase im Brachland pfeift eingeschlossener Dampf durch Die Höhlen des Wehklagens.",kw={"deviate","druiden des giftzahns","smaragdgrüner alptraum","lady anakondra","lord kobrahn","lord pythas","lord serpentis","die blühende oase","mutanus","naralex","verdan"},ang={["class:Druid"]="Für Druiden der Tradition des Zirkels des Cenarius wie auch für Tauren-Druiden sind die Höhlen eine tragische Warnung vor den Gefahren im Smaragdgrünen Traum. Ihre gefallenen Brüder, die Druiden des Giftzahns, zu läutern, ist eine ernste Pflicht.",["race:NightElf"]="Naralex wurde unter den Nachtelfen-Druiden verehrt. Seine Verderbnis durch den Smaragdgrünen Alptraum ist eine schmerzliche Katastrophe für sein Volk jenseits des Meeres.",["race:Tauren"]="Die verdrehten Wasser bedrohen die empfindlichen Oasen, die das Leben im ganzen Brachland erhalten. Die Quellen zu reinigen, ist für die Stämme von Mulgore und dem Wegekreuz lebenswichtig."},sec={{t="Eine edle Vision wird vergiftet",b="Der Nachtelfen-Druide Naralex entdeckte ein gewaltiges unterirdisches Wassersystem und wollte das Brachland wiederherstellen. Durch einen Kanal in den Smaragdgrünen Traum wollte er reines, urtümliches Leben durch die Quellen leiten und die ausgedörrte Savanne in ein blühendes Paradies verwandeln.\n\nTief in den Höhlen trat Naralex in Zwiesprache mit dem Traum, verankert durch seine treuen Akolythen. Doch sein schlafender Geist berührte den Smaragdgrünen Alptraum. Die Verderbnis ergriff ihn, und sein Kanal wurde zu einem Ventil, das Gift und Wahnsinn in die Wasser ergoss."},{t="Die Druiden des Giftzahns",b="Als sich die dunkle Energie des Alptraums von Naralex' hilfloser Gestalt ausbreitete, verfielen die Gedanken seiner Schüler dem Wahnsinn. Sie entsagten der friedvollen Weisheit des Zirkels des Cenarius und wurden zu den fanatischen Druiden des Giftzahns.\n\nIhre Anführer, Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis, nehmen reptilienartige Gestalten an. Sie nehmen die giftige Mutation der Höhlen an, statt sie zu bekämpfen, und schirmen ihren schlafenden Meister vor Einmischung von außen ab. Sie glauben, dieses verdrehte Wachstum sei die wahre Entwicklung der Natur."},{t="Der Alptraum wird Fleisch",b="Den Griff der Druiden des Giftzahns zu brechen, rettet Naralex nicht. Am Dreamer's Rock beginnen seine verbliebenen, unverdorbenen Jünger ein Ritual, um ihn sanft aus seiner Trance zu wecken. Sein schlafender Geist windet sich, und sein tiefster Schrecken bricht als Mutanus der Verschlinger hervor, ein monströser, entstellter Murloc. Mutanus ist das Fleisch gewordene Abbild von Naralex' schlimmsten Alpträumen.\n\nNur wenn Mutanus erschlagen wird, lässt sich der Kanal zum Alptraum kappen. Naralex kann erwachen, die Gestalt eines Vogels annehmen und aus den verdorbenen Höhlen fliegen."}},faq={{q="Warum heißen sie Die Höhlen des Wehklagens?",a="Die Höhlen des Wehklagens verdanken ihren Namen den klagenden Rufen, die durch ihre Tunnel hallen. Eingeschlossener unterirdischer Dampf und Windstöße unter hohem Druck zwängen sich durch enge Kalksteinspalten und erzeugen das unheimliche Pfeifen.",al={"warum heißen sie höhlen des wehklagens","ursprung des namens","warum klagen sie"}},{q="Was ließ die Tiere dort zu „Deviates“ werden?",a="Als Naralex dem Einfluss des Smaragdgrünen Alptraums verfiel, strömten verdorbene Traumenergien in die unterirdischen Quellen. Das verunreinigte Wasser verwandelte die dort lebenden Raptoren, Krokilisken und Schlangen in unnatürliche Deviates.",al={"deviate verderbnis","warum mutieren raptoren","ursprung der deviate tiere"}},{q="Wer sind die Druiden des Giftzahns?",a="Die Druiden des Giftzahns waren einst Naralex' ergebene Akolythen, Nachtelfen und Tauren. Der Alptraum verdarb sie zusammen mit ihm, zerschmetterte ihren Geist und ließ sie Schlangen und Gift verehren. Sie nahmen Titel wie Kobrahn, Pythas und Anakondra an.",al={"giftzahndruiden","geschichte der druide des giftzahns","wer ist lord serpentis"}},{q="Warum ist der Endgegner ein riesiger Murloc namens Mutanus?",a="Mutanus erscheint während des Versuchs, Naralex zu erwecken. Das Ritual offenbart Mutanus' Wesen und seine Verbindung zum schlafenden Druiden.",al={"warum ist mutanus ein murloc","was ist mutanus","geschichte des endgegners"}},{q="Was geschieht, nachdem Mutanus besiegt wurde?",a="Der Versuch der Jünger, Naralex zu erwecken, geht nach der Konfrontation weiter. Am Ende offenbart das Ritual das Schicksal des Druiden.",al={"naralex erwecken","naralex ende","was geschieht mit naralex"}},{q="Wer lebt in der Höhle über dem Eingang?",a="Getreue des Zirkels des Cenarius, darunter Nalpak und Ebru, leben in der schädelartigen Felshöhle über dem Eingang. Sie suchen tapfere Reisende, die Deviatbälge sammeln und die Verderbnis reinigen, bevor sie das Brachland verschlingt.",al={"höhle über dem eingang","npcs in schlangen-schädelhöhle","wer sind nalpak und ebru"}}},fx={["38e519c2"]={q="Warum macht sich jeder solche Sorgen um diesen Ort?",a="Die unterirdischen Quellen in den Höhlen speisen die primären Oasen, die das Leben im ariden Brachland erhalten. Sollte der Makel des Smaragdgrünen Traums ungehindert in diese Wasserwege sickern, könnten sich die verdrehten Mutationen und der Wahnsinn, die die Flora und Fauna der Höhlen korrumpieren, über die gesamte Region ausbreiten und das Land in einen Albtraum bei Tageslicht verwandeln.",al={"warum sorgen um die höhlen des wehklagens","die höhlen des wehklagens bedrohung für das brachland","wie schlimm sind die höhlen des wehklagens"}},["81917ac6"]={q="Wie bin ich in den Höhlen des Wehklagens gelandet?",a="Ihr seid vom Wegekreuz nach Süden in Die blühende Oase gereist, den Berichten über bizarre Bestien und korrumpiertes Wasser folgend, das durch das Brachland sickerte. Hinter dem üppigen Blattwerk und den Lagern der Kolkar-Zentauren liegt eine gewaltige, schädelförmige Höhle, die in den Fels gehauen wurde. Angelockt durch Hilferufe aus Donnerfels, durch Goblins aus Ratschet, die nach seltsamen Essenzen suchten, oder durch Jünger, die im Auge des Schädels oben kampierten, seid Ihr an den gewundenen Spalten und dem Zischen unterirdischer Geysire vorbei in die stöhnenden Tiefen hinabgestiegen.",al={"wie bin ich hierher gekommen","wie erreiche ich die höhlen des wehklagens","woher bin ich hierher gekommen"}},["28a012f3"]={q="Was soll ich in den Höhlen des Wehklagens tun?",a="Ihr seid hier, um die Korruption zu tilgen, die diese unterirdische Quelle befallen hat. Der Nachtelf-Druide Naralex fiel in einen albtraumhaften Schlaf, als er versuchte, das Brachland wiederzubeleben, was die Kreaturen darin verdrehte und seine Jünger in die giftigen Druiden des Giftzahns verwandelte. Ihr müsst die vier Giftzahnfürsten – Lady Anakondra, Lord Kobrahn, Lord Pythas und Lord Serpentis – zur Strecke bringen, um ihren Griff zu brechen, und dann den verbliebenen Jüngern helfen, Naralex zu wecken, bevor sein fiebriger Albtraum die Oase vollständig verschlingt.",al={"was ist mein ziel hier","warum bin ich in den höhlen des wehklagens","was mache ich hier unten"}},["3386ab3f"]={q="Was sind Die Höhlen des Wehklagens?",a="Die Höhlen des Wehklagens sind ein weitläufiges unterirdisches Höhlensystem, das unter dem trockenen Brachland, nahe der blühenden Oase, verläuft. Seine natürlichen unterirdischen Quellen leiten Wasser kilometerweit unter der Erde und speisen die seltenen Oasen an der Oberfläche, die über die Region verstreut sind. Entdeckt von dem Nachtelf-Druiden Naralex, sollten sie das Herz eines großen Projekts zur natürlichen Regeneration werden. Stattdessen wurden sie zu einem Epizentrum gefährlicher Verderbnis, nachdem eine tragische Katastrophe die Druiden darin ergriffen hatte.",al={"was sind die höhlen des wehklagens","übersicht der höhlen des wehklagens","über die höhlen des wehklagens"}},e070a543={q="Wer lebt dort unten?",a="Die Höhlen wimmeln von unnatürlicher Tierwelt und abtrünnigen Druiden. Naralex' korrumpierte Anhänger, die Leaders of the Fang, haben die Tunnel zusammen mit mutierten Schlangen, Schlämmen, Raptoren und Krokilisken als ihr Gebiet beansprucht. Außerhalb des Instanzeingangs lauern wilde Bestien, Schlämme und sogar Ausgestoßene in den feuchten Gängen, während die korrumpierten Druiden die inneren Kammern bewachen und ihren schlafenden Meister beschützen.",al={"wer ist in den höhlen des wehklagens","kreaturen in den höhlen des wehklagens","bewohner der höhlen des wehklagens"}},["49d47201"]={q="Warum hat mich die Horde hierher geschickt?",a="Die seltsamen Mutationen der einheimischen Bestien und die faulen Energien, die aus der blühenden Oase sprudeln, bedrohen das gesamte Brachland. Die Horde und die Cenarion-Druiden von Donnerfels können es nicht dulden, dass eine unkontrollierte dunkle Macht das Land und die Wasserwege direkt vor der Haustür des Wegekreuzes vergiftet. Ihr wurdet ausgesandt, um Nachforschungen anzustellen, den abtrünnigen Leaders of the Fang ein Ende zu bereiten und dabei zu helfen, die wachsende Gefahr zu unterdrücken.",al={"warum bin ich in den höhlen des wehklagens","mission der horde in den höhlen des wehklagens","warum hat man mich in die höhlen des wehklagens geschickt"}},d445bb78={q="Ist das Teil eines größeren Problems im Brachland?",a="Ja. Die unterirdischen Kanäle unter diesen Höhlen speisen die Oasen an der Oberfläche im gesamten Brachland. Die Verderbnis des Alptraums, die das Wasser in den Höhlen korrumpiert, hat begonnen, in die umliegende Landschaft überzulaufen, was dazu führt, dass wilde Kreaturen wie Raptoren und Krokilisken mutieren und die blühende Oase in eine Brutstätte für seltsames Deviatleben verwandelt.",al={"problem mit den oasen im brachland","deviatverderbnis im brachland","beeinflussen die höhlen des wehklagens das brachland"}},["038fd1cf"]={q="Breiten sich die Deviatwesen außerhalb der Höhlen aus?",a="Das tun sie bereits. Die unterirdischen Quellen fließen direkt in oberirdische Oasen wie die blühende Oase und bringen unnatürliches Wachstum und mutierte Kreaturen in die offene Savanne. Seltsame Kreaturen wie Deviatfisch können aus den Gewässern außerhalb gefischt werden, und aggressive mutierte Raubtiere belästigen zunehmend Reisende zwischen den Oasen und dem Wegekreuz.",al={"breiten sich die deviatwesen aus","deviatbestien im brachland","deviatfisch außerhalb"}},["8502642f"]={q="Wer hat hier das Sagen?",a="Während Naralex tief in den Höhlen in seinem korrumpierten Schlummer gefangen liegt, gehört die tägliche Herrschaft über die Höhlen den Druiden des Giftzahns. Sie werden von Lord Serpentis angeführt, einst Naralex' bester Schüler, der seine verdrehten Brüder versammelte, um das Land in ihr eigenes verzerrtes Paradies zu verwandeln, zusammen mit anderen fang lords wie Cobrahn, Pythas und Lady Anakondra.",al={"wer führt die höhlen des wehklagens","anführer der höhlen des wehklagens","boss der höhlen des wehklagens"}},["32be29c8"]={q="Was ist der Smaragdgrüne Traum und wie hängt er mit dieser Höhle zusammen?",a="Der Smaragdgrüne Traum ist ein riesiges Geisterreich, das Azeroth unberührt und wild darstellt, von dem grünen Drachenschwarm behütet und für Druiden zugänglich. Naralex glaubte, er könne die reinen, wiederherstellenden Energien des Traums in die unterirdischen Aquifere der Höhlen des Wehklagens leiten, um üppiges Pflanzenleben im Brachland wiederherzustellen. Als er ihn jedoch anzapfte, wurde er vom Smaragdgrünen Alptraum gefangen genommen, was eine verdrehte Version der Natur in die physischen Höhlen projizierte.",al={"verbindung zum smaragdgrünen traum","höhlen des wehklagens smaragdgrüner traum","naralex smaragdgrüner traum"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Kriegshymnenschlucht",s="An der Grenze zwischen Eschental und Brachland kämpfen Horde und Allianz ohne Unterlass in der Kriegshymnenschlucht. Orcs des Kriegshymnenklans schlagen Holz für die Horde, während die Nachtelfen der Feste Silverwing ihren heiligen Wald verteidigen. Kämpfer vieler Völker überfallen die gegnerische Festung, um deren Banner zu erbeuten.",h="An der Grenze zwischen Eschental und Brachland kämpfen Horde und Allianz ohne Unterlass in der...",kw={"kriegshymnenschlucht","schlachtfeld","vorhut des kriegshymnenklans","schildwachen der silberschwingen","feste silverwing","kriegshymnenmühle","flagge","bauholz","eschental","grom hellscream"},ang={["faction:Alliance"]="Soldaten der Allianz kämpfen an der Seite ihrer Nachtelfenverbündeten, während die Äxte des Kriegshymnenklans Bäume in deren heiligem Wald fällen.",["faction:Horde"]="Jeder Stamm aus der Kriegshymnenmühle hilft, irgendwo in Kalimdor eine Mauer der Horde zu errichten. Haltet die Schlucht, und die Horde kann weiterbauen.",["race:NightElf"]="Diese Wälder kennen die Schritte der Kaldorei seit zehntausend Jahren. Jeder aus der Schlucht vertriebene Orc bedeutet ein zurückgewonnenes Stück Eschental.",["race:Orc"]="Der Kriegshymnenklan ist Grom Hellscreams eigener Klan. In der Schlucht machen seine Krieger ihrem Namen noch immer Ehre, mit der Axt in der Hand gegen die Schildwachen."},sec={{t="Holz und Blut",b="Die Horde baut ihre Heimat in Kalimdor aus Holz, das zu großen Teilen im Eschental geschlagen wird. Der Kriegshymnenklan, Grom Hellscreams Krieger, fällt hier Bäume, seit die Horde erstmals an Land ging. Seine Kriegshymnenmühle am Ende der Schlucht liefert Holz für die Lager und Mauern der Horde. Die Nachtelfen sehen in jedem gefällten Baum eine Wunde in einem Wald, den sie seit zehntausend Jahren behüten. Sie erinnern sich auch daran, dass Groms Krieger Cenarius in diesen Wäldern erschlugen."},{t="Vorhut und Schildwachen",b="Die Kämpfer der Horde bilden die Vorhut des Kriegshymnenklans, die vom Mor'shan-Stützpunkt am nördlichen Rand des Brachlands versorgt wird. Dort hält Kelm Hargunth sie bewaffnet und verpflegt. Die Schildwachen der Silberschwingen aus der Feste Silverwing stellen sich ihnen entgegen.\n\nDiese Nachtelfenkrieger haben geschworen, jeden Eindringling aus dem Eschental zu vertreiben, und Illiyana Mondflamm versorgt sie im Hain der Silberschwingen. Auch Verbündete strömen in die Schlucht: Zwerge und Menschen an die Seite der Schildwachen, Tauren, Trolle und Verlassene an die Seite der Vorhut."},{t="Der Kampf um die Banner",b="Die Kriegshymnenmühle steht an einem Ende der Schlucht, die Feste Silverwing am anderen. Jede Festung beherbergt das Banner ihrer Seite. Kämpfer überfallen die feindliche Festung, ergreifen deren Flagge und eilen zurück, während Verteidiger sie jagen. Jedes heimgebrachte Banner trifft den Stolz des Feindes. Die Seite, die die meisten erbeutet, gewinnt den Tag."}},faq={{q="Was ist die Kriegshymnenschlucht?",a="Die Kriegshymnenschlucht liegt in einem bewaldeten Tal zwischen dem Eschental und dem Brachland. Dort kämpfen die Vorhut des Kriegshymnenklans der Horde und die Schildwachen der Silberschwingen der Nachtelfen um den Holzeinschlag der Horde und versuchen, die gegnerische Flagge zu erbeuten.",al={"was ist die kriegshymnenschlucht","kriegshymnenschlucht schlachtfeld","wsg"}},{q="Warum kämpft die Horde in der Kriegshymnenschlucht?",a="Die Horde braucht das Holz des Eschentals, um ihre Heimat in Kalimdor aufzubauen und zu halten. Die Kriegshymnenmühle an der Schlucht ist eine ihrer wichtigsten Holzquellen, und die Vorhut verteidigt sie, damit die Lager und Mauern der Horde entstehen können.",al={"was für die horde in der kriegshymnenschlucht auf dem spiel steht","warum fällen die orcs bäume im eschental","beweggrund der vorhut des kriegshymnenklans"}},{q="Warum kämpfen die Nachtelfen in der Kriegshymnenschlucht?",a="Die Nachtelfen behüten das heilige Eschental seit zehntausend Jahren, und der Kriegshymnenklan erschlug dort einst den Halbgott Cenarius. Die Schildwachen der Silberschwingen kämpfen mit dem Rest der Allianz an ihrer Seite, um den Holzeinschlag zu stoppen und die Orcs aus ihren Wäldern zu vertreiben.",al={"was für die allianz in der kriegshymnenschlucht auf dem spiel steht","warum kämpfen die schildwachen","beweggrund der schildwachen der silberschwingen"}},{q="Wer ist die Vorhut des Kriegshymnenklans?",a="Die Vorhut des Kriegshymnenklans besteht aus den Kämpfern der Horde in der Kriegshymnenschlucht und stammt aus dem einst von Grom Hellscream geführten Kriegshymnenklan. Sie erhält Nachschub am Mor'shan-Stützpunkt im nördlichen Brachland, wo Kelm Hargunth sie ausrüstet.",al={"vorhut des kriegshymnenklans","kämpfer des kriegshymnenklans","kelm hargunth"}},{q="Wer sind die Schildwachen der Silberschwingen?",a="Die Schildwachen der Silberschwingen sind Nachtelfenkrieger der Feste Silverwing, die geschworen haben, die Horde aus dem Eschental zu vertreiben. Im Hain der Silberschwingen versorgt Illiyana Mondflamm die Champions der Allianz, die in der Schlucht an ihrer Seite kämpfen.",al={"schildwachen der silberschwingen","feste silverwing","illiyana mondflamm"}},{q="Wie wird die Schlacht in der Kriegshymnenschlucht gewonnen?",a="Jede Seite bewahrt ihre Flagge in ihrer eigenen Festung auf. Kämpfer überfallen die feindliche Festung, ergreifen deren Flagge und tragen sie heim, während sie ihr eigenes Banner verteidigen. Die Seite, die die meisten Flaggen heimbringt, gewinnt.",al={"ziele in der kriegshymnenschlucht","flagge erobern kriegshymnenschlucht","wie gewinnt man die kriegshymnenschlucht"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Westliche Pestländer",s="Giftiger Nebel und Untotenlegionen ersticken die Westlichen Pestländer, wo Fraktionen um Boden kämpfen. Einst die Kornkammer des nördlichen Lordaeron, fielen ihre Höfe und Städte Kel'Thuzads Kesseln zum Opfer, doch im Boden hält sich noch Leben. Die Argentumdämmerung, die Allianz, die Verlassenen und der Scharlachrote Kreuzzug führen verzweifelte Feldzüge auf den verseuchten Feldern.",h="Giftiger Nebel und Untotenlegionen ersticken die Westlichen Pestländer, wo Fraktionen um Boden kämpfen.",kw={"andorhal","das bollwerk","darrowehr","pestkessel","zugwindlager","herdweiler","burg mardenholde","scholomance","uthers grabmal","westliche pestländer"},ang={["class:Paladin"]="Als Paladin steht Euch auf den entweihten Feldern Lordaerons eine ernste Prüfung bevor. Ihr könnt zu Uthers Grabmal pilgern und gegen die Schrecken von Scholomance sowie die verdorbenen Eiferer Herdweilers kämpfen.",["faction:Alliance"]="Das Zugwindlager ist der vorgeschobene Stützpunkt der Allianz. Kommandant Ashlam Valorfist leitet von dort Feldzüge, um die Pestkessel zu sabotieren und Lordaerons gefallene Städte zu rächen.",["faction:Horde"]="Das Bollwerk markiert die Grenze der Souveränität der Verlassenen. Von dort stößt die Horde nach Osten vor, um Kommandanten der Geißel auszuschalten und die Scharlachroten Eiferer an ihrer verwundbaren Flanke herauszufordern.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr seltene und gefährliche Pflanzen wie Pestblüte und Arthas' Tränen zwischen verseuchten Kiefernwäldern finden, wo die anhaltende Verderbnis ihr Wachstum ermöglicht."},sec={{t="Lordaerons Kornkammer",b="Vor dem Dritten Krieg erstreckten sich Höfe östlich von Tirisfal bis zum Darrowmeresee. Herdweiler verwaltete den Norden von Burg Mardenholde aus, während Andorhal Getreide für das ganze Königreich lagerte und verschiffte. Deshalb machte Kel'Thuzad die Region zu seinem Hauptziel. In Andorhal mischte der Kult der Verdammten die Seuche des Untods unter die Getreidelieferungen und verwandelte Lordaerons Nahrungsvorräte in seinen Untergang."},{t="Ein belagertes Land",b="Die Geißel errichtete vier gewaltige Pestkessel, um den Boden zu vergiften. Sie stehen auf dem Teufelssteinfeld, auf Dalsons Tränenfeld, beim Trostlosen Feld und auf Gahrrons Trauerfeld. Monströse Kessellords bewachen die Bottiche und füllen die Luft mit giftigem Nebel. Bäume winden sich mit geschwollenen Wucherungen, und verseuchte Wildtiere toben durchs Dickicht. Unter Darrowehr im Darrowmeresee bildet Dunkelmeister Gandling in Scholomance Nekromanten aus und verstärkt so die Bedrohung durch Untote."},{t="Geteilte Fraktionen",b="Die Geißel hält einen Großteil der Region, doch andere Fraktionen behaupten ihre Stützpunkte. Im Norden kontrolliert der Scharlachrote Kreuzzug Herdweiler und läutert alles, was er für verseucht hält. Streitkräfte der Allianz sammeln sich im Süden im Zugwindlager, während die Verlassenen ihre Grenzen vom Bollwerk aus verteidigen. Die neutrale Argentumdämmerung lenkt den Kampf gegen die Kessel, unterstützt Streiter beider Fraktionen und bewacht Uthers Grabmal, den letzten wahrhaft geweihten Boden der Region."}},faq={{q="Warum traf die Seuche diese Gegend so schwer?",a="Andorhal verschiffte Getreide durch das nördliche Lordaeron und wurde dadurch zum Ziel Kel'Thuzads. Dort mischte der Kult der Verdammten die Seuche des Untods unter die Getreidelieferungen und errichtete dann auf vier großen Höfen Pestkessel, um den Untod über die Nahrungsvorräte des Königreichs zu verbreiten.",al={"warum sind die westlichen pestländer verseucht","was geschah mit andorhal","warum stehen hier pestkessel"}},{q="Wer kontrolliert Herdweiler im Norden?",a="Der Scharlachrote Kreuzzug kontrolliert Herdweiler und Burg Mardenholde. Die einstige Verwaltungszentrale der Region für Lordaeron wird nun von Eiferern gehalten, die Außenstehende an ihren Grenzen hinrichten und allen misstrauen, die nicht zum Kreuzzug gehören.",al={"fraktion in herdweiler","wer lebt in burg mardenholde","ist herdweiler freundlich"}},{q="Wo finden Spieler der Allianz und der Horde sichere Außenposten?",a="Die Allianz sammelt sich im Zugwindlager nahe der Südgrenze zum Alteracgebirge. Dort gibt es einen Flugmeister und Verbündete der Argentumdämmerung. Die Horde operiert vom Bollwerk an der Westgrenze aus, das von Tirisfal aus erreichbar ist.",al={"wo sind die flugrouten","hordenlager in den westlichen pestländern","allianzlager in den westlichen pestländern"}},{q="Wozu dienen die Pestkessel auf den Feldern?",a="Der Kult der Verdammten errichtete Pestkessel auf dem Teufelssteinfeld, auf Dalsons Tränenfeld, beim Trostlosen Feld und auf Gahrrons Trauerfeld. Sie pumpen Pestdämpfe in Luft und Boden. Agenten der Argentumdämmerung werben Abenteurer an, die Kessellords zu töten und die giftigen Gebräue mit Gegenmitteln zu bekämpfen.",al={"was sind die pestkessel","zweck der pestkessel","pestkessel auf dem teufelssteinfeld"}},{q="Was ist Scholomance und wo liegt es?",a="Scholomance ist eine unterirdische Akademie der Nekromantie, die von der Geißel und dem Kult der Verdammten betrieben wird. Sie liegt unter den Ruinen von Darrowehr, einer Festungsinsel im Südosten des Darrowmeresees.",al={"standort von scholomance","wo liegt scholomance","verlies darrowehr"}},{q="Ist ein Teil der Westlichen Pestländer unverdorben?",a="Uthers Grabmal auf dem Trauerhügel nahe dem Südrand der Region ist heilig und unberührt von der Verderbnis. Es ist ein geweihtes Denkmal für Hochgeneral Uther den Lichtbringer und den untergegangenen Orden der Silbernen Hand.",al={"heiliger boden in den westlichen pestländern","ist uthers grabmal unversehrt","ist uthers grabmal sicher"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Westfall",s="Westfalls Höfe liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands. Einst die Kornkammer von Sturmwind, kommt das Gebiet nun ohne Unterstützung der Krone oder militärische Garnisonen kaum zurecht.",h="Westfalls Höfe liegen schutzlos da, und die Bruderschaft der Defias beherrscht weite Teile des Umlands.",kw={"die todesminen","defias","erntegolem","miliz","mondbruch","saldean","späherkuppe","starkmantel","van cleef","westfall"},ang={["class:Rogue"]="Als Schurke findet Ihr in ganz Westfall einen Schattenkrieg, in dem Spione von SI:7 den gewitzten Spähern, Dieben und Assassinen der Bruderschaft der Defias gegenüberstehen.",["faction:Alliance"]="Als Reisender der Allianz könnt Ihr sehen, wie die Volksmiliz die Späherkuppe hält. Ohne sie würde die Bruderschaft der Defias die südlichen Zugänge zum Wald von Elwynn kontrollieren.",["profession:Cooking"]="Als Koch könnt Ihr erfahren, wie sich die bedrängten Siedler auf Saldeans Farm mit zähen einheimischen Tieren behelfen und Reisenden beibringen, Westfall-Eintopf zuzubereiten.",["race:Human"]="Als Mensch zeigt Westfall den politischen Verfall von Sturmwind. Die Bauern, die im Dreck hungern, wurden von den Edlen im Stich gelassen, für die sie sich abmühten."},sec={{t="Ein zurückgelassenes Land",b="Westfalls Weiden und Weizenfelder versorgten einst das Königreich Sturmwind. Nach dem Zweiten Krieg wurden die Finanzen des Königreichs knapp, und seine Anführer vernachlässigten das Gebiet. Sturmwind schickte seine Ressourcen anderswohin und ließ seine Garnisonen abziehen. Das Land fiel brach.\n\nHeute machen öde Weiden, scharfe Küstenwinde, abtrünnige Erntegolems und Gnolle des Flusspfotenstamms den wenigen Siedlern, die noch geblieben sind, das Überleben schwer."},{t="Der Aufstieg der Bruderschaft",b="Die Ankunft der Bruderschaft der Defias beschleunigte Westfalls Niedergang. Die Banditen tragen rote Masken und folgen einem Anführer, dessen Namen niemand im Umland kennt. Sie machten Westfall zu ihrer Hochburg, verbrannten die Felder der Bauern, versalzten den Boden und bemächtigten sich verlassener Minen.\n\nVon Mondbruch aus, einer Geisterstadt, beherrscht die Bruderschaft fast das gesamte Umland, auch wenn sie es dem Namen nach nicht tut."},{t="Die Volksmiliz",b="Das Haus der Edlen hat Westfalls Notlage ignoriert, also haben die Einheimischen selbst zu ihrer Verteidigung gegriffen. Auf der Späherkuppe stellte Gryan Starkmantel die Volksmiliz auf, eine Freiwilligentruppe, die Gnollen und Banditen die Stirn bietet. Sturmwind schickt weder reguläre Soldaten noch Vorräte.\n\nDie Miliz ist auf umherziehende Abenteurer angewiesen, die die Defias zurückdrängen und die verbliebenen Höfe schützen."},{t="Steinmetze mit roten Masken",b="Edwin van Cleef führt die Bruderschaft an. Er war der Gildenmeister, der Sturmwind wiederaufbaute, doch das Haus der Edlen verweigerte seinen Steinmetzen den Lohn, und Aufstände trieben sie fort. In Westfall griffen sie zur roten Maske. Die Banditen, die seine Felder niederbrennen, sind dieselben Hände, die die Mauern der Hauptstadt errichteten."},{t="Die Verschwörung in den Todesminen",b="Unter Mondbruch hat Edwin van Cleef in den verlassenen Goldstollen der Todesminen Halsabschneider, Goblins und Abtrünnige versammelt. Die Bruderschaft baut dort einen gewaltigen gepanzerten Koloss. Er soll die Küste hinaufsegeln und Sturmwind bombardieren."}},faq={{q="Warum sind so viele Höfe in Westfall verlassen?",a="Sturmwind zog seine Garnisonen ab, als ihr Unterhalt zu teuer wurde, und ließ Westfall ungeschützt zurück. Daraufhin bemächtigte sich die Bruderschaft der Defias großer Teile des Umlands, vertrieb Siedler, brannte Ackerland nieder und programmierte mechanische Erntewächter zu tödlichen Wachen um.",al={"verlassene höfe","warum ist westfall tot","warum liegt westfall brach"}},{q="Warum schickt Sturmwind keine Truppen, um Westfall zu helfen?",a="Die Schatzkammer des Königreichs ist überlastet, und das Haus der Edlen gibt Bedrohungen in anderen Ländern höhere Priorität. Machtspiele am Hof haben Westfall zudem still und leise Aufmerksamkeit und Vorräte entzogen, sodass die Bewohner sich selbst verteidigen müssen.",al={"warum schickt sturmwind keine armee","wo sind die wachen","hilfe aus sturmwind"}},{q="Was ist die Volksmiliz?",a="Gryan Starkmantel stellte auf der Späherkuppe die Volksmiliz auf, um Westfall zu verteidigen. Da die Krone keine Soldaten schickt, schlossen sich Bauern und Siedler zusammen, um gegen die Bruderschaft der Defias und die Gnolle des Flusspfotenstamms zu kämpfen.",al={"volksmiliz","miliz auf der späherkuppe","gryans armee"}},{q="Wer führt die Bruderschaft der Defias in Westfall an?",a="Edwin van Cleef, der frühere Gildenmeister der Stonemasons Guild, führt die Bruderschaft der Defias an. Er beaufsichtigte den Wiederaufbau von Sturmwind, führte dann seine Arbeiter nach Westfall und bewaffnete sie, nachdem ein erbitterter Streit um die Bezahlung in Aufständen geendet hatte.",al={"anführer der defias","wer führt die defias an","van cleef"}},{q="Was ist in Mondbruch verborgen?",a="Unter einer unscheinbaren Scheune in Mondbruch liegt der Eingang zu den Todesminen. Die Bruderschaft der Defias machte aus der verlassenen Goldmine eine unterirdische Festung und Werft für ihren Krieg gegen Sturmwind.",al={"geheimnis von mondbruch","was ist in den todesminen","mine von mondbruch"}},{q="Warum greifen die mechanischen Vogelscheuchen Leute an?",a="Goblinbastler, die mit den Defias verbündet sind, erbeuteten die mechanischen Erntewächter, die ursprünglich für die Feldarbeit und zur Abschreckung von Schädlingen gebaut wurden. Sie rüsteten sie um, damit sie die Felder bewachen und Eindringlinge töten.",al={"erntegolems greifen an","erntewächter","böse vogelscheuchen"}}},fx={cd1e134e={q="Was ist Westfall?",a="Westfall ist das windgepeitschte westliche Territorium des Königreichs Sturmwind, das westlich des Wald von Elwynn und südlich bis zum Meer liegt. Einst die fruchtbare Kornkammer des Königreichs, ernährten seine sanften Hügel und weiten Weiden Sturmwind über Generationen hinweg. Heute, von der Krone vernachlässigt und von Konflikten verwüstet, ist es zu brachliegenden Staubebenen, verfallenen Gehöften und einem Gesetzlosen-Gebiet verkommen.",al={"was ist diese zone","erzähl mir von westfall","westfall lore"}},["44cadea7"]={q="Warum ist es hier so leer?",a="Eine Kombination aus Dürre, Vernachlässigung und Räubertum hat die Landschaft entvölkert. Nach dem Zweiten Krieg konzentrierte Sturmwind seine Soldaten anderswo und ließ die örtlichen Gehöfte schutzlos zurück. Als sich die Bruderschaft der Defias erhob, vertrieben sie Bauern, brannten Ackerland nieder und versalzten die Felder. Ohne königliche Garnisonen, die sie schützen konnten, flohen die meisten Bewohner oder verhungerten.",al={"warum ist westfall unfruchtbar","warum so leer","warum sind hier keine leute"}},["1a97e791"]={q="War Westfall schon immer so arm?",a="Ganz und gar nicht. Über Generationen hinweg war Westfall Sturmwinds stolzes landwirtschaftliches Herzland, berühmt für goldene Weizenfelder, reichen Boden und ertragreiche Goldminen wie Jangolode und die Todesminen. Seine Nahrung ernährte die Hauptstadt, und seine Minen füllten die königlichen Schatzkammern, bevor Kriege und innere Unruhen es unfruchtbar machten.",al={"war westfall schon immer arm","war westfall früher wohlhabend","westfall vergangenheit"}},["1d4a9481"]={q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine riesige kriminelle Organisation, die sich aus abtrünnigen Steinmetzen, Dieben, Wegelagerern und Ausgestoßenen zusammensetzt. Unter der Führung von Edwin van Cleef besetzten sie die verlassenen Ackerflächen und Minen von Westfall, um einen erbitterten Schattenkrieg gegen das Königreich Sturmwind zu führen, mit der Absicht, Vergeltung für unbezahlte Schulden und vermeintliche Verrate zu üben.",al={"wer sind die defias","was ist die bruderschaft der defias","wer sind diese banditen"}},b6953315={q="Warum tragen die Defias rote Bandanas?",a="Rote Bandanas sind das Markenzeichen der Bruderschaft der Defias, und das Material zeigt den Rang eines Mitglieds an. Red Silk Bandanas kennzeichnen hochrangigere Mitglieder; Späherin Riell bittet Abenteurer, sie als Beweis für deren Tod zu sammeln.",al={"warum rote bandanas","defias rote masken","bedeutung rote masken"}},["908b4fe1"]={q="Was wollen die Defias in Westfall?",a="Sie behandeln Westfall als ihre souveräne Festung und ihren Stützpunkt. Indem sie die Goldminen kontrollieren, Nahrungsmittelvorräte beschlagnahmen und loyale Bauern vertreiben, können sie im Geheimen ihre Streitkräfte und Maschinen abseits von Sturmwinds direktem Blickfeld aufbauen, während sie den Untergang des Königreichs planen.",al={"was wollen die defias","defias ziele westfall","warum sind die defias in westfall"}},d384bc2d={q="Warum wurde ich nach Westfall geschickt?",a="Ihr wurdet hierher geschickt, weil Sturmwinds reguläres Militär sich weigert oder nicht in der Lage ist, Truppen nach Westfall zu entsenden, was das Territorium an den Rand des Zusammenbruchs durch das Räubertum bringt. Die Behörden im Wald von Elwynn leiten fähige Abenteurer nach Westen, um die kämpfenden Einheimischen zu unterstützen, die verzweifelt nach Hilfe suchen.",al={"warum bin ich in westfall","wer hat mich nach westfall geschickt","warum wurde ich hierher geschickt"}},d59f010f={q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein Paladin der Silbernen Hand und stammt aus Westfall. Als er nach dem Kampf in Lordaeron während des Dritter Krieg nach Hause zurückkehrte, fand er seine Heimat von Banditen überrannt und vom Militär Sturmwinds verlassen vor. Als Reaktion darauf versammelte er lokale Verteidiger, um die Bürgerwehr bei Späherkuppe zu gründen.",al={"wer ist starkmantel","gryan starkmantel","wer führt späherkuppe"}},af1c3ddb={q="Hat Gryan Starkmantel tatsächlich das Sagen in Westfall?",a="Praktisch gesehen, ja. Während der junge König in Sturmwind rechtlichen Anspruch auf Westfall erhebt, übt die Krone hier so gut wie keine wirkliche Autorität aus. Starkmantel und seine freiwillige Bürgerwehr bei Späherkuppe stellen die einzige funktionierende Verteidigung und Strafverfolgung dar, die im Reich verblieben ist.",al={"wer regiert westfall","ist starkmantel der anführer","wer hat das sagen"}},ec2fd06e={q="Hat Sturmwind sich wirklich geweigert, die Steinmetze zu bezahlen?",a="Ja. Das Haus der Adligen hatte durch die Ausweitung militärischer Expeditionen an anderen Orten erschütternde Schulden angehäuft, was das Königreich fast in den Bankrott trieb. Beeinflusst von Hofintrigen und aristokratischer Arroganz boten die Adligen für die gewaltige Arbeit nur ein Almosen an und weigerten sich schlichtweg, die vollständigen Verträge einzuhalten.",al={"hat sturmwind die steinmetze betrogen","warum haben die adligen nicht bezahlt","bezahlungsstreit der steinmetze"}},cf60f690={q="Warum gibt es so viele Gnolle in Westfall?",a="Die Gnolle des Flusspfotenrudels sind über die Grenze migriert, um das Fehlen von Soldaten aus Sturmwind auszunutzen. Schlimmer noch, die Bruderschaft der Defias heuerte sie aktiv als Söldner an und stationierte sie in den Hügeln und Ebenen, um Reisende zu überfallen und alle überlebenden Gehöfte zu schikanieren.",al={"warum sind hier gnolle","flusspfoten gnolle westfall","danuvin gnolle"}},e40fa3bd={q="Was ist Mondbruch?",a="Mondbruch war einst der primäre Markt und die Bergbaustadt im südlichen Westfall. Über dem alten Eingang zu den Todesminen gelegen, wurde es vollständig von der Bruderschaft der Defias besetzt und geräumt, die nun die leeren Gebäude als perimetrischen Schutz für ihre unterirdische Festung nutzen.",al={"was ist mondbruch","mondbruch lore","erzähl mir von mondbruch"}},["46f1c864"]={q="Wohin führt die Untersuchung der Defias?",a="Eure Ermittlungen decken das geheime Herz der Bruderschaft unter Mondbruch in den Todesminen auf. Dort, tief in den unterirdischen Höhlen, überwacht Edwin van Cleef den Bau eines gewaltigen, eisenbeschlagenen Juggernauts, der Sturmwind vom Meer aus beschießen soll, was zu einem direkten Angriff auf den Gildenmeister selbst führt.",al={"wohin führt die defias-questreihe","wie endet die defias-geschichte","abschluss todesminen"}},["27471424"]={q="Wie bin ich in Westfall gelandet?",a="Ihr seid wahrscheinlich über die Flussbrücke aus dem Wald von Elwynn der Straße nach Westen gefolgt, geschickt von Behörden oder Freunden von Späherkuppe. Da Sturmwind überlastet ist und keine königlichen Truppen entbehren kann, hat sich in den benachbarten Ländern herumgesprochen, dass Gryan Starkmantel und die lokalen Bauern verzweifelt fähige Hände benötigen. Ob Ihr dem Ruf nach Hilfe gefolgt seid oder einfach nur dem Königsweg auf der Suche nach Arbeit gefolgt seid, Ihr seid in ein Reich eingetreten, das die Soldaten des Königreichs so gut wie aufgegeben haben.",al={"wie bin ich hierher gekommen","wie bin ich nach westfall gekommen","wie bin ich hier gelandet"}},["6324593c"]={q="Was soll ich in Westfall tun?",a="Eure Hauptmission ist es, die Bürgerwehr bei Späherkuppe dabei zu unterstützen, die unzähligen Bedrohungen zurückzuschlagen, die die Provinz ersticken. Gryan Starkmantel braucht Freiwillige, um die aggressive Tierwelt auszudünnen, die abtrünnigen Erntebeobachter zum Schweigen zu bringen, die durch brachliegende Felder streifen, und die Gnolle des Flusspfotenrudels zurückzudrängen. Vor allem seid Ihr damit beauftragt, die schwer fassbare Bruderschaft der Defias zu jagen, aufzudecken, wo sie sich verstecken, und ihren Würgegriff auf das zu lösen, was von Westfalls kämpfenden Gehöften übrig geblieben ist.",al={"was sollte ich hier tun","was mache ich in westfall","warum bin ich hier"}},c01912f7={q="Was geschah mit der Stonemasons Guild?",a="Unter Gildenmeister Edwin van Cleef verbrachte die Stonemasons Guild nach dem Ersten Krieg Jahre damit, Sturmwind wiederaufzubauen. Als die Arbeit getan war, weigerte sich das House of Nobles, die vereinbarte Summe zu zahlen. Nachdem friedliche Bitten gescheitert waren, wurde die Gilde gewaltsam aufgelöst, was wütende Aufstände entfachte, die die Steinmetze ins Exil trieben.",al={"was geschah mit den steinmetzen","geschichte der steinmetzgilde","wer waren die steinmetze"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Sumpfland",s="Nebel und Kämpfe prägen das Leben im Sumpfland zwischen Khaz Modan und der Baradinbucht. Zwergenkriege und Orc-Invasionen haben dieses Marschland zwischen Eisenschmiede und Lordaeron gezeichnet. Der Hafen von Menethil hält die Allianz mit fernen Küsten verbunden, während Orcs des Drachenmals, Murlocs und Gnolle das Land bedrohen.",h="Nebel und Kämpfe prägen das Leben im Sumpfland zwischen Khaz Modan und der Baradinbucht.",kw={"baradinbucht","drachenmalklan","dun algaz","dun modr","grim batol","menethil","hafen von menethil","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Für die Allianz ist der Hafen von Menethil die wichtigste Tiefwasserroute über das große Meer und verbindet die Östlichen Königreiche mit Außenposten in Kalimdor.",["profession:Mining"]="Als Bergarbeiter könnt Ihr in den Hügeln und Höhlen des Thelgenfelsens reiche Erzadern finden, darunter seltenes Pyrophorerz, das von Zwergenbergleuten und Ingenieuren gesucht wird.",["race:Dwarf"]="Für Zwerge steht das Sumpfland für den Verlust von Dun Modr, die Tragödie von Grim Batol und den andauernden Einsatz zur Verteidigung von König Magnis nördlicher Handelsroute."},sec={{t="Ein Land aus Wasser und Ruinen",b="Unterhalb des Steinwerkdamms liegt kaltes Marschland unter grauem Himmel und dichtem Nebel. Einst standen hier blühende Zwergensiedlungen. Heute füllen versunkene Steinruinen, durchnässte Moore und tückische Sümpfe das Land. Von Loch Modan aus gelangt Ihr durch den engen Pass bei Dun Algaz nach Norden, oder Ihr überquert die Bögen des Thandol-Übergangs aus dem Arathihochland."},{t="Die Narben von Grim Batol",b="Grim Batol ragt über dem östlichen Sumpf auf. Einst hielten die Wildhammerzwerge seine Hallen, doch der Krieg der drei Hämmer entweihte die Festung. Während des Zweiten Krieges machte der Drachenmalklan sie zu seiner Bastion. Dann befreite sich der rote Drachenschwarm aus der Gefangenschaft der Orcs und übte feurige Rache an ihnen. Dabei verwüstete er die Hänge.\n\nRote Wyrmkin bewachen die Tore des Drachenmals. Verwilderte Überlebende des Drachenmalklans leben in verstreuten Hügelcamps und bedrängen Reisende im ganzen Sumpf."},{t="Hafen an der Westküste",b="Der Hafen von Menethil säumt die Baradinbucht und führt Handel und Nachschub der Allianz durch Khaz Modan. Er ehrt König Terenas Menethil II. und verbindet die Östlichen Königreiche mit Kalimdor. Schiffe fahren zur Insel Theramore und über Süderstade nach Auberdine. Zwergische Verteidigungsanlagen schützen den Hafen, doch Küstenmurlocs, Sumpfkreaturen und Räuber bedrohen Schiffe in den felsigen Kanälen."},{t="Bedrohte Grenzen",b="Der Krieg erreicht das Sumpfland aus mehreren Richtungen. Im Norden sabotierten Dunkeleisenzwerge unter der Führung des Hexenmeisters Balgaras the Foul den Thandol-Übergang und nahmen Dun Modr ein. Überland-Nachschubzüge wurden abgeschnitten. Mosshide gnolls durchstreifen die zentralen Moore und bedrohen sogar Rethiel den Sumpfhüter, einen uralten Beschützer.\n\nSchurken-Orc-Kriegstrupps, Dunkeleisen-Infiltratoren und verfluchte Schiffswracks machen den Sumpf gefährlich. Seine Verteidiger müssen wachsam bleiben."}},faq={{q="Wie gelangt Ihr zu Fuß ins Sumpfland?",a="Nehmt von Loch Modan aus den Bergpass durch Dun Algaz nach Norden ins Sumpfland. Reisende aus dem Norden können den Thandol-Übergang aus dem Arathihochland überqueren. Feindliche Orcs des Drachenmals und Dunkeleisenzwerge kämpfen um beide Wege.",al={"wie kommt man ins sumpfland","weg ins sumpfland","zum sumpfland laufen"}},{q="Wohin fahren die Schiffe im Hafen von Menethil?",a="Ein Schiff fährt südwärts zur Insel Theramore in den Düstermarschen. Das andere läuft Süderstade im Vorgebirge des Hügellands an und überquert dann das große Meer nach Auberdine an den Ufern der Dunkelküste.",al={"schiffe in menethil","schiffe im hafen von menethil","wohin fährt das schiff im sumpfland"}},{q="Was ist Grim Batol und warum wird es bewacht?",a="Grim Batol ist eine uralte Zwergenfestung, die nach dem Krieg der drei Hämmer verlassen und später vom Drachenmalklan besetzt wurde. Nach dem Zweiten Krieg vertrieb der befreite rote Drachenschwarm die Orcs und versiegelte den Berg. Rote Drachkin und Wyrmkin patrouillieren an den Toren des Drachenmals, um Eindringlinge von den verfluchten Hallen fernzuhalten.",al={"warum gibt es drachen in grim batol","rote drachen in grim batol","tore des drachenmals"}},{q="Was geschah mit Dun Modr?",a="Dun Modr, eine nördliche Zwergenfestung, die den Thandol-Übergang bewacht, wurde vor Kurzem von Dunkeleisenzwergen unter Balgaras the Foul überrannt. Überlebende unter Rhag Garmason halten ein umkämpftes Lager in der Nähe und kämpfen darum, die Stadt zurückzuerobern.",al={"wer zerstörte dun modr","ruinen von dun modr","dunkeleisenzwerge in dun modr"}},{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel der Sumpfhüter ist ein uraltes Sumpfbiest, das im Grünen Gürtel des Sumpflands lebt. Er sucht die Hilfe von Reisenden gegen aggressive Mosshide gnolls und kranke Fen Creepers, damit sich das Moor erholen kann.",al={"der grüne gürtel","rethiel im sumpfland","wer ist der sumpfhüter"}},{q="Woher stammen all die Orcs im Sumpf?",a="Die Orcs im Sumpf gehören zum Drachenmalklan, der Grim Batol während des Zweiten Krieges befestigte. Nachdem der befreite rote Drachenschwarm sie verwüstet hatte, flohen Überlebende in den Sumpf und die Hügel. Sie überfallen noch immer Straßen und Reisende.",al={"warum gibt es orcs im sumpfland","drachenmalklan im sumpfland"}}},fx={["4984d286"]={q="Warum ist es hier überall Sumpf?",a="Das Sumpfland liegt in einem tiefen Becken, das an drei Seiten von hoch aufragenden Gebirgszügen begrenzt wird, die den Abfluss aus den Höhen darüber auffangen. Es wird von zahllosen Flüssen, Teichen und Bächen gespeist, die in Richtung der Baradinbucht fließen und die Erde ständig feucht und kalt halten.",al={"warum ist das sumpfland ein sumpf","geografie des sumpflands","warum so viel wasser im sumpfland"}},["60c5b961"]={q="Wer lebt im Sumpfland?",a="Die wichtigste zivilisierte Präsenz ist die Allianz im Hafen von Menethil, zusammen mit zwergischen Bergsteigern, die darum kämpfen, wichtige Außenposten zu halten. Die Wildnis wird jedoch von feindlichen Kräften dominiert: abtrünnige Orcs des Drachenmals, die sich in den östlichen Ausläufern verstecken, Mosshide-Gnolle, die durch die Moore streifen, Murlocs, die an den Küsten kriechen, und gewalttätige Dunkeleisenzwerge, die von Dun Modr aus nach Süden drängen.",al={"wer lebt hier","fraktionen im sumpfland","bewohner des sumpflands"}},["8d21dccb"]={q="Was ist der Hafen von Menethil und wer betreibt ihn?",a="Der Hafen von Menethil ist eine schwer befestigte Hafenstadt auf einer Insel in der Baradinbucht und dient als wichtigstes Küstentor der Allianz in Khaz Modan. Benannt zu Ehren von König Terenas Menethil II. von Lordaeron, wird sie von Zwergen und verbündeten Menschen unterhalten, durch die dicken Steinmauern von Burg Menethil geschützt und von der Garnison von Hauptmann Starkfaust bewacht.",al={"hafen von menethil","wer verwaltet menethil","stadt menethil"}},fd9bb568={q="Warum haben die Zwerge hier einen Hafen gebaut?",a="Während des Zweiten Krieges errichtete Orgrim Schicksalshammer hier eine Werft, um die Horde über die Baradinbucht nach Lordaeron zu übersetzen. Nachdem die Allianz die Orcs vertrieben hatte, beanspruchte sie den Ort für sich und baute ihn zu einem blühenden Hafen aus, wodurch wichtige maritime Versorgungsrouten etabliert wurden, die Khaz Modan sowohl mit menschlichen Verbündeten als auch mit fernen Ländern jenseits des Meeres verbinden.",al={"warum hafen von menethil","warum einen hafen im sumpf bauen","grund für den hafen von menethil"}},["4cff40a7"]={q="Ist der Hafen von Menethil Gebiet der Allianz?",a="Ja. Der Hafen von Menethil ist eine offizielle Festung der Allianz. Obwohl es eine raue, geschäftige Hafenstadt voller Seeleute, Händler, Reisender und grober Hafenarbeiter ist, weht dort das Banner der Allianz und sie wird von den Streitkräften aus Eisenschmiede verteidigt.",al={"ist menethil allianz","fraktion hafen von menethil","wem gehört der hafen von menethil"}},["6dc9c02b"]={q="Wer hat hier das Sagen?",a="Es gibt keinen einzelnen Herrscher über das ungezähmte Marschland. Die Autorität der Allianz konzentriert sich auf den Hafen von Menethil unter Hauptmann Starkfaust und der Garnison innerhalb von Burg Menethil. Außerhalb der Hafenmauern ist der Sumpf ein gesetzloses Grenzland, um das sich Militärpatrouillen, orcische Kriegsherren und urtümliche Bestien streiten.",al={"wer führt das sumpfland","kommandant des sumpflands","wer ist hier der chef"}},b8a9f96f={q="Wer ist Hauptmann Starkfaust?",a="Hauptmann Starkfaust ist der zwergische Kommandant, der die Garnison im Hafen von Menethil befehligt. Von der Sicherheit des Hafens aus koordiniert er Verteidigungsoperationen im gesamten Sumpf und beauftragt fähige Abenteurer damit, die unaufhörlichen Überfälle der nahegelegenen Orcs des Drachenmals einzudämmen.",al={"hauptmann starkfaust sumpfland","starkfaust lore","wer ist starkfaust"}},["38351a9f"]={q="Wer sind die Orcs des Drachenmals und warum sind sie hier?",a="Der Drachenmalclan ist ein brutaler Orcclan, der die Dämonenseele benutzte, um Alexstrasza und den roten Drachenschwarm während des Zweiten Krieges zu versklaven, und der von den Höhen von Grim Batol aus herrschte. Als die Drachenkönigin befreit wurde, zerschlugen die rachsüchtigen Drachen den Clan und zerstreuten die Überlebenden in die Sümpfe und Berge des Sumpflands, wo sie weiterhin eine gewalttätige, anhaltende Bedrohung darstellen.",al={"drachenmal sumpfland","warum sind drachenmal im sumpfland","orcs des drachenmals"}},ecc875bb={q="Wer sind die Dunkeleisenzwerge und warum greifen sie Dun Modr an?",a="Die Dunkeleisen sind ein tückischer, schattenwirkender Zwergenclan, der lange aus Eisenschmiede verbannt war. Sie nutzten aus, dass die Streitkräfte der Allianz im Ausland eingesetzt waren, stießen nach Norden vor, besetzten die Stadt Dun Modr und sabotierten den Thandol-Übergang, um wichtige Kommunikationswege zu kappen und Gebiete in Khaz Modan zurückzuerobern.",al={"dunkeleisen dun modr","warum dunkeleisen im sumpfland","dunkeleisen angriff sumpfland"}},["0f0d7fa8"]={q="Was ist der Thandol-Übergang und warum ist er wichtig?",a="Der Thandol-Übergang ist ein prächtiges Paar massiver steinerner Zwergenbrücken, die die Schlucht zwischen dem nördlichen Khaz Modan und dem Arathihochland überspannen. Er wurde nach dem Krieg der drei Hämmer gebaut, um Handel und Freundschaft mit den Wildhämmern zu erleichtern, und ist die einzige Landverbindung zwischen den südlichen Königreichen und dem nördlichen Lordaeron.",al={"thandol-übergang","thandol brücke","warum ist der thandol-übergang wichtig"}},faff9f74={q="Warum wollen die Dunkeleisen ihn in die Luft jagen?",a="Durch die Zerstörung des Thandol-Übergangs wollen die Dunkeleisen Eisenschmiede und Khaz Modan vollständig von den Verbündeten der Allianz in Lordaeron isolieren. Das Kappen dieser Überland-Lebensader verhindert, dass Verstärkung nach Süden marschiert, um Dun Modr zurückzuerobern oder bei weiteren Einfällen der Dunkeleisen zu helfen.",al={"warum thandol-übergang zerstören","dunkeleisen brückenkomplott","thandol-übergang in die luft jagen"}},eabba297={q="Wie bin ich im Sumpfland gelandet und wohin führt der Weg als Nächstes?",a="Die meisten Reisenden kommen an, indem sie von Loch Modan aus durch den Gebirgspass von Dun Algaz nach Norden marschieren oder die lange Reise mit dem Schiff in den Hafen von Menethil antreten. Von hier aus führt die Straße weiter nach Norden über den Thandol-Übergang in das Arathihochland, während Schiffe, die von den Docks ablegen, Abenteurer westlich über das große Meer tragen.",al={"wohin vom sumpfland aus","nächstes gebiet sumpfland","sumpfland weg"}},["75fb0ece"]={q="Ist das die Straße nach Eisenschmiede?",a="Ja. Wenn Ihr der Straße aus dem Sumpf nach Süden folgt, gelangt Ihr direkt in die engen Tunnel von Dun Algaz. Wenn Ihr das Gebirge durchquert, kommt Ihr nach Loch Modan, von wo aus die Hauptstraße nach Westen durch den Nordtorpass direkt in den Schnee von Dun Morogh und Eisenschmiede führt.",al={"straße nach eisenschmiede sumpfland","wie kommt man von sumpfland nach eisenschmiede","pfad nach eisenschmiede"}},["78aee5e0"]={q="Wie bin ich im Sumpfland gelandet?",a="Die meisten Reisenden der Allianz erreichen das Sumpfland, indem sie von Loch Modan aus nach Norden reisen und die engen Bergtunnel von Dun Algaz trotzen, um in die nebligen Marschlande unterhalb abzusteigen. Andere kommen mit dem Schiff von jenseits des großen Meeres an und segeln von den Küsten von Kalimdor in den Hafen von Menethil. Wer vom Arathihochland aus nach Süden reist, muss stattdessen die gefährlichen Übergänge des zerstörten Thandol-Übergangs meistern.",al={"wie bin ich hierher gekommen","wie kam ich im sumpfland an","woher bin ich gekommen"}},["87ca94d2"]={q="Was soll ich im Sumpfland tun?",a="Das Moor ist ein schwer bedrängtes Grenzland, in dem die Allianz an einem zerbrechlichen Stützpunkt festhält. Vom Hafen von Menethil aus seid Ihr dazu aufgerufen, wichtige Handelsrouten zu sichern und die verbliebenen Orcs des Drachenmals zurückzuschlagen, die das Tiefland überfallen. Weiter östlich und nördlich benötigen zwergische Bergsteiger Euren Stahl, um feindliche Gnollrudel einzudämmen, belagerten Ausgrabungsstätten zu helfen und Dunkeleisenzwerge zurückzudrängen, die drohen, den Thandol-Übergang vollständig zu unterbrechen.",al={"was soll ich hier tun","warum bin ich hier","was ist meine mission im sumpfland"}},["2cd88152"]={q="Was ist das Sumpfland?",a="Das Sumpfland ist ein kaltes, weitläufiges Marschland, eingebettet zwischen den Bergen von Khaz Modan und dem westlichen Meer. In ewigen grauen Nebel gehüllt, liegt es unmittelbar nördlich von Loch Modan und südlich vom Arathihochland. Einst Heimat zahlreicher Zwergensiedlungen, wurde die Region von vergangenen Kriegen verwüstet und dient nun als raue, ungezähmte Wildnis, die die Zwergenkönigreiche von den Ruinen von Lordaeron trennt.",al={"was ist das sumpfland","sumpfland lore","erzähl mir vom sumpfland"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Winterquell",s="Schneestürme fegen über Winterquell hinweg, wo alte Gefahren noch immer das Leben prägen. Hoch oben an den nordöstlichen Hängen des Hyjal liegt das Tal oberhalb von Mondlichtung und Teufelswald. Uralte Ruinen der Hochgeborenen und wilde Raubtiere prägen das Land, während die Ewige Warte in seinem Herzen liegt. Blaue Drachen finden hier Zuflucht, und dämonische Verderbnis erfasst die südlichen Höhen.",h="Schneestürme fegen über Winterquell hinweg, wo alte Gefahren noch immer das Leben prägen.",kw={"blaue drachen","die flüsternde schlucht","donova schneeweh","ewige warte","frostsäbler","eiskappe","kel'theril","mazthoril","holzschlund","winterquell"},ang={["class:Druid"]="Hoch über Mondlichtung hat Winterquell für Druiden eine heilige Bedeutung. Während des Dritten Krieges erweckte Malfurion Sturmgrimm hier die Druiden der Klaue aus ihrem uralten Schlaf.",["faction:Alliance"]="Helden der Allianz besuchen Rivern Frostwind am Frostsäblerfelsen, trotzen Winterquells Kälte und verdienen sich die Treue der angesehenen Winterquell-Frostsäbler als Reittiere.",["profession:Herbalism"]="In Winterquell wachsen die Eiskappe, ein alpines Kraut, das es sonst nirgends gibt, sowie Bergsilberweisling und der seltene Schwarze Lotus. Alchemisten suchen Eiskappe für fortgeschrittene Mixturen.",["profession:Mining"]="Winterquells eisige Felsen und Höhlenwände bergen kleine und reiche Thoriumadern sowie seltene Truesilbervorkommen.",["race:NightElf"]="Winterquell ist eng mit der Geschichte der Elfen verbunden. Die Druiden der Klaue ruhten Jahrtausende in seinen Grabhügeln, Kel'Theril liegt in Trümmern und Nordrassils freiliegende Wurzeln tragen Schäden aus der Schlacht am Hyjal."},sec={{t="Ein Reich ewigen Frosts",b="Schneestürme ziehen über Winterquells Hochwälder, Felsklippen und gefrorene Seen. Weit unterhalb des Gipfels erhebt sich das Tal über die umliegende Wildnis, umweht von kalter Bergluft. Gewaltige Wurzeln Nordrassils, des Weltbaums, wölben sich durch die Schneewehen, verdreht von den Kämpfen des Dritten Krieges. Im nördlichen Kalimdor ist es meist warm und dicht bewaldet, doch diese alpinen Wälder bieten Frostsäblern, Chimären, Yetis und Winterbären Zuflucht."},{t="Das Wegekreuz und Außenposten",b="Uralte Passagen durch die Holzschlundfeste verbinden Winterquell mit Teufelswald und Mondlichtung. Unverdorbene Furbolgs bewachen den Weg und mustern Reisende, die ihn passieren. Im Zentrum des Tals betreiben Goblins des Steamwheedle Cartels die Ewige Warte, eine Handelsstadt, die Allianz und Horde offensteht. Handel, Ingenieurskunst und warme Feuer bieten Schutz vor der Kälte der Berge."},{t="Alte Geister und blaue Drachen",b="Die zerstörten Säulen von Kel'Theril ragen neben einem gefrorenen See auf. Die Geister der einst dort lebenden Hochgeborenen spuken zwischen ihnen. Leichtsinnige Zauberer zerschmetterten den verfluchten Kristall von Zin-Malor, und der Wahnsinn ergriff sie. Weiter südlich bergen Mazthorils Höhlen die Festung des blauen Drachenschwarms auf Kalimdor. Haleh, seine schützende Matrone, wacht über Malygos' Brut, während diese arkane Strömungen bewacht und sich nahen Gefahren stellt."},{t="Der drohende Schatten der Schlucht",b="Die Flüsternde Schlucht durchbricht die Ruhe am südlichen Rand Winterquells. Dämonische Streitkräfte, die vom Dritten Krieg zurückgeblieben sind, kriechen durch ihre zerklüfteten Schluchten und versperren die hochgelegenen Zugänge zum Gipfel des Hyjal. Auch die Winterfall-Furbolgs sind übler Verderbnis anheimgefallen. Unabhängige Forscher wie Donova Schneeweh untersuchen die sich ausbreitende Verderbnis, während sie die Tierwelt des Tals bedroht."}},faq={{q="Wie komme ich nach Winterquell?",a="Winterquell liegt hinter der Holzschlundfeste, einem Tunnelsystem im Nordosten des Teufelswalds. Die Holzschlund-Furbolgs greifen Reisende an, die sie für feindselig halten. Ihr müsst also ihr Vertrauen gewinnen, um friedlich hindurchzukommen. Der östliche Ausgang führt auf Winterquells verschneite Hänge.",al={"nach winterquell gelangen","winterquell betreten","winterquell eingang","holzschlund tunnel winterquell"}},{q="Wer betreibt die Stadt Ewige Warte?",a="Das Steamwheedle Cartel betreibt die Ewige Warte. Seine Goblinhändler halten die Stadt neutral, sodass Reisende der Horde und der Allianz ihre Flugmeister, Reparaturhändler, Banktresore und Waren nutzen können, solange sie den Frieden wahren.",al={"wer kontrolliert die ewige warte","fraktion der ewigen warte","ist die ewige warte neutral"}},{q="Was sind die Geister am Kel'Therilsee?",a="Die Geister sind Hochgeborene Nachtelfen, die vor zehntausend Jahren in Kel'Theril lebten. Ihre Zauberer hantierten mit dem gestohlenen Kristall von Zin-Malor. Als er zersplitterte, entfesselte das einen Fluch, der sie in den Wahnsinn trieb. Jahrhunderte später verfielen auch Expeditionen von Hochelfen dem Wahnsinn. Nun spuken sie neben ihren Ahnen in den gefrorenen Ruinen.",al={"geister am kel'therilsee","geister in den ruinen von kel'theril","wer ist in kel'theril"}},{q="Warum sind die Winterfall-Furbolgs feindselig?",a="Die Winterfall-Furbolgs sind einer sich ausbreitenden, unnatürlichen Verderbnis anheimgefallen, die ihren Stamm in feindseligen Wahnsinn getrieben hat. Die nahen Holzschlund-Furbolgs haben ihren Verstand bewahrt, während dunkle Einflüsse die Winterfall-Furbolgs beherrschen. Forscher wie Donova Schneeweh untersuchen die Verderbnis und säubern die Lager des Stammes.",al={"warum sind die winterfall feindselig","verderbnis des winterfall stamms","donova schneeweh furbolgs"}},{q="Was lebt in Mazthoril?",a="Mazthoril ist der wichtigste Rastplatz und Zufluchtsort des blauen Drachenschwarms auf Kalimdor. Unter Halehs Aufsicht bewachen Wyrmkin, Elitewelpen und uralte Drachen in den höhlenartigen Türmen Drachenerbstücke und arkane Geheimnisse. Sie ist die Gefährtin des Aspekts Malygos.",al={"mazthoril drachen","was ist mazthoril","blaue drachen in winterquell"}},{q="Was ist die Flüsternde Schlucht?",a="Die Flüsternde Schlucht ist eine gefährliche Schlucht am südlichen Rand des Tals, die von mächtigen Dämonen aus dem Dritten Krieg gehalten wird. Sie bewachen die gefährlichen Pfade zu den Höhen des Hyjal.",al={"dämonen der flüsternden schlucht","was ist in der flüsternden schlucht","hyjal zugang winterquell"}},{q="Kann man hier Frostsäbler ausbilden oder zähmen?",a="Am Frostsäblerfelsen im hohen Norden Winterquells kümmert sich der Nachtelf Rivern Frostwind um die dort heimischen weißen Katzen. Helft ihm, Vorräte zu sichern und das Rudel zu schützen, dann könnt Ihr Euch als würdig erweisen, einen Frostsäbler aufzuziehen und zu reiten.",al={"frostsäbler reittier","rivern frostwind frostsäbler","wie bekomme ich einen frostsäbler"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Insel Zephras",s="Auf der Insel Zephras sehen die Skyborne ihrer langsam zerfallenden Heimat entgegen. Einst lebten Luftelementare auf der Insel, doch diese Wächter verschwanden und die Magie, die das Land in der Luft hält, schwindet. Flüchtlinge treffen von Anvilas und Siroccas ein, während diese Inseln zerfallen.",h="Auf der Insel Zephras sehen die Skyborne ihrer langsam zerfallenden Heimat entgegen.",kw={"luftschiffe","anvilas","elementarebene","siroccas","skyborne","der himmelswall","valanaar","windsteine","zephras"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass die Insel Zephras in der Elementarebene der Luft liegt. Ihre schwindende Elementarkraft zeigt, was geschieht, wenn die Geister verschwinden, die ein Elementarland erhalten.",["race:Skyborne"]="Als Skyborne ist die Insel Zephras Eure Heimat der Ahnen und Euer Ausgangspunkt. Ihre Schönheit bleibt bestehen, während das Land zusammenbricht und die Elementarkraft schwindet."},sec={{t="Ein Reich in den Lüften",b="Im Himmelswall, der Elementarebene der Luft, leben die Skyborne seit Generationen auf der Insel Zephras. Einheimische Luftelementare halfen einst dabei, die magischen Strömungen zu bewahren, die die Insel in der Luft halten. Vor mehreren Jahrhunderten verschwanden diese Elementare. Ohne sie wurden die Verzauberungen unter dem Land allmählich schwächer, und Zephras beginnt zu zerbrechen."},{t="Getrennte Horizonte",b="Anvilas und Siroccas trieben einst neben Zephras durch den Himmelswall, und die Skyborne lebten auf allen drei Inseln. Als die Elementare verschwanden, brach der Kontakt zwischen den Inseln ab. Nun haben Flüchtlinge von den zerfallenden Nachbarinseln Zephras erreicht und suchen Schutz. Sie berichten, dass das Land unter ihnen auf Anvilas und Siroccas auseinanderbricht."},{t="Schwelle nach Azeroth",b="Während Zephras zerfällt, blicken die Skyborne über den Himmelswall hinaus nach Azeroth. Luftschiffe brechen nun von den Himmelsdocks Valanaars auf, um seltene Verbindungen zum Reich der Sterblichen herzustellen. Ihre Reisen führen sie in die Randgebiete von Dalaran im Alteracgebirge und zum Himmelsschauerplateau in Mulgore."}},faq={{q="Wo liegt die Insel Zephras?",a="Die Insel Zephras schwebt im Himmelswall, der Elementarebene der Luft, und nicht auf Azeroth. Wolken und Windströmungen umgeben die Insel in diesem ätherischen Reich.",al={"lage der insel zephras","wo liegt zephras","auf welcher ebene liegt zephras"}},{q="Warum zerfällt die Insel Zephras?",a="Einst lebten einheimische Luftelementare neben den Skyborne und halfen, die Insel Zephras zu erhalten. Sie verschwanden vor mehreren Jahrhunderten, und die magischen Fundamente der Insel sind seither allmählich schwächer geworden.",al={"warum zerfällt zephras","zerstörung der insel zephras","sterbende insel"}},{q="Was sind Anvilas und Siroccas?",a="Anvilas und Siroccas sind benachbarte schwebende Inseln, auf denen die Skyborne im Himmelswall leben. Der Kontakt zu beiden brach ab, als die Elementare verschwanden, und Flüchtlinge berichten nun, dass die Inseln zusammenbrechen.",al={"anvilas","siroccas","andere skyborne-inseln"}},{q="Wie reisen die Bewohner zwischen der Insel Zephras und Azeroth?",a="Die Skyborne lassen Luftschiffe von den Himmelsdocks Valanaars aufsteigen und reisen damit nach Azeroth. Sie erreichen die Randgebiete von Dalaran im Alteracgebirge und das Himmelsschauerplateau in Mulgore.",al={"wie verlässt man zephras","luftschiffe von zephras","reise nach azeroth"}},{q="Wer sind die Skyborne?",a="Die Skyborne leben seit Generationen auf der Insel Zephras und in den Schwesterreichen am Himmel. Ihre Heimatinsel zerbricht langsam, während die Magie schwindet, die sie erhält.",al={"volk der skyborne","wer lebt auf zephras"}},{q="Wer lebt außer den Skyborne auf der Insel Zephras?",a="Auf der Insel Zephras leben örtliche Banditen, in Höhlen hausende Nachtklauen und wilde Tiere. Sie sind an Orten wie dem Kreischlingsbau und der Nachtklauenhöhle zu finden.",al={"bewohner von zephras","feinde auf zephras"}}},fx={["6e14d755"]={q="Werde ich die Insel irgendwann verlassen?",a="Ja. Während Insel Zephras als Euer Zuhause und anfänglicher Trainingsort dient, legen Luftschiffe von den Himmelsdocks in Valanaar ab, die durch dimensionale Risse das Festland von Azeroth erreichen und eine direkte Verbindung zu Dalaran im Alteracgebirge sowie zum Himmelsschauerplateau in Mulgore herstellen.",al={"werde ich zephras verlassen","insel zephras verlassen","können wir nach azeroth reisen"}},["19470e71"]={q="Wie bin ich auf Insel Zephras gelandet?",a="Ihr wurdet in das Volk der Himmelsgeborenen hineingeboren, den Shen'dorei, die auf dieser schwebenden Zuflucht hoch über Der Himmelswall, der Elementarebene der Luft, leben. Vor Jahrtausenden flohen Eure Vorfahren vor der Säuberung durch Prinz Tortheldrin in Eldre'Thalas und schlossen einen Pakt mit Windgeistern, die dieses Heiligtum in den Himmel hoben. Während andere Schwesterinseln wie Anvilas und Siroccas zerbröckeln oder in unerreichbare Ferne rücken, war Insel Zephras von Anfang an Euer Zuhause. Ihr beginnt Eure Reise hier inmitten Eures eigenen Volkes.",al={"wie bin ich hierher gekommen","wie habe ich insel zephras erreicht","warum bin ich hier aufgewacht","woher komme ich"}},["5dae6f41"]={q="Was soll ich auf Insel Zephras tun?",a="Euer Zuhause bröckelt unter Euren Füßen. Vor Jahrhunderten verschwanden die wohlwollenden Luftelementare und die arkanen Pylone, die Insel Zephras zusammenhalten, verlieren an Kraft. Flüchtlinge strömen von den zusammenbrechenden äußeren Inseln herbei, während rivalisierende Fraktionen, darunter Der Hohe Orden, die Windformer und die Al'Aketh, um das streiten, was noch übrig ist. Ihr müsst Eurem Volk helfen, interne Bedrohungen und wilde Bestien bezwingen, dabei helfen, die versagende Magie zu stabilisieren und letztendlich einen Weg hinunter nach Azeroth finden, bevor die Insel stürzt.",al={"was soll ich hier tun","was ist mein ziel hier","was mache ich auf insel zephras","warum bin ich hier"}},["1fd88046"]={q="Was ist die Insel Zephras?",a="Die Insel Zephras ist eine hoch aufragende, schwebende Landmasse innerhalb des Himmelswalls, der Elementarebene der Luft. Vor Jahrtausenden handelten verbannte Nachtelfen, die der Verfolgung in Eldre'Thalas entkamen, mit einheimischen Windgeistern, die die Insel in den Himmel hoben, um sie in Sicherheit zu bringen. Sie dient als angestammtes Heiligtum ihrer Nachkommen, den Himmelsgeborenen.",al={"was ist zephras","über die insel zephras","infos zur insel zephras"}},["7ea7c85c"]={q="Was ist auf der Insel Zephras passiert?",a="Die Insel Zephras wurde in den Himmelswall gehoben, nachdem hochgeborene Vorfahren sich von der blutigen Herrschaft von Prinz Tortheldrin in Eldre'Thalas abwandten. Die Himmelsgeborenen lebten jahrtausendelang in Harmonie mit Luftelementaren, doch vor Jahrhunderten verschwanden jene elementaren Gönner ohne Erklärung. Ohne ihre fortwährende Magie begannen die Pylone, die die Insel verankerten, zu verfallen, und Flüchtlinge von benachbarten, einstürzenden Inseln sind hierher geflohen, während interne Fraktionen um schwindende Ressourcen wetteifern.",al={"zephras geschichte","was ist hier auf zephras passiert","zephras lore"}},["70a3c6ae"]={q="Ist die Insel Zephras gefährlich?",a="Ja. Jenseits der drohenden physischen Gefahr, dass die Insel selbst instabil wird und vom Himmel stürzt, hat das Verschwinden der elementaren Beschützer das Land chaotisch hinterlassen. Banditenlager, feindliche Wildtierbaue und explosive politische Reibereien zwischen dem Hohen Orden, den Windformern und Al'Aketh machen Reisen außerhalb befestigter Siedlungen gefährlich.",al={"ist zephras gefährlich","zephras bedrohungen","gefahren auf zephras"}},b4875d06={q="Wo liegt die Insel im Vergleich zum Rest von Azeroth?",a="Die Insel Zephras ruht nicht auf der Oberfläche von Azeroth; sie treibt innerhalb des Himmelswalls, einer separaten dimensionalen Domäne, die von den Titanengeschmiedeten geschaffen wurde, um chaotische Luftelementare einzudämmen. Die einzigen physischen Verbindungen zwischen der Insel und der sterblichen Welt unterhalb sind spezialisierte Luftschiffe, die in Valanaar anlegen und über die Grenze zu Orten wie Dalaran und Mulgore reisen.",al={"wo liegt zephras zu azeroth","ist zephras in azeroth","zephras standort im vergleich zu azeroth"}},["2c89f95d"]={q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine der rivalisierenden Fraktionen, die neben dem Hohen Orden und den Windformern um die Vorherrschaft auf der Insel Zephras kämpfen. Da die Pylone, die die Insel verankern, versagen und das Überleben immer verzweifelter wird, wetteifern die Al'Aketh aktiv um die Vorherrschaft und die Kontrolle über die verbleibenden mystischen Ressourcen der Insel.",al={"was sind die alaketh","fraktion al'aketh","wer ist alaketh"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
